#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000  // AIN0 single-ended
#define ADS1115_CONFIG_GAIN_4_096V 0x0200 // +/-4.096V gain
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode

// I2C handle
int i2c_handle;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the ADS1115
int ads1115_init() {
    // Configure the ADS1115 for single-shot mode
    uint16_t config_value = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_GAIN_4_096V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_MODE_SINGLE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc() {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 for conversion: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    // Swap bytes (ADS1115 returns MSB first)
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to convert the ADC value to amperes
float convert_to_amperes(int16_t adc_value) {
    // ADS1115 range: +/- 4.096V, 16-bit resolution
    // Full scale: 4.096V / 2^15 = 0.0024V/LSB
    // Conversion factor: 1 LSB = 0.0024 V / 2^15 = 0.000001 V/LSB
    float voltage = (float)adc_value * 0.0024 / 32768.0;
    float current = voltage / 0.0024; // Current in Amperes
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init() != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        // Convert to amperes
        float current = convert_to_amperes(adc_value);

        // Log current value
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

