#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE0_PIN 8

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define SPI handle
int spi_handle;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(time_t timestamp, int flame_detected, float temperature);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // Adjust the slope and intercept based on your sensor's characteristics
    float temperature = (adc_value / 1023.0) * 100.0; // Scale to 0-100 degrees Celsius
    return temperature;
}

// Function to log data to CSV file
void log_data(time_t timestamp, int flame_detected, float temperature) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open flame_data.csv for writing\n");
        return;
    }

    fprintf(fp, "%s,%d,%.2f\n", timestamp_str, flame_detected, temperature);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CE0_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008 ADC
        int adc_value = read_mcp3008(0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 ADC\n");
            continue; // Skip to the next iteration
        }

        // Calculate temperature
        float temperature = calculate_temperature(adc_value);

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        log_data(current_time, flame_detected, temperature);

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

