#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define CO_REG 0x01
#define NO2_REG 0x03
#define ALERT_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file = NULL;
FILE *alert_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *co_value, int *no2_value);
float convert_co_ppm(int co_value);
int check_alert_threshold(float co_ppm);
int log_data(int co_value, float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    int co_value;
    int no2_value;
    float co_ppm;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Error initializing I2C. Exiting.\n");
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    alert_file = fopen(ALERT_FILE, "a");
    if (alert_file == NULL) {
        perror("Error opening alert file");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.co_value, &sensor_data.no2_value) == 0) {
            // Convert CO to ppm
            sensor_data.co_ppm = convert_co_ppm(sensor_data.co_value);

            // Log data
            if (log_data(sensor_data.co_value, sensor_data.co_ppm) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Check alert threshold
            if (check_alert_threshold(sensor_data.co_ppm)) {
                if (log_alert(sensor_data.co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert.\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up and exiting.\n");
    fclose(log_file);
    fclose(alert_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int *co_value, int *no2_value) {
    char buffer[4];
    int result;

    // Read CO data
    result = i2cReadI2CBlockData(i2c_handle, CO_REG, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading CO data: %d\n", result);
        return 1;
    }
    *co_value = (buffer[0] << 8) | buffer[1];

    // Read NO2 data
    result = i2cReadI2CBlockData(i2c_handle, NO2_REG, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading NO2 data: %d\n", result);
        return 1;
    }
    *no2_value = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Convert CO to ppm (example formula, adjust as needed)
float convert_co_ppm(int co_value) {
    // This is a placeholder.  Refer to the MICS-4514 datasheet for the correct conversion formula.
    // The formula might involve calibration data and temperature compensation.
    // For example, a simple linear conversion:
    float ppm = (float)co_value * 0.1; // Example: 0.1 ppm per unit
    return ppm;
}

// Check alert threshold
int check_alert_threshold(float co_ppm) {
    return (co_ppm >= ALERT_THRESHOLD) ? 1 : 0;
}

// Log data to file
int log_data(int co_value, float co_ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, CO: %d, CO (ppm): %.2f\n", timestamp, co_value, co_ppm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Log alert to file
int log_alert(float co_ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(alert_file, "%s, ALERT: CO concentration exceeds threshold (%.2f ppm > %.2f ppm)\n", timestamp, co_ppm, ALERT_THRESHOLD);
    fflush(alert_file); // Ensure data is written immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

