#define REF_VOLTAGE 3.3 // V
#define VREF 3.3 // V
#define DBS_PER_VOLT 0.1 // dB/V
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t sample[NUM_SAMPLES];
    int error_count;
} MicrophoneData;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_microphone_data(int i2c_handle, MicrophoneData *data);
float calculate_average_level(MicrophoneData *data);
int log_data(float avg_level1, float avg_level2);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read data from a microphone
int read_microphone_data(int i2c_handle, MicrophoneData *data) {
    int16_t raw_sample;
    int bytes_read;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        bytes_read = i2cReadWordData(i2c_handle, 0x00); // Read from register 0x00
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
            data->error_count++;
            data->sample[i] = -999.0; // Indicate error
            continue;
        }

        // Convert two's complement to signed 16-bit integer
        raw_sample = (int16_t)((bytes_read << 8) | (bytes_read >> 8)); // Byte swap
        raw_sample = raw_sample >> 8; // Shift right by 8 bits

        data->sample[i] = raw_sample;
    }
    return 0;
}

// Function to calculate the average level
float calculate_average_level(MicrophoneData *data) {
    float sum = 0.0;
    int valid_samples = 0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        if (data->sample[i] != -999.0) {
            sum += data->sample[i];
            valid_samples++;
        }
    }

    if (valid_samples > 0) {
        return (float)sum / valid_samples;
    } else {
        return -999.0; // Indicate no valid samples
    }
}

