    MicrophoneData mic1_data, mic2_data;
    float avg_level1, avg_level2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, MIC1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, MIC2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone data
        if (read_microphone_data(i2c_handle1, &mic1_data) != 0) {
            mic1_data.error_count = mic1_data.error_count + 1; // Increment error count
        }
        if (read_microphone_data(i2c_handle2, &mic2_data) != 0) {
            mic2_data.error_count = mic2_data.error_count + 1; // Increment error count
        }

        // Calculate average levels
        avg_level1 = calculate_average_level(&mic1_data);
        avg_level2 = calculate_average_level(&mic2_data);

        // Log data
        if (log_data(avg_level1, avg_level2) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_RATE * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

