#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC1_CE 8
#define MIC2_CE 9
#define MIC1_MISO 9
#define MIC1_MOSI 10
#define MIC1_SCLK 11
#define MIC2_CE 8
#define MIC2_MISO 9
#define MIC2_MOSI 10
#define MIC2_SCLK 11
#define LED_PIN 27

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define sampling window size
#define SAMPLING_WINDOW 100 // 100 samples * 1ms = 100ms

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Structure to hold microphone data
typedef struct {
    int mic1_channel;
    int mic2_channel;
} MicrophoneConfig;

MicrophoneConfig config = {MIC1_CE, MIC2_CE};

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control LED based on RMS values
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(500000);      // Wait 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.mic1_ce, PI_OUTPUT);
    gpioSetMode(config.mic2_ce, PI_OUTPUT);
    gpioSetMode(config.mic1_miso, PI_INPUT);
    gpioSetMode(config.mic1_mosi, PI_OUTPUT);
    gpioSetMode(config.mic1_sclk, PI_OUTPUT);
    gpioSetMode(config.mic2_ce, PI_OUTPUT);
    gpioSetMode(config.mic2_miso, PI_INPUT);
    gpioSetMode(config.mic2_mosi, PI_OUTPUT);
    gpioSetMode(config.mic2_sclk, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int mic1_samples[SAMPLING_WINDOW];
    int mic2_samples[SAMPLING_WINDOW];
    int sample_index = 0;

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read audio samples from microphones
        int mic1_adc = read_mcp3008(config.mic1_channel);
        int mic2_adc = read_mcp3008(config.mic2_channel);

        if (mic1_adc < 0 || mic2_adc < 0) {
            fprintf(stderr, "Error reading from MCP3008\n");
            continue; // Skip to the next iteration
        }

        // Store samples in arrays
        mic1_samples[sample_index] = mic1_adc;
        mic2_samples[sample_index] = mic2_adc;

        sample_index++;

        // Check if sampling window is full
        if (sample_index == SAMPLING_WINDOW) {
            // Calculate RMS values
            double mic1_rms = calculate_rms(mic1_samples, SAMPLING_WINDOW);
            double mic2_rms = calculate_rms(mic2_samples, SAMPLING_WINDOW);

            // Log data
            log_data(mic1_rms, mic2_rms);

            // Control LED
            control_led(mic1_rms, mic2_rms);

            // Reset sample buffers
            sample_index = 0;
        }

        gpioDelay(1000); // Wait 1ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

