    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control LED based on RMS values
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(500000);      // Wait 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.mic1_ce, PI_OUTPUT);
    gpioSetMode(config.mic2_ce, PI_OUTPUT);
    gpioSetMode(config.mic1_miso, PI_INPUT);
    gpioSetMode(config.mic1_mosi, PI_OUTPUT);
    gpioSetMode(config.mic1_sclk, PI_OUTPUT);
    gpioSetMode(config.mic2_ce, PI_OUTPUT);
    gpioSetMode(config.mic2_miso, PI_INPUT);
    gpioSetMode(config.mic2_mosi, PI_OUTPUT);
    gpioSetMode(config.mic2_sclk, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int mic1_samples[SAMPLING_WINDOW];
    int mic2_samples[SAMPLING_WINDOW];
    int sample_index = 0;

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read audio samples from microphones
        int mic1_adc = read_mcp3008(config.mic1_channel);
        int mic2_adc = read_mcp3008(config.mic2_channel);

        if (mic1_adc < 0 || mic2_adc < 0) {
            fprintf(stderr, "Error reading from MCP3008\n");
            continue; // Skip to the next iteration
        }

        // Store samples in arrays
        mic1_samples[sample_index] = mic1_adc;
        mic2_samples[sample_index] = mic2_adc;

        sample_index++;

        // Check if sampling window is full
        if (sample_index == SAMPLING_WINDOW) {
            // Calculate RMS values
            double mic1_rms = calculate_rms(mic1_samples, SAMPLING_WINDOW);
            double mic2_rms = calculate_rms(mic2_samples, SAMPLING_WINDOW);

            // Log data
            log_data(mic1_rms, mic2_rms);

            // Control LED
            control_led(mic1_rms, mic2_rms);

            // Reset sample buffers
            sample_index = 0;
        }

        gpioDelay(1000); // Wait 1ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

