#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // A
#define ADC_REF_VOLTAGE 4.096 // V
#define SENSITIVITY 0.1 // V/A
#define SLEEP_TIME 0.1 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float convert_to_current(int16_t adc_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(float average_current);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    float sample_rate;
    int buffer_size;
    float current_threshold;
    float adc_ref_voltage;
    float sensitivity;
} config_t;

config_t config = {
    I2C_BUS,
    ADS1115_ADDR,
    LED_GPIO,
    SAMPLE_RATE,
    BUFFER_SIZE,
    CURRENT_THRESHOLD,
    ADC_REF_VOLTAGE,
    SENSITIVITY
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);
    gpioWrite(config.led_gpio, 0); // Turn LED off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        float current = convert_to_current(adc_value);

        // Add current to circular buffer
        add_to_buffer(current);

        // Calculate average current
        float average_current = calculate_average();

        // Control LED
        control_led(average_current);

        // Sleep for a short period
        time_sleep(SLEEP_TIME);
    }

    // Cleanup
    gpioWrite(config.led_gpio, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, 128 SPS
    // Configuration register value: 0x4003 (Single-ended A0, 4.096V, 128 SPS, Disable comparator)
    char config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x4003; //0b0100000010000011
    config_data[2] = 0x83; //0b0100000000000011

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    char reg = CONVERSION_REG;
    char data[2];
    int16_t adc_value;

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    return adc_value;
}

// Convert ADC value to current
float convert_to_current(int16_t adc_value) {
    float voltage = (float)adc_value * config.adc_ref_voltage / 32768.0; // 32768 is 2^15
    float current = voltage / config.sensitivity;
    return current;
}

// Add current to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > config.current_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

