int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, TCS34725_CDATA);
        if (result >= 0) {
            *clear = (uint16_t)result;
        } else {
            fprintf(stderr, "Error: Failed to read clear data (0x%02X). Error code: %d\n", TCS34725_CDATA, errno);
            *clear = 0; // Set to 0 to avoid further issues
        }

        result = i2cReadWordData(i2c_handle, TCS34725_RDATA);
        if (result >= 0) {
            *red = (uint16_t)result;
        } else {
            fprintf(stderr, "Error: Failed to read red data (0x%02X). Error code: %d\n", TCS34725_RDATA, errno);
            *red = 0; // Set to 0 to avoid further issues
        }

        result = i2cReadWordData(i2c_handle, TCS34725_GDATA);
        if (result >= 0) {
            *green = (uint16_t)result;
        } else {
            fprintf(stderr, "Error: Failed to read green data (0x%02X). Error code: %d\n", TCS34725_GDATA, errno);
            *green = 0; // Set to 0 to avoid further issues
        }

        result = i2cReadWordData(i2c_handle, TCS34725_BDATA);
        if (result >= 0) {
            *blue = (uint16_t)result;
        } else {
            fprintf(stderr, "Error: Failed to read blue data (0x%02X). Error code: %d\n", TCS34725_BDATA, errno);
            *blue = 0; // Set to 0 to avoid further issues
        }

        if (*clear > 0 && *red > 0 && *green > 0 && *blue > 0) {
            return 0; // Success
        }

        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }

    return -1; // Failure after multiple retries
}

// Function to log data to a CSV file
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed. Error code: %d\n", errno);
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device. Error code: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. Error code: %d\n", errno);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

