#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define MOTOR_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define constants
#define OVERCURRENT_THRESHOLD 10.0
#define SPI_RETRY_COUNT 3

// Global variables
FILE *log_file = NULL;
int spi_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_amperes(int adc_value);
void log_current(float current);
void handle_overcurrent(float current);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;
    int retries = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    while (retries < SPI_RETRY_COUNT) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
            fprintf(stderr, "SPI read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            delay(10); // Small delay before retrying
        } else {
            adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
            return adc_value;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries.\n", SPI_RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert ADC value to amperes
float adc_to_amperes(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // Adjust the scaling factor based on the MLX91211's datasheet
    float current = (float)adc_value * 0.1; // Example scaling factor
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle overcurrent event
void handle_overcurrent(float current) {
    printf("Overcurrent detected! Current: %.2f A\n", current);
    digitalWrite(MOTOR_PIN, LOW); // Disable motor
    delay(1000); // Wait for 1 second
    digitalWrite(MOTOR_PIN, HIGH); // Re-enable motor
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Setup function to initialize wiringPi and SPI
int setup() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return -1;
    }

    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
    }

    pinMode(MOTOR_PIN, OUTPUT);
    digitalWrite(MOTOR_PIN, HIGH); // Initially enable the motor

    log_file = fopen("current_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Return to end of file after checking size

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (spi_fd != -1) {
        // No direct close function in wiringPiSPI, but we can reset the SPI channel
        // wiringPiSPIClose(SPI_CHANNEL); // Not a valid function in wiringPi
        // Attempt to reset the SPI channel by setting the CE pin low
        pinMode(8, OUTPUT); // CE0 is GPIO8
        digitalWrite(8, LOW);
        delay(10); // Small delay to allow the chip to reset
        digitalWrite(8, HIGH); // Set CE0 high again
    }

    digitalWrite(MOTOR_PIN, HIGH); // Ensure motor is re-enabled on exit
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() == -1) {
        fprintf(stderr, "Setup failed. Exiting.\n");
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value != -1) {
            float current = adc_to_amperes(adc_value);
            log_current(current);

            if (current > OVERCURRENT_THRESHOLD) {
                handle_overcurrent(current);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        delay(1000); // Sample every 1 second
    }

    cleanup();
    printf("Current monitoring stopped.\n");
    return 0;
}

