#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define SAMPLE_INTERVAL 1 // seconds

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
SensorData read_sensor_data();
void process_sensor_data(SensorData data);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the GPIO pin for the LED
int init_gpio() {
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn the LED off
    return 0;
}

// Function to initialize the ADS1115 sensor
int init_sensor() {
    // Configure ADS1115 for single-ended AIN0, single-ended AIN1, +/-4.096V, continuous conversion
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC2; // Single-ended, AIN0, AIN1, +/-4.096V, Continuous conversion
    config[2] = 0x83; // 128 SPS, Disable comparator

    int result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the ADS1115 sensor
SensorData read_sensor_data() {
    SensorData data;
    char buffer[4];
    int result;

    // Read pressure data (AIN0)
    result = i2cWriteDevice(i2c_handle, ADS1115_REG_CONVERT, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 convert register (pressure): %d\n", result);
        data.pressure = -999.0; // Indicate error
    } else {
        result = i2cReadDevice(i2c_handle, buffer, 4);
        if (result != 4) {
            fprintf(stderr, "Error reading from ADS1115 (pressure): %d\n", result);
            data.pressure = -999.0; // Indicate error
        } else {
            // Convert raw data to pressure (kPa)
            int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
            data.pressure = (float)raw_pressure * 0.1; // Example conversion, adjust as needed
        }
    }

    // Read temperature data (AIN1)
    result = i2cWriteDevice(i2c_handle, ADS1115_REG_CONVERT, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 convert register (temperature): %d\n", result);
        data.temperature = -999.0; // Indicate error
    } else {
        result = i2cReadDevice(i2c_handle, buffer, 4);
        if (result != 4) {
            fprintf(stderr, "Error reading from ADS1115 (temperature): %d\n", result);
            data.temperature = -999.0; // Indicate error
        } else {
            // Convert raw data to temperature (°C)
            int16_t raw_temperature = (buffer[2] << 8) | buffer[3];
            data.temperature = (float)raw_temperature * 0.01; // Example conversion, adjust as needed
        }
    }

    return data;
}

// Function to process the sensor data (currently just prints the values)
void process_sensor_data(SensorData data) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", data.pressure, data.temperature);
}

// Function to control the LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    printf("Sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        SensorData data = read_sensor_data();

        if (data.pressure != -999.0 && data.temperature != -999.0) {
            process_sensor_data(data);
            control_led(data.pressure);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        time_sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

