#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define MOTOR_PIN 27 // GPIO27 (BCM)
#define SPI_CE0_PIN 8  // GPIO8 (CE0)
#define SPI_SCLK_PIN 11 // GPIO11 (SCLK)
#define SPI_MOSI_PIN 10 // GPIO10 (MOSI)
#define SPI_MISO_PIN 9  // GPIO9 (MISO)

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define overcurrent threshold
#define OVERCURRENT_THRESHOLD 10.0 // 10 A

// Define ADC channel
#define ADC_CHANNEL 0

// Define SPI retry attempts
#define SPI_RETRY_ATTEMPTS 3

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;
static int spiHandle = -1;

// Function prototypes
int spiTransfer(int channel);
float adcToCurrent(int adcValue);
void logCurrent(float current);
void handleOvercurrent(float current);
void signalHandler(int signum);
void cleanup();

// Function to perform SPI transfer with retries
int spiTransfer(int channel) {
    int retries = 0;
    int result = -1; // Initialize to an error value

    while (retries < SPI_RETRY_ATTEMPTS) {
        unsigned char buffer[3];
        buffer[0] = 0x01; // Start bit
        buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
        buffer[2] = 0x00;

        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            delay(10); // Small delay before retrying
        } else {
            result = buffer[1] & 0x03; // Extract ADC value (bits 3-12)
            return result;
        }
    }

    fprintf(stderr, "SPI transfer failed after %d attempts.\n", SPI_RETRY_ATTEMPTS);
    return -1; // Return error after all retries
}

// Function to convert ADC value to current
float adcToCurrent(int adcValue) {
    // Assuming a linear relationship between ADC value and current
    // Adjust the scaling factor based on the MLX91209 datasheet
    float current = (float)adcValue * 0.1; // Example scaling factor
    return current;
}

// Function to log current reading with timestamp
void logCurrent(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (logFile != NULL) {
        fprintf(logFile, "%s, %.2f\n", timestamp, current);
        fflush(logFile); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle overcurrent event
void handleOvercurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("OVERCURRENT EVENT: Current exceeds threshold (%.2f A > %.2f A)!\n", current, OVERCURRENT_THRESHOLD);
        digitalWrite(MOTOR_PIN, HIGH); // Assert HIGH to shut down motor
        logCurrent(current);
        cleanup();
        exit(1); // Exit program after shutdown
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    printf("Caught signal %d, exiting gracefully...\n", signum);
    keepRunning = 0;
}

// Cleanup function to reset GPIO and close resources
void cleanup() {
    if (spiHandle != -1) {
        // No explicit SPI close function in wiringPi, but we can reset the CE pin
        digitalWrite(SPI_CE0_PIN, LOW); // Reset CE pin
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    digitalWrite(MOTOR_PIN, LOW); // Reset motor pin to LOW
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spiHandle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spiHandle == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set motor pin as output
    pinMode(MOTOR_PIN, OUTPUT);
    digitalWrite(MOTOR_PIN, LOW); // Initialize motor pin to LOW

    // Open log file
    logFile = fopen("current_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        int adcValue = spiTransfer(ADC_CHANNEL);
        if (adcValue != -1) {
            float current = adcToCurrent(adcValue);
            logCurrent(current);
            handleOvercurrent(current);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        delay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

