#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ALARM_GPIO 4
#define VOLTAGE_REF 3.3
#define VOLTAGE_THRESHOLD 2.5
#define LOG_FILE "co_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_from_adc(int adc_value);
void log_data(float voltage);
void control_alarm(float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration (optional, but good practice)
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 1); // Initially HIGH

    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    spi_handle = spiOpen(spi_config.channel, spi_config.baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_from_adc(int adc_value) {
    return ((float)adc_value / 1023.0) * VOLTAGE_REF;
}

// Function to log data to file
void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the alarm based on voltage
void control_alarm(float voltage) {
    if (voltage > VOLTAGE_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    } else {
        gpioWrite(ALARM_GPIO, 1); // Turn on alarm
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("CO Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float voltage = voltage_from_adc(adc_value);
            log_data(voltage);
            control_alarm(voltage);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(1); // Sample every 1 second
    }

    cleanup();
    return 0;
}

