// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define EMAIL_SUBJECT "Humidity Alert"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int init_spi();
int read_mcp3208(int channel);
float convert_to_humidity(int adc_value);
float convert_to_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message for single-ended read
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to humidity (HIH-4602-A)
float convert_to_humidity(int adc_value) {
    float humidity = ((float)adc_value / 1023.0) * 100.0;
    return humidity;
}

// Convert ADC value to temperature (HIH-4602-A)
float convert_to_temperature(int adc_value) {
    float temperature = ((float)adc_value / 1023.0) * 100.0;
    return temperature;
}

// Log data to file
int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Send email alert using ssmtp
int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "ssmtp %s", EMAIL_RECIPIENT);
    FILE *email_pipe = popen(command, "w");
    if (email_pipe == NULL) {
        fprintf(stderr, "Error opening email pipe\n");
        return -1;
    }

    fprintf(email_pipe, "To: %s\n", EMAIL_RECIPIENT);
    fprintf(email_pipe, "Subject: %s\n\n", EMAIL_SUBJECT);
    fprintf(email_pipe, "Humidity threshold exceeded: %.2f%%\n", humidity);

    int status = pclose(email_pipe);
    if (status != 0) {
        fprintf(stderr, "Email command failed with status %d\n", status);
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3208(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to humidity and temperature
        float humidity = convert_to_humidity(adc_value);
        float temperature = convert_to_temperature(adc_value);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert if necessary
        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded: %.2f%%\n", humidity);
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Error sending email alert\n");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("Humidity monitoring stopped.\n");
    return 0;
}

