#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0
#define IMPACT_THRESHOLD 500
#define SAMPLE_RATE 100    // Hz
#define LOG_FILE "impact_log.txt"

// ADXL335 Sensitivity (mV/g) - Adjust based on your sensor
#define ADXL335_SENSITIVITY 0.003 // 3 mV/g

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold ADC values
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} adc_values_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int validate_adc_value(int16_t value);
int log_data(adc_values_t values);
int detect_impact(adc_values_t values, int threshold);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the SPI interface using pigpio
int initialize_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads the ADC value from the specified channel of the MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Validates the ADC value to ensure it's within the valid range
int validate_adc_value(int16_t value) {
    if (value < 0 || value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", value);
        return -1;
    }
    return 0;
}

// Logs the timestamped data to the specified file
int log_data(adc_values_t values) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, values.x, values.y, values.z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Detects if an impact has occurred based on the threshold
int detect_impact(adc_values_t values, int threshold) {
    if (abs(values.x) > threshold || abs(values.y) > threshold || abs(values.z) > threshold) {
        return 1; // Impact detected
    }
    return 0; // No impact
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Impact logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        adc_values_t values;

        // Read ADC values
        values.x = read_mcp3008(0);
        values.y = read_mcp3008(1);
        values.z = read_mcp3008(2);

        // Validate ADC values
        if (validate_adc_value(values.x) != 0 ||
            validate_adc_value(values.y) != 0 ||
            validate_adc_value(values.z) != 0) {
            fprintf(stderr, "Invalid ADC values, skipping logging\n");
            gpioDelay(1000000 / SAMPLE_RATE); // Delay to avoid flooding the log
            continue;
        }

        // Log data
        log_data(values);

        // Detect impact
        if (detect_impact(values, IMPACT_THRESHOLD)) {
            fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
            fflush(log_file);
            printf("IMPACT DETECTED!\n");
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sampling rate
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

