float adc_to_flow_rate(int adc_value) {
    // Assuming a linear relationship between ADC value and flow rate
    // Adjust the scaling factor based on the sensor's datasheet
    float flow_rate = (float)adc_value * (FLOW_RATE_MAX - FLOW_RATE_MIN) / 1023.0 + FLOW_RATE_MIN;
