#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x68
#define HIGH_PRECISION_CMD 0x362F
#define CSV_FILE "environmental_data.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration data
typedef struct {
    int16_t c0;
    int16_t c1;
    int16_t c00;
    int16_t c10;
    int16_t c01;
    int16_t c11;
    int16_t c20;
    int16_t c21;
    int16_t c30;
} calibration_data_t;

calibration_data_t calibration;

// Function prototypes
int init_i2c();
int read_calibration_data(calibration_data_t *cal);
int trigger_measurement();
int read_measurement(uint16_t *pressure, uint16_t *temperature);
double convert_temperature(uint16_t raw_temp);
double convert_pressure(uint16_t raw_pressure);
int log_data(double temperature, double pressure);
void display_data(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the sensor
int read_calibration_data(calibration_data_t *cal) {
    uint8_t buffer[16];
    int result = i2cReadI2CBlockData(i2c_handle, 0x10, (char *)buffer, 16);
    if (result != 16) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    cal->c0 = (int16_t)((buffer[0] << 8) | buffer[1]);
    cal->c1 = (int16_t)((buffer[2] << 8) | buffer[3]);
    cal->c00 = (int16_t)((buffer[4] << 8) | buffer[5]);
    cal->c10 = (int16_t)((buffer[6] << 8) | buffer[7]);
    cal->c01 = (int16_t)((buffer[8] << 8) | buffer[9]);
    cal->c11 = (int16_t)((buffer[10] << 8) | buffer[11]);
    cal->c20 = (int16_t)((buffer[12] << 8) | buffer[13]);
    cal->c21 = (int16_t)((buffer[14] << 8) | buffer[15]);

    return 0;
}

// Trigger high-precision measurement
int trigger_measurement() {
    uint8_t cmd[2] = {(HIGH_PRECISION_CMD >> 8) & 0xFF, HIGH_PRECISION_CMD & 0xFF};
    int result = i2cWriteI2CBlockData(i2c_handle, 0x00, (char *)cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for measurement to complete
    return 0;
}

// Read measurement data
int read_measurement(uint16_t *pressure, uint16_t *temperature) {
    uint8_t buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    *pressure = (uint16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (uint16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

// Convert raw temperature to degrees Celsius
double convert_temperature(uint16_t raw_temp) {
    double temp = (double)raw_temp;
    double c0 = (double)calibration.c0;
    double c1 = (double)calibration.c1;
    double c00 = (double)calibration.c00;
    double c10 = (double)calibration.c10;
    double c01 = (double)calibration.c01;
    double c11 = (double)calibration.c11;
    double c20 = (double)calibration.c20;
    double c21 = (double)calibration.c21;
    double c30 = (double)calibration.c30;

    double temp_celsius = c00 + c10 * temp + c01 * temp * temp;
    temp_celsius = c20 * temp_celsius * temp_celsius + c30 * temp_celsius * temp_celsius + c11 * temp_celsius + c21 * temp_celsius + c0 + c1 * temp;
    return temp_celsius;
}

// Convert raw pressure to pascals
double convert_pressure(uint16_t raw_pressure) {
    double pressure = (double)raw_pressure;
    double c0 = (double)calibration.c0;
    double c1 = (double)calibration.c1;
    double c00 = (double)calibration.c00;
    double c10 = (double)calibration.c10;
    double c01 = (double)calibration.c01;
    double c11 = (double)calibration.c11;
    double c20 = (double)calibration.c20;
    double c21 = (double)calibration.c21;
    double c30 = (double)calibration.c30;

    double pressure_pascals = c00 + c10 * pressure + c01 * pressure * pressure + c11 * pressure * pressure * pressure + c20 * pressure * pressure * pressure * pressure + c21 * pressure * pressure * pressure * pressure + c30 * pressure * pressure * pressure * pressure + c0 + c1 * pressure;
    return pressure_pascals;
}

// Log data to CSV file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Display data on console
void display_data(double temperature, double pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_pressure, raw_temperature;
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        gpioDelay(100); // Wait for measurement to complete

        if (read_measurement(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading measurement, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        double temperature = convert_temperature(raw_temperature);
        double pressure = convert_pressure(raw_pressure);

        log_data(temperature, pressure);
        display_data(temperature, pressure);

        gpioDelay(5000); // Sample every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

