#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define NUM_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
double ambient_temperature = 25.0; // Default temperature

// Function prototypes
int read_mcp3008(int channel);
double voltage_to_adc(int adc_value);
double compensate_temperature(double adc_value, double temperature);
int log_data(int raw_adc, double voltage, double compensated_voltage, double temperature, int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage (assuming 3.3V reference)
double voltage_to_adc(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to compensate temperature (linear compensation)
double compensate_temperature(double adc_value, double temperature) {
    // Linear compensation formula
    return adc_value * temperature;
}

// Function to log data to file
int log_data(int raw_adc, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 1); // Initially turn on the buzzer

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        int raw_adc = -1;
        int retries = 0;

        // Retry loop for ADC reading
        while (retries < NUM_RETRIES) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0) {
                break; // Success, exit retry loop
            } else {
                retries++;
                fprintf(stderr, "Error: ADC read failed, retrying (%d/%d)...\n", retries, NUM_RETRIES);
                gpioDelay(100); // Wait before retrying
            }
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC after %d retries. Skipping iteration.\n", NUM_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next iteration
            continue;
        }

        // Convert ADC value to voltage
        double voltage = voltage_to_adc(raw_adc);

        // Temperature compensation
        double compensated_voltage = compensate_temperature(raw_adc, ambient_temperature);

        // Flame detection (simple threshold)
        int flame_detected = (voltage > 0.5) ? 1 : 0; // Example threshold

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, ambient_temperature, flame_detected);

        // Buzzer control
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

