void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 1); // Initially turn on the buzzer

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        int raw_adc = -1;
        int retries = 0;

        // Retry loop for ADC reading
        while (retries < NUM_RETRIES) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0) {
                break; // Success, exit retry loop
            } else {
                retries++;
                fprintf(stderr, "Error: ADC read failed, retrying (%d/%d)...\n", retries, NUM_RETRIES);
                gpioDelay(100); // Wait before retrying
            }
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC after %d retries. Skipping iteration.\n", NUM_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next iteration
            continue;
        }

        // Convert ADC value to voltage
        double voltage = voltage_to_adc(raw_adc);

        // Temperature compensation
        double compensated_voltage = compensate_temperature(raw_adc, ambient_temperature);

        // Flame detection (simple threshold)
        int flame_detected = (voltage > 0.5) ? 1 : 0; // Example threshold

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, ambient_temperature, flame_detected);

        // Buzzer control
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

