#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define READ_INTERVAL_MS 5000 // 5 seconds
#define SLEEP_MS 100

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
void control_led(float water_level);
void log_data(float water_level);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int led_gpio;
    float threshold_high;
    float threshold_low;
    int read_interval_ms;
    int sleep_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    LED_GPIO,
    WATER_LEVEL_THRESHOLD_HIGH,
    WATER_LEVEL_THRESHOLD_LOW,
    READ_INTERVAL_MS,
    SLEEP_MS
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open JSON file
    json_file = fopen("water_levels.json", "a");
    if (json_file == NULL) {
        fprintf(stderr, "Failed to open water_levels.json. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping.\n");
            gpioDelay(config.sleep_ms * 1000); // Convert ms to us
            continue;
        }

        // Calculate water level
        float water_level = calculate_water_level(adc_value);

        // Control LED
        control_led(water_level);

        // Log data
        log_data(water_level);

        // Sleep
        gpioDelay(config.read_interval_ms * 1000 - config.sleep_ms); // Adjust sleep time
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, SPI_BAUD, 0); // Mode 0, no flags
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate water level percentage
float calculate_water_level(int adc_value) {
    // Assuming ADC value ranges from 0 (dry) to 1023 (full)
    // and water level ranges from 0% to 100%.
    // This is a linear relationship, but you might need to adjust
    // based on your sensor's characteristics.
    return ((float)adc_value / 1023.0) * 100.0;
}

// Control LED based on water level
void control_led(float water_level) {
    if (water_level > config.threshold_high) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else if (water_level < config.threshold_low) {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

// Log data to JSON file
void log_data(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(json_file, "[");
    fprintf(json_file, "%s: %.2f\n", timestamp, water_level);
    fflush(json_file); // Ensure data is written to file immediately
    fprintf(json_file, "]");
    fflush(json_file);
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (json_file != NULL) {
        fclose(json_file);
    }
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();
}

