#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "soil_moisture.log"
#define DEFAULT_SAMPLE_INTERVAL 1 // seconds

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;
static int spiHandle = -1;

// Function prototypes
int spi_init(int channel, int speed);
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void log_data(FILE *fp, int adc_value, float moisture_percentage);
void signal_handler(int signum);
void cleanup();

// SPI initialization function
int spi_init(int channel, int speed) {
    int handle = wiringPiSPISetup(channel, speed);
    if (handle < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC value ranges from 0 (dry) to 1023 (wet)
    // This is a linear approximation.  Calibration is recommended.
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture_percentage;
}

// Function to log data to file
void log_data(FILE *fp, int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s, %d, %.2f\n", timestamp, adc_value, moisture_percentage);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        keepRunning = 0;
    }
}

// Cleanup function to close SPI and log file
void cleanup() {
    if (spiHandle >= 0) {
        // No direct SPI close function in wiringPi, but we can reset the SPI interface
        // wiringPiSPIClose(SPI_CHANNEL); // This is not a valid function in wiringPi
        printf("SPI closed (not a valid function in wiringPi).\n");
