    int sampleInterval = DEFAULT_SAMPLE_INTERVAL;

    // Parse command-line argument for sample interval
    if (argc > 1) {
        sampleInterval = atoi(argv[1]);
        if (sampleInterval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default value (%d seconds).\n", DEFAULT_SAMPLE_INTERVAL);
            sampleInterval = DEFAULT_SAMPLE_INTERVAL;
        }
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spiHandle = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        return 1;
    }

    // Open log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

