// Define MCP3008 channel for the pressure sensor
#define PRESSURE_CHANNEL 0

// Define pressure range for calibration
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int flags;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t config);
int read_mcp3008(int channel);
float convert_to_pressure(int adc_value);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

