// Define GPIO pins for SPI communication
#define SPI_CE0 8  // GPIO8 (BCM)
#define SPI_SCLK 11 // GPIO11 (BCM)
#define SPI_MOSI 10 // GPIO10 (BCM)
#define SPI_MISO 9  // GPIO9 (BCM)

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read soil moisture sensor value
        int adc_value = read_mcp3008(0);

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data to console
            printf("%s - Soil Moisture: %d\n", timestamp, adc_value);
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

