#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MAX30102_ADDR 0x57

// Define register addresses
#define MAX30102_PART_ID 0x00
#define MAX30102_INTSTAT1 0x01
#define MAX30102_INTENABLE1 0x02
#define MAX30102_FIFOWR 0x04
#define MAX30102_FIFOCONFIG 0x05
#define MAX30102_SPO2CONFIG 0x06
#define MAX30102_HRCONFIG 0x07
#define MAX30102_LEDPA1 0x08
#define MAX30102_LEDPA2 0x09
#define MAX30102_SPO2DATA0 0x06
#define MAX30102_SPO2DATA1 0x07
#define MAX30102_HRDATA0 0x09
#define MAX30102_HRDATA1 0x0A

// Define constants
#define SPO2_THRESHOLD 95.0
#define HR_THRESHOLD 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float spo2;
    int heart_rate;
} sensor_data_t;

// Function prototypes
int init_max30102();
int read_max30102_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
int verify_sensor(int handle);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to verify the sensor presence
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, MAX30102_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }

    if (part_id != 0x15) {
        fprintf(stderr, "Error: Invalid Part ID: 0x%02X\n", part_id);
        return -1;
    }

    return 0;
}

// Function to initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MAX30102_INTENABLE1, 0x00) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure FIFO
    if (i2cWriteByteData(i2c_handle, MAX30102_FIFOCONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error configuring FIFO\n");
        return -1;
    }

    // Configure SpO2
    if (i2cWriteByteData(i2c_handle, MAX30102_SPO2CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error configuring SpO2\n");
        return -1;
    }

    // Configure Heart Rate
    if (i2cWriteByteData(i2c_handle, MAX30102_HRCONFIG, 0x1F) < 0) {
        fprintf(stderr, "Error configuring Heart Rate\n");
        return -1;
    }

    // Enable interrupt on FIFO almost full
    if (i2cWriteByteData(i2c_handle, MAX30102_INTENABLE1, 0x01) < 0) {
        fprintf(stderr, "Error enabling FIFO interrupt\n");
        return -1;
    }

    return 0;
}

// Function to read SpO2 and heart rate data from the MAX30102 sensor
int read_max30102_data(sensor_data_t *data) {
    uint8_t buffer[6];
    int result;

    // Read SpO2 data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, MAX30102_SPO2DATA0, (char *)buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the SpO2 value
    int spo2_raw = (buffer[1] << 8) | buffer[0];
    data->spo2 = (float)spo2_raw / 4096.0 * 100.0;

    // Read Heart Rate data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, MAX30102_HRDATA0, (char *)buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading Heart Rate data: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the Heart Rate value
    int hr_raw = (buffer[3] << 8) | buffer[2];
    data->heart_rate = hr_raw;

    return 0;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (data.spo2 < SPO2_THRESHOLD || data.heart_rate > HR_THRESHOLD) {
        fprintf(log_file, "%s - SpO2: %.2f%%, Heart Rate: %d BPM\n", timestamp, data.spo2, data.heart_rate);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (verify_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_max30102() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_max30102_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio uses milliseconds
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

