            fprintf(stderr, "SPI read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            delay(config.retry_delay_ms);
        } else {
            adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
            return adc_value;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Channel: %d\n", config.retry_count, channel);
    return -1; // Indicate failure
}

// Function to convert ADC value to millivolts
float voltage_to_millivolts(int adc_value) {
    return (adc_value * 3.3) / 1024.0 * 1000.0;
}

// Function to log data to CSV file
void log_data(FILE *fp, int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

