        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
    }

    fp = fopen(config.csv_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Channel,Voltage\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (fp != NULL) {
        fclose(fp);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (keepRunning) {
        for (int channel = 0; channel < config.num_channels; channel++) {
            int adc_value = spi_read_channel(channel);
            if (adc_value != -1) {
                float voltage = voltage_to_millivolts(adc_value);
                log_data(fp, channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        delay(500); // 500ms delay
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

