#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <pthread.h>
#include <stdbool.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define GPIO_RELAY 17
#define GPIO_SENSOR 27
#define THRESHOLD 500 // mm
#define SAMPLE_INTERVAL_MS 200
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_INTERVAL_MS 50
#define MESSAGE_QUEUE_NAME "/door_events_queue"
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static mqd_t mq = -1;
static volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int distance;
    bool door_open;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *device);
int ads1115_init(int fd);
int ads1115_read(int fd, int16_t *value);
int ads1115_configure(int fd, unsigned char config);
int gpio_init(int pin);
int gpio_write(int pin, int value);
int gpio_read(int pin);
int calibrate_sensor(int fd, int *baseline);
int read_reed_sensor(int pin);
void log_event(const char *message);
void *sensor_thread(void *arg);
void *message_queue_thread(void *arg);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// ADS1115 initialization function
int ads1115_init(int fd) {
    unsigned char config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // Start single conversion

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// ADS1115 read function
int ads1115_read(int fd, int16_t *value) {
    unsigned char data[2];
    unsigned char reg = 0x00; // Conversion register address

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

// ADS1115 configuration function
int ads1115_configure(int fd, unsigned char config) {
    unsigned char data[3];
    data[0] = 0x01; // Configuration register address
    data[1] = config;
    data[2] = 0x00; // Dummy byte

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (write(fd, data, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// GPIO initialization function
int gpio_init(int pin) {
    int fd = open("/sys/class/gpio/gpio" + (pin > 26 ? "27" : "17") + "/direction", O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    return fd;
}

// GPIO write function
int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) != 1) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO read function
int gpio_read(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }
    char value[2];
    if (read(fd, value, 1) != 1) {
        perror("Error reading from GPIO value file");
        close(fd);
        return -1;
    }
    close(fd);
    return (value[0] == '0') ? 0 : 1;
}

// Calibration function
int calibrate_sensor(int fd, int *baseline) {
    int sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int16_t value;
        if (ads1115_read(fd, &value) != 0) {
            fprintf(stderr, "Error reading sensor during calibration\n");
            return -1;
        }
        sum += value;
        usleep(CALIBRATION_INTERVAL_MS * 1000); // Convert ms to us
    }
    *baseline = sum / CALIBRATION_SAMPLES;
    return 0;
}

// Reed sensor read function
int read_reed_sensor(int pin) {
    return gpio_read(pin);
}

// Logging function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fclose(fp);
}

// Sensor thread function
void *sensor_thread(void *arg) {
    int baseline;
    if (calibrate_sensor(i2c_fd, &baseline) != 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        pthread_exit(NULL);
    }

    while (!terminate) {
        int16_t value;
        if (ads1115_read(i2c_fd, &value) != 0) {
            fprintf(stderr, "Error reading sensor value\n");
            sleep(1); // Avoid spamming errors
            continue;
        }

        int distance = abs(value - baseline); // Calculate distance from baseline
        if (distance > 4095) distance = 4095; //Clamp to max value

        if (distance < THRESHOLD) {
            log_event("Door opened");
            gpio_write(GPIO_RELAY, 1); // Energize relay
            usleep(3000); // 3 seconds
            gpio_write(GPIO_RELAY, 0); // De-energize relay
            if (read_reed_sensor(GPIO_SENSOR) == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }
    pthread_exit(NULL);
}

// Message queue thread function
void *message_queue_thread(void *arg) {
    sensor_data_t data;
    while (!terminate) {
        if (mq_receive(mq, (char *)&data, sizeof(data), NULL) == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                perror("Error receiving message");
                break;
            }
        }
        // In a real distributed system, this data would be sent to a central server.
        // For this example, we just log the received data.
        log_event("Received sensor data: distance=" + (data.distance > 4095 ? "4095" : "distance") + ", door_open=" + (data.door_open ? "true" : "false"));
    }
    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (mq != -1) {
        mq_close(mq);
        mq_unlink(MESSAGE_QUEUE_NAME);
    }
    gpio_write(GPIO_RELAY, 0); // De-energize relay
    pthread_exit(NULL);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init(i2c_fd) != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_RELAY) < 0) {
        cleanup();
        return 1;
    }
    if (gpio_init(GPIO_SENSOR) < 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO as output
    gpio_write(GPIO_RELAY, 0); // Initially de-energized
    gpio_set_mode(GPIO_SENSOR, PI_INPUT); // Set reed sensor as input with pull-up

    // Configure message queue attributes
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10; // Maximum number of messages in the queue
    attr.mq_msgsize = sizeof(sensor_data_t);
    attr.mq_curmsgs = 0;

    // Create message queue
    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_RDWR | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("Error creating message queue");
        cleanup();
        return 1;
    }

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        perror("Error creating sensor thread");
        cleanup();
        return 1;
    }

    // Create message queue thread
    pthread_t message_queue_thread_id;
