#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define GPIO pins for chip select
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_close(void);
int read_mcp3008(int chip_select_pin, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int set_gpio_output(int pin);
int set_gpio_input(int pin);
int set_gpio_direction(int pin, const char *direction);

// Function to set GPIO pin as output
int set_gpio_output(int pin) {
    int fd;
    char buf[64];

    fd = open("/sys/class/gpio/gpio" + (pin + 10) + "/direction", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "output");
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to set GPIO direction to output");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set GPIO pin as input
int set_gpio_input(int pin) {
    int fd;
    char buf[64];

    fd = open("/sys/class/gpio/gpio" + (pin + 10) + "/direction", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "in");
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to set GPIO direction to input");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set GPIO direction
int set_gpio_direction(int pin, const char *direction) {
    int fd;
    char buf[64];

    fd = open("/sys/class/gpio/gpio" + (pin + 10) + "/direction", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }
    snprintf(buf, sizeof(buf), direction);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to set GPIO direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to initialize SPI
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret == -1) {
        perror("Failed to set max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to close SPI
int spi_close(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int chip_select_pin, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_MAX_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    // Select the chip
    if (set_gpio_direction(chip_select_pin, "out") < 0) {
        fprintf(stderr, "Failed to set chip select pin direction.\n");
        return -1;
    }
    if (write(chip_select_pin, "0", 1) < 0) {
        perror("Failed to write to chip select pin");
        return -1;
    }

    // Transfer SPI data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    // Deselect the chip
    if (write(chip_select_pin, "1", 1) < 0) {
        perror("Failed to write to chip select pin");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main(void) {
    int sensor1_value, sensor2_value, sensor3_value;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (set_gpio_direction(CS0_PIN, "out") < 0 ||
        set_gpio_direction(CS1_PIN, "out") < 0 ||
        set_gpio_direction(CS2_PIN, "out") < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins.\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        spi_close();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1_value = read_mcp3008(CS0_PIN, 0);
        sensor2_value = read_mcp3008(CS1_PIN, 0);
        sensor3_value = read_mcp3008(CS2_PIN, 0);

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close SPI
    spi_close();

    return 0;
}

