float calculate_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
