#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read from PCF8591 AIN0 channel
int read_pcf8591(int i2c_handle) {
    int value = i2cReadByteData(i2c_handle, 0x40); // Read from AIN0
    if (value < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, PCF8591_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Dummy read to clear the buffer
        i2cReadByteData(i2c_handle, 0x40);

        // Read the current value from AIN0
        int value = read_pcf8591(i2c_handle);

        // Print the value to stdout
        if (value >= 0) {
            printf("AIN0: %d\n", value);
        } else {
            fprintf(stderr, "Failed to read AIN0 value.\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

