#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_PIN 27
#define SAMPLE_RATE 1 // Hz
#define BUFFER_SIZE 100
#define THRESHOLD 500.0 // Gauss
#define VREF 3.3 // Volts
#define ADC_RESOLUTION 12 // Bits
#define ADC_REF_VOLTAGE 4.096 // Volts

// Global variables
int i2c_handle;
double rolling_average[BUFFER_SIZE];
int buffer_index = 0;
bool shutdown_flag = false;

// Function prototypes
int init_i2c();
int init_gpio();
int init_adc();
int16_t read_adc();
double voltage_to_magnetic_field(int16_t adc_value);
void update_rolling_average(double magnetic_field);
bool check_threshold(double magnetic_field);
void shutdown_motor();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize to LOW
    return 0;
}

// Function to initialize ADC
int init_adc() {
    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion mode
    // 0x01: Configuration register address
    // 0x4003: Single-ended AIN0, 4.096V, Continuous conversion, Disable comparator
    uint16_t config = 0x4003; //0x4003; //0x4003
    if (i2cWriteWordData(i2c_handle, 0x01, config) < 0) {
        syslog(LOG_ERR, "Failed to write to ADS1115 configuration register");
        return -1;
    }
    return 0;
}

// Function to read ADC value
int16_t read_adc() {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADC data");
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to convert ADC value to magnetic field strength
double voltage_to_magnetic_field(int16_t adc_value) {
    double voltage = (double)adc_value / 32768.0 * ADC_REF_VOLTAGE; // Assuming 16-bit ADC
    double magnetic_field = (voltage - 0.0) / 0.1; // Example conversion, adjust as needed
    return magnetic_field;
}

// Function to update rolling average
void update_rolling_average(double magnetic_field) {
    rolling_average[buffer_index] = magnetic_field;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check threshold
bool check_threshold(double magnetic_field) {
    return magnetic_field > THRESHOLD;
}

// Function to shutdown motor
void shutdown_motor() {
    gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    syslog(LOG_INFO, "Motor shutdown triggered!");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    shutdown_flag = true;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize ADC
    if (init_adc() != 0) {
        cleanup();
        return 1;
    }

    // Initialize rolling average buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        rolling_average[i] = 0.0;
    }

    syslog(LOG_INFO, "Sensor monitoring started");

    // Main loop
    while (!shutdown_flag) {
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            // Error already logged in read_adc function
            gpioDelay(1000000 / SAMPLE_RATE); // Wait for the next sample
            continue;
        }

        double magnetic_field = voltage_to_magnetic_field(adc_value);
        update_rolling_average(magnetic_field);

        if (check_threshold(magnetic_field)) {
            shutdown_motor();
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

