#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
int pump_state = 0; // 0: off, 1: on
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
int validate_sensor_reading(int reading);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to validate sensor reading
int validate_sensor_reading(int reading) {
    if (reading < 0 || reading > 1023) {
        fprintf(stderr, "Error: Invalid sensor reading %d\n", reading);
        return -1;
    }
    return 0;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", RELAY_GPIO);
    }
    pump_state = state;
}

// Function to log watering event
void log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    control_pump(0); // Turn off the pump
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off at startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            // Attempt to recover (e.g., wait and retry)
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate sensor reading
        if (validate_sensor_reading(moisture_level) < 0) {
            fprintf(stderr, "Error: Invalid moisture level, skipping watering\n");
            sleep(60); // Wait before next reading
            continue;
        }

        printf("Moisture level: %d\n", moisture_level);

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold, activating pump\n");
            control_pump(1); // Turn on the pump
            log_event(moisture_level);
            sleep(WATERING_DURATION); // Water for specified duration
            control_pump(0); // Turn off the pump
            printf("Pump deactivated\n");
        }

        sleep(60); // Wait 60 seconds before next reading
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

