#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_LED 17
#define THRESHOLD_GAUSS 100.0
#define BLINK_DURATION_MS 500
#define SAMPLE_INTERVAL_MS 100

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int16_t read_adc();
float convert_to_gauss(int16_t adc_value);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int threshold_gauss;
    int led_gpio;
} Config;

Config config = {THRESHOLD_GAUSS, GPIO_LED};

int main(int argc, char *argv[]) {
    int opt;
    int threshold_gauss = config.threshold_gauss;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold_gauss = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return 1;
        }
    }

    // Set the threshold
    config.threshold_gauss = threshold_gauss;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();

        // Convert to Gauss
        float gauss = convert_to_gauss(adc_value);

        // Print the result
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        // Check threshold and control LED
        if (gauss > config.threshold_gauss) {
            control_led(1); // Turn LED on
            gpioDelay(BLINK_DURATION_MS);
            control_led(0); // Turn LED off
            gpioDelay(BLINK_DURATION_MS);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, continuous conversion
    uint16_t config_value = 0x4003; // Single-ended, AIN0, +/-4.096V, Continuous conversion
    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config_value) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    int16_t adc_value = i2cReadWordData(i2c_handle, ADS1115_REG_CONVERT);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return 0; // Return 0 on error
    }
    return adc_value;
}

// Convert ADC value to Gauss
float convert_to_gauss(int16_t adc_value) {
    // Assuming a sensitivity of 0.1 Gauss/LSB for +/-4.096V range
    float gauss = (float)adc_value * 0.1;
    return gauss;
}

// Control LED
void control_led(int state) {
    gpioWrite(config.led_gpio, state);
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

