// Configuration
#define SPI_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "agriculture/soil_moisture"
#define MQTT_PUMP_CONTROL_TOPIC "agriculture/pump_control"
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_KEEPALIVE 60

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int pump_state);
void publish_moisture(float moisture);
void subscribe_to_pump_control();
void signal_handler(int signal);
