#define CSV_FILE "sensor_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float channel0;
    float channel1;
    float channel2;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int write_to_csv(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Write data to CSV file
int write_to_csv(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fp == NULL) {
        fprintf(stderr, "File pointer is NULL\n");
        return -1;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.channel0, data.channel1, data.channel2);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(fp);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        int adc_value0 = read_mcp3008(0);
        int adc_value1 = read_mcp3008(1);
        int adc_value2 = read_mcp3008(2);

        if (adc_value0 == -1 || adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Convert to voltages
        sensor_data.channel0 = convert_to_voltage(adc_value0);
        sensor_data.channel1 = convert_to_voltage(adc_value1);
        sensor_data.channel2 = convert_to_voltage(adc_value2);

        // Write to CSV file
        if (write_to_csv(sensor_data) != 0) {
            fprintf(stderr, "Error writing to CSV file\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

