    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping iteration.\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        int noise_level = calculate_noise_level(adc_value);

        control_motors(noise_level);

        gpioDelay(10000); // 10ms delay
    }

    return 0;
}

