#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define SOUND_THRESHOLD 50
#define LOG_FILE "tamper_log.csv"

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_sound_level();
int read_light_level();
void log_data(int sound_level, int light_level, int error_code);
void signal_handler(int signal);
int init_i2c();
int init_spi();

// Function to read sound level from MCP3008
int read_sound_level() {
    unsigned char buffer[3];
    int adc_value = -1;
    int result;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | 0) << 4; // Single-ended channel 0
    buffer[2] = 0x00;

    result = wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    if (result == -1) {
        fprintf(stderr, "SPI read failed!\n");
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    // Convert ADC value to dB (example conversion, adjust as needed)
    float voltage = (float)adc_value * 3.3 / 1024.0; // Assuming 3.3V reference
    float db = 20 * log10(voltage / 0.1); // Example dB calculation

    return (int)db;
}

// Function to read light level from BH1750
int read_light_level() {
    unsigned char buffer[2];
    int lux = -1;
    int result;

    if (i2c_fd == -1) {
        fprintf(stderr, "I2C not initialized!\n");
        return -1; // Indicate error
    }

    // Send power on and start measurement command (High Resolution Mode)
    if (i2cWriteByteData(i2c_fd, 0x00, 0x10) < 0) {
        fprintf(stderr, "I2C write failed!\n");
        return -1; // Indicate error
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180);

    // Read two bytes of data
    result = i2cReadI2CBlockData(i2c_fd, 0x00, (char *)buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed!\n");
        return -1; // Indicate error
    }

    // Convert data to lux (example conversion, adjust as needed)
    lux = (buffer[0] << 8) | buffer[1];
    lux = lux / 1.2; // BH1750 datasheet

    return lux;
}

// Function to log data to CSV file
void log_data(int sound_level, int light_level, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to initialize SPI!\n");
        return -1;
    }
    return 0;
}

int main() {
    int sound_level, light_level, error_code;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    init_result = init_spi();
    if (init_result != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    init_result = init_i2c();
    if (init_result != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sound_level = read_sound_level();
        light_level = read_light_level();
        error_code = -1; // Initialize error code

        if (sound_level == -1) {
            error_code = 1; // SPI read error
        } else if (light_level == -1) {
            error_code = 2; // I2C read error
        }

        log_data(sound_level, light_level, error_code);

        if (sound_level > SOUND_THRESHOLD) {
            printf("Tamper detected! Sound level: %d dB, Light level: %d lux\n", sound_level, light_level);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();

    return 0;
}

