// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to initialize SPI!\n");
        return -1;
    }
    return 0;
}

int main() {
    int sound_level, light_level, error_code;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    init_result = init_spi();
    if (init_result != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    init_result = init_i2c();
    if (init_result != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sound_level = read_sound_level();
        light_level = read_light_level();
        error_code = -1; // Initialize error code

        if (sound_level == -1) {
            error_code = 1; // SPI read error
        } else if (light_level == -1) {
            error_code = 2; // I2C read error
        }

        log_data(sound_level, light_level, error_code);

        if (sound_level > SOUND_THRESHOLD) {
            printf("Tamper detected! Sound level: %d dB, Light level: %d lux\n", sound_level, light_level);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();

    return 0;
}

