    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_INTERVAL);
            sleep(READ_INTERVAL);
            continue;
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);

        // Log data
        log_data(adc_value, moisture);

        // Control pump based on moisture threshold
        if (moisture < MOISTURE_THRESHOLD) {
            control_pump(1); // Turn pump ON
            printf("Moisture below threshold, turning pump ON\n");
        } else {
            control_pump(0); // Turn pump OFF
            printf("Moisture above threshold, turning pump OFF\n");
        }

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil Moisture Monitoring System stopped.\n");

    return 0;
}

