            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] == -1) {
                fprintf(stderr, "Error: Failed to read ADC value %d\n", i);
                // Consider adding a retry mechanism here
                continue; // Skip to the next iteration
            }
        }

