#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 500
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_RETRIES 5
#define BACKOFF_MULTIPLIER 2
#define SPI_HANDLE -1

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(int adc_value, float moisture_percentage);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int moisture_threshold;
    int sample_interval;
    int max_retries;
    int backoff_multiplier;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MOISTURE_THRESHOLD,
    SAMPLE_INTERVAL,
    MAX_RETRIES,
    BACKOFF_MULTIPLIER
};

// Function to initialize SPI
int initialize_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI_MODE0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        gpioTerminate();
        return -1;
    }
    return handle;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result = -1; // Initialize to error value

    while (retries < config.max_retries) {
        result = spiXfer(SPI_HANDLE, spi_tx_buf, spi_rx_buf, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait before retrying
            retries++;
            if (retries < config.max_retries) {
                // Exponential backoff
                gpioDelay(1000 * (1 << retries)); // 1, 2, 4, 8 seconds
            }
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", config.max_retries);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %.2f\n", timestamp, adc_value, moisture_percentage);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (SPI_HANDLE >= 0) {
        spiClose(SPI_HANDLE);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    SPI_HANDLE = initialize_spi();
    if (SPI_HANDLE < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage >= 0.0) {
                log_data(adc_value, moisture_percentage);
                printf("ADC Value: %d, Moisture: %.2f%%\n", adc_value, moisture_percentage);
            } else {
                fprintf(stderr, "Error calculating moisture percentage.\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }

        gpioDelay(config.sample_interval * 1000); // Delay for sample interval
    }

    cleanup();
    return 0;
}

