#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_FREQUENCY 440.0 // A4 note
#define PWM_RANGE 1000

// Define LDR calibration parameters
#define LDR_CALIBRATION_FILE "ldr_calibration.txt"

// Define error value for distance and volume
#define ERROR_DISTANCE -1.0
#define ERROR_VOLUME -1.0

// Global variables
double last_valid_distance = 0.0;
double last_valid_volume = 0.0;
int spi_handle;
FILE *log_file;

// Function prototypes
double read_distance();
double read_volume();
double map_distance_to_frequency(double distance);
double map_volume_to_amplitude(double volume);
void generate_tone(double frequency, double amplitude);
void signal_handler(int signal);
int load_calibration();

// Function to read distance from HC-SR04 sensor
double read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    int start_tick = gpioTick();
    int end_tick = start_tick;

    // Wait for echo to go high (with timeout)
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(log_file, "%ld: HC-SR04 timeout on ECHO pin\n", time(NULL));
        fflush(log_file);
        return ERROR_DISTANCE;
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(log_file, "%ld: HC-SR04 timeout on ECHO pin (high)\n", time(NULL));
        fflush(log_file);
        return ERROR_DISTANCE;
    }

    end_tick = gpioTick();

    double pulse_duration = (double)(end_tick - start_tick) / 1000000.0; // in seconds

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    double distance = (pulse_duration * 34300.0) / 2.0; // cm

    return distance;
}

// Function to read volume from MCP3008 ADC
double read_volume() {
    unsigned char spi_data[3];
    int adc_value;

    // MCP3008 configuration: single-ended channel 0
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = 0x80; // Single-ended, channel 0
    spi_data[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_data, spi_data, 3) != 0) {
        fprintf(log_file, "%ld: SPI transfer failed\n", time(NULL));
        fflush(log_file);
        return ERROR_VOLUME;
    }

    // Extract ADC value from the response
    adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];

    // Convert ADC value to voltage (assuming 3.3V reference)
    double voltage = (double)adc_value * (3.3 / 1024.0);

    return voltage;
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    // Linear mapping: 20cm - 80cm = 200Hz - 2000Hz
    double frequency = 200.0 + (distance - 20.0) * (2000.0 - 200.0) / 60.0;
    return frequency;
}

// Function to map volume to amplitude
double map_volume_to_amplitude(double volume) {
    // Linear mapping: 0.0 - 1.0 = 0.1 - 1.0
    double amplitude = 0.1 + (volume - 0.0) * (1.0 - 0.1) / 1.0;
    return amplitude;
}

