void generate_tone(double frequency, double amplitude) {
    int pwm_range = 1000; // Define PWM range
    int duty_cycle = (int)(amplitude * pwm_range); // Calculate duty cycle

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, pwm_range);

    // Set PWM duty cycle
    gpioPWM(PWM_PIN, duty_cycle);
}

