    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to load LDR calibration parameters from file
int load_calibration() {
    FILE *cal_file = fopen(LDR_CALIBRATION_FILE, "r");
    if (cal_file == NULL) {
        fprintf(log_file, "%ld: Error opening calibration file, using default values\n", time(NULL));
        fflush(log_file);
        return 0; // Use default values
    }

    double min_voltage, max_voltage;
    if (fscanf(cal_file, "%lf %lf", &min_voltage, &max_voltage) != 2) {
        fprintf(log_file, "%ld: Error reading calibration file, using default values\n", time(NULL));
        fflush(log_file);
        fclose(cal_file);
        return 0; // Use default values
    }

    fclose(cal_file);

    printf("Calibration file loaded: min_voltage=%.2f, max_voltage=%.2f\n", min_voltage, max_voltage);
    return 1; // Calibration loaded
}

int main() {
