        printf("Using default LDR calibration values.\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance and volume
        double distance = read_distance();
        double volume = read_volume();

        // Update last valid values
        if (distance != ERROR_DISTANCE) {
            last_valid_distance = distance;
        }
        if (volume != ERROR_VOLUME) {
            last_valid_volume = volume;
        }

        // Map distance to frequency and volume to amplitude
        double frequency = map_distance_to_frequency(distance);
        double amplitude = map_volume_to_amplitude(volume);

        // Generate tone
        generate_tone(frequency, amplitude);

        // Delay
        gpioDelay(100); // 100ms
    }

    return 0;
