    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retry = 0;

        // Retry reading ADC value
        while (adc_value == -1 && retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value == -1) {
                fprintf(stderr, "Failed to read ADC value, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            }
        }

        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value after %d retries. Re-initializing SPI.\n", RETRY_COUNT);
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Calculate AQI
        float aqi = calculate_aqi(adc_value);

        // Control fan
        control_fan((int)aqi);

        // Log data
        log_data(aqi);

        printf("ADC Value: %d, AQI: %.2f\n", adc_value, aqi);

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

