#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for motor control
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// Define GPIO pins for potentiometer reading
#define MCP3008_CS 8

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define motor parameters
#define MOTOR1_GEAR_RATIO 1.0
#define MOTOR2_GEAR_RATIO 1.0

// Define speed mapping parameters
#define MIN_SPEED 0.0
#define MAX_SPEED 255.0
#define MIN_POT_VALUE 0
#define MAX_POT_VALUE 1023

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_pot_to_speed(int pot_value);
void set_motor_speed(int motor_num, float speed);
void set_motor_direction(int motor_num, int direction);
void accelerate(int motor_num, float speed);
void decelerate(int motor_num, float speed);
void pause(float duration);
void reverse_directions();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map potentiometer value to speed
float map_pot_to_speed(int pot_value) {
    float speed = MIN_SPEED + (float)(pot_value - MIN_POT_VALUE) * (MAX_SPEED - MIN_SPEED) / (MAX_POT_VALUE - MIN_POT_VALUE);
    return speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_num, float speed) {
    if (speed < 0.0) speed = 0.0;
    if (speed > 255.0) speed = 255.0;

    int pwm_value = (int)speed;
    gpioPWM(motor_num, pwm_value);
}

// Function to set motor direction
