int compare_sound_level_to_baseline(float sound_level, float baseline);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calibrate noise level
float calibrate_noise_level() {
    float sum = 0.0;
    int num_samples = 0;

    printf("Calibrating noise level for 5 seconds...\n");
    for (int i = 0; i < 500; i++) { // 5 seconds * 10 samples/second = 50,000 samples
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value during calibration\n");
            return 0.0; // Return 0 if there's an error
        }
        sum += adc_value;
        num_samples++;
        gpioDelay(10000); // 10ms delay
    }

    float baseline = sum / num_samples;
    printf("Calibration complete. Baseline noise level: %.2f\n", baseline);
    return baseline;
}

// Compare sound level to baseline
int compare_sound_level_to_baseline(float sound_level, float baseline) {
    return (sound_level > baseline) ? 1 : 0;
}

