    if (initialize_spi()) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);

    // Calibrate noise level
    float baseline = calibrate_noise_level();

    // Main loop
    int led_state = 0; // 0 = off, 1 = on
    int last_led_state = 0; // Store the last LED state for debouncing
    int last_sound_level = 0; // Store the last sound level for debouncing

    printf("Monitoring sound levels...\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        float sound_level = (float)adc_value / 1023.0 * 100.0; // Scale to 0-100

        // Debouncing logic
        if (sound_level > baseline && last_led_state == 0 && last_sound_level < baseline) {
            led_state = 1;
        } else if (sound_level < baseline && last_led_state == 1 && last_sound_level > baseline) {
            led_state = 0;
        }

        if (led_state != last_led_state) {
            control_led(led_state);
            last_led_state = led_state;
            last_sound_level = sound_level;
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

