// Structure for calibration data
typedef struct {
    float slope;
    float intercept;
} CalibrationData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_airflow(float voltage);
int log_data(float airflow);
