#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>

// Define GPIO pins for SPI chip select
#define GPIO_CS 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_read(int fd, uint8_t *data, int len);
int read_adc(int spi_fd, int channel);
uint32_t get_monotonic_raw_time();
int log_data(uint32_t timestamp_ns, int raw_adc_value);
void signal_handler(int sig);

// GPIO export function
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }

    if (write(fd, value ? "1" : "0", 1) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("spi/open");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("spi/spi_mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        perror("spi/bits_per_word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("spi/max_speed_hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read function
int spi_read(int fd, uint8_t *data, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0, // Read only, no transmit data
        .rx_buf = (unsigned long)data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = 0, // Let SPI driver set the speed
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("spi/read");
        return -1;
    }

    return 0;
}

// Read ADC function
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_read(spi_fd, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading SPI data\n");
        return -1;
    }

    // Extract ADC value from response
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Get monotonic raw time function
uint32_t get_monotonic_raw_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (uint32_t)(tv.tv_sec) * 1000000000UL + (uint32_t)(tv.tv_usec);
}

// Log data function
int log_data(uint32_t timestamp_ns, int raw_adc_value) {
    char buffer[256];
    int len;

    len = snprintf(buffer, sizeof(buffer), "%u|%d\n", timestamp_ns, raw_adc_value);
    if (len < 0 || len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting log data\n");
        return -1;
    }

    if (fputs(buffer, log_file) == EOF) {
        perror("fputs");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint8_t spi_data[3];
    int adc_value;
    uint32_t timestamp_ns;
    struct timespec sleep_time;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_CS) < 0 ||
        gpio_export(GPIO_MOSI) < 0 ||
        gpio_export(GPIO_MISO) < 0 ||
        gpio_export(GPIO_SCLK) < 0) {
        fprintf(stderr, "Failed to export GPIO pins\n");
        goto cleanup;
    }

    // Set GPIO directions
    if (gpio_set_direction(GPIO_CS, "out") < 0 ||
        gpio_set_direction(GPIO_MOSI, "out") < 0 ||
        gpio_set_direction(GPIO_MISO, "in") < 0 ||
        gpio_set_direction(GPIO_SCLK, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO directions\n");
        goto cleanup;
    }

    // Set GPIO CS low initially
    gpio_set_value(GPIO_CS, 0);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000; // 1 ms
    while (!terminate) {
        // Read ADC value
        adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            goto cleanup;
        }

        // Get timestamp
        timestamp_ns = get_monotonic_raw_time();

        // Log data
        if (log_data(timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Failed to log data\n");
            goto cleanup;
        }

        // Sleep for 1 ms
        ret = nanosleep(&sleep_time, NULL);
        if (ret != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                perror("nanosleep");
                fprintf(stderr, "nanosleep error\n");
                goto cleanup;
            }
        }
    }

cleanup:
    // Cleanup resources
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_set_value(GPIO_CS, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO CS low\n");
    }
    gpio_unexport(GPIO_CS);
    gpio_unexport(GPIO_MOSI);
    gpio_unexport(GPIO_MISO);
    gpio_unexport(GPIO_SCLK);

    return 0;
}

