#define VREF 3.3
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float vref;
    char *log_file;
} config_t;

// Function prototypes
int init_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
void log_data(float voltage, float ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

