        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Propane leak detector started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        // Retry reading ADC value
        while (adc_value == -1 && retries < 3) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value == -1) {
                fprintf(stderr, "Retrying ADC read (%d/%d)...\n", retries + 1, 3);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        float voltage = adc_to_voltage(adc_value, VREF);
        float ppm = 0.0; // Placeholder PPM value

        log_data(voltage, ppm);

        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);

        gpioDelay(1000000); // 1 second delay
    }

    cleanup();
    return 0;
}

