#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // No special flags

// Define GPIO pins for SPI
#define MOSI 10
#define MISO 9
#define SCLK 11
#define CS 8

// Define ADXL335 sensitivity (adjust based on your setup)
#define ADXL335_SENSITIVITY 0.003 // 3 mV/g

// Define Kalman filter parameters
#define PROCESS_NOISE 0.001 // 1e-3
#define MEASUREMENT_NOISE 0.01 // 0.01

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    double q;
    double r;
    double P;
    double K;
} KalmanFilterState;

KalmanFilterState kalman_state = {PROCESS_NOISE, MEASUREMENT_NOISE, 1.0, 0.0};

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double convert_to_g(int adc_value);
void kalman_filter(double measurement, double *filtered_value);
void print_acceleration(double x, double y, double z);
void signal_handler(int signal);

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel (%d)\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: spiXfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to g
double convert_to_g(int adc_value) {
    return (double)adc_value * ADXL335_SENSITIVITY;
}

// Function to apply Kalman filter
void kalman_filter(double measurement, double *filtered_value) {
    // Prediction step
    kalman_state.P += kalman_state.q;
    kalman_state.P /= 2.0; // Divide by 2 for simplicity

    // Update step
    kalman_state.K = kalman_state.P / (kalman_state.P + kalman_state.r);
    *filtered_value = kalman_state.K * (measurement - kalman_state.P);
    kalman_state.P = (1 - kalman_state.K) * kalman_state.P;
}

// Function to print acceleration values
void print_acceleration(double x, double y, double z) {
    printf("X: %.4f g, Y: %.4f g, Z: %.4f g\n", x, y, z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS, PI_OUTPUT);
    gpioWrite(CS, 1); // Deactivate CS initially

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to g
        double x_g = convert_to_g(x_adc);
        double y_g = convert_to_g(y_adc);
        double z_g = convert_to_g(z_adc);

        // Apply Kalman filter
        double filtered_x, filtered_y, filtered_z;
        kalman_filter(x_g, &filtered_x);
        kalman_filter(y_g, &filtered_y);
        kalman_filter(z_g, &filtered_z);

        // Print acceleration values
        print_acceleration(filtered_x, filtered_y, filtered_z);

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100);
    }

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

