#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the ADC conversion factor (mV/mT)
#define ADC_CONVERSION_FACTOR 0.001

// Define the ADC resolution (mV)
#define ADC_RESOLUTION 0.1

// Define the magnetic field range (mT)
#define MAGNETIC_FIELD_RANGE -100.0
#define MAGNETIC_FIELD_RANGE_MAX 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital state of a GPIO pin
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to convert the digital state to a magnetic field strength value
float convert_to_magnetic_field(int sensor_value) {
    if (sensor_value == 1) {
        return 3.3 / ADC_CONVERSION_FACTOR;
    } else if (sensor_value == 0) {
        return 0.0;
    } else {
        fprintf(stderr, "Invalid sensor value: %d\n", sensor_value);
        return -1.0; // Indicate an error
    }
}

// Function to log the magnetic field strength values to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to check if the magnetic field strength is within the valid range
