#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int moisture_level);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        log_event("Error: SPI transfer failed.");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023 and moisture range is 0-100%
    // This is a linear approximation.  A more accurate calibration
    // would involve a lookup table or a more complex formula.
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump relay
void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        log_event("Pump ON");
    } else if (moisture_level > MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        log_event("Pump OFF");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value, continuing...");
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        // Calculate moisture level
        float moisture_level = calculate_moisture(adc_value);

        // Control pump
        control_pump((int)moisture_level);

        // Log moisture level
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%%", moisture_level);
        log_event(log_message);

        // Wait 60 seconds
        gpioDelay(60000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

