#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz
#define CSV_FILE "sensor_data.csv"

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_read_channel(int fd, int channel);
int read_mcp3008(int fd, int channel);
int log_data(FILE *fp, int channel0, int channel1, int channel2);
void signal_handler(int signal);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read channel function
int spi_read_channel(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_MAX_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Read MCP3008 channel function
int read_mcp3008(int fd, int channel) {
    return spi_read_channel(fd, channel);
}

// Log data to CSV file function
int log_data(FILE *fp, int channel0, int channel1, int channel2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0, channel1, channel2) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        int channel0_value = read_mcp3008(spi_fd, 0);
        int channel1_value = read_mcp3008(spi_fd, 1);
        int channel2_value = read_mcp3008(spi_fd, 2);

        // Log data to CSV file
        if (log_data(csv_file, channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close CSV file and SPI device
    fclose(csv_file);
    close(spi_fd);

    printf("Program finished.\n");
    return 0;
}

