#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static pthread_mutex_t led_mutex = PTHREAD_MUTEX_INITIALIZER;
static int led_state = 0; // 0: off, 1: on

// Function prototypes
void log_message(const char *message);
void signal_handler(int signum);
void led_control(int state);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void mqtt_connect_retries(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_disconnect_retries(struct mosquitto *mosq, void *userdata, int rc);

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received signal, shutting down...");
        running = 0;
    }
}

// LED control function
void led_control(int state) {
    pthread_mutex_lock(&led_mutex);
    gpioWrite(GPIO_PIN, state);
    led_state = state;
    pthread_mutex_unlock(&led_mutex);
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_message("MQTT connection failed");
        int reconnect_delay = 1;
        int rc = mosquitto_reconnect_delay_set(mosq, reconnect_delay, MAX_RECONNECT_DELAY, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message("Failed to set reconnection delay");
        }
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message("MQTT disconnected unexpectedly");
    }
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        json_error_t error;
        json_t *root = json_loads(message->payload, 0, &error);

        if (!root) {
            log_message("JSON parsing error");
            return;
        }

        json_t *led_state_json = json_object_get(root, "led_state");
        if (!led_state_json) {
            log_message("Key 'led_state' not found in JSON");
            json_decref(root);
            return;
        }

        if (!json_is_boolean(led_state_json)) {
            log_message("Value of 'led_state' is not a boolean");
            json_decref(root);
            return;
        }

        int led_state_value = json_boolean_value(led_state_json);

        pthread_mutex_lock(&led_mutex);
        led_control(led_state_value);
        pthread_mutex_unlock(&led_mutex);

        json_decref(root);
    } else {
        log_message("Empty MQTT message received");
    }
}

// MQTT connect retries callback
void mqtt_connect_retries(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == MOSQ_ERR_SUCCESS) {
        log_message("MQTT connected successfully");
    } else {
        int reconnect_delay = 1;
        int next_delay = reconnect_delay * 2;
        if (next_delay > MAX_RECONNECT_DELAY) {
            next_delay = MAX_RECONNECT_DELAY;
        }
        mosquitto_reconnect_delay_set(mosq, reconnect_delay, next_delay, 1);
        log_message("Reconnecting to MQTT broker...");
    }
}

// MQTT disconnect retries callback
void mqtt_disconnect_retries(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == MOSQ_ERR_SUCCESS) {
        log_message("MQTT disconnected successfully");
    } else {
        int reconnect_delay = 1;
        int next_delay = reconnect_delay * 2;
        if (next_delay > MAX_RECONNECT_DELAY) {
            next_delay = MAX_RECONNECT_DELAY;
        }
        mosquitto_reconnect_delay_set(mosq, reconnect_delay, next_delay, 1);
        log_message("Reconnecting to MQTT broker...");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn LED off initially

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);
    mosquitto_connect_retries_set(mosq, mqtt_connect_retries);
    mosquitto_disconnect_retries_set(mosq, mqtt_disconnect_retries);

    // Connect to MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    log_message("Exiting");
    return 0;
}

