#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Define constants
#define SOUND_THRESHOLD 0 // Sensor outputs LOW when sound is detected
#define ALARM_DURATION 1   // Alarm duration in seconds
#define DELAY_MS 100      // Delay between readings in milliseconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int result;
    int sound_level;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as input
    result = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", SOUND_SENSOR_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO18 as output
    result = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", ALARM_LED_PIN, result);
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sound sensor value
        sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Check for errors during GPIO read
        if (sound_level < 0) {
            fprintf(stderr, "Error reading GPIO%d: %d\n", SOUND_SENSOR_PIN, sound_level);
            gpioTerminate();
            return 1;
        }

        // Print sound level
        printf("Sound level: %d\n", sound_level);

        // Check for sound event
        if (sound_level == SOUND_THRESHOLD) {
            fprintf(stderr, "Sound event detected!\n");

            // Activate alarm LED
            result = gpioWrite(ALARM_LED_PIN, 1);
            if (result != 0) {
                fprintf(stderr, "Failed to write to GPIO%d: %d\n", ALARM_LED_PIN, result);
                gpioTerminate();
                return 1;
            }

            // Wait for alarm duration
            gpioDelay(ALARM_DURATION * 1000); // Convert seconds to milliseconds

            // Deactivate alarm LED
            result = gpioWrite(ALARM_LED_PIN, 0);
            if (result != 0) {
                fprintf(stderr, "Failed to write to GPIO%d: %d\n", ALARM_LED_PIN, result);
                gpioTerminate();
                return 1;
            }

            fprintf(stderr, "Alarm LED deactivated.\n");
        }

        // Delay before next reading
        gpioDelay(DELAY_MS);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

