// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LM35_CHANNEL 0   // MCP3008 Channel 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
float get_from_buffer(CircularBuffer *cb, int index);
void print_buffer(CircularBuffer *cb);
void log_to_file(CircularBuffer *cb);
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get value from circular buffer
float get_from_buffer(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        return -1.0; // Indicate out-of-bounds access
    }
