#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/spi/spidev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int i2c_read_sensor(int fd, uint8_t address, uint16_t *value);
int spi_read_adc(int fd, int channel);
int log_data(FILE *fp, uint16_t light_value, int sound_value);
void signal_handler(int sig);
int setup_i2c(int bus, int addr);
int setup_spi(int device, int mode, int bits, int speed);
int cleanup_i2c(int fd);
int cleanup_spi(int fd);
int open_log_file(const char *filename);

// I2C read function
int i2c_read_sensor(int fd, uint8_t address, uint16_t *value) {
    uint8_t buf[2];
    int result;

    if (fd < 0) {
        fprintf(stderr, "Error: I2C file descriptor is invalid.\n");
        return -1;
    }

    result = write(fd, &address, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing address to I2C: %s\n", strerror(errno));
        return -1;
    }

    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// SPI read function
int spi_read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    if (fd < 0) {
        fprintf(stderr, "Error: SPI file descriptor is invalid.\n");
        return -1;
    }

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

// Logging function
int log_data(FILE *fp, uint16_t light_value, int sound_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fp == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(fp, "%s, Light: %u lux, Sound: %d\n", timestamp, light_value, sound_value);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// I2C setup function
int setup_i2c(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI setup function
int setup_spi(int device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed hz
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        fprintf(stderr, "Error setting max speed hz: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C cleanup function
int cleanup_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

// SPI cleanup function
int cleanup_spi(int fd) {
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

// Open log file function
int open_log_file(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return fp;
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = setup_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = setup_spi(MCP3008_SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI setup failed, exiting.\n");
        cleanup_i2c(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = open_log_file(LOG_FILE);
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file, exiting.\n");
        cleanup_i2c(i2c_fd);
        cleanup_spi(spi_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        uint16_t light_value;
        int sound_value;

        // Read light sensor
        if (i2c_read_sensor(i2c_fd, BH1750_ADDR, &light_value) == 0) {
            // Read sound sensor
            sound_value = spi_read_adc(spi_fd, 0);
            if (sound_value >= 0) {
                // Log data
                if (log_data(log_file, light_value, sound_value) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error reading sound sensor.\n");
            }
        } else {
            fprintf(stderr, "Error reading light sensor.\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    cleanup_i2c(i2c_fd);
    cleanup_spi(spi_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

