#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define ALARM_MESSAGE "Flame detected on GPIO %d!\n"

static volatile int running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the flame sensor state
int read_flame_sensor() {
    return gpioRead(GPIO_PIN);
}

