int log_flame_event(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, GPIO_PIN, state);
    fclose(fp);
    return 0;
}

// Function to print the alarm message to stdout
void print_alarm_message() {
    printf(ALARM_MESSAGE);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

