#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP4725_I2C_ADDR 0x60
#define VREF 3.3
#define ADC_RESOLUTION 1024.0
#define TMP36_SENSITIVITY 0.01 // 10mV/°C
#define TMP36_OFFSET 0.5       // 500mV at 25°C

// Global variables
static volatile int keepRunning = 1;
static int spi_fd;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int spi_init(int channel, int speed);
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int i2c_init(int addr);
int write_mcp4725(int i2c_fd, float temperature);
int log_data(FILE *fp, int adc_value, float temperature, float dac_voltage);
void signal_handler(int sig);

// SPI initialization function
int spi_init(int channel, int speed) {
    int fd = wiringPiSPISetup(channel, speed);
    if (fd == -1) {
        fprintf(stderr, "SPI setup failed: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// MCP3008 read function
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// ADC to temperature conversion function
float adc_to_temperature(int adc_value) {
    float temperature = (adc_value / ADC_RESOLUTION) * 500.0; // 0-500mV
    temperature += TMP36_OFFSET;
    temperature *= TMP36_SENSITIVITY;
    return temperature;
}

// I2C initialization function
int i2c_init(int addr) {
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        fprintf(stderr, "I2C setup failed: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// MCP4725 write function
int write_mcp4725(int i2c_fd, float temperature) {
    int dac_value = (int)(temperature * 4095.0); // 0-4095 for 12-bit resolution
    if (dac_value < 0 || dac_value > 4095) {
        fprintf(stderr, "Invalid temperature value: %.2f\n", temperature);
        return -1;
    }

    int result = wiringPiI2CWriteReg16(i2c_fd, 0x00, dac_value);
    if (result == -1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Data logging function
int log_data(FILE *fp, int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%.2f,%.2f\n", timestamp, adc_value, temperature, dac_voltage) < 0) {
        fprintf(stderr, "File write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT. Shutting down...\n");
        keepRunning = 0;

        // Close SPI interface
        if (spi_fd != -1) {
            // No direct SPI close function in wiringPi, but we can reset the SPI interface
            // wiringPiSPIClose(SPI_CHANNEL); // Not a valid function
            printf("SPI interface closed (not a valid function).\n");
        }

        // Close I2C interface
        if (i2c_fd != -1) {
            // No direct I2C close function in wiringPi, but we can reset the I2C interface
            // wiringPiI2CClose(i2c_fd); // Not a valid function
            printf("I2C interface closed (not a valid function).\n");
        }

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
            printf("Log file closed.\n");
        }

        exit(0);
    }
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(MCP4725_I2C_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (keepRunning) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 0.5 seconds.\n");
            delay(500);
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Write DAC value
        if (write_mcp4725(i2c_fd, temperature) == -1) {
            fprintf(stderr, "Failed to write DAC value. Retrying in 0.5 seconds.\n");
            delay(500);
            continue;
        }

        // Calculate DAC voltage
        float dac_voltage = temperature * VREF / 1024.0;

        // Log data
        if (log_data(log_file, adc_value, temperature, dac_voltage) == -1) {
            fprintf(stderr, "Failed to log data. Retrying in 0.5 seconds.\n");
        }

        // Print data to stdout
        printf("%d,%.2f,%.2f\n", adc_value, temperature, dac_voltage);

        // Wait 0.5 seconds
        delay(500);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    return 0;
}

