#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define GPIO pins for SPI communication
#define CS_PIN 8

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int read_mcp3008(int channel);
int process_sensor_data(int adc_value);
int log_data(int sensor0_value, int sensor1_value, int sensor2_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor0;
    int sensor1;
    int sensor2;
} sensor_data_t;

// Function to initialize SPI
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to process sensor data (convert to percentage)
int process_sensor_data(int adc_value) {
    // Assuming ADC value ranges from 0 to 1023
    // Map the ADC value to a percentage (0-100)
    int percentage = (int)(((float)adc_value / 1023.0) * 100.0);
    return percentage;
}

// Function to log data to file
int log_data(int sensor0_value, int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor0_value, sensor1_value, sensor2_value);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int sensor0_value = read_mcp3008(0);
        int sensor1_value = read_mcp3008(1);
        int sensor2_value = read_mcp3008(2);

        if (sensor0_value == -1 || sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        } else {
            // Process sensor data
            int processed_sensor0 = process_sensor_data(sensor0_value);
            int processed_sensor1 = process_sensor_data(sensor1_value);
            int processed_sensor2 = process_sensor_data(sensor2_value);

            // Log data
            log_data(processed_sensor0, processed_sensor1, processed_sensor2);

            printf("Sensor 0: %d%%, Sensor 1: %d%%, Sensor 2: %d%%\n", processed_sensor0, processed_sensor1, processed_sensor2);
        }

        // Sleep for 60 seconds
        gpioDelay(60000); // pigpio's delay function
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Goodbye!\n");
    return 0;
}

