#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins for motor control
#define MOTOR_IN1 17  // BCM GPIO 17
#define MOTOR_IN2 18  // BCM GPIO 18
#define MOTOR_ENA 27  // BCM GPIO 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor speed (PWM duty cycle)
#define MOTOR_SPEED 150

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int log_rain_data(int rain_level);
void control_motor(int direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("Caught signal, stopping motor and exiting...\n");
    }
}

// Function to read analog value from MCP3008
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to log rain data to file
int log_rain_data(int rain_level) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("rain_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening rain_log.txt: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    fprintf(fp, "%s, Rain Level: %d\n", timestamp, rain_level);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to rain_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing rain_log.txt: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == 1) { // Forward
        digitalWrite(MOTOR_IN1, HIGH);
        digitalWrite(MOTOR_IN2, LOW);
        pwmWrite(MOTOR_ENA, MOTOR_SPEED);
        printf("Motor: Forward\n");
    } else { // Reverse
        digitalWrite(MOTOR_IN1, LOW);
        digitalWrite(MOTOR_IN2, HIGH);
        pwmWrite(MOTOR_ENA, MOTOR_SPEED);
        printf("Motor: Reverse\n");
    }
}

int main() {
    int rain_level;
    int result;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set motor control pins as output
    pinMode(MOTOR_IN1, OUTPUT);
    pinMode(MOTOR_IN2, OUTPUT);
    pinMode(MOTOR_ENA, PWM_OUTPUT);

    // Set PWM mode to mark:space and range to 0-255
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(255);

    // Set PWM clock divider (adjust as needed)
    pwmSetClock(192); // Example clock divider

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read rain sensor value
        rain_level = read_mcp3008(0);
        if (rain_level == -1) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            delay(1000); // Wait before retrying
            continue;
        }

        // Log rain data
        result = log_rain_data(rain_level);
        if (result != 0) {
            fprintf(stderr, "Error logging rain data, retrying...\n");
        }

        // Control motor based on rain level
        if (rain_level > RAIN_THRESHOLD) {
            control_motor(1); // Forward
            delay(3000);       // Run for 3 seconds
            control_motor(0); // Stop
        } else {
            control_motor(0); // Stop
        }

        delay(1000); // Wait 1 second
    }

    // Cleanup before exiting
    control_motor(0); // Stop the motor
    pwmWrite(MOTOR_ENA, 0); // Disable PWM
    close(SPI_CHANNEL); // Close SPI

    printf("Exiting program.\n");
    return 0;
}

