#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_DATA_PIN 26
#define MIC_CLK_PIN 19
#define LED_PIN 16

// Define constants
#define ADC_RESOLUTION 1024
#define ADC_RANGE 3.3f
#define CLAP_THRESHOLD 0.5f
#define DEBOUNCE_TIME 50 // milliseconds
#define LED_ON_TIME 500  // milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned int clap_time = 0;
static volatile int debounce_count = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
float calculate_adc_value(unsigned int adc_value);
void clap_detection(float adc_value);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int mic_data_pin;
    int mic_clk_pin;
    int led_pin;
    float clap_threshold;
    int debounce_time;
    int led_on_time;
} Config;

Config config = {
    .mic_data_pin = MIC_DATA_PIN,
    .mic_clk_pin = MIC_CLK_PIN,
    .led_pin = LED_PIN,
    .clap_threshold = CLAP_THRESHOLD,
    .debounce_time = DEBOUNCE_TIME,
    .led_on_time = LED_ON_TIME
};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpioTerminate();
        return 1;
    }

    printf("Clap detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc();

        // Calculate ADC value
        float adc_value_float = calculate_adc_value((unsigned int)adc_value);

        // Detect clap
        clap_detection(adc_value_float);

        // Delay to avoid busy-waiting
        gpioDelay(10); // 10 milliseconds
    }

    // Cleanup
    gpioWrite(config.led_pin, 0); // Turn off LED
    gpioTerminate();

    printf("Clap detection system stopped.\n");

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    // Set MIC_DATA_PIN as input
    if (gpioSetMode(config.mic_data_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_DATA_PIN as input\n");
        return 1;
    }

    // Set MIC_CLK_PIN as output
    if (gpioSetMode(config.mic_clk_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_CLK_PIN as output\n");
        return 1;
    }

    // Set LED_PIN as output
    if (gpioSetMode(config.led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        return 1;
    }

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Wait for MIC_DATA_PIN to go low
    while (gpioRead(config.mic_data_pin) == 1 && running) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (!running) return 0; // Exit if signal received

    // Read 10 bits of data
    for (i = 0; i < 10; i++) {
        // Wait for MIC_CLK_PIN to go high
        while (gpioRead(config.mic_clk_pin) == 0 && running) {
            gpioDelay(1);
        }

        if (!running) return 0; // Exit if signal received

        // Read MIC_DATA_PIN
        adc_value <<= 1;
        if (gpioRead(config.mic_data_pin) == 1) {
            adc_value |= 1;
        }

        // Wait for MIC_CLK_PIN to go low
        while (gpioRead(config.mic_clk_pin) == 1 && running) {
            gpioDelay(1);
        }

        if (!running) return 0; // Exit if signal received
    }

    return adc_value;
}

// Calculate ADC value from raw ADC value
float calculate_adc_value(unsigned int adc_value) {
    return ((float)adc_value / ADC_RESOLUTION) * ADC_RANGE;
}

// Detect clap event
void clap_detection(float adc_value) {
    if (adc_value > config.clap_threshold) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        unsigned long long timestamp_ms = (unsigned long long)ts.tv_sec * 1000 + (unsigned long long)ts.tv_nsec / 1000000;

        if (debounce_count == 0) {
            clap_time = timestamp_ms;
            debounce_count = 100; // Start debounce
        } else {
            if (timestamp_ms - clap_time < config.debounce_time) {
                debounce_count = 0; // Reset debounce
            } else {
                debounce_count = 0; // Reset debounce
                printf("Clap detected at %lld ms\n", timestamp_ms);
                gpioWrite(config.led_pin, 1); // Turn on LED
                gpioDelay(config.led_on_time); // Keep LED on for 500ms
                gpioWrite(config.led_pin, 0); // Turn off LED
                debounce_count = 0; // Reset debounce
            }
        }
    } else {
        debounce_count = 0; // Reset debounce
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Ctrl+C pressed, exiting...\n");
}

