#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define VCC 3.3
#define SENSITIVITY 0.001 // 1 mV/Gauss
#define LOG_FILE "magnetic_log.txt"

// Global variables
static volatile sig_atomic_t keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int read_mcp3008(int spi_fd, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_magnetic_field(float voltage, float sensitivity);
int log_data(float magnetic_field);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = (mode << 4) | (bits << 0);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to convert voltage to magnetic field strength
float voltage_to_magnetic_field(float voltage, float sensitivity) {
    return voltage / sensitivity;
}

// Function to log data to file
int log_data(float magnetic_field) {
    time_t now = time(NULL);
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%ld,%.4f\n", now, magnetic_field);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    // Release GPIO line (if needed - depends on the specific GPIO library used)
    // Example: gpioSetMode(8, PI_INPUT); // Set GPIO8 to input mode
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (keep_running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping sample.\n");
            usleep(500000); // Wait 500ms before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value, VREF);
        float magnetic_field = voltage_to_magnetic_field(voltage, SENSITIVITY);

        printf("ADC Value: %d, Voltage: %.4f V, Magnetic Field: %.4f Gauss\n", adc_value, voltage, magnetic_field);

        if (log_data(magnetic_field) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        usleep(500000); // Sample every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

