#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/time.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 5.0         // Reference voltage
#define MLX91211_SENSITIVITY 0.1 // 100mV/A
#define LOG_FILE "current_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;

// Structure for SPI configuration
typedef struct {
    uint8_t mode;
    uint8_t bits;
    uint32_t speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
float adc_to_current(int adc_value, float vref, float sensitivity);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init(spi_config_t *config) {
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &config->mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Current Conversion function
float adc_to_current(int adc_value, float vref, float sensitivity) {
    return (adc_value * sensitivity) / 1000.0; // Convert ADC value to current
}

