#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce interval in milliseconds
#define DEBOUNCE_INTERVAL 5

// Majority filter size
#define MAJORITY_SIZE 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio) {
    int sum = 0;
    for (int i = 0; i < MAJORITY_SIZE; i++) {
        sum += gpioRead(gpio);
        gpioDelay(DEBOUNCE_INTERVAL * 1000); // Convert ms to microseconds
    }
    return (sum >= MAJORITY_SIZE / 2) ? 1 : 0; // Return 1 if majority is 1, 0 otherwise
}

// Function to log the sensor states to the console
void log_sensor_states(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for object detection by both sensors
void check_object_detection(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 1 && sensor2_state == 1) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log sensor states
        log_sensor_states(sensor1_state, sensor2_state);

        // Check for object detection
        check_object_detection(sensor1_state, sensor2_state);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Proximity sensor monitoring stopped.\n");

    return 0;
}

