#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_setup(spi_config_t config);
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
void cleanup();

// SPI configuration structure
typedef struct {
    int channel;
    uint32_t baud_rate;
} spi_config_t;

// Function to set up SPI
int spi_setup(spi_config_t config) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed hz
    uint32_t speed = config.baud_rate;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_BAUD;
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    return ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

// Function to log data to file
int log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    wiringPiSetup(); // Reinitialize wiringPi to allow proper cleanup of GPIO pins
    pinMode(0, INPUT); // Set GPIO pin to input mode
    digitalWrite(0, LOW); // Set GPIO pin to LOW
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_setup({SPI_CHANNEL, SPI_BAUD});
    if (spi_fd == -1) {
        fprintf(stderr, "SPI setup failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        // Calculate moisture level
        double moisture_level = calculate_moisture_level(adc_value);

        // Log data
        log_data(moisture_level);

        // Print data to console
        printf("Moisture level: %.2f%%\n", moisture_level);

        // Wait for 60 seconds
        sleep(READ_DELAY);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

