#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <poll.h>
#include <sys/time.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define BUFFER_SIZE 1024

// Structure to hold video buffer information
typedef struct {
    int fd;
    void *buffer;
    size_t size;
    int width;
    int height;
} video_buffer_t;

// Global variables
static video_buffer_t video_buffer;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_video_buffer(video_buffer_t *buffer, int width, int height);
int capture_frame(video_buffer_t *buffer);
int write_frame_to_file(const video_buffer_t *buffer);
int log_timestamp(const char *filename);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize video buffer
int init_video_buffer(video_buffer_t *buffer, int width, int height) {
    buffer->width = width;
    buffer->height = height;

    buffer->fd = open(VIDEO_DEVICE, O_RDWR);
    if (buffer->fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Set the buffer size based on the resolution
    buffer->size = width * height * 2; // Assuming 2 bytes per pixel (YUV)

    // Map the video buffer to memory
    buffer->buffer = mmap(NULL, buffer->size, PROT_READ | PROT_WRITE, MAP_SHARED, buffer->fd, 0);
    if (buffer->buffer == MAP_FAILED) {
        perror("Error mapping video buffer");
        close(buffer->fd);
        return -1;
    }

    return 0;
}

// Capture a single frame from the video buffer
int capture_frame(video_buffer_t *buffer) {
    // MJPEG format requires a specific header
    unsigned char header[8] = {0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x00, 0x00, 0x00};

    // Write the header to the buffer
    if (lseek(buffer->fd, 0, SEEK_SET) == -1) {
        perror("Error seeking to beginning of buffer");
        return -1;
    }
    if (write(buffer->buffer, header, 8) != 8) {
        perror("Error writing header to buffer");
        return -1;
    }

    // Write the frame data (assuming a simple YUV format)
    unsigned char frame_data[BUFFER_SIZE];
    memset(frame_data, 0, BUFFER_SIZE);

    if (lseek(buffer->fd, 0, SEEK_SET) == -1) {
        perror("Error seeking to beginning of buffer");
        return -1;
    }
    if (read(buffer->buffer, frame_data, BUFFER_SIZE) != BUFFER_SIZE) {
        perror("Error reading frame data");
        return -1;
    }

    // Write the frame data to the log file
    if (write_frame_to_file(buffer) != 0) {
        return -1;
    }

    return 0;
}

// Write the frame data to the log file
int write_frame_to_file(const video_buffer_t *buffer) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp = (long)(tv.tv_sec) * 1000000 + (long)(tv.tv_usec);

    log_timestamp(FRAME_LOG_FILE);
    return 0;
}

// Log the timestamp to a file
int log_timestamp(const char *filename) {
    if (log_file == NULL) {
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%ld\n", (long)time(NULL));
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (video_buffer.buffer != MAP_FAILED) {
        if (munmap(video_buffer.buffer, video_buffer.size) == -1) {
            perror("Error unmapping video buffer");
        }
    }

    if (video_buffer.fd != -1) {
        close(video_buffer.fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    struct pollfd pfd;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize video buffer
    if (init_video_buffer(&video_buffer, 640, 480) != 0) {
        fprintf(stderr, "Video buffer initialization failed. Exiting.\n");
        return 1;
    }

    // Configure pollfd structure
    pfd.fd = video_buffer.fd;
    pfd.events = POLLPRI | POLLERR; // Monitor for priority events (frame ready) and errors

    // Main loop
    while (!terminate) {
        // Use select() to wait for a frame to be ready
        ret = select(video_buffer.fd + 1, &pfd, NULL, NULL, NULL);
        if (ret == -1) {
            perror("Error in select()");
            break;
        } else if (ret > 0) {
            // Frame is ready, capture it
            if (capture_frame(&video_buffer) != 0) {
                fprintf(stderr, "Frame capture failed.\n");
                break;
            }
        } else if (ret < 0) {
            // Error occurred
            fprintf(stderr, "Error in select() (error code %d).\n", ret);
            break;
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

