#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>

// Define the API call functions
#define API_CALL_OPEN 1
#define API_CALL_CONFIG 2
#define API_CALL_START 3
#define API_CALL_STOP 4
#define API_CALL_GET_FRAME 5
#define API_CALL_GET_BUFFER 6
#define API_CALL_GET_FRAME_SIZE 7
#define API_CALL_GET_BUFFER_SIZE 8
#define API_CALL_UNMAP 9
#define API_CALL_CLOSE 10

// Define the buffer size
#define BUFFER_SIZE 1920 * 1080 * 2 // YUYV format

// Define the maximum UDP packet size
#define MAX_UDP_PACKET_SIZE 65000

// Define the default target IP and port
#define DEFAULT_TARGET_IP "127.0.0.1"
#define DEFAULT_TARGET_PORT 5000

// Structure to hold the camera configuration
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int width;
    int height;
    int format;
    int index;
    int total_fragments;
    int fragment_index;
    int fragment_size;
    int socket_fd;
    char target_ip[INET_ADDRSTRLEN];
    int target_port;
} CameraConfig;

// Global variable to store the camera configuration
CameraConfig camera_config;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, stopping camera stream.", signum);
    camera_config.stop(camera_config.index);
    camera_config.unmap(camera_config.buffer);
    camera_config.close(camera_config.fd);
    closelog();
    exit(0);
}

// Function to open the camera device
int open_camera(CameraConfig *config) {
    int fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open camera device: %s", strerror(errno));
        return -1;
    }

    // Get the camera parameters
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        syslog(LOG_ERR, "Failed to query camera capabilities: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        syslog(LOG_ERR, "Camera does not support video capture.");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        syslog(LOG_ERR, "Camera does not support streaming I/O.");
        close(fd);
        return -1;
    }

    // Configure the camera
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = config->width;
    fmt.fmt.pix.height = config->height;
    fmt.fmt.pix.pixelformat = config->format;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        syslog(LOG_ERR, "Failed to set camera format: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Set the buffer count to 4
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        syslog(LOG_ERR, "Failed to request buffers: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Map the buffers
    config->buffer_size = req.count * BUFFER_SIZE;
    config->buffer = mmap(NULL, config->buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (config->buffer == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map buffers: %s", strerror(errno));
        close(fd);
        return -1;
    }

    config->fd = fd;

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &config->index) < 0) {
        syslog(LOG_ERR, "Failed to start streaming: %s", strerror(errno));
        munmap(config->buffer, config->buffer_size);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to configure the camera
int config_camera(CameraConfig *config) {
    // Set the target IP and port
    if (setsockopt(config->socket_fd, SOL_SOCKET, SO_REUSEADDR, &config->target_port, sizeof(config->target_port)) < 0) {
        syslog(LOG_ERR, "Failed to set reuse address option: %s", strerror(errno));
        return -1;
    }
    if (bind(config->socket_fd, (struct sockaddr *)&config->target_ip, sizeof(config->target_ip)) < 0) {
        syslog(LOG_ERR, "Failed to bind socket: %s", strerror(errno));
        return -1;
    }
    if (listen(config->socket_fd, 1) < 0) {
        syslog(LOG_ERR, "Failed to listen on socket: %s", strerror(errno));
        return -1;
    }

    // Create a UDP socket
    config->socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (config->socket_fd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to start the camera stream
int start_camera(CameraConfig *config) {
    if (ioctl(config->fd, VIDIOC_STREAMON, &config->index) < 0) {
        syslog(LOG_ERR, "Failed to start streaming: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to stop the camera stream
int stop_camera(CameraConfig *config) {
    if (ioctl(config->fd, VIDIOC_STREAMOFF, &config->index) < 0) {
        syslog(LOG_ERR, "Failed to stop streaming: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to get the next frame
int get_frame(CameraConfig *config) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = config->index;

    if (ioctl(config->fd, VIDIOC_DQBUF, &buf) < 0) {
        syslog(LOG_ERR, "Failed to dequeue buffer: %s", strerror(errno));
        return -1;
    }

    // Fragment the frame into UDP packets
    int fragment_index = 0;
    int total_fragments = 1; // Start with 1 fragment
    int fragment_size = BUFFER_SIZE; // Start with the full buffer size
    while (fragment_index < total_fragments - 1) {
        // Calculate the remaining buffer size
