#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;
int fd = -1;
buffer_t *buffers = NULL;
int buffer_count = 0;

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, stopping...");
    stop_flag = 1;
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open device %s: %s", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        syslog(LOG_ERR, "Failed to query capabilities: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to check if the device supports video capture and streaming
int supports_capture_streaming(int fd) {
    if (cap->capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        if (cap->capabilities & V4L2_CAP_STREAMING) {
            return 1;
        } else {
            syslog(LOG_WARNING, "Device supports video capture but not streaming.");
            return 0;
        }
    } else {
        syslog(LOG_ERR, "Device does not support video capture.");
        return 0;
    }
}

