int set_pixel_format(int fd, enum v4l2_PIX_FMT pix_fmt, int width, enum v4l2_field field) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.pixelformat = pix_fmt;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = 0; // Height is not set here, it will be set by the driver
    fmt.fmt.pix.field = field;
    fmt.fmt.pix.colorspace = V4L2_COLORSPACE_SRGB; // Example: Set color space

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        syslog(LOG_ERR, "Failed to set pixel format: %s", strerror(errno));
        return -1;
    }
    return 0;
}

