#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos and buttons
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define servo limits
#define SERVO_MIN 25
#define SERVO_MAX 125

// Global variables for servo positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
int set_servo_position(int pin, int position);
int read_button_state(int pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to set servo position using PWM
int set_servo_position(int pin, int position) {
    // Calculate pulse width (1-2000 us)
    int pulse_width = (int)(((float)(position - SERVO_MIN) / (SERVO_MAX - SERVO_MIN)) * 2000.0);

    // Set PWM duty cycle
    gpioPWM(pin, pulse_width);

    return 0; // Return 0 for success
}

// Function to read button state
int read_button_state(int pin) {
    return gpioRead(pin);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for servos and buttons
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Initialize servos to mid-position
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read button states
        int tilt_up_state = read_button_state(TILT_UP_PIN);
        int tilt_down_state = read_button_state(TILT_DOWN_PIN);
        int pan_left_state = read_button_state(PAN_LEFT_PIN);
        int pan_right_state = read_button_state(PAN_RIGHT_PIN);

        // Adjust servo positions based on button presses
        if (tilt_up_state == 0) {
            tilt_position = (tilt_position + 5) < SERVO_MAX ? tilt_position + 5 : SERVO_MAX;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
        }
        if (tilt_down_state == 0) {
            tilt_position = (tilt_position - 5) > SERVO_MIN ? tilt_position - 5 : SERVO_MIN;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
        }
        if (pan_left_state == 0) {
            pan_position = (pan_position - 5) < SERVO_MIN ? pan_position - 5 : SERVO_MIN;
            set_servo_position(PAN_SERVO_PIN, pan_position);
        }
        if (pan_right_state == 0) {
            pan_position = (pan_position + 5) < SERVO_MIN ? pan_position + 5 : SERVO_MIN;
            set_servo_position(PAN_SERVO_PIN, pan_position);
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 us
    }

    return 0;
}

