        }
        if (tilt_down_state == 0) {
            tilt_position = (tilt_position - 5) > SERVO_MIN ? tilt_position - 5 : SERVO_MIN;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
        }
        if (pan_left_state == 0) {
            pan_position = (pan_position - 5) < SERVO_MIN ? pan_position - 5 : SERVO_MIN;
            set_servo_position(PAN_SERVO_PIN, pan_position);
        }
        if (pan_right_state == 0) {
            pan_position = (pan_position + 5) < SERVO_MIN ? pan_position + 5 : SERVO_MIN;
            set_servo_position(PAN_SERVO_PIN, pan_position);
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 us
    }

    return 0;
}

