    if (bytes_written != jpeg_size) {
        perror("Error writing to JPEG file");
        syslog(LOG_ERR, "Error writing to JPEG file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        syslog(LOG_INFO, "Received SIGINT, stopping...");
        running = 0; // Set the flag to stop the main loop

        // Stop streaming
        if (camera_fd != -1) {
            stop_streaming(camera_fd);
        }

        // Unmap buffers
        if (buffer_map != NULL) {
            unmap_buffer(buffer_map, FRAME_SIZE);
        }

        // Close file descriptor
        if (camera_fd != -1) {
            close(camera_fd);
        }

        // Destroy mutex
        pthread_mutex_destroy(&buffer_mutex);

        syslog(LOG_INFO, "Exiting program.");
        exit(0);
    }
}

int main() {
    // Initialize syslog
    openlog("bookworm_capture", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the camera device
    camera_fd = open_camera(VIDEO_DEVICE);
    if (camera_fd == -1) {
        syslog(LOG_ERR, "Failed to open camera. Exiting.");
        closelog();
        return 1;
    }

    // Request initial buffers
    int buffers = 4; // Number of buffers
    size_t buffer_size = FRAME_SIZE; // Size of each buffer
    if (request_buffers(camera_fd, &buffers, &buffer_size) == -1) {
        syslog(LOG_ERR, "Failed to request initial buffers. Exiting.");
        close(camera_fd);
        closelog();
        return 1;
    }

    // Map the buffer
    buffer_map = map_buffer(NULL, buffer_size);
    if (buffer_map == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map buffer. Exiting.");
        close(camera_fd);
        closelog();
        return 1;
    }

    // Initialize frame data
    frame_t yuyv_frame, rgb24_frame, blurred_frame;
    memset(&yuyv_frame, 0, sizeof(yuyv_frame));
    memset(&rgb24_frame, 0, sizeof(rgb24_frame));
    memset(&blurred_frame, 0, sizeof(blurred_frame));

    // Main loop
    while (running) {
        // Capture a frame
        if (capture_frame(camera_fd, &yuyv_frame) == -1) {
            syslog(LOG_ERR, "Failed to capture frame. Continuing...");
            sleep(1); // Avoid spamming errors
            continue;
        }

        // Convert to RGB24
        if (convert_yuyv_to_rgb24(&yuyv_frame, &rgb24_frame) == -1) {
            syslog(LOG_ERR, "Failed to convert YUYV to RGB24. Continuing...");
            sleep(1); // Avoid spamming errors
            continue;
        }

        // Apply blur filter
        if (apply_blur_filter(&rgb24_frame, &blurred_frame) == -1) {
            syslog(LOG_ERR, "Failed to apply blur filter. Continuing...");
            sleep(1); // Avoid spamming errors
            continue;
        }

        // Encode as JPEG
        char jpeg_buffer[640 * 480 * 3]; // Allocate enough space for the JPEG buffer
        size_t jpeg_size = 0;
        if (encode_jpeg(&blurred_frame, jpeg_buffer, &jpeg_size) == -1) {
            syslog(LOG_ERR, "Failed to encode JPEG. Continuing...");
            sleep(1); // Avoid spamming errors
            continue;
        }

        // Save JPEG file
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char filename[80];
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tstruct);

        if (save_jpeg(filename, jpeg_buffer, jpeg_size) == -1) {
            syslog(LOG_ERR, "Failed to save JPEG file. Continuing...");
        } else {
            syslog(LOG_INFO, "Saved JPEG file: %s", filename);
        }

        // Enqueue the buffer
        if (enqueue_buffer(camera_fd, buffer_map, buffer_size) == -1) {
            syslog(LOG_ERR, "Failed to enqueue buffer. Continuing...");
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_streaming(camera_fd);
    unmap_buffer(buffer_map, FRAME_SIZE);
    close(camera_fd);
    pthread_mutex_destroy(&buffer_mutex);
    closelog();

    return 0;
}

