#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_DEVICES 4

// Structure to hold camera information
typedef struct {
    char device_name[256];
    int fd;
    int supported_frame_sizes;
    int supported_frame_intervals;
    int autofocus_supported;
} camera_info_t;

// Global array to store camera information
camera_info_t cameras[MAX_DEVICES];

// Signal handler for graceful exit
void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    for (int i = 0; i < MAX_DEVICES; i++) {
        if (cameras[i].fd != -1) {
            close(cameras[i].fd);
        }
    }
    exit(0);
}

// Function to check if a device exists
int device_exists(const char *device_name) {
    struct stat st;

    if (stat(device_name, &st) == 0) {
        return 1; // Device exists
    } else {
        return 0; // Device does not exist
    }
}

// Function to open a camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening camera device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_device_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) == -1) {
        perror("Error querying device capabilities");
        return -1;
    }
    return 0;
}

// Function to enumerate supported frame sizes
int enumerate_frame_sizes(int fd, unsigned int *frame_sizes, unsigned int *num_sizes) {
    struct v4l2_frmsizeenum req;
    struct v4l2_frmsizeenum resp;
    *num_sizes = 0;

    req.type = VIDIOC_ENUM_FRAMESIZES;
    req.mixed = 0;
    req.index = 0;

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &req) == -1) {
        perror("Error enumerating frame sizes");
        return -1;
    }

    *num_sizes = req.count;

    if (*num_sizes > 0) {
        frame_sizes = (unsigned int *)malloc(*num_sizes * sizeof(unsigned int));
        if (frame_sizes == NULL) {
            perror("Error allocating memory for frame sizes");
            return -1;
        }

        for (int i = 0; i < *num_sizes; i++) {
            resp.type = VIDIOC_ENUM_FRAMESIZES;
            resp.mixed = 0;
            resp.index = i;

            if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &resp) == -1) {
                perror("Error getting frame size");
                free(frame_sizes);
                return -1;
            }

            frame_sizes[i] = resp.dispwidth;
        }
    }

    free(frame_sizes);
    return 0;
}

// Function to enumerate supported frame intervals
int enumerate_frame_intervals(int fd, unsigned int *frame_intervals, unsigned int *num_intervals) {
    struct v4l2_frameinterval req;
    struct v4l2_frameinterval resp;
    *num_intervals = 0;

    req.type = VIDIOC_ENUM_FRAMEINTERVALS;
    req.index = 0;

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &req) == -1) {
        perror("Error enumerating frame intervals");
        return -1;
    }

    *num_intervals = req.count;

    if (*num_intervals > 0) {
        frame_intervals = (unsigned int *)malloc(*num_intervals * sizeof(unsigned int));
        if (frame_intervals == NULL) {
            perror("Error allocating memory for frame intervals");
            return -1;
        }

        for (int i = 0; i < *num_intervals; i++) {
            resp.type = VIDIOC_ENUM_FRAMEINTERVALS;
            resp.index = i;

            if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &resp) == -1) {
                perror("Error getting frame interval");
                free(frame_intervals);
                return -1;
            }

            frame_intervals[i] = resp.interval;
        }
    }

    free(frame_intervals);
    return 0;
}

