#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define POLL_INTERVAL 0.1 // seconds
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define HTTP_PORT 8080
#define HTTP_ENDPOINT "http://localhost:8080/upload"

// Global variables
static volatile int running = 1;
static int http_socket = -1;
static int http_server_socket = -1;
static int motion_captures_dir = -1;
static int motion_captures_count = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_image(const char *filename);
int compose_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
int post_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read PIR sensor
int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to capture image using raspistill
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -w %d -h %d -q %d -o %s", IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY, filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistill command\n");
        return -1;
    }
    return 0;
}

// Function to compose JSON payload
int compose_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    json_t *root = json_object();
    json_t *filename_json = json_string(filename);
    json_t *timestamp_json = json_string(timestamp);
    json_t *motion_json = json_integer(motion_status);
    json_t *gpio_json = json_integer(gpio_pin);

    json_object_set_new(root, "filename", filename_json);
    json_object_set_new(root, "timestamp", timestamp_json);
    json_object_set_new(root, "motion_status", motion_json);
    json_object_set_new(root, "gpio_pin", gpio_json);

    char *json_string = json_dumps(root, JSON_REAL_PRECISION(5));
    json_decref(root);

    if (!json_string) {
        fprintf(stderr, "Error creating JSON string\n");
        return -1;
    }

    return 0;
}

// Function to post data to HTTP endpoint
int post_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    if (http_socket == -1) {
        fprintf(stderr, "HTTP socket not initialized\n");
        return -1;
    }

    char json_payload[256];
    snprintf(json_payload, sizeof(json_payload), "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}", filename, timestamp, motion_status, gpio_pin);

    char request[512];
    snprintf(request, sizeof(request), "POST /upload HTTP/1.1\r\nHost: localhost:8080\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", strlen(json_payload), json_payload);

    if (send(http_socket, request, strlen(request), 0) < 0) {
        fprintf(stderr, "Error sending data to HTTP server\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Release GPIO resources
    gpioTerminate();

    // Close HTTP socket
    if (http_socket != -1) {
        close(http_socket);
    }

    // Close HTTP server socket
    if (http_server_socket != -1) {
        close(http_server_socket);
    }

    // Remove motion_captures directory if it exists
    if (motion_captures_dir != -1) {
        if (rmdir(motion_captures_dir) == 0) {
            printf("Motion captures directory removed\n");
        } else {
            fprintf(stderr, "Error removing motion_captures directory\n");
        }
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port>\n", argv[0]);
        return 1;
    }

    const char *ip_address = argv[1];
    int port = atoi(argv[2]);

    // Initialize HTTP socket
    http_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (http_socket == -1) {
        fprintf(stderr, "Error creating socket\n");
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(http_socket);
        return 1;
    }

    if (connect(http_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error connecting to server\n");
        close(http_socket);
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        close(http_socket);
        return 1;
    }

    // Create motion_captures directory
    if (mkdir("motion_captures", 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error creating motion_captures directory\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    time_t last_motion_time = 0;
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                // Generate filename
                char filename[64];
                snprintf(filename, sizeof(filename), "motion_%ld.jpg", current_time);

                // Capture image
                if (capture_image(filename) != 0) {
                    fprintf(stderr, "Error capturing image\n");
                    continue; // Skip to the next iteration
                }

                // Get timestamp
                time_t timestamp = current_time;
                struct tm *tm_info = localtime(&timestamp);
                char timestamp_str[32];
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

                // Compose JSON payload
                if (compose_json_payload(filename, timestamp_str, 1, GPIO_PIN) != 0) {
                    fprintf(stderr, "Error composing JSON payload\n");
                    continue; // Skip to the next iteration
                }

                // Post data to HTTP endpoint
                if (post_data(filename, timestamp_str, 1, GPIO_PIN) != 0) {
                    fprintf(stderr, "Error posting data to HTTP endpoint\n");
                }

                // Update last motion time
                last_motion_time = current_time;
            }
        } else {
            // Polling loop
            gpioDelay(POLL_INTERVAL * 1000000); // Convert seconds to microseconds
        }
    }

    cleanup();
    return 0;
}

