#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in YYYYMMDD_HHMMSS_mmm format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y%m%d_%H%M%S_%m", timeinfo);
}

// Function to log messages to the log file
void log_message(const char *message)
