#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>

#define DEVICE_NAME "/dev/video0"
#define BUFFER_SIZE 1024
#define FRAME_SIZE 200 * 150 * 2 // 200x150 YUYV (2 bytes per pixel)
#define TIMEOUT_SEC 2

// Structure to hold camera configuration
typedef struct {
    int width;
    int height;
    int pixelformat;
    int field;
} camera_config_t;

// Global variables
static int camera_fd = -1;
static void *buffer = NULL;
static FILE *output_file = NULL;
static camera_config_t camera_config;
static volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_camera(camera_config_t *config);
int query_camera_info(camera_config_t *config);
int request_buffers(int fd, int *num_buffers, size_t *buffer_size);
int mmap_buffer(int fd, int fd_set, size_t *buffer_size);
int start_streaming(int fd);
int capture_frame(int fd, void *buffer, size_t buffer_size);
int process_frame(const void *buffer, size_t buffer_size);
int crop_frame(const void *buffer, size_t buffer_size, int x1, int y1, int x2, int y2, unsigned char *cropped_buffer, size_t cropped_buffer_size);
int write_cropped_frame(const unsigned char *cropped_buffer, size_t cropped_buffer_size, FILE *file);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, stopping...");
    stop_flag = 1;
}

// Initialize camera
int init_camera(camera_config_t *config) {
    config->pixelformat = V4L2_PIX_FMT_YUYV;
    config->field = V4L2_FIELD_NONE;
    config->width = 640;
    config->height = 480;

    // Set the desired resolution (adjust as needed)
    char buf[256];
    snprintf(buf, sizeof(buf), "v4l2-ctl -d %s -r %dx%d -p %d -t YUYV -f %d", DEVICE_NAME, config->width, config->height, config->field, config->pixelformat);
    int ret = system(buf);
    if (ret == -1) {
        perror("Failed to set resolution");
        return -1;
    }
    syslog(LOG_INFO, "Camera initialized with %dx%d, %s", config->width, config->height, (config->pixelformat == V4L2_PIX_FMT_YUYV) ? "YUYV" : "Unknown");
    return 0;
}

// Query camera information
int query_camera_info(camera_config_t *config) {
    struct v4l2_capability cap;
    int ret = ioctl(camera_fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        syslog(LOG_ERR, "Device does not support video capture");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        syslog(LOG_ERR, "Device does not support streaming I/O");
        return -1;
    }

    config->pixelformat = cap.pixelformat;
    config->width = cap.width;
    config->height = cap.height;
    config->field = cap.field;

    syslog(LOG_INFO, "Camera capabilities: %x, %dx%d, %s, %d", cap.capabilities, config->width, config->height, (config->pixelformat == V4L2_PIX_FMT_YUYV) ? "YUYV" : "Unknown", config->field);
    return 0;
}

// Request buffers
int request_buffers(int fd, int *num_buffers, size_t *buffer_size) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    int ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    *num_buffers = req.count;
    *buffer_size = req.buffer_count * sizeof(struct v4l2_buffer);

    return 0;
}

// Map buffer
int mmap_buffer(int fd, int fd_set, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    int ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret == -1) {
        perror("VIDIOC_QUERYBUF failed");
        return -1;
    }

    *buffer_size = buf.length;
    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

    if (*buffer == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0; // Use the first buffer

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret == -1) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    return 0;
}

// Start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    int ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret == -1) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }
    syslog(LOG_INFO, "Streaming started");
    return 0;
}

// Capture frame
int capture_frame(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0; // Use the first buffer

    int ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret == -1) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    if (buffer_size != buf.bytesused) {
        syslog(LOG_ERR, "Buffer size mismatch: expected %zu, got %zu", buffer_size, buf.bytesused);
        return -1;
    }

    return 0;
}

// Process frame (currently does nothing)
int process_frame(const void *buffer, size_t buffer_size) {
    // This function is currently a no-op
    return 0;
}

// Crop frame
int crop_frame(const void *buffer, size_t buffer_size, int x1, int y1, int x2, int y2, unsigned char *cropped_buffer, size_t cropped_buffer_size) {
    // This is a placeholder.  A real implementation would use the buffer
    // to access the YUYV data and perform the cropping.
    // For simplicity, we'll just copy the entire buffer to the cropped buffer.
    // This is not efficient and should be replaced with a proper cropping algorithm.
    if (x1 >= x2 || y1 >= y2) {
        syslog(LOG_ERR, "Invalid crop bounds: x1=%d, y1=%d, x2=%d, y2=%d", x1, y1, x2, y2);
        return -1;
    }

    // Calculate the number of bytes to copy
    size_t num_bytes = (x2 - x1) * (y2 - y1) * 2; // 2 bytes per pixel

    // Copy the data
    memcpy(cropped_buffer, buffer, num_bytes);

    return 0;
}

// Write cropped frame to file
int write_cropped_frame(const unsigned char *cropped_buffer, size_t cropped_buffer_size, FILE *file) {
    size_t bytes_written = fwrite(cropped_buffer, 1, cropped_buffer_size, file);
    if (bytes_written != cropped_buffer_size) {
        perror("fwrite failed");
        return -1;
    }
    return 0;
}

void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    if (camera_fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(camera_fd, VIDIOC_STREAMOFF, &type);
        if (buffer != NULL) {
            munmap(buffer, sizeof(struct v4l2_buffer));
        }
        close(camera_fd);
    }

    if (output_file != NULL) {
        fclose(output_file);
    }

    closelog();
}

int main() {
    openlog("uvc_camera", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    camera_fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK);
    if (camera_fd == -1) {
        perror("Failed to open camera device");
        syslog(LOG_ERR, "Failed to open camera device: %s", DEVICE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    // Query camera information
    if (query_camera_info(&camera_config) != 0) {
        syslog(LOG_ERR, "Failed to query camera information");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize the camera
    if (init_camera(&camera_config) != 0) {
        syslog(LOG_ERR, "Failed to initialize camera");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request buffers
    int num_buffers, buffer_size;
    if (request_buffers(camera_fd, &num_buffers, &buffer_size) != 0) {
        syslog(LOG_ERR, "Failed to request buffers");
        cleanup();
        return EXIT_FAILURE;
    }

    // Map the buffer
    if (mmap_buffer(camera_fd, 0, &buffer_size) != 0) {
        syslog(LOG_ERR, "Failed to map buffer");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the output file
    output_file = fopen("cropped.yuv", "wb");
    if (output_file == NULL) {
        perror("Failed to open output file");
        syslog(LOG_ERR, "Failed to open output file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(camera_fd) != 0) {
        syslog(LOG_ERR, "Failed to start streaming");
        cleanup();
        return EXIT_FAILURE;
    }

    fd_set readfds;
    struct timeval timeout;
    int ret;

    // Main loop
    while (!stop_flag) {
        fd_set readfds_copy;
        struct timeval timeout_copy;
        int r;

        FD_ZERO(&readfds_copy);
        FD_SET(camera_fd, &readfds_copy);

        timeout_copy.tv_sec = TIMEOUT_SEC;
        timeout_copy.tv_usec = 0;

        r = select(camera_fd + 1, &readfds_copy, NULL, NULL, &timeout_copy);

        if (r == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, stop streaming
                syslog(LOG_INFO, "Select interrupted by signal, stopping...");
                stop_flag = 1;
            } else {
                perror("Select error");
                syslog(LOG_ERR, "Select error: %s", strerror(errno));
                break;
            }
        } else if (r > 0) {
            // Data is available
            if (capture_frame(camera_fd, buffer, buffer_size) == 0) {
                // Process the frame
                if (process_frame(buffer, buffer_size) == 0) {
                    // Crop the frame
                    unsigned char *cropped_buffer = (unsigned char *)malloc(FRAME_SIZE);
                    if (cropped_buffer == NULL) {
                        perror("Failed to allocate memory for cropped buffer");
                        syslog(LOG_ERR, "Failed to allocate memory for cropped buffer");
                        break;
                    }

                    if (crop_frame(buffer, buffer_size, 0, 0, 200, 150, cropped_buffer, FRAME_SIZE) == 0) {
                        // Write the cropped frame to file
                        if (write_cropped_frame(cropped_buffer, FRAME_SIZE, output_file) == 0) {
                            syslog(LOG_INFO, "Frame processed and written to file");
                        } else {
                            syslog(LOG_ERR, "Failed to write frame to file");
                        }
                    } else {
                        syslog(LOG_ERR, "Failed to crop frame");
                    }

                    free(cropped_buffer);
                } else {
                    syslog(LOG_ERR, "Frame processing failed");
                }
            } else {
                syslog(LOG_ERR, "Failed to capture frame");
            }
        } else {
            // Timeout occurred
            syslog(LOG_INFO, "Timeout waiting for frame");
        }
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

