#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define servo angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define servo pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int set_servo_angle(int gpio_pin, int angle);
int move_servo(int gpio_pin, int angle_change);
int get_key_input(char *buffer, int buffer_size);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set servo angle using PWM
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    // Calculate pulse width based on angle (0-180 degrees)
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    gpioPWM(gpio_pin, pulse_width);

    return 0;
}

// Function to move servo a specified number of degrees
int move_servo(int gpio_pin, int angle_change) {
    int current_angle = 90; // Start at neutral position

    if (angle_change > 0) {
        current_angle += angle_change;
    } else {
        current_angle -= -angle_change; // Use -angle_change to make it work for both positive and negative changes
    }

    // Clamp angle to limits
    if (current_angle < MIN_ANGLE) {
        current_angle = MIN_ANGLE;
    } else if (current_angle > MAX_ANGLE) {
        current_angle = MAX_ANGLE;
    }

    // Set servo angle
    if (set_servo_angle(gpio_pin, current_angle) != 0) {
        fprintf(stderr, "Error setting servo angle.\n");
        return -1;
    }

    return 0;
}

// Function to get key input from stdin
int get_key_input(char *buffer, int buffer_size) {
    int i = 0;
    int c;

    while (program_running && (c = getchar()) != EOF) {
        if (c == '\n') {
            buffer[i] = '\0'; // Null-terminate the string
            return 0; // Indicate no key pressed
        } else if (c == '\r') {
            // Handle carriage return (not needed, but good practice)
            continue;
        } else if (c == 'q') {
            buffer[i] = 'q';
            return 1; // Indicate 'q' key pressed
        } else if (c >= 33 && c <= 126) { // Check if character is printable (ASCII 32-126)
            buffer[i++] = c;
            if (i >= buffer_size - 1) {
                fprintf(stderr, "Error: Input buffer overflow.\n");
                program_running = 0; // Stop the loop if buffer overflow
                break;
            }
        }
    }

    buffer[i] = '\0'; // Null-terminate the string
    return 0; // Indicate no key pressed
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(PAN_SERVO_PIN, 1000); // Example range, adjust as needed
    gpioSetPWMrange(TILT_SERVO_PIN, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    char key_buffer[10]; // Buffer to store key input

    // Main loop
    while (program_running) {
        // Get key input
        if (get_key_input(key_buffer, sizeof(key_buffer)) == 1) {
            // Handle 'q' key press
            if (strcmp(key_buffer, "q") == 0) {
                printf("Exiting program...\n");
                break;
            }
        }

        // Move pan servo
        if (key_buffer[0] == 'A') {
            if (move_servo(PAN_SERVO_PIN, 5) != 0) {
                fprintf(stderr, "Error moving pan servo.\n");
            }
        } else if (key_buffer[0] == 'D') {
            if (move_servo(PAN_SERVO_PIN, -5) != 0) {
                fprintf(stderr, "Error moving pan servo.\n");
            }
        } else if (key_buffer[0] == 'W') {
            if (move_servo(PAN_SERVO_PIN, 10) != 0) {
                fprintf(stderr, "Error moving pan servo.\n");
            }
        } else if (key_buffer[0] == 'S') {
            if (move_servo(PAN_SERVO_PIN, -10) != 0) {
                fprintf(stderr, "Error moving pan servo.\n");
            }
        }

        // Move tilt servo
        if (key_buffer[0] == 'A') {
            if (move_servo(TILT_SERVO_PIN, 5) != 0) {
                fprintf(stderr, "Error moving tilt servo.\n");
            }
        } else if (key_buffer[0] == 'D') {
            if (move_servo(TILT_SERVO_PIN, -5) != 0) {
                fprintf(stderr, "Error moving tilt servo.\n");
            }
        } else if (key_buffer[0] == 'W') {
            if (move_servo(TILT_SERVO_PIN, 10) != 0) {
                fprintf(stderr, "Error moving tilt servo.\n");
            }
        } else if (key_buffer[0] == 'S') {
            if (move_servo(TILT_SERVO_PIN, -10) != 0) {
                fprintf(stderr, "Error moving tilt servo.\n");
            }
        }

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    gpioPWM(PAN_SERVO_PIN, 0); // Stop PWM for pan servo
    gpioPWM(TILT_SERVO_PIN, 0); // Stop PWM for tilt servo
    gpioTerminate(); // Terminate pigpio library

    return 0;
}

