// Initialize I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize OLED display
int oled_init(int fd) {
    // Initialization sequence (SSD1306)
    unsigned char init_sequence[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Set display clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Set multiplex ratio
        0xD3, 0x00, // Set display offset
        0x40,       // Set display start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode
        0xA1,       // Set segment re-map
        0xC8,       // Set COM output scan direction
        0xDA, 0x12, // Set COM pins hardware configuration
        0x81, 0xCF, // Set contrast control
        0xD9, 0xF1, // Set pre-charge period
        0xDB, 0x40, // Set VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Set normal display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        unsigned char buf[2];
        buf[0] = init_sequence[i];
        buf[1] = 0x00; // Dummy byte
        if (write(fd, buf, 2) != 2) {
            perror("Error writing to I2C device");
            return -1;
        }
        usleep(1000); // Wait for command to complete
    }

    return 0;
}

// Clear the OLED display
int oled_clear(int fd) {
    unsigned char clear_buffer[OLED_WIDTH * OLED_HEIGHT / 8];
    memset(clear_buffer, 0x00, sizeof(clear_buffer));

    for (int page = 0; page < 8; page++) {
        unsigned char page_buffer[OLED_WIDTH];
        for (int col = 0; col < OLED_WIDTH; col++) {
            // Set column start address for the page
            unsigned char command[2];
            command[0] = 0xB0 + page; // Page address
            command[1] = 0x00;       // Lower column address
            if (write(fd, command, 2) != 2) {
                perror("Error writing to I2C device");
                return -1;
            }
            usleep(1000); // Wait for page start

            // Write the page data
            if (write(fd, &clear_buffer[col], 1) != 1) {
                perror("Error writing to I2C device");
                return -1;
            }
        }
    }

    return 0;
}

// Set the cursor position on the OLED display
int oled_set_cursor(int fd, int x, int y) {
    unsigned char command[2];
    command[0] = 0xB0 + y; // Page address
    command[1] = 0x00 + x;  // Lower column address
    if (write(fd, command, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Write a character to the OLED display
int oled_write_char(int fd, int x, int y, unsigned char c) {
    if (c < 32 || c > 126) {
        c = 0; // Default to space if out of range
    }

    // Look up the font data for the character
    int index = c - 32;
    if (index < 0 || index >= FONT_SIZE) {
        index = 0; // Default to space if out of range
    }

    // Extract the character data from the font buffer
    unsigned char char_data[FONT_WIDTH];
    for (int i = 0; i < FONT_WIDTH; i++) {
        char_data[i] = font.data[index * FONT_WIDTH * FONT_HEIGHT + i * FONT_HEIGHT + index];
    }

    // Write the character data to the OLED
    for (int i = 0; i < FONT_WIDTH; i++) {
        unsigned char page_buffer[OLED_WIDTH];
        memset(page_buffer, 0x00, sizeof(page_buffer));

        // Set column start address for the page
        unsigned char command[2];
        command[0] = 0xB0 + y; // Page address
        command[1] = 0x00 + x + i; // Lower column address
        if (write(fd, command, 2) != 2) {
            perror("Error writing to I2C device");
            return -1;
        }
        usleep(1000); // Wait for page start

        // Write the page data
        if (write(fd, &char_data[i], 1) != 1) {
            perror("Error writing to I2C device");
            return -1;
        }
    }

    return 0;
}

// Read CPU temperature from /sys/class/thermal/thermal_zone0/temp
int read_cpu_temp(float *temp) {
    FILE *fp;
    char buffer[10];

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading temperature file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Convert temperature to float
    *temp = (float)atoi(buffer) / 1000.0;
    return 0;
}

// Read CPU usage from /proc/stat
int read_cpu_usage(float *usage) {
    FILE *fp;
    char buffer[256];
    static unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    static int prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening proc/stat file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading proc/stat file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the data
    char *col = strtok(buffer, " ");
    user = atoi(col);
    col = strtok(NULL, " ");
    nice = atoi(col);
    col = strtok(NULL, " ");
    system = atoi(col);
    col = strtok(NULL, " ");
    idle = atoi(col);
    col = strtok(NULL, " ");
    iowait = atoi(col);
    col = strtok(NULL, " ");
    irq = atoi(col);
    col = strtok(NULL, " ");
    softirq = atoi(col);
    col = strtok(NULL, " ");
    steal = atoi(col);
    col = strtok(NULL, " ");
    guest = atoi(col);
    col = strtok(NULL, " ");
    guest_nice = atoi(col);

    // Calculate the difference
    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;

    user = user - prev_user - prev_nice;
    system = system - prev_system;
    idle = idle - prev_idle - prev_iowait;
    iowait = iowait - prev_iowait;
    irq = irq - prev_irq;
    softirq = softirq - prev_softirq;
    steal = steal - prev_steal;
    guest = guest - prev_guest - prev_guest_nice;

    *usage = (float)(user + system + idle) / (float)(user + system + idle + iowait + irq + softirq + steal + guest) * 100.0;
    return 0;
}

// Display temperature and CPU usage on the OLED display
int oled_display(int fd, float temp, float usage) {
    char temp_str[20];
    char usage_str[20];

    // Format temperature string
    snprintf(temp_str, sizeof(temp_str), "Temp: %.1fC", temp);

    // Format usage string
    snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", usage);

    // Clear the display
    if (oled_clear(fd) != 0) {
        log_error("Failed to clear OLED display.");
        return -1;
    }

    // Display temperature
    if (oled_set_cursor(fd, 0, 0) != 0) {
        log_error("Failed to set cursor position for temperature.");
        return -1;
    }
    if (oled_write_char(fd, 0, 0, temp_str[0]) != 0) {
        log_error("Failed to write character for temperature.");
        return -1;
    }
    for (int i = 1; i < strlen(temp_str); i++) {
        if (oled_write_char(fd, 0, 0, temp_str[i]) != 0) {
            log_error("Failed to write character for temperature.");
            return -1;
        }
    }

    // Display usage
    if (oled_set_cursor(fd, 0, 16) != 0) {
        log_error("Failed to set cursor position for usage.");
        return -1;
    }
    if (oled_write_char(fd, 0, 16, usage_str[0]) != 0) {
        log_error("Failed to write character for usage.");
        return -1;
    }
    for (int i = 1; i < strlen(usage_str); i++) {
        if (oled_write_char(fd, 0, 16, usage_str[i]) != 0) {
            log_error("Failed to write character for usage.");
            return -1;
        }
    }

    return 0;
}

// Log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Error: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup resources
void cleanup(int fd) {
    if (fd >= 0) {
        oled_clear(fd);
        close(fd);
    }
}

