#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define GPIO_PIN 17
#define I2C_BUS 1
#define LCD_ADDR 0x27 // Replace with your LCD's I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_LITER 450.0 // Calibration factor for YF-S201
#define PULSES_PER_MINUTE 60.0 // Pulses per minute
#define PULSES_PER_SECOND 60.0 // Pulses per second
#define PULSES_PER_MILLISECOND (PULSES_PER_SECOND / 1000.0)
#define LOG_INTERVAL_SEC 1
#define LCD_UPDATE_INTERVAL_SEC 10

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulse_count);
double calculate_total_volume(double flow_rate, double time_interval);
void log_data(double flow_rate, double total_volume);
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
void lcd_display_flow_rate(double flow_rate);
void lcd_display_total_volume(double total_volume);
void signal_handler(int signal);
void cleanup();

// Structure for LCD configuration (example)
typedef struct {
    int i2c_address;
    int lcd_width;
    int lcd_height;
} lcd_config_t;

// Function to initialize the LCD
void lcd_init() {
    // Send initialization sequence (example for 4-bit mode)
    gpioWrite(4, 1); // Enable pulse 1
    gpioWrite(1, 0); // Enable pulse 2
    gpioWrite(4, 0); // Enable pulse 3
    gpioWrite(1, 0); // Enable pulse 4
    gpioDelay(500);  // Wait for LCD to power up

    // 4-bit initialization sequence (example)
    gpioWrite(4, 1); // Enable pulse 1
    gpioWrite(1, 0); // Enable pulse 2
    gpioWrite(4, 0); // Enable pulse 3
    gpioWrite(1, 0); // Enable pulse 4
    gpioDelay(500);  // Wait for LCD to power up

    gpioWrite(4, 1); // Enable pulse 1
    gpioWrite(1, 0); // Enable pulse 2
    gpioWrite(4, 0); // Enable pulse 3
    gpioWrite(1, 0); // Enable pulse 4
    gpioDelay(500);  // Wait for LCD to power up

    gpioWrite(4, 1); // Enable pulse 1
    gpioWrite(1, 0); // Enable pulse 2
    gpioWrite(4, 0); // Enable pulse 3
    gpioWrite(1, 0); // Enable pulse 4
    gpioDelay(500);  // Wait for LCD to power up

    gpioWrite(4, 1); // Enable pulse 1
    gpioWrite(1, 0); // Enable pulse 2
    gpioWrite(4, 0); // Enable pulse 3
    gpioWrite(1, 0); // Enable pulse 4
    gpioDelay(500);  // Wait for LCD to power up

    lcd_clear();
}

void lcd_clear() {
    char buffer[32];
    for (int i = 0; i < 16; i++) {
        buffer[i * 2] = 0x01; // Clear column
        buffer[i * 2 + 1] = 0x01; // Clear column
    }
    i2cWriteDevice(i2c_handle, buffer, 32);
}

void lcd_set_cursor(int row, int col) {
    // Set cursor position (example)
    char buffer[4];
    buffer[0] = 0x80; // Function code for set cursor
    buffer[1] = (row & 0x07); // Lower nibble of row address
    buffer[2] = ((row >> 4) & 0x0F); // Upper nibble of row address
    buffer[3] = col; // Column address
    i2cWriteDevice(i2c_handle, buffer, 4);
}

void lcd_print(const char *str) {
    // Print string to LCD (example)
    for (int i = 0; str[i] != '\0'; i++) {
        char buffer[5];
        buffer[0] = 0xC0; // Function code for set DDR
        buffer[1] = 0x00; // Lower nibble of column address
        buffer[2] = ((str[i] - '0') << 4); // Upper nibble of column address
        buffer[3] = 0x00; // Lower nibble of data
        buffer[4] = 0x00; // Upper nibble of data
        i2cWriteDevice(i2c_handle, buffer, 5);
    }
}

void lcd_display_flow_rate(double flow_rate) {
    char buffer[32];
    sprintf(buffer, "Flow: %.2f LPM", flow_rate);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(buffer);
}

void lcd_display_total_volume(double total_volume) {
    char buffer[32];
    sprintf(buffer, "Total: %.2f L", total_volume);
    lcd_clear();
    lcd_set_cursor(1, 0);
    lcd_print(buffer);
}

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_MILLISECOND * PULSES_PER_SECOND / 60.0;
}

// Function to calculate total volume
double calculate_total_volume(double flow_rate, double time_interval) {
    return flow_rate * time_interval;
}

// Function to log data
void log_data(double flow_rate, double total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow Rate: %.2f LPM, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle); // Close I2C device
    }
    if (log_file != NULL) {
        fclose(log_file); // Close log file
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler for rising edge
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0); // Open I2C device
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Calculate flow rate and total volume
        double flow_rate = calculate_flow_rate(pulse_count);
        double total_volume = calculate_total_volume(flow_rate, LOG_INTERVAL_SEC);

        // Log data
        log_data(flow_rate, total_volume);

        // Update LCD (every 10 seconds)
        if (time(NULL) % 10 == 0) {
            lcd_display_flow_rate(flow_rate);
            lcd_display_total_volume(total_volume);
        }

        // Sleep for the specified interval
        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

