#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Configuration
#define ANEMOMETER_PIN 17  // GPIO17 (BCM)
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27 // I2C address of PCF8574 LCD
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define NUM_SAMPLES 10 // Number of samples for moving average filter

// Global variables
volatile unsigned long pulse_count = 0;
volatile unsigned long last_interrupt_time = 0;
volatile int running = 1;

// Moving average filter variables
float wind_speed_history[NUM_SAMPLES] = {0.0};
int history_index = 0;
float wind_speed = 0.0;

int i2c_fd;

// Function prototypes
void anemometer_interrupt();
float calculate_wind_speed();
int read_wind_direction();
void update_lcd(float wind_speed, int wind_direction);
void signal_handler(int signal);
void cleanup();

// Anemometer interrupt handler
void anemometer_interrupt() {
    unsigned long current_time = millis();
    if (current_time - last_interrupt_time > 1) { // Debounce
        pulse_count++;
        last_interrupt_time = current_time;
    }
}

// Calculate wind speed (crude approximation)
float calculate_wind_speed() {
    float pulses_per_second = (float)pulse_count / (float)(millis() - last_interrupt_time);
    float wind_speed = pulses_per_second * 60.0; // Pulses per second * 60 seconds per minute
    pulse_count = 0; // Reset pulse count
    return wind_speed;
}

// Read wind direction from MCP3008
int read_wind_direction() {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    // Basic validation: Check if ADC value is within reasonable range
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// Update LCD with wind speed and direction
void update_lcd(float wind_speed, int wind_direction) {
    char buffer[32]; // Buffer for LCD data
    int i;

    // Clear LCD
    wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x01); // Command to clear display
    delay(2); // Delay for display clear command to complete

    // Set cursor position (0,0)
    wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x00); // Command to set cursor position
    wiringPiI2CWriteReg8(i2c_fd, 0x40, 0x00); // Command to set display address

    // Display wind speed
    snprintf(buffer, sizeof(buffer), "Speed: %.2f m/s", wind_speed);
    for (i = 0; i < strlen(buffer); i++) {
        wiringPiI2CWriteReg8(i2c_fd, 0x40, buffer[i]);
    }

    // Display wind direction
    snprintf(buffer, sizeof(buffer), "Dir: %d", wind_direction);
    for (i = 0; i < strlen(buffer); i++) {
        wiringPiI2CWriteReg8(i2c_fd, 0x40, buffer[i]);
    }

    // Update display (optional, but recommended)
    wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x38); // Command to display
    delay(2); // Delay for display update
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    // Reset GPIO pin (optional)
    pinMode(ANEMOMETER_PIN, INPUT); // Set pin to input to avoid short circuit
    digitalWrite(ANEMOMETER_PIN, LOW); // Set to LOW

    // Close SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI close failed: %s\n", strerror(errno));
    }

    // Close I2C
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set up anemometer pin as input with pull-up resistor
    pinMode(ANEMOMETER_PIN, INPUT);
    pullUpDnControl(ANEMOMETER_PIN, PUD_UP);

    // Set up interrupt on anemometer pin
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, &anemometer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Anemometer and wind vane data logger started.\n");

    // Main loop
    while (running) {
        // Calculate wind speed
        float wind_speed = calculate_wind_speed();

        // Read wind direction
        int wind_direction = read_wind_direction();

        // Update LCD
        if (wind_direction != -1) {
            update_lcd(wind_speed, wind_direction);
        } else {
            fprintf(stderr, "Error reading wind direction, skipping LCD update.\n");
        }

        // Apply moving average filter
        wind_speed_history[history_index] = wind_speed;
        history_index = (history_index + 1) % NUM_SAMPLES;

        float filtered_wind_speed = 0.0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            filtered_wind_speed += wind_speed_history[i];
        }
        filtered_wind_speed /= NUM_SAMPLES;

        // Print wind speed and direction to stderr
        printf("Wind Speed: %.2f m/s, Direction: %d\n", filtered_wind_speed, wind_direction);

        // Wait for the next sample window
        delay(SAMPLE_WINDOW_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

