#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define GPIO_PIN 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_SEC 1
#define ALERT_THRESHOLD 5 // Number of consecutive zero pulses to trigger alert

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static int i2c_handle;
static int lcd_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
int initialize_gpio();
int initialize_i2c();
int initialize_lcd();
void display_flow_rate(float flow_rate);
void handle_alert();
void signal_handler(int signal);
void cleanup();

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFunc(GPIO_PIN, pulse_callback);

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LCD
int initialize_lcd() {
    // Initialization sequence (adjust as needed for your LCD)
    char init_commands[] = {
        0x33, // Initialize
        0x32, // Initialize
        0x28, // 2 lines, 5x8 font
        0x0C, // Display on, cursor off, blink off
        0x06, // Increment cursor, no shift
        0x01  // Clear display
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteDevice(i2c_handle, &init_commands[i], 1) != 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            return -1;
        }
        gpioDelay(100); // Small delay between commands
    }

    return 0;
}

// Display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[32];

    // Clear the LCD
    if (i2cWriteDevice(i2c_handle, 0x01, 1) != 0) {
        fprintf(stderr, "Failed to clear LCD\n");
        return;
    }
    gpioDelay(100);

    // Display flow rate
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    if (i2cWriteDevice(i2c_handle, buffer, strlen(buffer) + 1) != 0) {
        fprintf(stderr, "Failed to write to LCD\n");
        return;
    }
    gpioDelay(100);

    // Display "LPM" on the second line
    snprintf(buffer, sizeof(buffer), "LPM");
    if (i2cWriteDevice(i2c_handle, buffer, strlen(buffer) + 1) != 0) {
        fprintf(stderr, "Failed to write to LCD\n");
        return;
    }
    gpioDelay(100);
}

// Handle alert condition
void handle_alert() {
    time_t now;
    time(&now);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "ALERT: No water flow detected for %d seconds.\n", ALERT_THRESHOLD);
    fprintf(stderr, "Timestamp: %s\n", timestamp);

    // Attempt to re-initialize I2C and LCD
    i2cClose(i2c_handle);
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to re-open I2C device\n");
        return;
    }
    if (initialize_lcd() != 0) {
        fprintf(stderr, "Failed to re-initialize LCD\n");
        return;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize LCD
    if (initialize_lcd() != 0) {
        cleanup();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    time_t last_pulse_time = 0;
    int consecutive_zeros = 0;

    while (running) {
        time_t current_time = time(NULL);
        double elapsed_time = difftime(current_time, last_pulse_time);

        if (elapsed_time >= SAMPLE_INTERVAL_SEC) {
            // Calculate flow rate
            float flow_rate = (float)pulse_count / PULSES_PER_LITER * 60.0; // LPM
            pulse_count = 0; // Reset pulse count for the next interval

            // Display flow rate
            display_flow_rate(flow_rate);

            // Check for alert condition
            if (flow_rate == 0.0) {
                consecutive_zeros++;
                if (consecutive_zeros >= ALERT_THRESHOLD) {
                    handle_alert();
                    consecutive_zeros = 0; // Reset after handling alert
                }
            } else {
                consecutive_zeros = 0; // Reset if flow is detected
            }

            last_pulse_time = current_time;
        }

        gpioDelay(100); // Check every 100ms
    }

    cleanup();
    return 0;
}

