// Define GPIO pins for row anodes
#define ROW1 2
#define ROW2 3
#define ROW3 4
#define ROW4 17
#define ROW5 27
#define ROW6 22
#define ROW7 10
#define ROW8 9

// Define GPIO pins for column cathodes
#define COL1 14
#define COL2 15
#define COL3 18
#define COL4 23
#define COL5 24
#define COL6 25
#define COL7 8
#define COL8 7

// Define the number of columns
#define NUM_COLS 8

// Define the delay between column updates (in milliseconds)
#define DELAY_MS 150

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set row anode pins as outputs
    gpioSetMode(ROW1, PI_OUTPUT);
    gpioSetMode(ROW2, PI_OUTPUT);
    gpioSetMode(ROW3, PI_OUTPUT);
    gpioSetMode(ROW4, PI_OUTPUT);
    gpioSetMode(ROW5, PI_OUTPUT);
    gpioSetMode(ROW6, PI_OUTPUT);
    gpioSetMode(ROW7, PI_OUTPUT);
    gpioSetMode(ROW8, PI_OUTPUT);

    // Set column cathode pins as outputs
    gpioSetMode(COL1, PI_OUTPUT);
    gpioSetMode(COL2, PI_OUTPUT);
    gpioSetMode(COL3, PI_OUTPUT);
    gpioSetMode(COL4, PI_OUTPUT);
    gpioSetMode(COL5, PI_OUTPUT);
    gpioSetMode(COL6, PI_OUTPUT);
    gpioSetMode(COL7, PI_OUTPUT);
    gpioSetMode(COL8, PI_OUTPUT);

    // Set all row anodes HIGH initially (common anode)
    gpioWrite(ROW1, 1);
    gpioWrite(ROW2, 1);
    gpioWrite(ROW3, 1);
    gpioWrite(ROW4, 1);
    gpioWrite(ROW5, 1);
    gpioWrite(ROW6, 1);
    gpioWrite(ROW7, 1);
    gpioWrite(ROW8, 1);

    return 0; // Indicate success
}

// Function to clear the LED matrix
void clear_matrix() {
    // Set all row anodes HIGH (common anode)
    gpioWrite(ROW1, 1);
    gpioWrite(ROW2, 1);
    gpioWrite(ROW3, 1);
    gpioWrite(ROW4, 1);
    gpioWrite(ROW5, 1);
    gpioWrite(ROW6, 1);
    gpioWrite(ROW7, 1);
    gpioWrite(ROW8, 1);

    // Set all column cathodes HIGH
    gpioWrite(COL1, 1);
    gpioWrite(COL2, 1);
    gpioWrite(COL3, 1);
    gpioWrite(COL4, 1);
    gpioWrite(COL5, 1);
    gpioWrite(COL6, 1);
    gpioWrite(COL7, 1);
    gpioWrite(COL8, 1);
}

// Function to update the LED matrix for a given column
void update_column(int col_num) {
    // Set the column cathode LOW
    gpioWrite(COL_num, 0);

    // Scan the rows and set the corresponding row anodes HIGH
    for (int row = 0; row < 8; row++) {
        gpioWrite(ROW_num, 1); // Set row anode HIGH
    }

    // Delay for the specified duration
    gpioDelay(DELAY_MS * 1000); // Convert milliseconds to microseconds
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("LED matrix wave animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Clear the matrix
        clear_matrix();

        // Update each column sequentially
        for (int col = 1; col <= NUM_COLS; col++) {
            update_column(col);
        }
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    return 0;
}

