#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_SPAD_NB 0x001E
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L3CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L3CX_REG_SYSRANGE_START 0x000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int model_id;
    int i2c_address;
    int range_mm[4]; // Range for up to 4 targets
} sensor_data_t;

// Function prototypes
int init_sensor(sensor_data_t *sensor);
int read_distance(sensor_data_t *sensor);
void print_distances(sensor_data_t *sensor);
void signal_handler(int signal);
int set_i2c_address(sensor_data_t *sensor);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set the I2C address of the VL53L3CX sensor
int set_i2c_address(sensor_data_t *sensor) {
    int result = i2cWriteByteData(sensor->i2c_handle, VL53L3CX_REG_I2C_SLAVE_DEVICE_ADDRESS, sensor->i2c_address);
    if (result != 0) {
        fprintf(stderr, "Error setting I2C address: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L3CX sensor
int init_sensor(sensor_data_t *sensor) {
    // Verify sensor model ID
    int model_id = i2cReadByteData(sensor->i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%X\n", model_id);
        return -1;
    }

    // Stub for proprietary initialization sequence (replace with actual sequence)
    // For example, writing a configuration register with a specific value
    // int init_result = i2cWriteByteData(sensor->i2c_handle, 0x0040, 0x01); // Example register and value
    // if (init_result != 0) {
    //     fprintf(stderr, "Error during initialization: %d\n", init_result);
    //     return -1;
    // }

    printf("VL53L3CX sensor initialized successfully.\n");
    return 0;
}

// Function to read distance measurements from the VL53L3CX sensor
int read_distance(sensor_data_t *sensor) {
    int result;
    uint8_t data[2];

    // Start a single measurement
    result = i2cWriteByteData(sensor->i2c_handle, VL53L3CX_REG_SYSRANGE_START, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10000); // 10ms

    // Read range status
    int range_status = i2cReadByteData(sensor->i2c_handle, VL53L3CX_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", range_status);
        return -1;
    }

    // Read distance data (4 bytes for up to 4 targets)
    data[0] = i2cReadByteData(sensor->i2c_handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    data[1] = i2cReadByteData(sensor->i2c_handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);

    if (data[0] < 0 || data[1] < 0) {
        fprintf(stderr, "Error reading distance data: %d, %d\n", data[0], data[1]);
        return -1;
    }

    // Store the distance values
    sensor->range_mm[0] = (int16_t)((data[0] << 8) | data[1]);
    sensor->range_mm[1] = 0; // Dummy value for target 2
    sensor->range_mm[2] = 0; // Dummy value for target 3
    sensor->range_mm[3] = 0; // Dummy value for target 4

    return 0;
}

// Function to print the distance measurements
void print_distances(sensor_data_t *sensor) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Target 1: %d mm, Target 2: %d mm, Target 3: %d mm, Target 4: %d mm\n",
           timestamp, sensor->range_mm[0], sensor->range_mm[1], sensor->range_mm[2], sensor->range_mm[3]);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor data
    sensor_data_t sensor;
    sensor.model_id = 0;
    sensor.i2c_address = VL53L3CX_ADDR;
    sensor.range_mm[0] = 0; // Initialize range values
    sensor.range_mm[1] = 0;
    sensor.range_mm[2] = 0;
    sensor.range_mm[3] = 0;

    // Initialize the sensor
    if (init_sensor(&sensor) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&sensor) == 0) {
            print_distances(&sensor);
        } else {
            fprintf(stderr, "Error reading distance data\n");
        }

        gpioDelay(100000); // 100ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

