#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02

#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25

#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_HW_KEY 0x07

#define SI1145_HW_KEY_VAL 0x17

// Commands
#define SI1145_RESET 0x01
#define SI1145_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init(int i2c_handle);
int read_si1145_data(int i2c_handle, int *proximity, int *ambient_light);
int log_data(FILE *log_file, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init(int i2c_handle) {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to force ALS measurement\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(int i2c_handle, int *proximity, int *ambient_light) {
    uint8_t data[4];

    // Read proximity data
    if (i2cReadI2CBlockData(i2c_handle, SI1145_REG_PS1_DATA0, (char *)data, 4) < 0) {
        fprintf(stderr, "Error: Failed to read proximity data\n");
        return -1;
    }

    *proximity = (data[1] << 8) | data[0];

    // Read ambient light data
    if (i2cReadI2CBlockData(i2c_handle, SI1145_REG_ALS_VIS_DATA0, (char *)data, 4) < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data\n");
        return -1;
    }

    *ambient_light = (data[1] << 8) | data[0];

    return 0;
}

// Function to log the data to a file
int log_data(FILE *log_file, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int proximity, ambient_light;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_si1145_data(i2c_handle, &proximity, &ambient_light);
        if (result < 0) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        } else {
            // Log the data
            log_data(log_file, proximity, ambient_light);
        }

        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

