#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the Si1145 sensor
int init_si1145() {
    // Check if the sensor is present by reading the PART_ID register
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Si1145 sensor not found. PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1145 sensor found with PART_ID: 0x%02X\n", part_id);
    return 0;
}

// Function to read proximity data from the Si1145 sensor
int read_proximity() {
    int proximity = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    return proximity;
}

// Function to read ambient light data from the Si1145 sensor
int read_ambient_light() {
    int ambient_light = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (ambient_light < 0) {
        fprintf(stderr, "Error reading ambient light data: %s\n", strerror(errno));
        return -1;
    }
    return ambient_light;
}

// Function to log data to a file
void log_data(int proximity, int ambient_light) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

