#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 300000      // 300ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define WATER_THRESHOLD 15.0   // cm

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void trigger_pulse();
long pulse_width();
double calculate_distance(long pulse_width);
void log_distance(double distance);
void check_watering(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        start_time = gpioTick();
        timeout++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal never rose (timeout)\n");
        return -1; // Indicate timeout error
    }

    // Wait for the echo pin to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        end_time = gpioTick();
        timeout++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal never fell (timeout)\n");
        return -1; // Indicate timeout error
    }

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to check if watering is needed
void check_watering(double distance) {
    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        if (distance < WATER_THRESHOLD) {
            printf("Time to water the plant!\n");
        }
    } else {
        fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width_result = pulse_width();

        // Calculate the distance
        double distance = calculate_distance(pulse_width_result);

        // Log the distance
        log_distance(distance);

        // Check for watering
        check_watering(distance);

        // Wait for 60 seconds
        gpioDelay(60000); // 60 seconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

