#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROX_DATA_REG 0x24 // Example register address
#define HEART_RATE_REG 0x26 // Example register address
#define SAMPLE_RATE_MS 100
#define HEART_RATE_MIN 40
#define HEART_RATE_MAX 200

// Global variables
static volatile int running = true;
static int i2c_handle = -1;
static FILE *fp = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_proximity(int handle);
int read_heart_rate(int handle);
float calculate_bpm(int proximity, int heart_rate);
int write_to_csv(FILE *fp, const char *timestamp, float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = false;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read proximity data
int read_proximity(int handle) {
    int proximity = i2cReadByteData(handle, PROX_DATA_REG);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    return proximity;
}

// Read heart rate data
int read_heart_rate(int handle) {
    int heart_rate = i2cReadByteData(handle, HEART_RATE_REG);
    if (heart_rate < 0) {
        fprintf(stderr, "Error reading heart rate data: %s\n", strerror(errno));
        return -1;
    }
    return heart_rate;
}

// Calculate BPM
float calculate_bpm(int proximity, int heart_rate) {
    // Simple linear mapping (replace with a more sophisticated algorithm)
    float bpm = (float)(heart_rate - HEART_RATE_MIN) * (HEART_RATE_MAX - HEART_RATE_MIN) / (HEART_RATE_MAX - HEART_RATE_MIN) + HEART_RATE_MIN;
    return bpm;
}

// Write to CSV file
int write_to_csv(FILE *fp, const char *timestamp, float bpm) {
    if (fprintf(fp, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, SI1182_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    fp = fopen("heartrate.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Get timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Read sensor data
        int proximity = read_proximity(i2c_handle);
        int heart_rate = read_heart_rate(i2c_handle);

        if (proximity >= 0 && heart_rate >= 0) {
            // Calculate BPM
            float bpm = calculate_bpm(proximity, heart_rate);

            // Write to CSV
            if (write_to_csv(fp, timestamp, bpm) != 0) {
                running = false; // Stop if writing fails
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data. Skipping this sample.\n");
        }

        // Sleep for 100ms
        gpioDelay(SAMPLE_RATE_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

