// Define the I2C bus and address
#define I2C_BUS 1
#define CH101_ADDR 0x70

// Define register addresses (replace with actual values from datasheet)
#define CH101_REG_STATUS 0x00
#define CH101_REG_DISTANCE 0x01
#define CH101_REG_TRIGGER 0x02

// Define trigger pulse duration (in microseconds)
#define TRIGGER_PULSE_DURATION 10

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 200

// Define the size of the timestamp buffer
#define TIMESTAMP_BUFFER_SIZE 32

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint8_t status;
    uint16_t distance;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_sensor();
int read_distance(uint8_t *status, uint16_t *distance);
void log_data(uint16_t distance);
void print_data(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger the ultrasonic sensor
int trigger_sensor() {
    char buf[1];
    buf[0] = CH101_REG_TRIGGER;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_DURATION * 1000); // Convert microseconds to microseconds
    return 0;
}

// Function to read distance from the sensor
int read_distance(uint8_t *status, uint16_t *distance) {
    char buf[1];
    char data[2];

    buf[0] = CH101_REG_DISTANCE;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    *status = data[0];

    return 0;
}

// Function to log the distance data to a file
void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[TIMESTAMP_BUFFER_SIZE];
    char log_entry[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, TIMESTAMP_BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, %d\n", timestamp, distance);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s", log_entry) < 0) {
            fprintf(stderr, "Error writing to log file\n");
        }
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
    }

    printf("%s", log_entry);
}

// Function to print the distance data to stdout
void print_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[TIMESTAMP_BUFFER_SIZE];
    char log_entry[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, TIMESTAMP_BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, %d\n", timestamp, distance);

    printf("%s", log_entry);
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    uint8_t status;
    uint16_t distance;
    uint16_t previous_distance = 0; // Store the previous distance for hysteresis

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error triggering sensor, skipping this sample\n");
            gpioDelay(SAMPLING_INTERVAL * 1000); // Wait before next sample
            continue;
        }

        // Read the distance
        if (read_distance(&status, &distance) != 0) {
            fprintf(stderr, "Error reading distance, skipping this sample\n");
            gpioDelay(SAMPLING_INTERVAL * 1000); // Wait before next sample
            continue;
        }

        // Validate the distance (example: 0-2000mm)
        if (distance >= 0 && distance <= 2000) {
            // Hysteresis: Only log if the distance is different from the previous one
            if (distance != previous_distance) {
                log_data(distance);
                print_data(distance);
                previous_distance = distance;
            }
        } else {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
        }

        gpioDelay(SAMPLING_INTERVAL * 1000); // Wait for the sampling interval
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

