#define LOG_FILE "obstacle_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    if (reading < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, reading);
        return -1; // Indicate an error
    }
    return reading;
}

// Function to log data to a file
void log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value);
    fclose(fp);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, continue to the next iteration
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        log_data(sensor1_value, sensor2_value);

        gpioDelay(100); // Wait 100ms
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Obstacle detection stopped.\n");
    return 0;
}

