#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1182-GMR I2C address
#define SI1182_ADDR 0x60

// Si1182-GMR Register Addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x10
#define REG_PS1_DATA0 0x12
#define REG_MEAS_RATE0 0x08
#define REG_ALS_IR_DATA0 0x18

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_proximity();
int read_ambient_light();
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the Si1182-GMR sensor
int init_sensor() {
    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate (example: 100ms)
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE0\n");
        return -1;
    }

    return 0;
}

// Read proximity data
int read_proximity() {
    int proximity = -1;
    for (int i = 0; i < 3; i++) {
        proximity = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
        if (proximity >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", i + 1, proximity);
            gpioDelay(1000); // Wait before retrying
        }
    }
    return proximity;
}

// Read ambient light data
int read_ambient_light() {
    int ambient_light = -1;
    for (int i = 0; i < 3; i++) {
        ambient_light = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        if (ambient_light >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", i + 1, ambient_light);
            gpioDelay(1000); // Wait before retrying
        }
    }
    return ambient_light;
}

// Log data to file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

