#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C address of the Omron B5L-LD50-07050 sensor
#define I2C_ADDRESS 0x50

// Define the command frame to request a measurement
#define COMMAND_FRAME 0x01

// Define the header value for the response
#define RESPONSE_HEADER 0x02

// Define the distance register address
#define DISTANCE_REGISTER 0x0A

// Define the number of samples to take per cycle
#define NUM_SAMPLES 10

// Define the delay between cycles in milliseconds
#define CYCLE_DELAY 100

// Define the intrusion threshold in millimeters
#define INTRUSION_THRESHOLD 1000

// Global variable for the I2C handle
int i2c_handle;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, I2C_ADDRESS, 0); // Open I2C bus 1 with the specified address
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, unsigned short command) {
    char buffer[4];
    buffer[0] = (command >> 8) & 0xFF; // MSB
    buffer[1] = command & 0xFF;       // LSB
    buffer[2] = 0x00; // Pad byte
    buffer[3] = 0x00; // Pad byte

    int result = i2cWriteDevice(handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the response from the sensor
int read_response(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read response: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to verify the response header
int verify_header(char *buffer) {
    return (buffer[0] == RESPONSE_HEADER);
}

// Function to extract the distance from the response
int extract_distance(char *buffer) {
    return (buffer[11] << 8) | buffer[12];
}

// Function to calculate the average distance
float calculate_average_distance(int *distances, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Function to log the intrusion event
int log_intrusion(float average_distance) {
    FILE *fp = fopen("intrusion_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", s, average_distance);
    fclose(fp);
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Send the command to request a measurement
        if (send_command(i2c_handle, COMMAND_FRAME) != 0) {
            fprintf(stderr, "Failed to send command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for at least 10ms
        gpioDelay(10);

        // Read the response from the sensor
        char response[15];
        if (read_response(i2c_handle, response, 15) != 0) {
            fprintf(stderr, "Failed to read response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Verify the response header
        if (!verify_header(response)) {
            fprintf(stderr, "Invalid response header\n");
            continue;
        }

        // Extract the distance from the response
