// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0010
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the model ID from the VL53L0X sensor
int read_model_id(int handle, uint8_t *model_id) {
    uint8_t value;
    if (read_register(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &value) != 0) {
        return -1;
    }
    *model_id = value;
    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int handle, int *distance) {
    uint8_t range_status;
    uint8_t range_value;

    if (read_register(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &range_status) != 0) {
        return -1;
    }

    if (read_register(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range_value) != 0) {
        return -1;
    }

    *distance = range_value;

    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t model_id;
    if (read_model_id(i2c_handle, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X, expected 0xEA)\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            char timestamp[20];
            get_timestamp(timestamp);
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(500000); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

