// Si1182 I2C address
#define SI1182_ADDR 0x60

// Si1182 register addresses (example, adjust based on datasheet)
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_ALS_VIS_DATA0 0x10
#define SI1182_REG_ALS_VIS_DATA1 0x11

// I2C handle
int i2c_handle;

// Function to handle Ctrl+C signal
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the Si1182 sensor
int read_si1182_data(int i2c_handle, int reg_addr)
{
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading I2C block data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int16_t data = (buf[1] << 8) | buf[0];
    return data;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read proximity data
        int proximity_data = read_si1182_data(i2c_handle, SI1182_REG_ALS_VIS_DATA0);

        if (proximity_data >= 0) {
            // Log the data to the console
            printf("Proximity data: %d\n", proximity_data);
        } else {
            fprintf(stderr, "Failed to read proximity data.\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

