#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00 // Example register address

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int main() {
    int i2c_fd;
    unsigned char buffer[2]; // Assuming 2 bytes for distance data
    int distance;
    int bytes_read;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence (optional, but good practice)
    // Write a dummy byte to the sensor
    if (write(i2c_fd, "\0", 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }
    usleep(10000); // Small delay to allow sensor to respond

    // Check if the sensor responds by reading back the dummy byte
    bytes_read = read(i2c_fd, buffer, 1);
    if (bytes_read != 1) {
        fprintf(stderr, "Error reading from I2C device (sensor not present)\n");
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 sensor found at address 0x%02X\n", MLX75030_ADDR);

    // Main loop
    while (program_running) {
        // Read distance data
        bytes_read = read(i2c_fd, buffer, 2);
        if (bytes_read != 2) {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        // Convert the data to distance in millimeters (example conversion)
        distance = (buffer[0] << 8) | buffer[1];

        // Print the distance
        printf("Distance: %d mm\n", distance);

        // Wait 500ms
        nanosleep((const struct timespec[]){{0, 500000000}}, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

