#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 200 // ms
#define MAX_RANGE 38 // ms
#define RESISTOR_VALUE 1000 // 1 kΩ

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measure_pulse() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration <= 0) {
        return -1.0; // Invalid pulse duration
    }
    if (pulse_duration > MAX_RANGE) {
        return -1.0; // Timeout
    }
    return (float)pulse_duration * 0.0343 / RESISTOR_VALUE; // cm
}

// Function to log the distance with a timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance >= 0) {
        printf("%s Distance: %.2f cm\n", timestamp, distance);
    } else {
        fprintf(stderr, "%s Invalid distance reading\n", timestamp);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program running. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_duration = measure_pulse();

        if (pulse_duration > 0) {
            float distance = calculate_distance(pulse_duration);
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse duration\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    gpioTerminate();
    return 0;
}

