#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_LED 17
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define TARGET_DISTANCE_THRESHOLD 1.0 // meters
#define ALERT_DURATION 2 // seconds
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Function prototypes
int uart_init(const char *device, int baud_rate);
int uart_read_data(int fd, unsigned char *buffer, int max_len);
int uart_close(int fd);
int gpio_init(int pin);
int gpio_write(int pin, int value);
int gpio_read(int pin);
int gpio_cleanup(int pin);
int decode_magic_word(const unsigned char *buffer, size_t buffer_len, unsigned char *magic_word);
int validate_range_profile(const unsigned char *buffer, size_t buffer_len);
int detect_target(const unsigned char *range_profile, size_t range_profile_len);
int log_intrusion(const char *timestamp, float distance);
int activate_alert(int pin, int duration);
void signal_handler(int signal);

// UART initialization function
int uart_init(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8; // 8 data bits

    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_lflag &= ~ECHOE;  // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG;   // Disable interpretation of INTR, QUIT and SUSP

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// UART read data function
int uart_read_data(int fd, unsigned char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    }
    return (int)bytes_read;
}

// UART close function
int uart_close(int fd) {
    if (close(fd) == -1) {
        perror("Error closing UART");
        return -1;
    }
    return 0;
}

// GPIO initialization function
int gpio_init(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(pin, PI_OUTPUT);
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    gpioWrite(pin, value);
    return 0;
}

// GPIO read function
int gpio_read(int pin) {
    return gpioRead(pin);
}

// GPIO cleanup function
int gpio_cleanup(int pin) {
    gpioSetMode(pin, PI_INPUT); // Set back to input
    gpioTerminate();
    return 0;
}

// Magic word decoding function
int decode_magic_word(const unsigned char *buffer, size_t buffer_len, unsigned char *magic_word) {
    if (buffer_len != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Invalid magic word size: %zu\n", buffer_len);
        return -1;
    }

    memcpy(magic_word, buffer, MAGIC_WORD_SIZE);
    return 0;
}

// Range profile validation function
int validate_range_profile(const unsigned char *buffer, size_t buffer_len) {
    if (buffer_len != RANGE_PROFILE_SIZE) {
        fprintf(stderr, "Invalid range profile size: %zu\n", buffer_len);
        return -1;
    }
    return 0;
}

// Target detection function
int detect_target(const unsigned char *range_profile, size_t range_profile_len) {
    for (size_t i = 0; i < range_profile_len; ++i) {
        if (range_profile[i] > 0) { // Assuming distance is represented by a non-zero value
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Logging function
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Alert activation function
int activate_alert(int pin, int duration) {
    if (gpio_write(pin, 1) != 0) {
        fprintf(stderr, "Error activating alert\n");
        return -1;
    }
    gpioDelay(duration * 1000000); // Delay in microseconds
    if (gpio_write(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating alert\n");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = uart_init(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_LED) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        uart_close(uart_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_cleanup(GPIO_LED);
        uart_close(uart_fd);
        return 1;
    }

    unsigned char magic_word[MAGIC_WORD_SIZE];
    unsigned char range_profile[RANGE_PROFILE_SIZE];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // ISO 8601 timestamp string
    float distance;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read data from UART
        int bytes_read = uart_read_data(uart_fd, range_profile, RANGE_PROFILE_SIZE);
        if (bytes_read > 0) {
            // Validate range profile
            if (validate_range_profile(range_profile, RANGE_PROFILE_SIZE) == 0) {
                // Decode magic word
                if (decode_magic_word(range_profile, RANGE_PROFILE_SIZE, magic_word) == 0) {
                    // Detect target
                    if (detect_target(range_profile, RANGE_PROFILE_SIZE) == 1) {
                        // Get current timestamp
                        time(&rawtime);
                        timeinfo = localtime(&rawtime);
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                        // Log intrusion
                        distance = 0.0; // Placeholder, replace with actual distance calculation
                        if (log_intrusion(timestamp, distance) != 0) {
                            fprintf(stderr, "Error logging intrusion\n");
                        }

                        // Activate alert
                        if (activate_alert(GPIO_LED, ALERT_DURATION) != 0) {
                            fprintf(stderr, "Error activating alert\n");
                        }
                    }
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading data from UART\n");
            break; // Exit loop on UART read error
        }

        gpioDelay(10000); // Delay to avoid busy-waiting (10ms)
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (uart_fd != -1) {
        uart_close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_cleanup(GPIO_LED);

    printf("Exiting.\n");
    return 0;
}

