#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000 // Hz
#define PWM_DUTY_CYCLE_RANGE 1000 // 0-1000
#define PWM_PERIOD 1000000 / PWM_FREQUENCY // Period in microseconds
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
void set_led_frequency(uint16_t distance);
void log_data(uint16_t distance, uint16_t led_frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    // Trigger measurement (write 0x00 to register 0x00)
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteByte(i2c_handle, 0x00);
        if (result == 0) break; // Success
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break; // Success
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
