#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file name
#define LOG_FILE "proximity_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_id;
    int last_state;
    int debounce_counter;
    int last_log_time;
} sensor_data_t;

// Global variables
FILE *log_file = NULL;
sensor_data_t sensor1_data, sensor2_data;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void log_event(int sensor_id, const char *event_type);
void cleanup();
void signal_handler(int signal);

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log an event to the log file
void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM) for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to clean up resources before exiting
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize sensor data structures
    sensor1_data.gpio = SENSOR1_GPIO;
    sensor1_data.sensor_id = 1;
    sensor1_data.last_state = read_sensor(SENSOR1_GPIO);
    sensor1_data.debounce_counter = 0;
    sensor1_data.last_log_time = 0;

    sensor2_data.gpio = SENSOR2_GPIO;
    sensor2_data.sensor_id = 2;
    sensor2_data.last_state = read_sensor(SENSOR2_GPIO);
    sensor2_data.debounce_counter = 0;
    sensor2_data.last_log_time = 0;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor 1
        int sensor1_state = read_sensor(SENSOR1_GPIO);

        // Debounce sensor 1
        if (sensor1_state != sensor1_data.last_state) {
            sensor1_data.debounce_counter++;
            if (sensor1_data.debounce_counter >= DEBOUNCE_TIME) {
                sensor1_data.last_state = sensor1_state;
                if (sensor1_state == 0) { // Obstacle detected
                    log_event(sensor1_data.sensor_id, "DETECTED");
                } else { // Obstacle cleared
                    log_event(sensor1_data.sensor_id, "CLEARED");
                }
                sensor1_data.debounce_counter = 0; // Reset debounce counter
            }
        }

        // Read sensor 2
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Debounce sensor 2
        if (sensor2_state != sensor2_data.last_state) {
            sensor2_data.debounce_counter++;
            if (sensor2_data.debounce_counter >= DEBOUNCE_TIME) {
                sensor2_data.last_state = sensor2_data.last_log_time = sensor2_state;
                if (sensor2_state == 0) { // Obstacle detected
                    log_event(sensor2_data.sensor_id, "DETECTED");
                } else { // Obstacle cleared
                    log_event(sensor2_data.sensor_id, "CLEARED");
                }
                sensor2_data.debounce_counter = 0; // Reset debounce counter
            }
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms = 10000 microseconds
    }

    return 0;
}

