    sensor1_data.last_log_time = 0;

    sensor2_data.gpio = SENSOR2_GPIO;
    sensor2_data.sensor_id = 2;
    sensor2_data.last_state = read_sensor(SENSOR2_GPIO);
    sensor2_data.debounce_counter = 0;
    sensor2_data.last_log_time = 0;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor 1
        int sensor1_state = read_sensor(SENSOR1_GPIO);

        // Debounce sensor 1
        if (sensor1_state != sensor1_data.last_state) {
            sensor1_data.debounce_counter++;
            if (sensor1_data.debounce_counter >= DEBOUNCE_TIME) {
                sensor1_data.last_state = sensor1_state;
                if (sensor1_state == 0) { // Obstacle detected
                    log_event(sensor1_data.sensor_id, "DETECTED");
                } else { // Obstacle cleared
                    log_event(sensor1_data.sensor_id, "CLEARED");
                }
                sensor1_data.debounce_counter = 0; // Reset debounce counter
            }
        }

        // Read sensor 2
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Debounce sensor 2
        if (sensor2_state != sensor2_data.last_state) {
            sensor2_data.debounce_counter++;
            if (sensor2_data.debounce_counter >= DEBOUNCE_TIME) {
                sensor2_data.last_state = sensor2_data.last_log_time = sensor2_state;
                if (sensor2_state == 0) { // Obstacle detected
                    log_event(sensor2_data.sensor_id, "DETECTED");
                } else { // Obstacle cleared
                    log_event(sensor2_data.sensor_id, "CLEARED");
                }
                sensor2_data.debounce_counter = 0; // Reset debounce counter
            }
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms = 10000 microseconds
    }

    return 0;
}

