#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define CH101_I2C_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define DISTANCE_SCALE_FACTOR 0.1 // Example scale factor, adjust as needed
#define DISTANCE_OFFSET 0.0       // Example offset, adjust as needed

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

int i2c_read_register(int fd, int reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Error reading register");
        return -1;
    }
    return buf[0];
}

int i2c_write_register(int fd, int reg, int value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

int read_distance(int fd) {
    int status = i2c_read_register(fd, MEAS_STATUS_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading MEAS_STATUS register\n");
        return -1;
    }

    // Check if measurement is ready (example: status bit is set)
    if (status & 0x01) {
        // Read distance
        int distance = i2c_read_register(fd, DISTANCE_REG);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance register\n");
            return -1;
        }
        return (int)(distance * DISTANCE_SCALE_FACTOR + DISTANCE_OFFSET);
    } else {
        fprintf(stderr, "Measurement not ready\n");
        return -1;
    }
}

int log_distance(const char *filename, int distance) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = i2c_open(I2C_DEVICE);
    if (fd < 0) {
        return 1;
    }

    if (i2c_set_slave_address(fd, CH101_I2C_ADDR) < 0) {
        i2c_close(fd);
        return 1;
    }

    FILE *fp = fopen("distance_log.csv", "w");
    if (fp == NULL) {
        perror("Error creating log file");
        i2c_close(fd);
        return 1;
    }

    fprintf(fp, "timestamp,distance_mm\n"); // Write header

    while (program_running) {
        int distance = read_distance(fd);
        if (distance >= 0) {
            if (log_distance("distance_log.csv", distance) < 0) {
                fprintf(stderr, "Error logging distance\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        usleep(500000); // 500ms
    }

    i2c_close(fd);
    fclose(fp);

    return 0;
}

