#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// VL53L5CX register addresses (Example, adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L5CX_REG_SYSRANGE_START 0x0040
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L5CX_REG_RESULT_DISTANCE 0x001E
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG 0x0088
#define VL53L5CX_REG_SYSRANGE_CONFIG 0x0080
#define VL53L5CX_REG_MEASURE_CONFIG 0x0082
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG 0x0088
#define VL53L5CX_REG_SYSRANGE_START 0x0040
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L5CX_REG_RESULT_DISTANCE 0x001E
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG 0x0088
#define VL53L5CX_REG_SYSRANGE_CONFIG 0x0080
#define VL53L5CX_REG_MEASURE_CONFIG 0x0082

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to write a byte to a VL53L5CX register
int vl53l5cx_write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L5CX register
int vl53l5cx_read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int vl53l5cx_init(int handle) {
    // Example initialization sequence (adjust based on datasheet)
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L5CX_ADDR) != 0) return -1;
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_SYSRANGE_START, 0x01) != 0) return -1; // Start continuous ranging
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_MEASURE_CONFIG, 0x00) != 0) return -1; // Set measurement mode
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_SYSRANGE_CONFIG, 0x00) != 0) return -1; // Set ranging mode
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x00) != 0) return -1;
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG, 0x00) != 0) return -1;

    return 0;
}

// Function to read distance data from all 64 zones
int vl53l5cx_read_distance_data(int handle, uint16_t *distances) {
    uint8_t range_status;
    uint8_t distance_high, distance_low;

    // Read range status
    if (vl53l5cx_read_register(handle, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) return -1;

    // Read distance data (64 zones)
    for (int i = 0; i < 64; i++) {
        if (vl53l5cx_read_register(handle, VL53L5CX_REG_RESULT_DISTANCE + (i * 2), &distance_high) != 0) return -1;
        if (vl53l5cx_read_register(handle, VL53L5CX_REG_RESULT_DISTANCE + (i * 2) + 1, &distance_low) != 0) return -1;

        distances[i] = (distance_high << 8) | distance_low;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L5CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L5CX sensor
    if (vl53l5cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t distances[64];

    // Main loop
    while (!terminate) {
        // Read distance data
        if (vl53l5cx_read_distance_data(i2c_handle, distances) == 0) {
            // Print distance data
            for (int i = 0; i < 64; i++) {
                printf("Zone %d: %d mm\n", i, distances[i]);
            }
        } else {
            fprintf(stderr, "Error reading distance data\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

