#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L4CX_REG_SYSTEM_START 0x0000
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_SPAD_NB 0x001E
#define VL53L4CX_REG_RESULT_DISTANCE 0x0020
#define VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L4CX_REG_SYSRANGE_START 0x000
#define VL53L4CX_REG_SYSRANGE_STOP 0x002
#define VL53L4CX_REG_MEASURE_MODE 0x0010
#define VL53L4CX_REG_INTERMEASUREMENT_PERIOD 0x001E
#define VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L4CX_REG_SYSRANGE_START 0x000
#define VL53L4CX_REG_SYSRANGE_STOP 0x002
#define VL53L4CX_REG_MEASURE_MODE 0x0010
#define VL53L4CX_REG_INTERMEASUREMENT_PERIOD 0x001E

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l4cx();
int read_distance(int *distance);
void log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize VL53L4CX sensor
int init_vl53l4cx() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Set I2C address
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L4CX_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_MEASURE_MODE, 0x01) < 0) {
        fprintf(stderr, "Error setting continuous ranging mode\n");
        return -1;
    }

    // Set inter-measurement period
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERMEASUREMENT_PERIOD, 0x0A) < 0) {
        fprintf(stderr, "Error setting inter-measurement period\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L4CX sensor
int read_distance(int *distance) {
    int range_status;
    int distance_msb, distance_lsb;

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", range_status);
        return -1;
    }

    // Read distance MSB
    distance_msb = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_DISTANCE);
    if (distance_msb < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", distance_msb);
        return -1;
    }

    // Read distance LSB
    distance_lsb = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_DISTANCE + 1);
    if (distance_lsb < 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", distance_lsb);
        return -1;
    }

    // Combine MSB and LSB to get distance in mm
    *distance = (distance_msb << 8) | distance_lsb;

    return 0;
}

// Log distance data with timestamp
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx() != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distance;
    int interrupt_status;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Log distance
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Poll interrupt status
        interrupt_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS);
        if (interrupt_status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", interrupt_status);
        }

        // Check if interrupt is set
        if (interrupt_status > 0) {
            // Read distance
            if (read_distance(&distance) == 0) {
                // Log distance
                log_distance(distance);
            } else {
                fprintf(stderr, "Error reading distance after interrupt\n");
            }
        }

        // Delay
        gpioDelay(500000); // 500ms
    }

    // Cleanup
    cleanup();

    return 0;
}

