#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define TIMEOUT_MS 50
#define SERVO_MIN_PULSE_WIDTH 1000 // Minimum pulse width in microseconds
#define SERVO_MAX_PULSE_WIDTH 2000 // Maximum pulse width in microseconds
#define SERVO_RANGE 180            // Servo angle range in degrees
#define MIN_DISTANCE 2.0           // Minimum distance in cm
#define MAX_DISTANCE 400.0          // Maximum distance in cm

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void trigger_pulse();
float get_distance();
void set_servo_angle(float distance);
void log_data(float distance);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0) {
        pulse_end = tick;
        echo_received = 2; // Indicate that the falling edge has been received
    }
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float get_distance() {
    timeout_flag = 0; // Reset timeout flag
    echo_received = 0; // Reset echo received flag

    trigger_pulse();
    pulse_start = 0;
    pulse_end = 0;
    echo_received = 0;

    // Wait for echo or timeout
    int start_time = gpioTick();
    while (!echo_received && (gpioTick() - start_time) < (TIMEOUT_MS * 1000)) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (echo_received == 0) {
        fprintf(stderr, "Error: Timeout occurred.\n");
        return -1.0; // Return a sentinel error value
    }

    // Calculate pulse duration
    int pulse_duration = pulse_end - pulse_start;
    if (pulse_duration < 0) {
        pulse_duration += 0xFFFFFFFF; // Handle wrap-around
    }

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (pulse_duration / 1000000.0) * 34300.0 / 2.0;

    return distance;
}

// Function to set the servo angle based on the distance
void set_servo_angle(float distance) {
    // Linear mapping from distance to servo angle
    float angle = -90.0 + (distance - MIN_DISTANCE) * (SERVO_RANGE / (MAX_DISTANCE - MIN_DISTANCE));

    // Clamp angle to servo range
    if (angle < -90.0) {
        angle = -90.0;
    } else if (angle > 90.0) {
        angle = 90.0;
    }

    // Convert angle to pulse width (SG90 servo)
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / 90.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log the distance data to a file
void log_data(float distance) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", s, distance);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        float distance = get_distance();

        if (distance > 0) {
            set_servo_angle(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        gpioDelay(200); // Delay for 200 ms
    }

    return 0;
}

