#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_BUZZER 23
#define MESSAGE_QUEUE_NAME "/tmp/queue"
#define DISTANCE_THRESHOLD 100 // mm
#define TIMEOUT_US 50000       // 50ms

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0020
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
int message_queue_fd;
void *message_queue;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void activate_buzzer(int state);
void signal_handler(int signal);
int create_message_queue();
void destroy_message_queue();
void map_message_queue();

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) { // Example: Set ranging mode
        fprintf(stderr, "Error writing to VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // Delay for 1ms

    // Check sensor ID (example)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%X\n", sensor_id);
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // Wait for measurement to complete (adjust as needed)

    // Read the distance
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

// Function to activate the buzzer
void activate_buzzer(int state) {
    gpioWrite(GPIO_BUZZER, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to create the message queue
int create_message_queue() {
    if (mkfifo(MESSAGE_QUEUE_NAME, 0666) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to destroy the message queue
void destroy_message_queue() {
    if (unlink(MESSAGE_QUEUE_NAME) == -1) {
        fprintf(stderr, "Error destroying message queue: %s\n", strerror(errno));
    }
}

// Function to map the message queue
void map_message_queue() {
    if (message_queue = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, message_queue_fd, 0) == MAP_FAILED) {
        fprintf(stderr, "Error mapping message queue: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to unmap the message queue
void unmap_message_queue() {
    if (munmap(message_queue, 0) == -1) {
        fprintf(stderr, "Error unmapping message queue: %s\n", strerror(errno));
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GPIO_BUZZER, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    if (create_message_queue() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Map message queue
    map_message_queue();

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);

        // Send data to message queue
        if (msgsnd(message_queue, (const char *)&distance, sizeof(distance), 0) == -1) {
            fprintf(stderr, "Error sending message: %s\n", strerror(errno));
        } else {
            // Log timestamp
            printf("Timestamp: %ld, Distance: %d mm\n", now, distance);
        }

        // Check distance threshold and activate buzzer
        if (distance < DISTANCE_THRESHOLD) {
