        } else {
            activate_buzzer(0); // Turn off buzzer
        }

        gpioDelay(TIMEOUT_US); // Wait for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    destroy_message_queue();
    unmap_message_queue();
    gpioTerminate();

