#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_THRESHOLD 30.0   // cm

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;
volatile int distance = 0.0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start_tick, uint32_t end_tick);
void control_buzzer(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start_tick, uint32_t end_tick) {
    if (!echo_valid) {
        return -1.0; // Indicate invalid reading
    }

    double diff = (double)(end_tick - start_tick);
    if (diff < 0) {
        diff += 4294967296.0; // Handle tick wraparound
    }

    double time_taken = diff / 1000000.0; // Convert to seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate out-of-range reading
    }

    return distance;
}

// Function to control the buzzer
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt callback
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100); // Wait 100ms

        if (echo_valid) {
            distance = calculate_distance(echo_start_tick, echo_end_tick);
            if (distance >= 0) {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            } else {
                printf("Invalid reading or timeout.\n");
            }
        } else {
            printf("No echo received.\n");
        }
    }

    return 0;
}

