#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSE_WIDTH 1500
#define SERVO_CLOSE_PULSE_WIDTH 1000
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP 0x001E
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP 0x0020
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_SPAD_NB_DETECTED 0x008A
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
int vl53l1x_reset();
int servo_open();
int servo_close();
int send_command(const char *command);
void log_event(const char *message);
void signal_handler(int signal);

// VL53L1X Initialization
int vl53l1x_init() {
    int status;
    int model_id;

    // Reset the sensor
    if (vl53l1x_reset() != 0) {
        log_event("VL53L1X reset failed");
        return -1;
    }

    gpioDelay(100); // Wait for reset to complete

    // Check sensor ID
    model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        log_event("Failed to read VL53L1X model ID");
        return -1;
    }

    if (model_id != 0xEACC) {
        log_event("Incorrect VL53L1X model ID");
        return -1;
    }

    // Configure ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP, 0x00); // Set timeout to 50ms
    if (status < 0) {
        log_event("Failed to write to VL53L1X");
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP, 0x00); // Set timeout to 50ms
    if (status < 0) {
        log_event("Failed to write to VL53L1X");
        return -1;
    }

    log_event("VL53L1X initialized successfully");
    return 0;
}

// VL53L1X Reset
int vl53l1x_reset() {
    int status;
    char data[2];

    data[0] = 0x00; // Reset command
    data[1] = 0x04; // Register address for reset

    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status < 0) {
        log_event("Failed to write reset command to VL53L1X");
        return -1;
    }

    gpioDelay(100); // Wait for reset to complete
    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int *distance) {
    int status;
    char data[1];
    char result[2];

    // Start ranging
    data[0] = VL53L1X_REG_SYSRANGE_START;
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        log_event("Failed to start ranging");
        return -1;
    }

    gpioDelay(10); // Wait for measurement

    // Read distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status < 0) {
        log_event("Failed to write to VL53L1X");
        return -1;
    }

    status = i2cReadDevice(i2c_handle, result, 2);
    if (status < 0) {
        log_event("Failed to read distance from VL53L1X");
        return -1;
    }

    *distance = (result[0] << 8) | result[1];

    return 0;
}

// Servo Open
int servo_open() {
    gpioServo(SERVO_PIN, SERVO_OPEN_PULSE_WIDTH);
    log_event("Servo opened");
    return 0;
}

// Servo Close
int servo_close() {
    gpioServo(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
    log_event("Servo closed");
    return 0;
}

// Send Command
int send_command(const char *command) {
    FILE *fp = fopen("gate_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s\n", command);
    fclose(fp);
    return 0;
}

// Log Event
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    int distance;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Failed to open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (vl53l1x_init() != 0) {
        log_event("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Gate control system started");

    while (program_running) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (vl53l1x_read_distance(&distance) == 0) {
                log_event("Distance read");
                if (distance < DISTANCE_THRESHOLD) {
                    servo_open();
                } else {
                    servo_close();
                }
                break; // Exit retry loop on success
            } else {
                log_event("Failed to read distance, retrying...");
                retry++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retry == RETRY_COUNT) {
            log_event("Failed to read distance after multiple retries");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    servo_close();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Gate control system stopped");

    return 0;
}

