    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status < 0) {
        log_event("Failed to write reset command to VL53L1X");
        return -1;
    }

    gpioDelay(100); // Wait for reset to complete
    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int *distance) {
    int status;
    char data[1];
    char result[2];

    // Start ranging
    data[0] = VL53L1X_REG_SYSRANGE_START;
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        log_event("Failed to start ranging");
        return -1;
    }

    gpioDelay(10); // Wait for measurement

    // Read distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status < 0) {
        log_event("Failed to write to VL53L1X");
        return -1;
    }

    status = i2cReadDevice(i2c_handle, result, 2);
    if (status < 0) {
        log_event("Failed to read distance from VL53L1X");
        return -1;
    }

    *distance = (result[0] << 8) | result[1];

    return 0;
}

// Servo Open
int servo_open() {
    gpioServo(SERVO_PIN, SERVO_OPEN_PULSE_WIDTH);
    log_event("Servo opened");
    return 0;
}

// Servo Close
int servo_close() {
    gpioServo(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
    log_event("Servo closed");
    return 0;
}

// Send Command
int send_command(const char *command) {
    FILE *fp = fopen("gate_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s\n", command);
    fclose(fp);
    return 0;
}

// Log Event
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    int distance;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Failed to open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (vl53l1x_init() != 0) {
        log_event("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Gate control system started");

    while (program_running) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (vl53l1x_read_distance(&distance) == 0) {
                log_event("Distance read");
                if (distance < DISTANCE_THRESHOLD) {
                    servo_open();
                } else {
                    servo_close();
                }
                break; // Exit retry loop on success
            } else {
                log_event("Failed to read distance, retrying...");
                retry++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retry == RETRY_COUNT) {
            log_event("Failed to read distance after multiple retries");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    servo_close();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Gate control system stopped");

    return 0;
}

