#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT 30000          // 30 ms timeout
#define NOISE_THRESHOLD 100     // 100 us noise threshold
#define TIMEOUT_THRESHOLD 30000 // 30 ms timeout threshold
#define SAMPLE_RATE 5           // 5 Hz sampling rate

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static volatile int echo_duration = 0;
static volatile int echo_distance = 0;
static volatile int echo_timestamp = 0;
static volatile int echo_valid_duration = 0;
static volatile int echo_valid_distance = 0;
static volatile int echo_valid_timestamp = 0;
static volatile int echo_valid_duration_duration = 0;
static volatile int echo_valid_duration_distance = 0;
static volatile int echo_valid_duration_timestamp = 0;
static volatile int echo_valid_distance_duration = 0;
static volatile int echo_valid_distance_timestamp = 0;
static volatile int echo_valid_duration_timestamp_duration = 0;
static volatile int echo_valid_duration_distance_duration = 0;
static volatile int echo_valid_distance_timestamp_duration = 0;
static volatile int echo_valid_duration_timestamp_duration_duration = 0;
static volatile int echo_valid_distance_timestamp_duration_duration = 0;

static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void alert_callback(int gpio, int level, uint32_t tick);
void log_data();
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 0; // Reset validity flag
    }
}

// Callback function for alert (rising and falling edges)
void alert_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 0; // Reset validity flag
    }
}

// Function to log data to stdout and file
void log_data() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (echo_valid) {
        double duration = (double)(echo_end_tick - echo_start_tick) / 1000000.0; // in seconds
        echo_duration = (int)(duration * SPEED_OF_SOUND / 2.0); // in cm
        echo_distance = (int)echo_duration;
        echo_timestamp = (int)(duration * 1000000.0); // in microseconds

        if (echo_duration > TIMEOUT_THRESHOLD || echo_duration < NOISE_THRESHOLD) {
            fprintf(stderr, "Warning: Invalid echo duration: %.2f seconds\n", duration);
        } else {
            printf("%s Distance: %.2f cm\n", timestamp, (double)echo_distance / 100.0); // cm
            fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, (double)echo_distance / 100.0); // cm
            fflush(log_file);
        }
    } else {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(stderr, "Warning: No echo received within %.2f seconds\n", 0.5); // 0.5 seconds timeout
        fprintf(log_file, "%s Warning: No echo received within %.2f seconds\n", timestamp, 0.5); // seconds
        fflush(log_file);
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    gpioSetAlertFuncEx(ECHO_PIN, alert_callback, NULL); // Use alert callback for both rising and falling edges
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(200000); // 200 ms delay
    }

    // Cleanup and exit
    fclose(log_file);
    cleanup_gpio();
    return 0;
}

