int main()
{
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(VL53L1X_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        return 1;
    }

    // Initialize SPI for servo
    if (wiringPiSPISetup(0, 1000000) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set servo pin to PWM output mode
    pinMode(SERVO_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(SERVO_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD_HIGH && !gate_open) {
                servo_open();
                gate_open = 1;
                log_event("Gate opened");
            } else if (distance > DISTANCE_THRESHOLD_LOW && gate_open) {
                servo_close();
                gate_open = 0;
                log_event("Gate closed");
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        delay(100); // Delay for 100ms
    }

    // Cleanup
    servo_close();
    fclose(log_file);
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init()
{
    uint8_t model_id;

    // Check model ID
    if (vl53l1x_check_model_id() != 0) {
        fprintf(stderr, "VL53L1X model ID check failed.\n");
        return -1;
    }

    // Send initialization sequence
    for (int i = 0; i < sizeof(init_sequence); i++) {
        if (vl53l1x_write_byte(0x00, init_sequence[i]) != 0) {
            fprintf(stderr, "VL53L1X write failed during init.\n");
            return -1;
        }
        delay(1); // Small delay between writes
    }

    return 0;
}

// VL53L1X model ID check function
int vl53l1x_check_model_id()
{
    uint8_t model_id;
    int result = 0;

    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID.\n");
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance()
{
    uint8_t range;
    int distance = -1;

    // Read range status
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_RANGE_STATUS, &range) != 0) {
        fprintf(stderr, "Failed to read range status.\n");
        return -1;
    }

    // Read distance
    if (range & 0x01) {
        if (vl53l1x_read_byte(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range) != 0) {
            fprintf(stderr, "Failed to read distance data.\n");
            return -1;
        }
        distance = range;
    } else {
        fprintf(stderr, "No object detected.\n");
    }

    return distance;
