#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define POLLING_INTERVAL 500 // ms

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP 0x001E
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP 0x0020
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_SPAD_NB_DETECTED 0x008A
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_start_ranging(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);
int vl53l1x_read_register(int i2c_handle, uint8_t reg, uint8_t *value);
int vl53l1x_write_register(int i2c_handle, uint8_t reg, uint8_t value);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// VL53L1X Initialization
int vl53l1x_init(int i2c_handle) {
    uint8_t model_id, revision_id;

    // Check sensor ID
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure timing budget (example values)
    if (vl53l1x_write_register(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP, 0x00) != 0) return -1;
    if (vl53l1x_write_register(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP, 0x50) != 0) return -1;

    printf("VL53L1X initialized successfully\n");
    return 0;
}

// VL53L1X Start Ranging
int vl53l1x_start_ranging(int i2c_handle) {
    if (vl53l1x_write_register(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }
    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int i2c_handle) {
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;

    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    if (range_status & 0x01) {
        if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (uint8_t *) &distance_msb) != 0) return -1;
        if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, (uint8_t *) &distance_lsb) != 0) return -1;

        int distance = (distance_msb << 8) | distance_lsb;
        return distance;
    } else {
        return -1; // No object detected
    }
}

// Control Gate
void control_gate(int distance) {
    if (distance > 0 && distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
        log_event("Gate Open");
    } else {
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
        log_event("Gate Closed");
    }
}

// Log Event
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, event);
}

// VL53L1X Read Register
int vl53l1x_read_register(int i2c_handle, uint8_t reg, uint8_t *value) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        fprintf(stderr, "Error reading register value\n");
        return -1;
    }
    return 0;
}

// VL53L1X Write Register
int vl53l1x_write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register value\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            control_gate(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(POLLING_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

