        if (mpr121_write_register(i2c_handle, 0x42 + 2 * i, 0x10) < 0) return -1; // Release threshold
    }

    // Filter Configuration
    if (mpr121_write_register(i2c_handle, 0x5B, 0x06) < 0) return -1; // Filter control register
    if (mpr121_write_register(i2c_handle, 0x5C, 0x01) < 0) return -1; // Filter control register

    // Debounce Configuration
    if (mpr121_write_register(i2c_handle, 0x5D, 0x01) < 0) return -1; // Debounce control register

    // Enter Run Mode
    if (mpr121_write_register(i2c_handle, 0x80, 0x00) < 0) return -1;
    gpioDelay(1); // Delay for 1 ms

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int i2c_handle) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        return -1;
    }
    return ((uint16_t)buf[1] << 8) | buf[0];
}

// MPR121 write register function
int mpr121_write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteI2CBlockData(i2c_handle, reg, buf, 1) != 1) {
        return -1;
    }
    return 0;
}

// MPR121 read register function
int mpr121_read_register(int i2c_handle, uint8_t reg) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteI2CBlockData(i2c_handle, reg, buf, 1) != 1) {
        return -1;
    }
    char data[1];
    if (i2cReadI2CBlockData(i2c_handle, reg, data, 1) != 1) {
        return -1;
    }
    return data[0];
}

// LED on function
void led_on(int gpio) {
    gpioWrite(gpio, 1);
}

// LED off function
void led_off(int gpio) {
    gpioWrite(gpio, 0);
}

// Log proximity event function
void log_proximity_event(const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Proximity event detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    int device_id = mpr121_read_register(i2c_handle, 0x00);
    if (device_id != 0x5A) {
        fprintf(stderr, "MPR121 not found. Device ID: 0x%X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        // Check for proximity event
        if (touch_status > 0) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

            // Re-read touch status to confirm
            touch_status = mpr121_read_touch_status(i2c_handle);
            if (touch_status > 0) {
                // Proximity event detected
                printf("Proximity event detected!\n");
                led_on(LED_GPIO);
                gpioDelay(1000000); // 1 second
                led_off(LED_GPIO);
                log_proximity_event("proximity.log");
            }
        }

        gpioDelay(10000); // Check every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

