    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(5); // 5 us
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10); // 10 us
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout_count = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout_count++ > TIMEOUT_US) {
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    start_time = gpioTick();

    // Wait for the echo pin to go low
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout_count++ > TIMEOUT_US) {
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    end_time = gpioTick();

    return end_time - start_time;
}

