// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static volatile int echo_width = 0;
static volatile int echo_valid_width = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(int pulse_width);
void log_distance(double distance);
