// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine for echo pin
void echo_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 1;
        echo_width = 0;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid_width = echo_end_tick - echo_start_tick;
        if (echo_valid_width > 0) {
            echo_width = echo_valid_width;
            echo_valid = 1;
        } else {
            echo_valid = 0;
        }
    }
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

