#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for XSHUT
#define XSHUT_GPIO 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_fd = -1;
int running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int init_sensor(int i2c_fd);
int read_distance(int i2c_fd);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", filename);
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %d", addr);
        close(fd);
        return -1;
    }
    return fd;
}

// Initialize the VL53L1X sensor
int init_sensor(int i2c_fd) {
    // Example initialization sequence (refer to VL53L1X datasheet)
    // This is a simplified example and may need adjustments
    unsigned char init_data[] = {0x00, 0x01}; // Example register and value
    if (write(i2c_fd, init_data, sizeof(init_data)) != sizeof(init_data)) {
        syslog(LOG_ERR, "Failed to write to sensor during initialization");
        return -1;
    }
    gpioWrite(XSHUT_GPIO, 0); // Enable sensor
    gpioDelay(100); // Short delay
    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int i2c_fd) {
    unsigned char cmd[] = {0x00, 0x00}; // Example command to trigger a measurement
    unsigned char data[2]; // Example buffer to store the distance
    int distance = -1; // Default value in case of error

    // Trigger a measurement
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        syslog(LOG_ERR, "Failed to write to sensor to trigger measurement");
        return -1;
    }

