#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0020
#define VL53L1X_REG_START_STOP_MEASURE 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    char data[2];
    int status;

    // Check sensor ID
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 1);
    if (status != 1) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Set ranging mode (e.g., short distance)
    data[0] = VL53L1X_REG_RANGING_MODE;
    data[1] = 0x02; // Short distance mode
    status = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1);
    if (status != 1) {
        fprintf(stderr, "Error writing ranging mode: %d\n", status);
        return -1;
    }

    // Start continuous ranging
    data[0] = VL53L1X_REG_START_STOP_MEASURE;
    data[1] = 0x01; // Start continuous ranging
    status = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1);
    if (status != 1) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    int status;
    int distance_mm;

    // Read distance
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    distance_mm = (data[0] << 8) | data[1];

    return distance_mm;
}

// Function to control the gate actuator
void control_gate(int distance) {
    int gate_state = 0; // 0 = closed, 1 = open

    if (distance < DISTANCE_THRESHOLD) {
        gate_state = 1; // Open the gate
    } else {
        gate_state = 0; // Close the gate
    }

    gpioWrite(GPIO_GATE, gate_state);
}

// Function to log data to a file
void log_data(int distance, int gate_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Gate: %s\n", timestamp, (float)distance / 10.0, gate_state ? "Open" : "Closed");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

int main() {
    int distance;
    int gate_state;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GPIO_GATE, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance >= 0) {
            control_gate(distance);
            gate_state = gpioRead(GPIO_GATE);
            log_data(distance, gate_state);
        } else {
            fprintf(stderr, "Error reading distance, skipping gate control\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

