#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define PULSE_WIDTH_US 10       // 10us pulse width
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for SG90 (us)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for SG90 (us)
#define SERVO_RANGE 2000         // Range of pulse widths for SG90 (us)
#define MAX_DISTANCE 400.0      // Maximum measurable distance (cm)
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)

// Global variables
volatile sig_atomic_t program_running = 1;
volatile int new_pulse = 0;
volatile int pulse_width = 0;
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;

// Function prototypes
void trigger_sensor();
float measure_distance();
void set_servo_angle(int angle);
void log_data(float distance, int angle);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(PULSE_WIDTH_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure distance using the ultrasonic sensor
float measure_distance() {
    echo_valid = 0; // Reset echo validity flag
    echo_start_tick = 0;
    echo_end_tick = 0;

    trigger_sensor();

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    echo_start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    echo_end_tick = gpioTick();

    // Calculate pulse width
    int pulse_width_us = echo_end_tick - echo_start_tick;
    if (pulse_width_us < 0) {
        pulse_width_us += 0xFFFFFFFF; // Handle tick rollover
    }

    // Validate pulse width
    if (pulse_width_us > 50000) { // 50ms timeout for echo
        fprintf(stderr, "Error: Invalid pulse width: %d us\n", pulse_width_us);
        return -1.0; // Indicate error
    }

    // Calculate distance
    float distance = (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Invalid distance: %.2f cm\n", distance);
        return -1.0; // Indicate error
    }

    echo_valid = 1; // Set echo validity flag
    return distance;
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return;
    }

    // Calculate pulse width based on angle (SG90 servo)
    int pulse_width_us = (int)(((float)angle / 180.0) * SERVO_RANGE + SERVO_MIN_PULSE_WIDTH);

    gpioServo(SERVO_PIN, pulse_width_us);
}

// Function to log data to a file
void log_data(float distance, int angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv\n");
        return;
    }

    // Write header if the file is new
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Distance(cm),Angle(deg)\n");
    }

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    fprintf(fp, "%s,%.2f,%d\n", timestamp, distance, angle);
    fclose(fp);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        echo_start_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;
        if (echo_start_tick != 0 && echo_end_tick != 0) {
            int pulse_width_us = echo_end_tick - echo_start_tick;
            if (pulse_width_us < 0) {
                pulse_width_us += 0xFFFFFFFF; // Handle tick rollover
            }

            if (pulse_width_us > 50000) { // 50ms timeout for echo
                echo_valid = 0; // Indicate invalid echo
                return;
            }

            echo_valid = 1; // Set echo validity flag
            new_pulse = 1; // Set the flag to indicate a new pulse width
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Stopping program...\n");
        program_running = 0;

        // Stop the servo
        set_servo_angle(90);

        // Close the CSV file
        FILE *fp = fopen("distance_log.csv", "a");
        if (fp != NULL) {
            fclose(fp);
        }

        // Cleanup
        gpioTerminate();

        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
