    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_led(int distance);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the last added value from the circular buffer
int get_last_value(CircularBuffer *cb) {
    if (cb->count == 0) {
        return -1; // Indicate empty buffer
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[index];
}

