#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200 // mm

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP 0x0070
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0058

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_led(int distance);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the last added value from the circular buffer
int get_last_value(CircularBuffer *cb) {
    if (cb->count == 0) {
        return -1; // Indicate empty buffer
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[index];
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer distance_buffer;
    init_circular_buffer(&distance_buffer);

    // Main loop
    while (!terminate) {
        int distance;

        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Add distance to circular buffer
            add_to_circular_buffer(&distance_buffer, distance);

            // Control LED based on distance
            control_led(distance);

            // Print distance
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

