#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000      // 200ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_valid = 0;
volatile int current_frequency = 0; // Store the current frequency
volatile int running = 1; // Flag to control the main loop

// Function prototypes
void triggerSensor();
float getDistance();
float mapDistanceToFrequency(float distance);
void setPWMFrequency(int frequency);
void echoCallback(int gpio, int level, uint32_t tick);
void signalHandler(int signal);

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end = tick;
        if (echo_end - echo_start > TIMEOUT_US) {
            echo_valid = 0; // Timeout occurred
        } else {
            float pulse_width = (float)(echo_end - echo_start) / 1000000.0; // in seconds
            float distance = (SPEED_OF_SOUND * pulse_width) / 2.0;
            echo_valid = 1;
        }
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to get the distance from the sensor
float getDistance() {
    echo_valid = 0; // Reset validity flag
    echo_start = 0;  // Reset start time
    echo_end = 0;    // Reset end time

    triggerSensor();
    gpioDelay(50); // Wait for echo

    if (!echo_valid) {
        fprintf(stderr, "Error: Timeout or invalid echo data.\n");
        return -1.0; // Indicate an error
    }

    return (float)(echo_end - echo_start) / 1000000.0 * SPEED_OF_SOUND / 2.0; // in cm
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY * (1.0 + log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE));
    }
}

// Function to set the PWM frequency
void setPWMFrequency(int frequency) {
    if (frequency < 0) {
        frequency = 0;
    } else if (frequency > 2000) {
        frequency = 2000;
    }

    int range = 1000000 / frequency; // Calculate PWM range
    gpioSetPWMrange(PWM_PIN, range);
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, 500000 / range); // 50% duty cycle
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range and frequency (optional, but good practice)
    gpioSetPWMrange(PWM_PIN, 1000000); // Set PWM range to 1ms
    gpioSetPWMfrequency(PWM_PIN, 0);   // Set PWM frequency to 0 (stop PWM initially)

    // Register signal handler
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Set up interrupt on echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = getDistance();
        if (distance > 0) {
            float frequency = mapDistanceToFrequency(distance);
            setPWMFrequency((int)frequency);
            current_frequency = (int)frequency; // Update the global frequency
        } else {
            setPWMFrequency(current_frequency); // Preserve previous frequency if error
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    return 0;
}

