void triggerSensor();
long pulseIn(int pin, int level, long timeout);
float calculateDistance(long pulse_width);
float mapDistanceToFrequency(float distance);
void setFrequency(float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    running = 0;
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2);              // Wait 2 us
    gpioWrite(TRIGGER_PIN, 1); // Send a 10 us pulse
    gpioDelay(10);             // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
}

// Function to measure the pulse width of the echo signal
long pulseIn(int pin, int level, long timeout) {
    long start = gpioTick();
    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout) {
            return 0; // Timeout
        }
    }
    long pulse_start = gpioTick();
    while (gpioRead(pin) == level) {
        if (gpioTick() - pulse_start > timeout) {
            return 0; // Timeout
        }
    }
    return gpioTick() - pulse_start;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long pulse_width) {
    if (pulse_width <= 0) {
        return 0.0; // Invalid pulse width
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the frequency of the PWM signal
void setFrequency(float frequency) {
    int range = 1000; // PWM range
    int duty_cycle = (int)(range * frequency / 1000.0); // Calculate duty cycle
    gpioPWM(PWM_PIN, duty_cycle); // Set PWM frequency
}

