#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_MS 10
#define TRIGGER_PULSE_US 10000 // 10 us

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measure_pulse() {
    long start_tick, end_tick, pulse_duration;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_MS * 1000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_MS * 1000) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_MS * 1000) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_MS * 1000) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;

    return pulse_duration;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }

    double distance = (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance, convert us to s
    return distance;
}

// Function to validate the distance
int validate_distance(double distance) {
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to print the distance
void print_distance(double distance) {
    if (distance < 0) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_duration = measure_pulse();
        double distance = calculate_distance(pulse_duration);

        if (validate_distance(distance) == 1) {
            print_distance(distance);
        }

        gpioDelay(500); // Delay for 500ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

