#include <errno.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_VIS_DATA0 0x10
#define SI1120_REG_PS1_DATA0 0x18

// Si1120 reset command
#define SI1120_RESET_CMD 0x01

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_reset();
int si1120_read_register(int reg);
int si1120_write_register(int reg, int value);
int si1120_read_als_proximity();
void log_data(int als, int proximity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to reset the Si1120 sensor
int si1120_reset() {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET_CMD, SI1120_RESET_CMD);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error resetting Si1120: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
    return -1; // Failure
}

// Function to read a single byte from a Si1120 register
int si1120_read_register(int reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a single byte to a Si1120 register
int si1120_write_register(int reg, int value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read ALS and proximity data from the Si1120
int si1120_read_als_proximity() {
    int als_low, als_high, ps_low, ps_high;

    als_low = si1120_read_register(SI1120_REG_ALS_VIS_DATA0);
    if (als_low < 0) return -1;

    als_high = si1120_read_register(SI1120_REG_ALS_VIS_DATA0 + 1);
    if (als_high < 0) return -1;

    ps_low = si1120_read_register(SI1120_REG_PS1_DATA0);
    if (ps_low < 0) return -1;

    ps_high = si1120_read_register(SI1120_REG_PS1_DATA0 + 1);
    if (ps_high < 0) return -1;

    // Combine the bytes into 16-bit little-endian values
    int als = (als_high << 8) | als_low;
    int proximity = (ps_high << 8) | ps_low;

    return als | (proximity << 16); // Combine into a single 32-bit value
}

// Function to log the data to a file
void log_data(int als, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %d, Proximity: %d\n", timestamp, als, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

