    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Reset the Si1120 sensor
    if (si1120_reset() != 0) {
        fprintf(stderr, "Si1120 reset failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify the part ID
    int part_id = si1120_read_register(SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read part ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int als_proximity = si1120_read_als_proximity();
        if (als_proximity >= 0) {
            log_data(als_proximity >> 16, als_proximity & 0xFFFF);
        } else {
            fprintf(stderr, "Failed to read ALS/Proximity data\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

