#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the Si1182-A-GM I2C address
#define SI1182_A_GM_ADDR 0x39

// Define register addresses
#define SI1182_A_GM_REG_PART_ID 0x00
#define SI1182_A_GM_REG_MEAS_RATE 0x08
#define SI1182_A_GM_REG_ALS_DATA 0x22
#define SI1182_A_GM_REG_PS_DATA 0x24

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, int reg, int value);
int i2c_read_reg(int fd, int reg);
int si1182_init(int fd);
int read_sensor_data(int fd, float *lux, int *proximity);
void log_data(FILE *fp, float lux, int proximity);
void print_data(FILE *fp, float lux, int proximity);
void signal_handler(int signal);
char* get_timestamp();

// I2C write function
int i2c_write_reg(int fd, int reg, int value) {
    int result;
    unsigned char buf[2];

    buf[0] = reg;
    buf[1] = value;

    result = write(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, int reg) {
    int result;
    unsigned char buf[1];
    unsigned char read_buf[1];

    buf[0] = reg;

    result = write(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    result = read(fd, read_buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return read_buf[0];
}

// Si1182-A-GM initialization function
int si1182_init(int fd) {
    int part_id;

    // Verify part ID
    part_id = i2c_read_reg(fd, SI1182_A_GM_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID\n");
        return -1;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_reg(fd, SI1182_A_GM_REG_MEAS_RATE, 0x0A) != 0) { // Example value, check datasheet
        fprintf(stderr, "Error writing to measurement rate register\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, float *lux, int *proximity) {
    int als_data, ps_data;

    als_data = i2c_read_reg(fd, SI1182_A_GM_REG_ALS_DATA);
    if (als_data < 0) {
        fprintf(stderr, "Error reading ALS data\n");
