    int result;
    // Example initialization sequence (refer to Si1145 datasheet)
    result = i2cWriteByteData(i2c_handle, 0x18, 0x0F); // Enable PS1
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x18: %d\n", result);
        return -1;
    }
