        fprintf(stderr, "Error writing to register 0x19: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x1A, 0x00); // PS1 LED drive strength
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x1A: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x17, 0x01); // Enable force mode
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x17: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x18, 0x0F); // Enable PS1
    if (result < 0) {
