#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm
#define TIMEOUT_US 50000        // Timeout for echo pulse measurement (50ms)

// Global variables
static volatile int echo_start = 0;
static volatile int echo_end = 0;
static volatile int echo_valid = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(int pulse_width);
void set_buzzer(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioTerminate();
        running = 0;
        exit(0);
    }
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        echo_start = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end = tick;
        echo_valid = 1; // Set validity flag
    }
}

// Calculate distance from pulse width
double calculate_distance(int pulse_width) {
    if (!echo_valid) {
        return -1.0; // Indicate invalid measurement
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Set buzzer based on distance
void set_buzzer(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Buzzer off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for ECHO_PIN
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(100); // Delay between measurements

        if (echo_valid) {
            int pulse_width = echo_end - echo_start;
            if (pulse_width > TIMEOUT_US) {
                pulse_width = TIMEOUT_US; // Set to timeout value
