#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for servo (0 degrees)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for servo (180 degrees)
#define SERVO_CENTER_PULSE_WIDTH 1500 // Center pulse width for servo (90 degrees)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
void set_servo_angle(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();         // Terminate pigpio
        exit(0);
    }
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle based on distance
void set_servo_angle(float distance) {
    float angle;

    if (distance < 20.0) {
        angle = 180.0;
    } else if (distance > 200.0) {
        angle = 0.0;
    } else {
        angle = (distance - 20.0) / (200.0 - 20.0) * 90.0;
    }

    // Map distance to pulse width (microseconds)
    int pulse_width = (int)(SERVO_CENTER_PULSE_WIDTH + (angle / 90.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_CENTER_PULSE_WIDTH));

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            set_servo_angle(distance);
            printf("Distance: %.2f cm, Servo Angle: %.2f degrees\n", distance, (float)(gpioGetServoPulsewidth(SERVO_PIN) - SERVO_CENTER_PULSE_WIDTH) / 10.0);
