#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 18
#define DISTANCE_THRESHOLD_HIGH 250 // mm
#define DISTANCE_THRESHOLD_LOW 200  // mm
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 2000 // Range of PWM duty cycle (0-2000)
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void set_servo_pulse_width(int gpio, int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_CONFIG_TIMEOUT_MACROP 0x0010
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    // Check model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set timing budget (example value, adjust as needed)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_CONFIG_TIMEOUT_MACROP, 0x00) != 0) {
        fprintf(stderr, "Error writing to timing budget register\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to set the servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width) {
    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_GATE, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int distance;
    int pulse_width = 0; // Initial pulse width
    int target_pulse_width = 0; // Target pulse width for hysteresis

    // Main loop
    while (program_running) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        printf("Distance: %d mm\n", distance);

        // Hysteresis control
        if (distance > DISTANCE_THRESHOLD_HIGH) {
            target_pulse_width = 1000; // Close
        } else if (distance < DISTANCE_THRESHOLD_LOW) {
            target_pulse_width = 2000; // Open
        } else {
            target_pulse_width = 1500; // Middle
        }

        // Smooth transition
        pulse_width = (int)(((float)(target_pulse_width - pulse_width) / (target_pulse_width - DISTANCE_THRESHOLD_HIGH)) * (DISTANCE_THRESHOLD_HIGH - DISTANCE_THRESHOLD_LOW) + pulse_width);
        if (pulse_width < 0) pulse_width = 0;
        if (pulse_width > PWM_RANGE) pulse_width = PWM_RANGE;

        set_servo_pulse_width(GPIO_GATE, pulse_width);

        // Log event
        char event[50];
        snprintf(event, sizeof(event), "Gate opened to %d us", pulse_width);
        log_event(event);

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    set_servo_pulse_width(GPIO_GATE, 0); // Stop the servo
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

