#define TIMEOUT_US 50000 // 50ms timeout
#define TRIGGER_PULSE_US 10000 // 10us
#define SERVO_MIN_PULSE_WIDTH 500 // 0.5ms
#define SERVO_MAX_PULSE_WIDTH 2500 // 2.5ms
#define SERVO_RANGE 2000 // 20 degrees

// Global variables
volatile sig_atomic_t program_running = 1;
float distance = -1.0; // Initialize to -1.0 to indicate invalid distance

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_width);
float mapDistanceToAngle(float distance);
void setServoAngle(float angle);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, stopping servo and exiting...\n");
        program_running = 0;
        setServoAngle(0.0); // Set to 0 degrees before exiting
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulseIn(int pin, int level, int timeout) {
    long start = gpioTick();
    long end = start + timeout;

    while (gpioRead(pin) != level) {
        if (gpioTick() > end) {
            return -1; // Timeout
        }
    }

    long pulse_start = gpioTick();
    while (gpioRead(pin) == level) {
        if (gpioTick() > end) {
            return -1; // Timeout
        }
    }
    long pulse_end = gpioTick();

    return pulse_end - pulse_start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate timeout error
    }
    return (float)pulse_width * 0.0343 / 2.0; // Speed of sound: 343 m/s
}

// Function to map the distance to a servo angle
float mapDistanceToAngle(float distance) {
    if (distance < 2.0) {
        return 0.0;
    } else if (distance > 400.0) {
        return 180.0;
    } else {
        return 90.0 + (distance - 2.0) / (400.0 - 2.0) * SERVO_RANGE;
    }
}

// Function to set the servo angle
void setServoAngle(float angle) {
    if (angle < 0.0 || angle > 180.0) {
        fprintf(stderr, "Error: Invalid angle: %.2f\n", angle);
        return;
    }

    float pulse_width = SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Ultrasonic sensor and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_width = pulseIn(ECHO_PIN, 1, TIMEOUT_US);
        float distance = calculateDistance(pulse_width);

        if (distance > 0) {
            float angle = mapDistanceToAngle(distance);
            setServoAngle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            printf("Timeout error\n");
        }

        gpioDelay(100000); // Pause for 100ms
    }

    // Stop servo and terminate pigpio (should not reach here if signal handler works)
    setServoAngle(0.0);
    gpioTerminate();

    return 0;
}

