#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x10
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
void log_sensor_data(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the Si7005 sensor
int configure_sensor() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = 0x00; // Default configuration

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[1];
    char read_buf[2];
    int result;

    // Write the register address to be read
    buf[0] = TEMP_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to temperature register: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 10ms)
    gpioDelay(10);

    // Read the temperature data
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    // Convert the raw data to temperature (Celsius)
    int raw_temperature = (read_buf[0] << 8) | read_buf[1];
    data->temperature = ((float)raw_temperature / 65535.0) * 165.0 - 40.0;

    // Read humidity data
    buf[0] = HUMID_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to humidity register: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 10ms)
    gpioDelay(10);

    // Read the humidity data
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }

    // Convert the raw data to humidity (%RH)
    int raw_humidity = (read_buf[0] << 8) | read_buf[1];
    data->humidity = ((float)raw_humidity / 65535.0) * 100.0;

    return 0;
}

// Log sensor data to the console
void log_sensor_data(const sensor_data_t *data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data->temperature, data->humidity);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data with retries
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(&sensor_data) == 0) {
                log_sensor_data(&sensor_data);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Failed to read sensor data, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        }

        sleep(2);
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

