#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void parse_mpu6050_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *accel_x_g, float *accel_y_g, float *accel_z_g, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);
void print_data(float accel_x_g, float accel_y_g, float accel_z_g, float gyro_x_dps, float gyro_y_dps, float gyro_z_dps);
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_x_g, accel_y_g, accel_z_g, gyro_x_dps, gyro_y_dps, gyro_z_dps;

    while (1) {
        // Read MPU6050 data
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Parse MPU6050 data
            parse_mpu6050_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, &accel_x_g, &accel_y_g, &accel_z_g, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Print data
            print_data(accel_x_g, accel_y_g, accel_z_g, gyro_x_dps, gyro_y_dps, gyro_z_dps);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

// Initialize MPU6050
int init_mpu6050() {
    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, PWR_MGMT_1);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    // Wake up the MPU6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to ACCEL_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure gyroscope range (+/- 250 dps)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read MPU6050 data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];

    // Read 14 bytes of data starting from ACCEL_XOUT_H
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14) != 14) {
        fprintf(stderr, "Failed to read 14 bytes of data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y  = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z  = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Parse MPU6050 data
void parse_mpu6050_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *accel_x_g, float *accel_y_g, float *accel_z_g, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    // Convert accelerometer data to g's (assuming +/- 2g range)
    *accel_x_g = (float)accel_x / 16384.0f;
    *accel_y_g = (float)accel_y / 16384.0f;
    *accel_z_g = (float)accel_z / 16384.0f;

    // Convert gyroscope data to degrees per second (assuming +/- 250 dps range)
    *gyro_x_dps = (float)gyro_x / 131.0f;
    *gyro_y_dps = (float)gyro_y / 131.0f;
    *gyro_z_dps = (float)gyro_z / 131.0f;
}

// Print data to console
