#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command for high repeatability measurement
#define SHT40_MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, uint8_t crc);
int read_sensor_data_safe(uint8_t *data);
void signal_handler(int signal);
void log_data(sensor_data_t data);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with error handling and CRC validation
int read_sensor_data(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, SHT40_MEASURE_CMD) != 0) {
        fprintf(stderr, "Error writing to I2C\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10ms)

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C\n");
        return -1;
    }

    if (!validate_crc(data, data[2]) || !validate_crc(data + 3, data[5])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t *data, uint8_t crc) {
    uint8_t polynomial = CRC8_POLYNOMIAL;
    uint8_t data_byte = data[0];
    uint8_t crc_calculated = 0xFF;

    for (int i = 0; i < 8; i++) {
        if (crc_calculated & 0x80) {
            data_byte ^= polynomial;
        }
        crc_calculated <<= 1;
        crc_calculated &= 0x07;
    }

    return (crc_calculated == crc);
}

// Safe read function with error handling and retry
int read_sensor_data_safe(uint8_t *data) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = read_sensor_data(data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(100); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

// Log data to console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t sensor_data_t;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data_safe(sensor_data) == 0) {
            // Convert raw data to temperature and humidity
            uint16_t temperature_raw = (sensor_data[0] << 8) | sensor_data[1];
            uint16_t humidity_raw = (sensor_data[3] << 8) | sensor_data[4];

            sensor_data_t.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
            sensor_data_t.humidity = 100.0 * (float)humidity_raw / 65535.0;

            // Log data
            log_data(sensor_data_t);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

