#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature data
typedef struct {
    float ambient_temp;
    float object_temp;
} TemperatureData;

// Function prototypes
int initialize_i2c();
TemperatureData read_temperatures();
char* get_timestamp();
int log_data(TemperatureData data, char* timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperatures from the sensor
TemperatureData read_temperatures() {
    TemperatureData data;
    int raw_ambient, raw_object;

    raw_ambient = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
    if (raw_ambient < 0) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", raw_ambient);
        data.ambient_temp = -999.0; // Indicate error
    } else {
        data.ambient_temp = (float)raw_ambient * 0.02 - 273.15; // Convert to Celsius
    }

    raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
    if (raw_object < 0) {
        fprintf(stderr, "Error reading object temperature: %d\n", raw_object);
        data.object_temp = -999.0; // Indicate error
    } else {
        data.object_temp = (float)raw_object * 0.02 - 273.15; // Convert to Celsius
    }

    return data;
}

// Get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(TemperatureData data, char* timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        TemperatureData temperatures = read_temperatures();
        char* timestamp = get_timestamp();

        if (temperatures.ambient_temp != -999.0 && temperatures.object_temp != -999.0) {
            if (log_data(temperatures, timestamp) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperatures. Skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

