// Function to send a command to the SHT40
int send_command(uint8_t command) {
    char buf[1];
    buf[0] = command;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
