// Function to validate the CRC checksum
int validate_crc(const uint8_t *data, uint8_t crc) {
    uint8_t crc_calculated = crc8(data, 2);
    if (crc_calculated != crc) {
        fprintf(stderr, "CRC validation failed: calculated = 0x%02X, received = 0x%02X\n", crc_calculated, crc);
