// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define TRIGGER_MEASUREMENT 0x2400
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS (1 << MAX_RETRIES) // 2^MAX_RETRIES

// Global variables
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement(int handle);
int read_sensor_data(int handle, uint8_t *data);
sensor_data_t convert_data(uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void cleanup(int handle, FILE *fp);
void signal_handler(int signal);

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Measurement trigger function
int trigger_measurement(int handle) {
    char cmd[2] = {(TRIGGER_MEASUREMENT >> 8) & 0xFF, TRIGGER_MEASUREMENT & 0xFF};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, cmd, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to trigger measurement after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Sensor data reading function
int read_sensor_data(int handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(handle, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Data conversion function
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Scale factors (from SDP31 datasheet)
    const float pressure_scale = 60.0; // Pa
    const float temperature_scale = 200.0; // °C

    sensor_data.pressure_pa = (float)raw_pressure / pressure_scale;
    sensor_data.temperature_c = (float)raw_temperature / temperature_scale;

    return sensor_data;
}

