int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function
void cleanup(int handle, FILE *fp) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(i2c_handle, log_file);
        return 1;
    }

    // Main loop
    uint8_t sensor_data[6];
    sensor_data_t sensor_data_typed;
    while (running) {
        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying in 1 second\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement to complete (datasheet says 20ms max)
        gpioDelay(50); // Wait 50ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying in 1 second\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        sensor_data_typed = convert_data(sensor_data);

        // Log data
        if (log_data(log_file, sensor_data_typed) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    cleanup(i2c_handle, log_file);

    return 0;
}

