#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c(int handle, int reg, int count, const char *data);
int read_i2c(int handle, int reg, char *buf, int count);
int read_sensor_data(int handle, float *temperature, float *humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c(int handle, int reg, int count, const char *data) {
    int result = i2cWriteDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c(int handle, int reg, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(int handle, float *temperature, float *humidity) {
    char buf[2];
    int retries = RETRY_COUNT;

    // Trigger temperature measurement
    if (write_i2c(handle, TEMP_CMD, 0, NULL) != 0) {
        fprintf(stderr, "Failed to trigger temperature measurement\n");
        return -1;
    }
    gpioDelay(20); // Wait for measurement (datasheet says 12.1ms)

    while (retries > 0) {
        if (read_i2c(handle, 0, buf, 2) == 0) {
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read temperature data, retrying...\n");
            gpioDelay(RETRY_DELAY_MS);
            retries--;
        }
    }
    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Failure

    // Trigger humidity measurement
    if (write_i2c(handle, HUMID_CMD, 0, NULL) != 0) {
        fprintf(stderr, "Failed to trigger humidity measurement\n");
        return -1;
    }
    gpioDelay(20); // Wait for measurement

    while (retries > 0) {
        if (read_i2c(handle, 0, buf, 2) == 0) {
            uint16_t raw_humidity = (buf[0] << 8) | buf[1];
            *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read humidity data, retrying...\n");
            gpioDelay(RETRY_DELAY_MS);
            retries--;
        }
    }
    fprintf(stderr, "Failed to read humidity after multiple retries\n");
    return -1; // Failure
}

// Log data to file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
