    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

