#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the continuous measurement trigger command
#define TRIGGER_CMD 0x362F

// Define the number of bytes to read from the sensor
#define NUM_BYTES 9

// Define the scaling factor
#define SCALE_FACTOR 60.0

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Trigger continuous measurement
int trigger_measurement() {
    char cmd[2] = {(TRIGGER_CMD >> 8) & 0xFF, TRIGGER_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, NUM_BYTES);
    if (result != NUM_BYTES) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 validation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[len]) {
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Apply scaling factor
    sensor_data->pressure = (float)raw_pressure / SCALE_FACTOR;
    sensor_data->temperature = (float)raw_temperature / SCALE_FACTOR;

    return 0;
}

// Log data to file
int log_data(sensor_data_t sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, sensor_data.pressure, sensor_data.temperature);
    fflush(data_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen("airflow_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(data_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    fflush(data_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Trigger measurement
    if (trigger_measurement() != 0) {
        fclose(data_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t sensor_data[NUM_BYTES];
    sensor_data_t sensor_data_read;
    while (!terminate) {
        // Wait for 45ms
        gpioDelay(45000); // 45ms

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 6) == 0) {
                // Convert data
                if (convert_data(sensor_data, &sensor_data_read) == 0) {
                    // Log data
                    if (log_data(sensor_data_read) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "Error converting data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
    }

    // Close data file
    fclose(data_file);

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

