#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int length);
int read_temperature(int handle, float *temperature);
int log_data(float temperature);
void log_error(const char *message);
void signal_handler(int signal);

// Structure for grouping configuration data
typedef struct {
    int i2c_bus;
    int sts30_address;
    const char *log_file_path;
    const char *error_log_file_path;
    uint16_t measure_command;
    uint8_t crc_polynomial;
    uint8_t crc_initial_value;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .sts30_address = STS30_ADDR,
    .log_file_path = LOG_FILE,
    .error_log_file_path = ERROR_LOG_FILE,
    .measure_command = MEASURE_CMD,
    .crc_polynomial = CRC_POLYNOMIAL,
    .crc_initial_value = CRC_INITIAL_VALUE
};

int main() {
    float temperature;
    int result;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        result = read_temperature(i2c_handle, &temperature);
        if (result == 0) {
            // Log data
            if (log_data(temperature) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read temperature");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send command");
        return 1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        log_error("Failed to read data");
        return 1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(const char *data, int length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Read temperature from the sensor
int read_temperature(int handle, float *temperature) {
    char buffer[3];
    if (send_command(handle, config.measure_command) != 0) {
        return 1;
    }
    gpioDelay(15000); // Wait 15ms for conversion

    if (read_data(handle, buffer, 3) != 0) {
        return 1;
    }

    // Extract temperature data
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    *temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    // Validate CRC
    if (!validate_crc(buffer, 3)) {
        return 1;
    }

    return 0;
}

// Log data to file
int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

