FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send the measurement command to the SHT40
int send_measurement_command() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate the CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC checksum failure\n");
        return -1;
    }
    return 0;
}

