int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("SHT40 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying in 1 second...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement (at least 8.5ms)
        gpioDelay(8500); // Wait 8.5ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying in 1 second...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC checksum
        if (validate_crc(data, 6) != 0) {
            fprintf(stderr, "Error validating CRC checksum, retrying in 1 second...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        uint16_t raw_temperature = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];

        sensor_data.temperature = convert_temperature(raw_temperature);
        sensor_data.humidity = convert_humidity(raw_humidity);

        // Log the data
        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_SECONDS * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    printf("SHT40 sensor monitoring stopped.\n");

    return 0;
}

