#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_FILE "airflow_data.txt"
#define ERROR_FILE "error_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *data_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to write to the I2C device
int write_i2c(int handle, uint8_t *data, int len) {
    int result = i2cWriteDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(error_file, "%ld: I2C write error: %d\n", time(NULL), result);
        fflush(error_file);
        return -1;
    }
    return 0;
}

// Function to read from the I2C device
int read_i2c(int handle, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(error_file, "%ld: I2C read error: %d\n", time(NULL), result);
        fflush(error_file);
        return -1;
    }
    return 0;
}

// Function to initialize the sensor
int init_sensor(int handle) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    if (write_i2c(handle, cmd, 2) != 0) {
        fprintf(error_file, "%ld: Sensor initialization failed\n", time(NULL));
        fflush(error_file);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    if (write_i2c(handle, cmd, 2) != 0) {
        fprintf(error_file, "%ld: Sensor data read failed\n", time(NULL));
        fflush(error_file);
        return -1;
    }

    gpioDelay(1000); // Wait for measurement (adjust as needed)

    if (read_i2c(handle, data, 6) != 0) {
        fprintf(error_file, "%ld: Sensor data read failed\n", time(NULL));
        fflush(error_file);
        return -1;
    }

    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[len]) {
        fprintf(error_file, "%ld: CRC check failed\n", time(NULL));
        fflush(error_file);
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure = (float)raw_pressure / 240.0; // Pa
    sensor_data.temperature = (float)raw_temperature / 200.0; // °C

    return sensor_data;
}

// Function to log data to a file
int log_data(FILE *file, float pressure, float temperature) {
    time_t now = time(NULL);
    fprintf(file, "%ld,%.2f,%.2f\n", now, pressure, temperature);
    fflush(file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file\n");
        gpioTerminate();
        return 1;
    }

    // Open data log file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(error_file, "%ld: Error opening data log file\n", time(NULL));
        fflush(error_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(error_file, "%ld: I2C open failed: %d\n", time(NULL), i2c_handle);
        fflush(error_file);
        fclose(data_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(error_file, "%ld: Sensor initialization failed\n", time(NULL));
        fflush(error_file);
        i2cClose(i2c_handle);
        fclose(data_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t data[6];
    sensor_data_t sensor_data;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(i2c_handle, data) == 0) {
                // Validate CRC-8 checksums
                if (validate_crc(data, 2) == 0 && validate_crc(data + 3, 2) == 0) {
                    // Convert data to pressure and temperature
                    sensor_data = convert_data(data);

                    // Log data to file
                    log_data(data_file, sensor_data.pressure, sensor_data.temperature);

                    break; // Exit retry loop on success
                } else {
                    fprintf(error_file, "%ld: CRC validation failed, retrying...\n", time(NULL));
                    fflush(error_file);
                }
            } else {
                fprintf(error_file, "%ld: Sensor read failed, retrying...\n", time(NULL));
                fflush(error_file);
            }
            retry++;
            gpioDelay(RETRY_DELAY_MS);
        }

        if (retry == RETRY_COUNT) {
            fprintf(error_file, "%ld: Sensor read failed after %d retries\n", time(NULL), RETRY_COUNT);
            fflush(error_file);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Close data log file
    fclose(data_file);

    // Close error log file
    fclose(error_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

