#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(time_t timestamp, float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char cmd[1] = {0xE3}; // Command for temperature and humidity measurement
    unsigned char data[4];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

    result = i2cReadDevice(i2c_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert data to temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((175.72 * raw_temperature) / 65536.0) - 46.85;
    *humidity = ((125.0 * raw_humidity) / 65536.0) - 6.0;

    return 0;
}

// Function to control the fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Temperature: %.2f°C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f°C)\n", temperature);
    }
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, float humidity) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Humidity: %.2f%%\n", time_str, circular_buffer[index].temperature, circular_buffer[index].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t current_time;

    printf("Starting sensor monitoring...\n");

    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&temperature, &humidity) == 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Add data to circular buffer
            add_to_buffer(current_time, temperature, humidity);

            // Print sensor data
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

            // Control fan
            control_fan(temperature);

            // Wait for 2 seconds
            gpioDelay(2000); // Delay in milliseconds
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            for (int i = 0; i < RETRY_COUNT; i++) {
                if (read_sensor_data(&temperature, &humidity) == 0) {
                    printf("Sensor data read successfully after retry.\n");
                    break; // Exit retry loop if successful
                } else {
                    fprintf(stderr, "Retry %d failed. Retrying...\n", i + 1);
                    gpioDelay(100); // Small delay before retrying
                }
            }
            if (i == RETRY_COUNT) {
                fprintf(stderr, "Max retries reached. Sensor likely absent.\n");
            }
        }

        // Print buffer every 10 minutes
        time_t now = time(NULL);
        if (now % 600 == 0) { // 600 seconds = 10 minutes
            print_buffer();
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

