#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_scd40();
int start_periodic_measurement();
int read_data_ready_flag();
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity);
int verify_crc(uint8_t data[], uint8_t crc);
int log_data(uint16_t co2, float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the SCD40 sensor
int initialize_scd40() {
    int result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Reset command
    if (result != 0) {
        fprintf(stderr, "Error: Failed to reset SCD40. Error code: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    result = i2cWriteByteData(i2c_handle, 0x00, 0x3646); // Software reset
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send software reset command. Error code: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    result = i2cWriteByteData(i2c_handle, 0x00, 0x21B1); // Start periodic measurement
    if (result != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement. Error code: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CMD_START_PERIODIC_MEASUREMENT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement. Error code: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for command to be processed
    return 0;
}

// Function to read the data ready flag
int read_data_ready_flag() {
    int result = i2cReadByteData(i2c_handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read data ready flag. Error code: %d\n", result);
        return -1;
    }
    return result;
}

// Function to read SCD40 data
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Failed to read data. Error code: %d\n", result);
        return -1;
    }

    if (!verify_crc(data, data[8])) {
        fprintf(stderr, "Error: CRC check failed\n");
        return -1;
    }

    *co2 = (uint16_t)data[0] << 8 | data[1];
    *temperature = -45 + 175 * ((float)((uint16_t)data[3] << 8 | data[4])) / 65535;
    *humidity = 100 * ((float)((uint16_t)data[6] << 8 | data[7])) / 65535;

    return 0;
}

// Function to verify CRC
int verify_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial = CRC8_POLYNOMIAL;
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < 8; i++) {
        crc_calculated ^= (data[i] & 0x01);
        if (crc_calculated != 0) {
            crc_calculated = (crc_calculated >> 1) ^ polynomial;
        } else {
            crc_calculated = crc_calculated >> 1;
        }
    }
    return (crc_calculated == crc);
}

// Function to log data to file
int log_data(uint16_t co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, stopping program...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
