#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_scd40();
int start_periodic_measurement();
int read_data_ready_flag();
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity);
int verify_crc(uint8_t data[], uint8_t crc);
