} sensor_data_t;

// Function to initialize the SCD40 sensor
int initialize_scd40() {
    int result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Reset command
    if (result != 0) {
        fprintf(stderr, "Error: Failed to reset SCD40. Error code: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    result = i2cWriteByteData(i2c_handle, 0x00, 0x3646); // Software reset
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send software reset command. Error code: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    result = i2cWriteByteData(i2c_handle, 0x00, 0x21B1); // Start periodic measurement
    if (result != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement. Error code: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CMD_START_PERIODIC_MEASUREMENT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement. Error code: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for command to be processed
    return 0;
