#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define READ_INTERVAL 5 // seconds

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_REINIT 0x3646

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_scd40();
int read_scd40(uint16_t *co2, float *temperature, float *humidity);
void validate_crc(uint8_t data[], uint8_t checksum);
void store_reading(uint16_t co2, float temperature, float humidity);
void print_reading(uint16_t co2, float temperature, float humidity);
void control_led(uint16_t co2);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SCD40 sensor
int init_scd40() {
    char cmd[2];
    int result;

    // Stop periodic measurement
    cmd[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to stop

    // Reinit the sensor
    cmd[0] = (CMD_REINIT >> 8) & 0xFF;
    cmd[1] = CMD_REINIT & 0xFF;
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error reinitializing sensor: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for the sensor to reinit

    // Start periodic measurement
    cmd[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read data from the SCD40 sensor
int read_scd40(uint16_t *co2, float *temperature, float *humidity) {
    char cmd[2];
    char data[9];
    int result;

    // Read measurement command
    cmd[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for the sensor to prepare data

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC for CO2
    uint8_t co2_data[2] = {data[0], data[1]};
    validate_crc(co2_data, data[2]);

    // Validate CRC for Temperature
    uint8_t temp_data[2] = {data[3], data[4]};
    validate_crc(temp_data, data[5]);

    // Validate CRC for Humidity
    uint8_t humidity_data[2] = {data[6], data[7]};
    validate_crc(humidity_data, data[8]);

    *co2 = (uint16_t)data[0] << 8 | data[1];
    *temperature = -45 + 175 * ((float)((uint16_t)data[3] << 8 | data[4]) / 65535);
    *humidity = 100 * ((float)((uint16_t)data[6] << 8 | data[7]) / 65535);

    return 0;
}

// Function to validate the CRC checksum
void validate_crc(uint8_t data[], uint8_t checksum) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "CRC validation failed for data: 0x%02X, checksum: 0x%02X\n", data[0], checksum);
        *co2 = 0; // Indicate invalid reading
        *temperature = -999.0; // Indicate invalid reading
        *humidity = -999.0; // Indicate invalid reading
    }
}

// Function to store the reading in the circular buffer
void store_reading(uint16_t co2, float temperature, float humidity) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the reading to stdout
void print_reading(uint16_t co2, float temperature, float humidity) {
    printf("Timestamp: %ld, CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
           time(NULL), co2, temperature, humidity);
}

// Function to control the CO2 warning LED
void control_led(uint16_t co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    // Stop periodic measurement
    char cmd[2];
    cmd[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, cmd, 2);

    // Release GPIO
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set back to input

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("SCD40 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        uint16_t co2;
        float temperature;
        float humidity;

        // Read sensor data
        if (read_scd40(&co2, &temperature, &humidity) == 0) {
            // Validate data
            if (co2 > 0 && temperature > -50 && temperature < 100 && humidity > 0 && humidity < 100) {
                // Store reading
                store_reading(co2, temperature, humidity);

                // Print reading
                print_reading(co2, temperature, humidity);

                // Control LED
                control_led(co2);
            } else {
                fprintf(stderr, "Invalid sensor data: CO2=%d, Temp=%.2f, Hum=%.2f\n", co2, temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

