#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL 5   // seconds
#define TIMEOUT_US 50000     // 50ms in microseconds
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data and state
typedef struct {
    int gpio_pin;
    int pwm_frequency;
    int sample_interval;
    int timeout_us;
    double min_temp;
    double max_temp;
    FILE *log_file;
    int consecutive_errors;
} sensor_config_t;

// Function prototypes
int initialize_sensor(sensor_config_t *config);
double read_temperature(sensor_config_t *config);
void log_data(sensor_config_t *config, double temperature);
void signal_handler(int signal);
void cleanup(sensor_config_t *config);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(sensor_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->gpio_pin, PI_OUTPUT);
    gpioSetPWMfrequency(config->gpio_pin, config->pwm_frequency);
    gpioPWM(config->gpio_pin, 128); // 50% duty cycle

    config->log_file = fopen("temperature_log.txt", "a");
    if (config->log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return -1;
    }

    config->consecutive_errors = 0;
    return 0;
}

// Function to read temperature from the sensor
double read_temperature(sensor_config_t *config) {
    uint32_t high_pulse_width, total_cycle_width;
    double temperature;
    int i;

    // Wait for the rising edge of the PWM signal
    for (i = 0; i < TIMEOUT_US; i++) {
        if (gpioRead(config->gpio_pin) == 1) {
            break;
        }
    }
    if (i >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -999.0; // Indicate timeout error
    }
    high_pulse_width = i;

    // Wait for the falling edge of the PWM signal
    for (i = 0; i < TIMEOUT_US; i++) {
        if (gpioRead(config->gpio_pin) == 0) {
            break;
        }
    }
    if (i >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -999.0; // Indicate timeout error
    }
    total_cycle_width = i;

    // Calculate temperature
    if (total_cycle_width == 0) {
        fprintf(stderr, "Error: Total cycle width is zero\n");
        return -999.0; // Indicate division by zero error
    }
    temperature = (double)high_pulse_width / total_cycle_width * 100.0;

    return temperature;
}

// Function to log temperature data
void log_data(sensor_config_t *config, double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        fprintf(config->log_file, "ERROR: Temperature out of range: %.2f\n", temperature);
        config->consecutive_errors++;
        if (config->consecutive_errors >= 3) {
            fprintf(config->log_file, "SENSOR MALFUNCTION\n");
            config->consecutive_errors = 0; // Reset counter after logging malfunction
        }
    } else {
        fprintf(config->log_file, "%s, %.2f\n", timestamp, temperature);
        config->consecutive_errors = 0; // Reset error counter on valid reading
    }
    fflush(config->log_file);
}

// Function to perform cleanup before exiting
void cleanup(sensor_config_t *config) {
    printf("Cleaning up...\n");
    if (config->log_file != NULL) {
        fclose(config->log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t sensor_config = {
        .gpio_pin = GPIO_PIN,
        .pwm_frequency = PWM_FREQUENCY,
        .sample_interval = SAMPLE_INTERVAL,
        .timeout_us = TIMEOUT_US,
        .min_temp = MIN_TEMP,
        .max_temp = MAX_TEMP,
        .log_file = NULL,
        .consecutive_errors = 0
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (initialize_sensor(&sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double temperature = read_temperature(&sensor_config);

        if (temperature != -999.0) {
            log_data(&sensor_config, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        time_sleep(sensor_config.sample_interval);
    }

    // Perform cleanup before exiting
    cleanup(&sensor_config);

    return 0;
}

