#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define LOG_FILE "environmental_data.txt"
#define SLEEP_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht35(uint8_t *data);
int validate_crc(uint8_t *data, uint8_t checksum);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
float apply_sinusoidal_offset(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from SHT35
int read_sht35(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait for measurement (datasheet specifies 12.1ms for high repeatability)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC
int validate_crc(uint8_t *data, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t data_len = 2; // Temperature and humidity data

    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial: x^8 + x^5 + x^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == checksum);
}

// Convert temperature
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Convert humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Apply sinusoidal offset
float apply_sinusoidal_offset(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    float offset_temp = 2.0 * sinf((float)time(NULL) / 3600.0 + 0.5); // Offset between 2 and 4
    float offset_humidity = 5.0 * sinf((float)time(NULL) / 3600.0 + 1.0); // Offset between 5 and 10

    return temperature + offset_temp + humidity + offset_humidity;
}

// Log data
int log_data(float temperature, float humidity) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[6];
    sensor_data_t sensor_data;
    float temperature, humidity;

    printf("Starting data logging...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sht35(data) == 0) {
            // Validate CRC
            if (validate_crc(data, data[2]) && validate_crc(data + 3, data[5])) {
                // Convert data
                uint16_t raw_temp = (data[0] << 8) | data[1];
                uint16_t raw_humidity = (data[3] << 8) | data[4];

                temperature = convert_temperature(raw_temp);
                humidity = convert_humidity(raw_humidity);

                // Apply sinusoidal offset
                sensor_data.temperature = apply_sinusoidal_offset(temperature, humidity);
                sensor_data.humidity = apply_sinusoidal_offset(temperature, humidity);

                // Log data
                if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SLEEP_INTERVAL * 1000); // Sleep for SLEEP_INTERVAL seconds
    }

    // Cleanup resources
    cleanup();

    printf("Exiting.\n");
    return 0;
}

