#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor-specific constants
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400 // Single shot high repeatability, clock stretching disabled
#define CSV_FILE "environment.csv"

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int data_len, uint8_t checksum);
int read_sensor_data_safe(uint8_t *data);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void shutdown_sensor();

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHT35_ADDR, 0); // I2C bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(uint8_t *data, int data_len, uint8_t checksum) {
    uint8_t crc = 0;
    for (int i = 0; i < data_len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == checksum);
}

// Function to safely read sensor data with error handling
int read_sensor_data_safe(uint8_t *data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = read_sensor_data(data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Sensor read failed, retrying... (%d retries left)\n", retries);
            gpioDelay(100); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries\n");
    return -1; // Failure after retries
}

// Function to log the data to a CSV file
int log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (fp == NULL) {
        fprintf(stderr, "File not opened for writing\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to shut down the sensor
void shutdown_sensor() {
    char cmd[2] = {0x30, 0x80}; // Soft reset command
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send soft reset command: %d\n", result);
    }
    gpioDelay(100); // Wait for reset to complete
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Sensor shut down successfully\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        shutdown_sensor();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%)\n");
    }
    fseek(fp, 0, SEEK_END); // Reset file pointer to the end

    uint8_t sensor_data[6];
    sensor_data_t sensor_data_raw;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data_safe(sensor_data) == 0) {
            // Validate CRC checksums
            if (validate_crc(sensor_data, 2, sensor_data[2]) &&
                validate_crc(sensor_data + 3, 2, sensor_data[5])) {
                // Convert raw data to temperature and humidity
                int temperature_raw = (sensor_data[0] << 8) | sensor_data[1];
                int humidity_raw = (sensor_data[3] << 8) | sensor_data[4];

                sensor_data_raw.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
                sensor_data_raw.humidity = 100.0 * (float)humidity_raw / 65535.0;

                // Log the data
                if (log_data(sensor_data_raw.temperature, sensor_data_raw.humidity) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Clean up and shut down
    fclose(fp);
    shutdown_sensor();

    return 0;
}

