int init_i2c();
int read_sensor_data(uint8_t command, uint16_t *data);
int verify_crc(uint8_t data[], uint8_t checksum);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t command, uint16_t *data) {
    char buf[3];
    int result;

    result = i2cWriteByte(i2c_handle, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (datasheet specifies 10ms for temp, 25ms for humidity)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to verify CRC checksum
int verify_crc(uint8_t data[], uint8_t checksum) {
    uint8_t crc = 0;
    uint8_t bit;
    uint8_t byte;

