int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t pressure_crc = buffer[2];
    if (crc8(pressure_data, 2) != pressure_crc) {
