        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Send measurement command
    if (send_measurement_command() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(fp);
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    time_t start_time = time(NULL);

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(fp);

    printf("Program terminated gracefully.\n");
    return 0;
}

