int validate_crc(uint8_t *data, int length, uint8_t polynomial) {
    for (int i = 0; i < length; i++) {
        uint8_t crc = 0xFF;
        uint8_t bit;
        for (int j = 0; j < 8; j++) {
            bit = (crc ^ data[i]) & 0x01;
            crc >>= 1;
