int read_sensor_data(int *pressure);
float convert_to_pressure(int raw_pressure);
float calculate_flow_rate(float pressure);
int set_fan_speed(float flow_rate);
int log_data(float pressure, float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from I2C
int read_sensor_data(int *pressure) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw pressure data to Pascals
float convert_to_pressure(int raw_pressure) {
    // Assuming a linear relationship between raw pressure and pressure in Pascals
    // Adjust the scaling factor based on the sensor's datasheet
    float pressure_pa = (float)raw_pressure * 0.01; // Example scaling
    return pressure_pa;
}

// Calculate flow rate from pressure
float calculate_flow_rate(float pressure) {
    // Assuming a linear relationship between pressure and flow rate
    // Adjust the scaling factor based on the sensor's datasheet
    float flow_rate = pressure * 0.1; // Example scaling
    return flow_rate;
}

// Set fan speed using hardware PWM
int set_fan_speed(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate * 10); // Example mapping
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

