    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int raw_pressure;
    float pressure_pa, flow_rate;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure) == 0) {
            // Convert to pressure
            pressure_pa = convert_to_pressure(raw_pressure);

            // Calculate flow rate
            flow_rate = calculate_flow_rate(pressure_pa);

            // Set fan speed
            set_fan_speed(flow_rate);

            // Log data
            log_data(pressure_pa, flow_rate);

            printf("Pressure: %.2f Pa, Flow Rate: %.2f\n", pressure_pa, flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_fan_speed(0.0); // Turn off the fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

