#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_register(int handle, uint8_t reg, uint8_t *value);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_sensor_data(int handle, sensor_data_t *data);
char* format_data(sensor_data_t data);
int log_data(const char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Enable continuous data acquisition (ODR = 1 Hz)
    if (write_register(i2c_handle, CTRL_REG1, 0x44) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read a single byte from a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Write a single byte to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t press_xl, press_l, press_h, temp_l, temp_h;
    int32_t press_raw, temp_raw;

    if (read_register(handle, PRESS_OUT_XL, &press_xl) != 0) return -1;
    if (read_register(handle, PRESS_OUT_L, &press_l) != 0) return -1;
    if (read_register(handle, PRESS_OUT_H, &press_h) != 0) return -1;
    if (read_register(handle, TEMP_OUT_L, &temp_l) != 0) return -1;
    if (read_register(handle, TEMP_OUT_H, &temp_h) != 0) return -1;

    press_raw = (int32_t)press_xl | ((int32_t)press_l << 8) | ((int32_t)press_h << 16);
    temp_raw = (int32_t)temp_l | ((int32_t)temp_h << 8);

    // Convert raw values to hPa and °C (from LPS33HW datasheet)
    data->pressure = (float)press_raw / 4096.0; // hPa
    data->temperature = (float)temp_raw / 100.0; // °C

    return 0;
}

// Format the sensor data into a string
char* format_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char buffer[100]; // Static buffer to avoid memory allocation issues

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(buffer, sizeof(buffer), "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
    return buffer;
}

// Log the data to a file
int log_data(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fputs(data, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            char *data_string = format_data(sensor_data);
            if (log_data(data_string) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Sleep for 1 second (1000 ms)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

