    return 0;
}

// Read data from SCD30 sensor
int read_scd30_data(sensor_data_t *data) {
    char buf[2];
    char read_measurement_buf[9];
    int result;

    // Read measurement command
    buf[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    // Read measurement data
    result = i2cReadDevice(i2c_handle, read_measurement_buf, 9);
    if (result != 0) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    // Extract data
    unsigned int co2_raw = (read_measurement_buf[0] << 24) | (read_measurement_buf[1] << 16) | (read_measurement_buf[2] << 8) | read_measurement_buf[3];
    unsigned int temperature_raw = (read_measurement_buf[4] << 24) | (read_measurement_buf[5] << 16) | (read_measurement_buf[6] << 8) | read_measurement_buf[7];
    unsigned int humidity_raw = (read_measurement_buf[8] << 24) | (read_measurement_buf[9] << 16) | (read_measurement_buf[10] << 8) | read_measurement_buf[11];

    // CRC check
    unsigned char co2_crc = read_measurement_buf[3];
    unsigned char temperature_crc = read_measurement_buf[6];
    unsigned char humidity_crc = read_measurement_buf[9];

    unsigned char co2_data[2] = {read_measurement_buf[0], read_measurement_buf[1]};
    unsigned char temperature_data[2] = {read_measurement_buf[4], read_measurement_buf[5]};
    unsigned char humidity_data[2] = {read_measurement_buf[8], read_measurement_buf[9]};

    if (crc8(co2_data, 2) != co2_crc) {
        fprintf(stderr, "CO2 CRC mismatch\n");
        return -1;
    }

    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    if (crc8(humidity_data, 2) != humidity_crc) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    // Convert data
    data->co2 = (float)co2_raw / 65536.0 * 65536.0; // ppm
    data->temperature = (float)temperature_raw / 65536.0 * 200.0 - 45.0; // °C
    data->humidity = (float)humidity_raw / 65536.0 * 100.0; // %RH

    return 0;
}

// Write data to log file
int write_data_to_log(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data->co2, data->temperature, data->humidity);
    fflush(log_file);

    return 0;
}

// Ventilation control logic
void ventilation_control(float co2) {
    if (co2 < 800.0) {
        printf("Ventilation: OFF\n");
    } else if (co2 >= 800.0 && co2 <= 1199.0) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd30_data(&sensor_data) == 0) {
            // Write data to log file
            if (write_data_to_log(&sensor_data) != 0) {
                fprintf(stderr, "Error writing data to log\n");
            }

            // Ventilation control
            ventilation_control(sensor_data.co2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

