#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the trigger command
#define TRIGGER_COMMAND 0x362F

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int len);
int parse_sensor_data(const uint8_t *data, sensor_data_t *data);
void log_sensor_data(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    uint8_t command[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t *data, int len) {
    for (int i = 0; i < len; i += 3) {
        uint8_t crc = 0xFF;
        for (int j = 0; j < 8; j++) {
            crc ^= (data[i + 2] & 0x01);
            data[i + 2] >>= 1;
            if (crc) {
                crc ^= CRC_POLYNOMIAL;
            }
        }
        if (crc != data[i + 1]) {
            fprintf(stderr, "CRC mismatch at byte %d\n", i + 1);
            return -1;
        }
    }
    return 0;
}

// Parse sensor data
int parse_sensor_data(const uint8_t *data, sensor_data_t *data) {
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Apply scale factors (from datasheet)
    data->pressure = (float)raw_pressure / 60.0; // Pa
    data->temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Log sensor data
void log_sensor_data(const sensor_data_t *data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", data->pressure, data->temperature);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Wait for conversion to complete (at least 45ms)
        gpioDelay(45000); // 45ms

        // Read sensor data
        uint8_t data[9];
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Validate CRC
        if (validate_crc(data, 3) != 0) {
            fprintf(stderr, "Error validating CRC, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Parse sensor data
        sensor_data_t sensor_data;
        if (parse_sensor_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Error parsing sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Log sensor data
        log_sensor_data(&sensor_data);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

