#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read temperature from Si7051
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Send temperature measurement command
        result = i2cWriteByteData(i2c_handle, TEMP_MEASURE_CMD, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Wait for measurement (at least 25ms)
        gpioDelay(25000); // Delay in microseconds

        // Read temperature data
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert raw data to temperature (Celsius)
        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        result = read_temperature(&temperature);

        if (result == 0) {
            // Print temperature
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // Delay in microseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

