#define MLX90833_ADDR 0x60

// Define the register address for pressure data
#define PRESSURE_REG 0x00

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C bus
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read pressure data from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int result;

    // Read two bytes from the pressure register
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw pressure to Pascals (Pa)
    *pressure = (float)raw_pressure * 0.1; // Example conversion, adjust as needed

    return 0;
}

// Function to log the pressure value with a timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
}

// Function to cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and I2C bus
    if (initialize() != 0) {
        return 1;
    }

    float pressure;

    // Main loop to read and log pressure data
    while (!terminate) {
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

