#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the measurement command
#define MEASURE_CMD 0x362F // Trigger measurement command

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint16_t data, uint8_t crc);
int process_sensor_data(uint8_t *data, sensor_data_t *data_t);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t polynomial = CRC_POLYNOMIAL;
    uint8_t crc_calculated = 0;
    uint8_t data_bytes[2];

    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    for (int i = 0; i < 8; i++) {
        crc_calculated ^= (data_bytes[i / 8] & 0x01);
        if (crc_calculated) {
            crc_calculated ^= polynomial;
        }
        data_bytes[i / 8] >>= 1;
    }

    return (crc_calculated == crc);
}

// Process sensor data
int process_sensor_data(uint8_t *data, sensor_data_t *data_t) {
    // Extract raw data
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Convert to physical units (refer to SDP800 datasheet)
    data_t->differential_pressure = (float)raw_pressure / 240.0; // Pa
    data_t->temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor_data[9];
    sensor_data_t sensor_data_t;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Wait for measurement to complete (datasheet specifies 50ms for SDP800-500Pa)
        gpioDelay(50000); // 50ms delay

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Validate CRC
        if (!validate_crc(sensor_data[0], sensor_data[8])) {
            fprintf(stderr, "CRC validation failed, skipping data point.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Process sensor data
        if (process_sensor_data(sensor_data, &sensor_data_t) != 0) {
            fprintf(stderr, "Error processing sensor data, skipping data point.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Log data
        if (log_data(sensor_data_t) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        // Wait before next measurement
        gpioDelay(450000); // 45ms delay
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

