#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define TRIGGER_COMMAND 0x362F
#define LOG_FILE "airflow_log.csv"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    uint8_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(sensor_data_t *data);
int verify_crc(uint8_t data[], uint8_t crc);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char command[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Verify CRC for pressure data
    if (verify_crc(buffer, 2) != 0) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Verify CRC for temperature data
    if (verify_crc(buffer + 2, 1) != 0) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = buffer[2];

    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], uint8_t crc) {
    uint8_t crc_calculated = crc8(data, 2);
    return (crc_calculated == crc);
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (float)data.pressure, (float)data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
