#define RETRY_DELAY_MS 10
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_pressure(float *pressure);
int log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read pressure from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert the raw data to pressure (kPa)
            // Assuming the sensor returns a 16-bit value in big-endian format
            int16_t raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure / 100.0; // Example conversion, adjust as needed
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Log pressure to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
