            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }

        // Check if the file is newly created (size == 0)
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to the end
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Check pressure range and emit warning
void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa is outside safe range (%.2f - %.2f kPa)\n",
                pressure, SAFE_PRESSURE_MIN, SAFE_PRESSURE_MAX);
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    float pressure;
    sensor_data_t data;

    while (!terminate) {
        // Read pressure
        if (read_pressure(&pressure) == 0) {
            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Failed to log pressure\n");
            }

            // Check pressure range
            check_pressure_range(pressure);

            // Store data
            data.pressure_kPa = pressure;
            data.timestamp = time(NULL);

            // Print to console (optional)
            printf("Pressure: %.2f kPa, Timestamp: %ld\n", pressure, data.timestamp);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        gpioDelay(1000000); // 1 second delay (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting cleanly\n");
    return 0;
}

