    uint16_t temperature_raw = ((uint16_t)buf[2] << 6) | ((uint16_t)buf[3] >> 2);

    // Convert to Celsius and percentage relative humidity
    data->humidity = ((float)humidity_raw / 16383) * 100;
    data->temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return 0;
}

// Validate sensor data
int validate_sensor_data(const sensor_data_t *data) {
    if (data->temperature < -40 || data->temperature > 125) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", data->temperature);
        return -1;
    }
    if (data->humidity < 0 || data->humidity > 100) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", data->humidity);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Write data to log file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);

    // Close log file
    fclose(fp);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate sensor data
            if (validate_sensor_data(&sensor_data) == 0) {
                // Log data
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error validating sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next measurement interval
        gpioDelay(MEASUREMENT_INTERVAL_S * 1000000); // Convert seconds to microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

