#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define TEMP_OFFSET 25.0
#define LOG_FILE "greenhouse_temps.dat"
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify device ID (optional, but good practice)
    char id;
    if (i2cReadDevice(i2c_handle, &id, 1) != 1) {
        fprintf(stderr, "Error reading device ID\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (id != 0x00) {
        fprintf(stderr, "Incorrect device ID: 0x%02x\n", id);
        i2cClose(i2c_handle);
        return -1;
    }

    printf("I2C initialized successfully.\n");
    return 0;
}

// Temperature reading function
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (raw_temp * TEMP_SCALE) + TEMP_OFFSET;

    return temperature;
}

// Temperature logging function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    if (fwrite(timestamp, sizeof(char), strlen(timestamp), log_file) != strlen(timestamp)) {
        fprintf(stderr, "Error writing timestamp to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

