#define MEASURE_HIGH_PRECISION 0xFD
#define DATA_FILE "environmental_data.txt"
#define SLEEP_SECONDS 5

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c_command(int handle, uint8_t command);
int read_i2c_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], uint8_t crc);
int read_sht40_data(int handle, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to write I2C command
int write_i2c_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read I2C data
int read_i2c_data(int handle, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t crc_calculated = 0;
    for (int i = 0; i < 6; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Function to read SHT40 data
int read_sht40_data(int handle, sensor_data_t *data) {
    uint8_t command = MEASURE_HIGH_PRECISION;
    uint8_t data_buffer[6];

    if (write_i2c_command(handle, command) < 0) {
        return -1;
    }

    // Wait for measurement (at least 8.5ms)
    gpioDelay(8500); // 8500 us = 8.5 ms

    if (read_i2c_data(handle, data_buffer, 6) < 0) {
        return -1;
    }

    // Validate CRC for temperature
    if (!validate_crc(data_buffer, data_buffer[2])) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (!validate_crc(data_buffer + 3, data_buffer[5])) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (data_buffer[0] << 8) | data_buffer[1];
    uint16_t humidity_raw = (data_buffer[3] << 8) | data_buffer[4];

    data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

