#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60

// Structure to hold temperature data and timestamp
typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureReading;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
TemperatureReading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_sensor();
float read_temperature();
void add_reading(float temperature);
void flush_buffer();
void log_data_to_file();
void signal_handler(int signal);
int verify_sensor_id();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the TMP117 sensor
int initialize_sensor() {
    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        fprintf(stderr, "Error: TMP117 sensor ID verification failed.\n");
        return -1;
    }

    // Configure the sensor for continuous conversion mode (default)
    // No explicit configuration needed for continuous mode, but we can check the status register if needed.

    return 0;
}

// Function to read the temperature from the TMP117 sensor
float read_temperature() {
    int raw_temperature;
    float temperature;

    raw_temperature = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temperature);
        return -1000.0; // Indicate an error
    }

    // Convert raw temperature to Celsius (refer to TMP117 datasheet)
    temperature = (float)((raw_temperature >> 4) * 0.0078125);
    return temperature;
}

// Function to add a temperature reading to the circular buffer
void add_reading(float temperature) {
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to flush the circular buffer to a file
void flush_buffer() {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature_log.dat for writing!\n");
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(TemperatureReading), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to temperature_log.dat!\n");
    }

    fclose(fp);
}

// Function to log the data to a file
void log_data_to_file() {
    FILE *fp = fopen("temperature_log.dat", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature_log.dat for appending!\n");
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        fprintf(fp, "%ld,%.2f\n", temperature_buffer[index].timestamp, temperature_buffer[index].temperature);
    }

    fclose(fp);
}

// Function to verify the TMP117 sensor ID
int verify_sensor_id() {
    char id;
    int result = i2cReadByteData(i2c_handle, 0x0F); // Read ID register
    if (result < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    id = (char)result;

    if (id != 0x48) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            add_reading(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Flush the buffer and close I2C
    flush_buffer();
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

