#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x01
#define TEMP_REG 0x02
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float rotational_speed;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *mag_data, int16_t *temp_data);
float convert_mag_data(int16_t raw_data);
float convert_temp_data(int16_t raw_data);
sensor_data_t process_sensor_data(int16_t mag_data, int16_t temp_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data from the Si7202
int read_sensor_data(int16_t *mag_data, int16_t *temp_data) {
    char buf[4];

    // Read magnetic data
    if (i2cReadI2CBlockData(i2c_handle, MAG_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read magnetic data\n");
        return -1;
    }
    *mag_data = (int16_t)((buf[0] << 8) | buf[1]);

    // Read temperature data
    if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    *temp_data = (int16_t)((buf[0] << 8) | buf[1]);

    return 0;
}

// Function to convert raw magnetic data to degrees per second
float convert_mag_data(int16_t raw_data) {
    // Assuming a linear relationship between raw data and degrees per second
    // Adjust the scaling factor as needed based on the sensor's datasheet
    return (float)raw_data * 0.01; // Example scaling
}

// Function to convert raw temperature data to degrees Celsius
float convert_temp_data(int16_t raw_data) {
    // Assuming a linear relationship between raw data and degrees Celsius
    // Adjust the scaling factor as needed based on the sensor's datasheet
    return (float)raw_data * 0.01; // Example scaling
}

// Function to process sensor data and convert to meaningful units
sensor_data_t process_sensor_data(int16_t mag_data, int16_t temp_data) {
    sensor_data_t data;
    data.rotational_speed = convert_mag_data(mag_data);
    data.temperature = convert_temp_data(temp_data);
    return data;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.rotational_speed, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Rotational Speed (deg/s),Temperature (C)\n");
    }
    rewind(log_file);

    int16_t mag_data, temp_data;
    sensor_data_t sensor_data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&mag_data, &temp_data) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(mag_data, temp_data);

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Logging NaN values.\n");
            fprintf(log_file, "%s,NaN,NaN\n", ctime(NULL));
            fflush(log_file);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

