typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *flow, uint16_t *temperature);
sensor_data_t process_sensor_data(uint16_t raw_flow, uint16_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the I2C bus
int read_sensor_data(uint16_t *flow, uint16_t *temperature) {
    char buf[4];
    int result;

    for (int i = 0; i < I2C_RETRIES; ++i) {
        result = i2cReadDevice(i2c_handle, buf, 4);
        if (result == 4) {
            // Combine the bytes to form 14-bit flow and 12-bit temperature values
            *flow = (uint16_t)((buf[0] << 8) | buf[1]);
            *temperature = (uint16_t)((buf[2] << 4) | (buf[3] & 0x0F));
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", I2C_RETRIES);
    return -1; // Failure
}

// Function to process raw sensor data
sensor_data_t process_sensor_data(uint16_t raw_flow, uint16_t raw_temperature) {
    sensor_data_t data;

    // Convert raw flow to SLPM (example conversion, adjust as needed)
    data.flow_slpm = (float)raw_flow / 100.0; // Example scaling

    // Convert raw temperature to Celsius (example conversion, adjust as needed)
    data.temperature_c = (float)raw_temperature / 10.0; // Example scaling

    return data;
}

