#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DHT11_PIN 4

// Define timing constants (in microseconds)
#define START_PULSE_MIN 18000
#define START_PULSE_MAX 25000
#define DATA_BIT_LOW_PERIOD 50
#define DATA_BIT_HIGH_PERIOD 26
#define DATA_BIT_HIGH_1 70
#define DATA_BIT_HIGH_0 28
#define CHECKSUM_PULSE_MIN 2000
#define CHECKSUM_PULSE_MAX 4000

// Define timeout values
#define TIMEOUT_START 10000
#define TIMEOUT_RESPONSE 10000
#define TIMEOUT_DATA 20000
#define TIMEOUT_CHECKSUM 20000

// Define checksum calculation constants
#define HUMIDITY_BYTE_0 0
#define HUMIDITY_BYTE_1 0
#define TEMPERATURE_BYTE_0 0
#define TEMPERATURE_BYTE_3 0

// Define error codes
#define ERROR_TIMEOUT 1
#define ERROR_CHECKSUM 2
#define ERROR_LINE_STUCK 3
#define ERROR_SENSOR_ABSENT 4

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;

// Structure to hold DHT11 data
typedef struct {
    uint8_t humidity_byte0;
    uint8_t humidity_byte1;
    uint8_t temperature_byte0;
    uint8_t temperature_byte3;
    uint8_t checksum;
    int status;
} DHT11Data;

// Function prototypes
void start_pulse();
void end_pulse();
void data_bit(uint8_t bit_value);
void decode_data(DHT11Data *data);
void calculate_checksum(DHT11Data *data);
void log_error(int error_code, const char *message);
void log_data(DHT11Data *data);
void signal_handler(int signal);
void cleanup();

// Function to generate a start pulse
void start_pulse() {
    if (gpioWrite(DHT11_PIN, 0) != 0) {
        log_error(ERROR_LINE_STUCK, "Failed to set DHT11 pin low for start pulse.");
        return;
    }
    gpioDelay(START_PULSE_MIN);
    if (gpioWrite(DHT11_PIN, 1) != 0) {
        log_error(ERROR_LINE_STUCK, "Failed to set DHT11 pin high after start pulse.");
        return;
    }
    gpioDelay(START_PULSE_MAX - START_PULSE_MIN);
}

// Function to generate an end pulse
void end_pulse() {
    if (gpioWrite(DHT11_PIN, 0) != 0) {
        log_error(ERROR_LINE_STUCK, "Failed to set DHT11 pin low for end pulse.");
        return;
    }
    gpioDelay(START_PULSE_MAX);
}

// Function to send a data bit
void data_bit(uint8_t bit_value) {
    if (gpioWrite(DHT11_PIN, 0) != 0) {
        log_error(ERROR_LINE_STUCK, "Failed to set DHT11 pin low for data bit.");
        return;
    }
    gpioDelay(DATA_BIT_LOW_PERIOD);
    if (bit_value == 0) {
        gpioDelay(DATA_BIT_HIGH_PERIOD);
    } else {
        gpioDelay(DATA_BIT_HIGH_1);
    }
    if (gpioWrite(DHT11_PIN, 1) != 0) {
        log_error(ERROR_LINE_STUCK, "Failed to set DHT11 pin high after data bit.");
        return;
    }
    gpioDelay(DATA_BIT_LOW_PERIOD);
}

// Function to decode the data bits
void decode_data(DHT11Data *data) {
    for (int i = 0; i < 40; i++) {
        data_bit(data->humidity_byte0 & 0x01);
        data_bit(data->humidity_byte1 & 0x01);
        data_bit(data->temperature_byte0 & 0x01);
        data_bit(data->temperature_byte3 & 0x01);
        data_bit((data->humidity_byte0 >> 1) & 0x01);
        data_bit((data->humidity_byte1 >> 1) & 0x01);
        data_bit((data->temperature_byte0 >> 1) & 0x01);
        data_bit((data->temperature_byte3 >> 1) & 0x01);
        data_bit((data->humidity_byte0 >> 2) & 0x01);
        data_bit((data->humidity_byte1 >> 2) & 0x01);
        data_bit((data->temperature_byte0 >> 2) & 0x01);
        data_bit((data->temperature_byte3 >> 2) & 0x01);
        data_bit((data->humidity_byte0 >> 3) & 0x01);
        data_bit((data->humidity_byte1 >> 3) & 0x01);
        data_bit((data->temperature_byte0 >> 3) & 0x01);
        data_bit((data->temperature_byte3 >> 3) & 0x01);
        data_bit((data->humidity_byte0 >> 4) & 0x01);
        data_bit((data->humidity_byte1 >> 4) & 0x01);
        data_bit((data->temperature_byte0 >> 4) & 0x01);
        data_bit((data->temperature_byte3 >> 4) & 0x01);
        data_bit((data->humidity_byte0 >> 5) & 0x01);
        data_bit((data->humidity_byte1 >> 5) & 0x01);
        data_bit((data->temperature_byte0 >> 5) & 0x01);
        data_bit((data->temperature_byte3 >> 5) & 0x01);
        data_bit((data->humidity_byte0 >> 6) & 0x01);
        data_bit((data->humidity_byte1 >> 6) & 0x01);
        data_bit((data->temperature_byte0 >> 6) & 0x01);
        data_bit((data->temperature_byte3 >> 6) & 0x01);
        data_bit((data->humidity_byte0 >> 7) & 0x01);
        data_bit((data->humidity_byte1 >> 7) & 0x01);
        data_bit((data->temperature_byte0 >> 7) & 0x01);
        data_bit((data->temperature_byte3 >> 7) & 0x01);
    }
}

// Function to calculate the checksum
void calculate_checksum(DHT11Data *data) {
    uint8_t humidity_sum = data->humidity_byte0 + data->humidity_byte1;
    uint8_t temperature_sum = data->temperature_byte0 + data->temperature_byte3;
    data->checksum = humidity_sum + temperature_sum;
}

// Function to log errors
void log_error(int error_code, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s - ERROR: %s (Code: %d)\n", timestamp, message, error_code);
    fflush(log_file);
}

// Function to log data
void log_data(DHT11Data *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s - DHT11 Data: Humidity Byte0=%d, Humidity Byte1=%d, Temperature Byte0=%d, Temperature Byte3=%d, Checksum=%d, Status=%d\n",
            timestamp, data->humidity_byte0, data->humidity_byte1, data->temperature_byte0, data->temperature_byte3, data->checksum, data->status);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(DHT11_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        DHT11Data data = {0, 0, 0, 0, 0, 0};
        data.status = 0; // Initialize status to 0 (success)

        // Start pulse
        start_pulse();
        gpioDelay(TIMEOUT_RESPONSE);

        // Check for timeout on start pulse
        if (gpioRead(DHT11_PIN) == 1) {
            log_error(ERROR_TIMEOUT, "Timeout waiting for start pulse.");
            data.status = ERROR_TIMEOUT;
        } else {
            // Response pulse
            gpioDelay(TIMEOUT_RESPONSE);
            if (gpioRead(DHT11_PIN) == 0) {
                gpioDelay(TIMEOUT_DATA);
                if (gpioRead(DHT11_PIN) == 1) {
                    // Data bits
                    for (int i = 0; i < 40; i++) {
                        gpioDelay(TIMEOUT_DATA);
                        if (gpioRead(DHT11_PIN) == 0) {
                            data.humidity_byte0 |= (1 << i);
                            data.humidity_byte1 |= (1 << i);
                            data.temperature_byte0 |= (1 << i);
                            data.temperature_byte3 |= (1 << i);
                            gpioDelay(DATA_BIT_LOW_PERIOD);
                        } else {
                            data.humidity_byte0 &= ~(1 << i);
                            data.humidity_byte1 &= ~(1 << i);
                            data.temperature_byte0 &= ~(1 << i);
                            data.temperature_byte3 &= ~(1 << i);
                            gpioDelay(DATA_BIT_LOW_PERIOD);
                        }
                    }

                    // Checksum
                    gpioDelay(TIMEOUT_DATA);
                    if (gpioRead(DHT11_PIN) == 1) {
                        gpioDelay(CHECKSUM_PULSE_MIN);
                        if (gpioRead(DHT11_PIN) == 0) {
                            gpioDelay(CHECKSUM_PULSE_MAX);
                            if (gpioRead(DHT11_PIN) == 1) {
                                calculate_checksum(&data);
                                uint8_t checksum = data.checksum;
                                uint8_t calculated_checksum = (data.humidity_byte0 + data.humidity_byte1 + data.temperature_byte0 + data.temperature_byte3) & 0xFF;

                                if (checksum == calculated_checksum) {
                                    data.status = 0; // Success
                                } else {
                                    log_error(ERROR_CHECKSUM, "Checksum mismatch.");
                                    data.status = ERROR_CHECKSUM;
                                }
                            } else {
                                log_error(ERROR_TIMEOUT, "Timeout waiting for checksum start pulse.");
                                data.status = ERROR_TIMEOUT;
                            }
                        } else {
                            log_error(ERROR_TIMEOUT, "Timeout waiting for checksum low pulse.");
                            data.status = ERROR_TIMEOUT;
                        }
                    } else {
                        log_error(ERROR_TIMEOUT, "Timeout waiting for checksum high pulse.");
                        data.status = ERROR_TIMEOUT;
                    }
                } else {
                    log_error(ERROR_TIMEOUT, "Timeout waiting for response high pulse.");
                    data.status = ERROR_TIMEOUT;
                }
            } else {
                log_error(ERROR_TIMEOUT, "Timeout waiting for response low pulse.");
                data.status = ERROR_TIMEOUT;
            }
        }

        // Log data
        log_data(&data);

        // Wait for 2 seconds
        gpioDelay(2000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

