#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// SHT31-D I2C address
#define SHT31_ADDR 0x44

// SHT31-D command to trigger a single measurement
#define SHT31_MEASURE_CMD 0x2C06

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_log_file();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int bytes, uint8_t polynomial);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT31_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize log file
int init_log_file() {
    log_file = fopen("sht31d_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from SHT31-D sensor
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(SHT31_MEASURE_CMD >> 8) & 0xFF, SHT31_MEASURE_CMD & 0xFF};
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(15000); // Wait 15ms
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
                retries--;
                gpioDelay(1000); // Wait 1ms before retrying
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", 4 - retries, result);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    return -1; // All retries failed
}

// Validate CRC-8 checksum
int validate_crc(uint8_t *data, int bytes, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < bytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Convert raw humidity data to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize log file
    if (init_log_file() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t sensor_data_typed;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 2, CRC_POLYNOMIAL) && validate_crc(sensor_data + 3, 2, CRC_POLYNOMIAL)) {
                // Convert data
                uint16_t raw_temp = (sensor_data[0] << 8) | sensor_data[1];
                uint16_t raw_humidity = (sensor_data[3] << 8) | sensor_data[4];

                sensor_data_typed.temperature = convert_temperature(raw_temp);
                sensor_data_typed.humidity = convert_humidity(raw_humidity);

                // Log data
                if (log_data(sensor_data_typed.temperature, sensor_data_typed.humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

