void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ADPD105_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data from ADPD105 registers
int read_sensor_data(sensor_data_t *sensor1, sensor_data_t *sensor2) {
    uint8_t buffer[8];
    int result;

    // Read Red channel data (example, adjust based on datasheet)
    result = i2cReadI2CBlockData(i2c_handle, ADPD105_REG_FIFO_DATA_LSB, (char *)buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    sensor1->red = (int16_t)((buffer[1] << 8) | buffer[0]);
    sensor1->green = (int16_t)((buffer[3] << 8) | buffer[2]);
    sensor1->blue = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read Green channel data (example, adjust based on datasheet)
    result = i2cReadI2CBlockData(i2c_handle, ADPD105_REG_FIFO_DATA_LSB, (char *)buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    sensor2->red = (int16_t)((buffer[1] << 8) | buffer[0]);
    sensor2->green = (int16_t)((buffer[3] << 8) | buffer[2]);
    sensor2->blue = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate Correlated Color Temperature (CCT)
float calculate_cct(sensor_data_t sensor1, sensor_data_t sensor2) {
