    float cct = 5000.0; // Example value
    return cct;
}

// Log average CCT to file
int log_cct(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, cct);
    fclose(log_file);

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor1, sensor2;
    float cct;

    while (!terminate) {
        if (read_sensor_data(&sensor1, &sensor2) == 0) {
            cct = calculate_cct(sensor1, sensor2);
            if (log_cct(cct) != 0) {
                fprintf(stderr, "Failed to log CCT.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping logging.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

