#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90824_ADDR 0x60

// Define the log file name
#define LOG_FILE "pressure_log.txt"

// Define the sensor's register addresses (replace with actual values from datasheet)
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02

// Define the number of retries for I2C read
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *pressure, uint16_t *temperature);
sensor_data_t convert_data(uint16_t raw_pressure, uint16_t raw_temperature);
int log_data(sensor_data_t data);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint16_t *pressure, uint16_t *temperature) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, PRESSURE_REG);
        if (result >= 0) {
            *pressure = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading pressure data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read pressure data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
        if (result >= 0) {
            *temperature = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read temperature data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint16_t raw_pressure, uint16_t raw_temperature) {
    sensor_data_t data;
    // Implement the conversion formulas from the MLX90824 datasheet here
    // These are placeholder values, replace with actual calculations
    data.pressure = (float)raw_pressure * 0.1; // Example conversion
    data.temperature = (float)raw_temperature * 0.01 - 40.0; // Example conversion
    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint16_t raw_pressure, raw_temperature;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            sensor_data = convert_data(raw_pressure, raw_temperature);

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

