#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define SAMPLES 60
#define AVG_WINDOW 5
#define HISTOGRAM_SIZE 10
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define TEMP_HYSTERESIS 1.0
#define TEMP_HYSTERESIS_OFFSET 0.5
#define TEMP_HYSTERESIS_THRESHOLD 0.5

// Global variables
int i2c_handle;
double temperature_buffer[SAMPLES];
int buffer_index = 0;
double running_average = 0.0;
int fan_state = 0; // 0 = off, 1 = on
int histogram[HistogramSize];
int histogram_index = 0;
int histogram_count = 0;

// Function prototypes
int initialize();
double read_temperature();
double calculate_running_average();
void control_fan(double average_temperature);
void update_histogram(double temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int lm75b_address;
    int fan_gpio;
    int samples;
    double temp_threshold_high;
    double temp_threshold_low;
    double temp_hysteresis;
    int histogram_size;
} config_t;

config_t config = {
    I2C_BUS,
    LM75B_ADDR,
    FAN_GPIO,
    SAMPLES,
    TEMP_THRESHOLD_HIGH,
    TEMP_THRESHOLD_LOW,
    TEMP_HYSTERESIS,
    HistogramSize
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        double temperature = read_temperature();
        if (temperature < -273.0) {
            fprintf(stderr, "Error reading temperature. Retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        running_average = calculate_running_average();
        control_fan(running_average);

        update_histogram(temperature);

        printf("Temperature: %.2f °C, Running Average: %.2f °C, Fan: %s\n", temperature, running_average, fan_state ? "ON" : "OFF");

        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(config.i2c_bus, config.lm75b_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(config.fan_gpio, PI_OUTPUT);
    fan_state = 0; // Ensure fan is off on startup

    return 0;
}

