    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    double temperature = raw_temp * 0.125; // Each bit is 0.125 degrees C

    return temperature;
}

double calculate_running_average() {
    double sum = 0.0;
    for (int i = 0; i < SAMPLES; i++) {
        sum += temperature_buffer[i];
    }
    return sum / SAMPLES;
}

void control_fan(double average_temperature) {
    if (average_temperature > config.temp_threshold_high && fan_state == 0) {
        gpioWrite(config.fan_gpio, 1); // Turn fan on
        fan_state = 1;
        printf("Fan turned ON\n");
    } else if (average_temperature < config.temp_threshold_low && fan_state == 1) {
        gpioWrite(config.fan_gpio, 0); // Turn fan off
        fan_state = 0;
        printf("Fan turned OFF\n");
    }
}

void update_histogram(double temperature) {
    histogram[histogram_index] = temperature;
    histogram_index = (histogram_index + 1) % HistogramSize;
    if (histogram_count < HistogramSize) {
        histogram_count++;
    }

    // Calculate the average of the histogram
    double histogram_sum = 0.0;
    for (int i = 0; i < histogram_count; i++) {
        histogram_sum += histogram[i];
    }
    double histogram_average = histogram_sum / histogram_count;

    // Check if the temperature is outside the hysteresis range
    if (temperature > (histogram_average + config.temp_hysteresis)) {
        // Turn the fan on
        if (fan_state == 0) {
            gpioWrite(config.fan_gpio, 1);
            fan_state = 1;
        }
    } else if (temperature < (histogram_average - config.temp_hysteresis)) {
        // Turn the fan off
        if (fan_state == 1) {
            gpioWrite(config.fan_gpio, 0);
            fan_state = 0;
        }
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    gpioWrite(config.fan_gpio, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

