#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_MS 1000
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 polynomial
const uint8_t crc_polynomial = 0x31;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, int data_len, uint8_t checksum);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(sensor_data_t data);
void check_pressure_threshold(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(const uint8_t *data, int data_len, uint8_t checksum) {
    uint8_t crc = 0;
    for (int i = 0; i < data_len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc_polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == checksum);
}

// Process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Convert to physical units (Pa and °C)
    sensor_data.pressure = (float)raw_pressure / 240.0; // Scaling factor from datasheet
    sensor_data.temperature = (float)raw_temperature / 200.0; // Scaling factor from datasheet

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Check pressure threshold
void check_pressure_threshold(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa > %.2f Pa)!\n", pressure, PRESSURE_THRESHOLD);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Send measurement command and wait
    if (send_measurement_command() != 0) {
        cleanup();
        return 1;
    }
    gpioDelay(45000); // 45ms

    // Main loop
    uint8_t sensor_data[9];
    sensor_data_t processed_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 9, sensor_data[8])) {
                // Process sensor data
                processed_data = process_sensor_data(sensor_data);

                // Log data
                log_data(processed_data);

                // Check pressure threshold
                check_pressure_threshold(processed_data.pressure);

                // Print data to console
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", processed_data.pressure, processed_data.temperature);
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

