#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDR 0x25

// Define the measurement command (continuous measurement without averaging)
#define MEASURE_CMD 0x362F

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t differential_pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], uint8_t crc);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SDP800_I2C_ADDR, 0); // Bus 1, address 0x25, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Extract data from the buffer
    data->differential_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t crc_calculated = 0;
    for (int i = 0; i < 8; i++) {
        crc_calculated ^= (data[i] & 0x01);
        if (crc_calculated != 0) {
            crc_calculated = (crc_calculated >> 1) ^ CRC_POLYNOMIAL;
        } else {
            crc_calculated >>= 1;
        }
    }
    return (crc_calculated == crc);
}

// Function to log the data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Differential Pressure: %d Pa, Temperature: %d C, Scale Factor: %u\n",
            timestamp, data.differential_pressure, data.temperature, data.scale_factor);
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Wait for at least 45ms
        gpioDelay(45000); // 45ms

        // Read sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate CRC checksums
        if (!validate_crc((uint8_t[]){sensor_data.differential_pressure}, (uint8_t)(sensor_data.differential_pressure >> 8))) {
            fprintf(stderr, "CRC error in differential pressure\n");
        }
        if (!validate_crc((uint8_t[]){sensor_data.temperature}, (uint8_t)(sensor_data.temperature >> 8))) {
            fprintf(stderr, "CRC error in temperature\n");
        }

        // Log the data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

