#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_NOHOLD 0xE3
#define MEASURE_RH_NOHOLD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t command, uint16_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry
int read_sensor_data(uint8_t command, uint16_t *data) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, command);
        if (result != 0) {
            fprintf(stderr, "Error writing command 0x%02X: %d, retry %d\n", command, result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(20 * 1000); // Wait for measurement (at least 20ms)

        result = i2cReadWordData(i2c_handle, 0); // Read 2 bytes
        if (result < 0) {
            fprintf(stderr, "Error reading data: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        *data = (uint16_t)result;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor readings...\n");

    while (!terminate) {
        uint16_t raw_temp, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(MEASURE_TEMP_NOHOLD, &raw_temp) == 0) {
            temperature = convert_temperature(raw_temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(MEASURE_RH_NOHOLD, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            fprintf(stderr, "Failed to read humidity.\n");
            humidity = -999.0; // Indicate error
        }

        // Log data
        if (temperature != -999.0 && humidity != -999.0) {
            log_data(temperature, humidity);
            printf("Timestamp: %s, Temperature: %.2f C, Humidity: %.2f %%\n", time_string(time(NULL)), temperature, humidity);
        } else {
            fprintf(stderr, "Skipping logging due to sensor error.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

