#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS40_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define LOG_FILE "temperature_log.txt"

int i2c_handle;
FILE *log_file;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
float read_temperature() {
    uint8_t data[3];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Wait for conversion (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 3 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // CRC verification
    uint8_t crc_calculated = crc8(data, 2);
    if (crc_calculated != data[2]) {
        fprintf(stderr, "CRC mismatch!\n");
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temperature = (data[0] << 8) | data[1];
    float temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping log.\n");
        }

        sleep(5);
    }

    return 0;
}

