// Structure for sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Structure for circular buffer
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle;
static circular_buffer_t buffer;
static pthread_t logging_thread;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_sensor_data(sensor_data_t *data);
int validate_crc(const unsigned char *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void *logging_thread_func(void *arg);
void log_error(const char *message);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void flush_buffer_to_csv();

// CRC-8 validation function
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    char read_buf[9];
    int result;

    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Extract data
    data->co2 = (read_buf[0] << 8) | read_buf[1];
    data->temperature = (read_buf[3] << 8) | read_buf[4];
    data->humidity = (read_buf[6] << 8) | read_buf[7];

    // Validate CRC
    if (!validate_crc(read_buf, 8)) {
        log_error("CRC validation failed");
        return -1;
    }

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get data from circular buffer
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        log_error("Invalid buffer index");
        sensor_data_t empty_data = {0.0, 0.0, 0.0}; // Return a default value
        return empty_data;
    }
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

