        return;
    }

    int start_index = buffer.head;
    if (buffer.count == BUFFER_SIZE) {
        start_index = buffer.tail;
    }

    for (int i = 0; i < buffer.count; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                buffer.data[index].co2, buffer.data[index].temperature, buffer.data[index].humidity,
                buffer.data[index].co2, buffer.data[index].temperature, buffer.data[index].humidity);
    }

    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

