#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_ADDR 0x69
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 95000.0f
#define SAMPLE_INTERVAL_MS 1000
#define LED_ON_TIME_MS 500
#define LED_OFF_TIME_MS 500
#define LED_BLINK_RATE_1HZ (LED_ON_TIME_MS + LED_OFF_TIME_MS)
#define LED_BLINK_RATE_5HZ (LED_ON_TIME_MS + LED_OFF_TIME_MS + LED_ON_TIME_MS + LED_OFF_TIME_MS)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int verify_crc(uint8_t *data, uint8_t crc);
sensor_data_t process_sensor_data(uint8_t *data);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6); // Read 6 bytes starting from register 0x00
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Verify CRC
int verify_crc(uint8_t *data, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < 5; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Process sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    // Convert raw data to pressure and temperature (example formulas, adjust as needed)
    sensor_data.pressure = (float)((data[0] << 8) | data[1]) / 10.0f; // Example: 2 bytes * 10 Pa/byte
    sensor_data.temperature = (float)((data[2] << 8) | data[3]) / 10.0f; // Example: 2 bytes * 10 degC/byte
    return sensor_data;
}

// Control LED based on pressure
void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
        gpioDelay(LED_BLINK_RATE_5HZ); // Blink at 5Hz
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
        gpioDelay(LED_BLINK_RATE_1HZ); // Blink at 1Hz
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t processed_data;

    printf("Starting sensor monitoring...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Verify CRC
            if (verify_crc(sensor_data, sensor_data[5])) {
                // Process sensor data
                processed_data = process_sensor_data(sensor_data);

                // Control LED
                control_led(processed_data.pressure);

                // Print sensor data (optional)
                printf("Pressure: %.2f Pa, Temperature: %.2f degC\n", processed_data.pressure, processed_data.temperature);
            } else {
                fprintf(stderr, "CRC verification failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

