#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define HYSTERESIS 2.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(int reg, float *temperature);
int log_temperature(float ambient_temp, float object_temp);
int control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
int read_temperature(int reg, float *temperature) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            // Success, convert to Celsius
            *temperature = (float)((int16_t)result * 0.02) - 273.15;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retrying...\n", reg);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Failure
}

