int control_fan(float object_temp) {
    if (object_temp > 30.0 + HYSTERESIS) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (object_temp < 28.0 - HYSTERESIS) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

int main() {
