    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    float ambient_temp, object_temp;

    // Main loop
    while (!terminate) {
        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &ambient_temp) == 0 &&
            read_temperature(OBJECT_TEMP_REG, &object_temp) == 0) {
            // Log temperatures
            if (log_temperature(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Failed to log temperature data\n");
            }

            // Control fan
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature data\n");
        }

        gpioDelay(2000); // 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

