#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[6];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing to I2C device.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(10000); // Wait for measurement (at least 10ms)

        bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (bytes_read == 6) {
            // Convert data
            unsigned short temp_raw = (data[0] << 8) | data[1];
            unsigned short humidity_raw = (data[3] << 8) | data[4];

            *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
            *humidity = -6.0 + 125.0 * (float)humidity_raw / 65535.0;

            // Clamp humidity
            if (*humidity < 0.0) *humidity = 0.0;
            if (*humidity > 100.0) *humidity = 100.0;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device, retries remaining: %d\n", retries);
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read SHT40 after multiple retries.\n");
    return -1; // Failure
}

int main() {
    float temperature, humidity;
    char http_response[512];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create HTTP server
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (!terminate) {
        // Read sensor data
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Format data for HTTP response
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            snprintf(http_response, sizeof(http_response), 
                     "HTTP/1.1 200 OK\r\n" 
                     "Content-Type: text/html\r\n" 
                     "Connection: close\r\n" 
                     "\r\n" 
                     "<!DOCTYPE html><html><head><title>SHT40 Sensor</title></head><body>" 
                     "<h1>SHT40 Sensor Data</h1>" 
                     "<p>Timestamp: %s</p>" 
                     "<p>Temperature: %.2f °C</p>" 
                     "<p>Humidity: %.2f %%</p>" 
                     "</body></html>", timestamp, temperature, humidity);
        } else {
            http_response[0] = '\0'; // Clear response if read failed
        }

        // Send HTTP response
        if (send(server_fd, http_response, strlen(http_response), 0) < 0) {
            perror("send failed");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Clean up
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

