#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp102_address;
    char csv_filename[64];
} config_t;

config_t config = {I2C_BUS, TMP102_ADDR, CSV_FILE};

int main() {
    float temperature;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open CSV file for appending
    log_file = fopen(config.csv_filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s. Exiting.\n", config.csv_filename);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpioInitialise());
        return 1;
    }

    i2c_handle = i2cOpen(config.i2c_bus, config.tmp102_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read temperature from TMP102
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    *temperature = raw_temp * 0.0625;

    return 0;
}

// Log temperature to CSV file
int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Terminating program...\n");
    terminate = 1;
}

