// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define HDC2010_CONFIG_REG 0x0E
#define HDC2010_TEMP_REG 0x00
#define HDC2010_HUMID_REG 0x02
#define HDC2010_RESET_REG 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_sensor();
int read_sensor_data(float *temperature, float *humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the HDC2010 sensor
int config_sensor() {
    // Configure for temperature and humidity measurement, 14-bit resolution
    // Configuration value: 0x00 (default settings)
    char config_data[2] = {HDC2010_CONFIG_REG, 0x00};
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    char trigger_data[1] = {HDC2010_TEMP_REG};
    char read_data[4];
    int result;

    // Trigger temperature and humidity measurement
    result = i2cWriteDevice(i2c_handle, trigger_data, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 7ms)
    gpioDelay(10000); // 10ms

    // Read temperature and humidity data
    result = i2cReadDevice(i2c_handle, read_data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temp_raw = (read_data[0] << 8) | read_data[1];
    uint16_t humid_raw = (read_data[2] << 8) | read_data[3];

    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humid_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (config_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    int retry_count = 0;
    int config_result;

    while (!terminate) {
        // Retry reading sensor data up to 5 times
        for (int i = 0; i < 5; i++) {
            config_result = config_sensor();
            if (config_result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Sensor configuration failed, retrying (%d/%d)...\n", i + 1, 5);
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (config_result != 0) {
            fprintf(stderr, "Failed to configure sensor after multiple retries. Exiting.\n");
            break;
        }

        if (retry_count >= 5) {
            fprintf(stderr, "Failed to read sensor data after multiple retries. Exiting.\n");
            break;
        }

        if (read_sensor_data(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            retry_count = 0; // Reset retry count on success
        } else {
            fprintf(stderr, "Failed to read sensor data. Retry count: %d\n", retry_count + 1);
            retry_count++;
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

