#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the measurement command
#define MEASURE_CMD 0x362F

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for the I2C handle
int i2c_handle;

// Function prototypes
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature);
void validate_crc(uint8_t data[], int length, uint8_t crc);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature) {
    uint8_t buffer[6];
    int result;

    // Send the measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 45ms)
    gpioDelay(45000); // 45ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate the CRC checksums
    if (!validate_crc(buffer, 2, buffer[2]) || !validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    // Extract the pressure and temperature values
    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

// Function to validate the CRC checksum
void validate_crc(uint8_t data[], int length, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < length; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    if (crc_calculated != crc) {
        fprintf(stderr, "CRC check failed\n");
        exit(EXIT_FAILURE);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int16_t pressure, temperature;
    sensor_data_t sensor_data;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the sensor data
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            // Store the data in the sensor_data_t struct
            sensor_data.pressure = pressure;
            sensor_data.temperature = temperature;

            // Log the data to the console
            printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

