#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define TARGET_PROFILE_FILE "profile.txt"
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_SEC 1
#define MAX_RETRIES 3

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static FILE *target_profile_file;
static double target_temperature = 0.0; // Default target temperature
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
int spi_read_max6675(int spi_handle, double *temperature);
double pid_control(double setpoint, double actual_temperature, double *integral, double *previous_error, double kp, double ki, double kd, double dt);
void set_relay_duty_cycle(int gpio_pin, double duty_cycle);
void log_data(double temperature, double duty_cycle);
void load_target_profile(const char *filename);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(RELAY_GPIO, 1000); // 1 kHz
    gpioSetPWMrange(RELAY_GPIO, 100); // 0-100 duty cycle

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    target_profile_file = fopen(TARGET_PROFILE_FILE, "r");
    if (target_profile_file == NULL) {
        fprintf(stderr, "Failed to open target profile file\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    load_target_profile(TARGET_PROFILE_FILE);

    return 0;
}

// Function to read temperature from MAX6675
int spi_read_max6675(int spi_handle, double *temperature) {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return 1;
    }

    // Check for fault
    if (buffer[3] & 0x01) {
        fprintf(stderr, "Thermocouple fault detected\n");
        return 1;
    }

    // Extract temperature (14-bit, signed)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate PID output
double pid_control(double setpoint, double actual_temperature, double *integral, double *previous_error, double kp, double ki, double kd, double dt) {
    double error = setpoint - actual_temperature;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;

    // Clamp output to 0-100
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Function to set relay duty cycle
void set_relay_duty_cycle(int gpio_pin, double duty_cycle) {
    gpioPWM(gpio_pin, (int)duty_cycle);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
