    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(RELAY_GPIO, 1000); // 1 kHz
    gpioSetPWMrange(RELAY_GPIO, 100); // 0-100 duty cycle

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
