#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <w1_slave.h>

// Define GPIO pins
#define HEATER_RELAY_PIN 17
#define PWM_PIN 18
#define DS18B20_PIN 4 // Physical pin 7, WiringPi pin 4

// Define constants
#define LOG_FILE "greenhouse.log"
#define TEMPERATURE_THRESHOLD 30.0
#define PWM_RANGE 1024
#define PWM_FREQUENCY 1000 // Hz

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// PID gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Function prototypes
float read_temperature();
float validate_crc(const char *data);
void set_pwm_duty_cycle(int duty_cycle);
void set_relay_state(int state);
void log_data(float avg_temp, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], float *setpoint, float *kp, float *ki, float *kd);

// Function to read temperature from DS18B20 sensor
float read_temperature() {
    float temperature = -1000.0; // Initialize to an invalid value
    char *w1_device = NULL;
    int i;

    // Find the w1_slave device
    w1_device = find_w1_slave();
    if (w1_device == NULL) {
        fprintf(stderr, "Error: Could not find w1_slave device.\n");
        return temperature;
    }

    // Read the temperature data
    if (w1_slave(w1_device, "t") == 0) {
        char *temp_str = strstr(w1_slave(w1_device, "t"), "t=");
        if (temp_str != NULL) {
            long temp_raw = strtol(temp_str + 2, NULL, 10);
            temperature = (float)temp_raw / 1000.0;
        } else {
            fprintf(stderr, "Error: Could not find temperature data in w1_slave output.\n");
            return temperature;
        }
    } else {
        fprintf(stderr, "Error: w1_slave command failed.\n");
        return temperature;
    }

    // Free the w1_slave device
    free(w1_device);

    // Validate the CRC
    if (validate_crc((char *)temperature) != 0) {
        fprintf(stderr, "Error: CRC validation failed for temperature data.\n");
        return temperature;
    }

    return temperature;
}

// Function to validate the CRC checksum
float validate_crc(const char *data) {
    unsigned char crc = 0;
    unsigned char bit;
    int i;

    for (i = 0; data[i] != '\0'; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // XOR with 0x131
            else
                crc = (crc << 1);
        }
    }
    if (crc != 0) {
        fprintf(stderr, "Error: CRC checksum failed for data: %s\n", data);
        return -1;
    }
    return 0;
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    pwmWrite(PWM_PIN, duty_cycle);
}

// Function to set the relay state
void set_relay_state(int state) {
    digitalWrite(HEATER_RELAY_PIN, state);
}

// Function to log data to a file
void log_data(float avg_temp, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, avg_temp, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    set_relay_state(LOW); // Turn off the heater
    set_pwm_duty_cycle(0); // Set PWM to 0
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], float *setpoint, float *kp, float *ki, float *kd) {
    int opt;
    while ((opt = getopt(argc, argv, "s:k:i:d:")) != -1) {
        switch (opt) {
            case 's':
                *setpoint = atof(optarg);
                break;
            case 'k':
                *kp = atof(optarg);
                break;
            case 'i':
                *ki = atof(optarg);
                break;
            case 'd':
                *kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s setpoint] [-k Kp] [-i Ki] [-d Kd]\n", argv[0]);
                return 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    float setpoint = 25.0; // Default setpoint
    float pid_output = 0.0;
    int pwm_duty_cycle = 0;
    float temperature;
    float avg_temp = 0.0;
    int i;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &setpoint, &Kp, &Ki, &Kd) != 0) {
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Unable to initialize wiringPi.\n");
        return 1;
    }

    // Set GPIO modes
    pinMode(HEATER_RELAY_PIN, OUTPUT);
    pinMode(PWM_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired frequency

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Greenhouse heater control started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, Kp, Ki, Kd);

    // Main loop
    while (program_running) {
        // Read temperature
        temperature = read_temperature();

        if (temperature > -999.0) {
            // Calculate average temperature
            avg_temp = temperature;

            // Calculate PID output
            pid_output = Kp * (setpoint - avg_temp) + Ki * (avg_temp - (avg_temp - temperature) * 0.1) + Kd * (avg_temp - temperature) * 0.1;

            // Limit PID output to 0-100
            if (pid_output < 0) pid_output = 0;
            if (pid_output > 100) pid_output = 100;

            // Set PWM duty cycle
            pwm_duty_cycle = (int)pid_output;
            set_pwm_duty_cycle(pwm_duty_cycle);

            // Set relay state
            set_relay_state(HIGH);

            // Log data
            log_data(avg_temp, setpoint, pid_output, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Error: Could not read temperature. Skipping PID calculation.\n");
        }

        // Check temperature threshold
        if (avg_temp > TEMPERATURE_THRESHOLD) {
            set_relay_state(LOW); // Turn off heater
            pwm_duty_cycle = 0;
            set_pwm_duty_cycle(pwm_duty_cycle);
        }

        // Wait for 5 seconds
        delay(5000);
    }

    // Cleanup (should not reach here if signal handler is working)
    set_relay_state(LOW); // Turn off heater
    set_pwm_duty_cycle(0); // Set PWM to 0
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

