            set_relay_state(HIGH);

            // Log data
            log_data(avg_temp, setpoint, pid_output, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Error: Could not read temperature. Skipping PID calculation.\n");
        }

        // Check temperature threshold
        if (avg_temp > TEMPERATURE_THRESHOLD) {
            set_relay_state(LOW); // Turn off heater
            pwm_duty_cycle = 0;
            set_pwm_duty_cycle(pwm_duty_cycle);
        }

        // Wait for 5 seconds
        delay(5000);
    }

    // Cleanup (should not reach here if signal handler is working)
    set_relay_state(LOW); // Turn off heater
    set_pwm_duty_cycle(0); // Set PWM to 0
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
