        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("AHT20 Humidity Sensor Program\n");

    while (!terminate) {
        // Read humidity from sensor
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_aht20(data) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retry %d failed, attempting again...\n", retry + 1);
                retry++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read from AHT20 after %d retries. Sensor may be absent or malfunctioning.\n", RETRY_COUNT);
            cleanup();
            return 1;
