        // Calculate humidity
        humidity = calculate_humidity(data);

        // Get current timestamp
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log humidity reading
        printf("%s Humidity: %.2f%%\n", timestamp, humidity);

        // Control dehumidifier relay
        control_relay(humidity);

        // Wait for 5 seconds
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

