#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 80
#define POLL_INTERVAL 60 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
int running = 1;

// Function prototypes
int init_i2c();
int read_humidity();
int post_data(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C bus initialized successfully.");
    return 0;
}

// Function to read humidity from the HTU21D sensor
int read_humidity() {
    unsigned char cmd[2] = {0xE5, 0x9C}; // Trigger measurement command
    unsigned char data[3];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            syslog(LOG_ERR, "I2C write error (trigger): %d, retry %d", result, retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result != 3) {
            syslog(LOG_ERR, "I2C read error (data): %d, retry %d", result, retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Check CRC
        if (data[2] != ((data[0] + data[1]) & 0xFF)) {
            syslog(LOG_ERR, "CRC check failed.");
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data to humidity
        int raw_humidity = (data[0] << 8) | data[1];
        float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);
        if (humidity < 0.0) humidity = 0.0;
        if (humidity > 100.0) humidity = 100.0;

        return (int)humidity;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries.", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to post data to the server
int post_data(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[100];
    int retries = 0;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed: %m");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %m");
        close(sockfd);
        return -1;
    }

    // Format JSON data
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    // Send data
    if (send(sockfd, json_data, strlen(json_data), 0) < 0) {
        syslog(LOG_ERR, "Failed to send data: %m");
        close(sockfd);
        return -1;
    }

    syslog(LOG_INFO, "Data posted successfully: %s", json_data);
    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        float humidity = read_humidity();
        if (humidity >= 0) {
            if (post_data(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        sleep(POLL_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

