// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_PRESSURE_LSB 0xF8
#define BMP280_REG_PRESSURE_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRESS 5 // x16

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int log_pressure(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize BMP280 sensor
int init_bmp280() {
    // Set oversampling and power mode
    char config_data[2];
    config_data[0] = BMP280_REG_CTRL_MEAS;
    config_data[1] = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | 0x03; // Normal mode
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set filter and standby time
    config_data[0] = BMP280_REG_CONFIG;
    config_data[1] = 0x00; // Filter off, standby 0.5ms
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

