#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define RETRY_COUNT 3
#define BACKOFF_MS 10

// Global variables
static volatile int running = 1;
static int i2c_handle;

// Function prototypes
int init_i2c();
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir();
int log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sensor_data_t data;

        // Read sensor data
        if (read_tmp117(&data.temperature) != 0) {
            fprintf(stderr, "Failed to read TMP117\n");
            data.temperature = -999.0; // Indicate error
        }
        if (read_aht20(&data.humidity) != 0) {
            fprintf(stderr, "Failed to read AHT20\n");
            data.humidity = -999.0; // Indicate error
        }
        if (read_pir() != 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
            data.motion_detected = -1; // Indicate error
        } else {
            data.motion_detected = gpioRead(PIR_GPIO);
        }

        // Log data
        if (log_data(data.temperature, data.humidity, data.motion_detected) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    char buf[2];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        buf[0] = 0x00; // Register address for temperature
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "I2C write error (TMP117 read)\n");
            gpioDelay(10); // Wait before retrying
            retries++;
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            // Combine the two bytes into a 16-bit integer
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            // Convert to Celsius (TMP117 is in Celsius)
            *temperature = (float)raw_temp / 128.0;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (TMP117 read)\n");
            gpioDelay(10 * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Read humidity from AHT20
int read_aht20(float *humidity) {
    char buf[3];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        buf[0] = 0xAC; // Trigger measurement command
        buf[1] = 0x33; // Argument for trigger measurement
        buf[2] = 0x00; // Dummy byte

        if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
            fprintf(stderr, "I2C write error (AHT20 trigger)\n");
            gpioDelay(10); // Wait before retrying
            retries++;
            continue;
        }

        gpioDelay(80); // Wait for measurement (at least 75ms)

        if (i2cReadDevice(i2c_handle, buf, 3) == 3) {
            // Check status bit (bit 7 of buf[0])
            if (!(buf[0] & 0x80)) {
                // Convert humidity data
                int32_t raw_humidity = ((buf[1] << 8) | buf[2]) & 0x3FFF; // Mask out status bits
                *humidity = (float)raw_humidity / 0.0625;
                return 0; // Success
            } else {
                fprintf(stderr, "AHT20 not ready\n");
                gpioDelay(10 * (1 << retries)); // Exponential backoff
                retries++;
            }
        } else {
            fprintf(stderr, "I2C read error (AHT20 data)\n");
            gpioDelay(10 * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Read motion detection from PIR sensor
int read_pir() {
    return gpioRead(PIR_GPIO);
}

// Log data to CSV file
int log_data(float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[50];
    char timestamp[20];

    // Create filename based on the current date
    strftime(filename, sizeof(filename), "sensor_data_%Y-%m-%d.csv", &tm);

    // Create timestamp string
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the file in append mode
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        return -1;
    }

    // Write header if the file is new
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }

    // Write data to the file
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);

    // Close the file
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

