#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_FORWARD_DURATION 5 // seconds
#define MOTOR_SPEED 150 // PWM duty cycle (0-255)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int forward);
int stop_motor();
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set PWM range and frequency (optional, but good practice)
    gpioSetPWMrange(MOTOR_ENA_PIN, 255);
    gpioSetPWMfrequency(MOTOR_ENA_PIN, 1000); // 1 kHz

    return 0; // Indicate success
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
int control_motor(int forward) {
    if (forward) {
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, MOTOR_SPEED);
        log_message("Motor started forward");
    } else {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, 0);
        log_message("Motor stopped");
    }
    return 0;
}

// Function to stop the motor
int stop_motor() {
    gpioPWM(MOTOR_ENA_PIN, 0);
    return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, stopping...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    log_message("Cleaning up...");
    stop_motor();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    log_message("Cleanup complete. Exiting.");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("window_control.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    log_message("Program started");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) { // Assuming active-low logic
            log_message("Rain detected!");
            if (control_motor(1) != 0) {
                log_message("Error controlling motor forward");
            }
            gpioDelay(MOTOR_FORWARD_DURATION * 1000000); // Delay for motor duration (microseconds)
            if (control_motor(0) != 0) {
                log_message("Error controlling motor stop");
            }
        } else {
            log_message("No rain detected");
        }

        gpioDelay(2000000); // Poll every 2 seconds (microseconds)
    }

    cleanup();
    return 0;
}

