#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
int udp_socket;
struct sockaddr_in server_addr;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} calib;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temp);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int create_udp_socket();
int send_udp_packet(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Reset the sensor
    char reset_cmd[2] = {BMP280_REG_RESET, 0xB6};
    if (i2cWriteDevice(i2c_handle, reset_cmd, 2) != 0) {
        fprintf(stderr, "Error resetting BMP280\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure sensor (example: oversampling x16, normal mode)
    char config_cmd[2] = {BMP280_REG_CONFIG, 0x04}; // t_sb = 0.5ms, filter off
    if (i2cWriteDevice(i2c_handle, config_cmd, 2) != 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    char ctrl_meas_cmd[2] = {BMP280_REG_CTRL_MEAS, 0x27}; // osrs_t = x16, osrs_p = x16, normal mode
    if (i2cWriteDevice(i2c_handle, ctrl_meas_cmd, 2) != 0) {
        fprintf(stderr, "Error writing control register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    char calib_data[26];
    if (i2cReadDevice(i2c_handle, calib_data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)calib_data[0] | ((uint16_t)calib_data[1] << 8);
    calib.dig_T2 = (int16_t)calib_data[2] | ((int16_t)calib_data[3] << 8);
    calib.dig_T3 = (int16_t)calib_data[4] | ((int16_t)calib_data[5] << 8);
    calib.dig_P1 = (uint16_t)calib_data[6] | ((uint16_t)calib_data[7] << 8);
    calib.dig_P2 = (int16_t)calib_data[8] | ((int16_t)calib_data[9] << 8);
    calib.dig_P3 = (int16_t)calib_data[10] | ((int16_t)calib_data[11] << 8);
    calib.dig_P4 = (int16_t)calib_data[12] | ((int16_t)calib_data[13] << 8);
    calib.dig_P5 = (int16_t)calib_data[14] | ((int16_t)calib_data[15] << 8);
    calib.dig_P6 = (int16_t)calib_data[16] | ((int16_t)calib_data[17] << 8);
    calib.dig_P7 = (int16_t)calib_data[18] | ((int16_t)calib_data[19] << 8);
    calib.dig_P8 = (int16_t)calib_data[20] | ((int16_t)calib_data[21] << 8);
    calib.dig_P9 = (int16_t)calib_data[22] | ((int16_t)calib_data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the sensor
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double var1_p, var2_p;

    var1_p = ((double)t_fine / 2.0) - 64000.0;
    var2_p = var1_p * var1_p * ((double)calib.dig_P6) / 32768.0;
    var2_p = var2_p + var1_p * ((double)calib.dig_P5) * 2.0;
    var2_p = (var2_p / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1_p = (((double)calib.dig_P3) * var1_p * var1_p / 524288.0 + ((double)calib.dig_P2) * var1_p) / 524288.0;
    var1_p = (1.0 + var1_p / 32768.0) * ((double)calib.dig_P1);

    if (var1_p == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2_p / 4096.0)) * 6250.0 / var1_p;
