// Read raw temperature and pressure data from the sensor
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double var1_p, var2_p;

    var1_p = ((double)t_fine / 2.0) - 64000.0;
    var2_p = var1_p * var1_p * ((double)calib.dig_P6) / 32768.0;
    var2_p = var2_p + var1_p * ((double)calib.dig_P5) * 2.0;
