#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500kHz
#define FAN_PIN 18        // GPIO18 (BCM)
#define PWM_RANGE 255
#define PWM_FREQUENCY 1000 // 1kHz
#define BUFFER_SIZE 20

// MAX31855 Fault Codes
#define MAX31855_NO_FAULT 0
#define MAX31855_OPEN_CIRCUIT 1
#define MAX31855_SHORT_TO_GND 2
#define MAX31855_SHORT_TO_VCC 3

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} TemperatureData;

TemperatureData temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_transfer(int channel, uint8_t *data, int len);
float read_temperature();
int calculate_duty_cycle(float temperature);
void set_fan_speed(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to perform SPI transfer
int spi_transfer(int channel, uint8_t *data, int len) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid SPI channel: %d\n", channel);
        return -1;
    }

    if (data == NULL || len == 0) {
        fprintf(stderr, "Invalid data or length for SPI transfer\n");
        return -1;
    }

    int result = wiringPiSPIDataRW(channel, data, len);
    if (result == -1) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31855
float read_temperature() {
    uint8_t data[4];
    int retries = 3;

    while (retries > 0) {
        if (spi_transfer(SPI_CHANNEL, data, 4) == 0) {
            // Check for fault
            if (data[3] & 0x01) {
                fprintf(stderr, "MAX31855 Fault: %d\n", data[3] & 0x01);
                return -273.15; // Return absolute zero as error value
            }

            // Extract thermocouple temperature (bits 31:18)
            int16_t thermocouple_data = ((data[0] << 8) | data[1]) >> 2;
            float temperature = thermocouple_data * 0.25;

            return temperature;
        } else {
            fprintf(stderr, "SPI read failed, retrying... (%d retries left)\n", retries - 1);
            delay(10); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -273.15; // Return absolute zero as error value
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0) {
        return 0;
    } else if (temperature < 40.0) {
        return (int)(((temperature - 25.0) / (40.0 - 25.0)) * 50.0);
    } else if (temperature < 60.0) {
        return (int)(((temperature - 40.0) / (60.0 - 40.0)) * 150.0 + 50.0);
    } else {
        return 255;
    }
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    pwmWrite(FAN_PIN, duty_cycle);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    temperature_buffer[buffer_index].timestamp = timestamp;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&temperature_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d%%\n", time_str, temperature_buffer[index].temperature, temperature_buffer[index].duty_cycle);
    }
    printf("--- End of Log ---\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping fan and exiting...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    set_fan_speed(0); // Stop the fan
    printf("Fan stopped.\n");
    if (spi_fd != -1) {
        close(spi_fd);
        printf("SPI closed.\n");
    }
    wiringPiSetup(); // Reset wiringPi
    pinMode(FAN_PIN, INPUT); // Set pin to input mode
    printf("GPIO setup reset.\n");
    printf("Program terminated.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() == -1) {
        return 1;
    }

    // Configure fan pin as PWM output
    pinMode(FAN_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Mark:Space mode
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired frequency (1kHz = 1000Hz / 192 = 5.21us period, so 5.21us / 2 = 2.605us mark space time)
    pwmSetClock(192); // Set PWM clock to achieve 1kHz frequency

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float temperature = read_temperature();
        if (temperature > -273.0) {
            int duty_cycle = calculate_duty_cycle(temperature);
            set_fan_speed(duty_cycle);
            add_to_buffer(time(NULL), temperature, duty_cycle);
            printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        delay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

