#define MAX31865_REG Fault 0x00
#define MAX31865_REG RTD_MSB 0x01
#define MAX31865_REG RTD_LSB 0x02
#define MAX31865_REG RTD_XLSB 0x03
#define MAX31865_REG CONFIG 0x08

// RTD Constants
#define RTD_NOMINAL 100.0  // Nominal resistance of the RTD
#define RTD_R0 430.0       // Resistance at 0°C
#define RREF 430.0         // Reference resistor value

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold RTD data
typedef struct {
    double rtd_resistance;
    double temperature;
} rtd_data_t;

// Function Prototypes
int initialize_spi();
int read_max31865(rtd_data_t *data);
double calculate_temperature(double rtd_resistance);
int log_data(rtd_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read MAX31865 Data
int read_max31865(rtd_data_t *data) {
    char tx_buf[4];
    char rx_buf[4];

    // Read Fault Register
    tx_buf[0] = MAX31865_REG_Fault;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading fault register\n");
        return -1;
    }

    // Read RTD MSB, LSB, and XLSB Registers
    tx_buf[0] = MAX31865_REG_RTD_MSB;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading RTD MSB register\n");
        return -1;
    }
    tx_buf[0] = MAX31865_REG_RTD_LSB;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading RTD LSB register\n");
        return -1;
    }
    tx_buf[0] = MAX31865_REG_RTD_XLSB;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading RTD XLSB register\n");
        return -1;
    }

    uint32_t rtd_raw = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];

    // Check for Fault Bit
    if (rtd_raw & 0x00000007) {
        fprintf(stderr, "MAX31865 Fault: 0x%08X\n", rtd_raw & 0x00000007);
        return -1; // Indicate fault
    }

    // Extract RTD Resistance
    data->rtd_resistance = ((double)rtd_raw / 32768.0) * RREF;

    // Calculate Temperature
    data->temperature = calculate_temperature(data->rtd_resistance);

    return 0;
}

// Calculate Temperature using Callendar-Van Dusen equation
double calculate_temperature(double rtd_resistance) {
    double rtd_resistance_r0 = rtd_resistance / RTD_R0;
    double temperature = (rtd_resistance_r0 - 1) / 0.385;
    return temperature;
}

// Log Data to File
int log_data(rtd_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup Resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    rtd_data_t rtd_data;

    // Main loop
    while (!terminate) {
        if (read_max31865(&rtd_data) == 0) {
            log_data(rtd_data);
        } else {
            fprintf(stderr, "Error reading MAX31865 data\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

