    calib.dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib.dig_H3 = data_h[2];
    calib.dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)((data_h[5] << 4) | (data_h[4] >> 4));
    calib.dig_H6 = (int8_t)data_h[6];

    return 0;
}

// Function to read temperature, humidity, and pressure data from the BME280
int bme280_read_data(float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    int32_t raw_temperature, raw_pressure, raw_humidity;

    // Read temperature, pressure and humidity data
    if (bme280_read_register(BME280_REG_PRESSURE_MSB, data) != 0) {
        return -1;
    }

    raw_pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    raw_humidity = (int32_t)data[6] << 8 | (int32_t)data[7];

    // Compensate temperature
    double var1 = (raw_temperature / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temperature / 131072.0 - calib.dig_T1 / 8192.0) * (raw_temperature / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Compensate pressure
    double var3 = t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * calib.dig_P6 / 32768.0;
    double var5 = var4 + var3 * calib.dig_P5 * 2.0;
    double var6 = var5 / 4.0 + calib.dig_P4 * 65536.0;
    double var7 = calib.dig_P3 * var3 * var3 / 524288.0;
    double var8 = calib.dig_P2 * var3 / 524288.0;
    double var9 = (1.0 + var7 + var8) * calib.dig_P1;
    *pressure = 1048576.0 - raw_pressure;
    *pressure = (*pressure - var6 / 4096.0) * 6250.0 / var9;
    var3 = calib.dig_P9 * (*pressure) * (*pressure) / 2147483648.0;
    var4 = (*pressure) * calib.dig_P8 / 32768.0;
    *pressure = *pressure + (var3 + var4 + calib.dig_P7) / 16.0;

    // Compensate humidity
    double var_H = t_fine - 76800.0;
    double var_H2 = (raw_humidity - (calib.dig_H4 * 64.0 + calib.dig_H5 / 16384.0 * var_H)) * (calib.dig_H2 / 65536.0 * (1.0 + calib.dig_H6 / 67108864.0 * var_H * (1.0 + calib.dig_H3 / 67108864.0 * var_H)));
    *humidity = var_H2 * (1.0 - calib.dig_H1 * var_H / 524288.0);

    if (*humidity > 100.0) {
        *humidity = 100.0;
    } else if (*humidity < 0.0) {
        *humidity = 0.0;
    }

    return 0;
