int read_raw_temperature(int *raw_temp) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate the pressure in pascals
double calculate_pressure(int raw_pressure, double temperature) {
    long x1 = ((long)temperature * 10 - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    unsigned long x1_pressure = ((long)ac3 * b6) / pow(2, 13);
    unsigned long x2_pressure = ((long)b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) * 4);
    unsigned long b4 = ((unsigned long)ac4 * (x3_pressure + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    long pressure;
    if (b7 < 0x80000000) {
        pressure = (b7 * 2) / b4;
    } else {
        pressure = (b7 / b4) * 2;
    }

    x1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    x1_pressure = (x1_pressure * 3038) / pow(2, 16);
    x2_pressure = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (x1_pressure + x2_pressure + 3791) / pow(2, 4);

    return pressure;
}

// Function to log the temperature and pressure data to a file
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Timer interrupt handler
void timer_interrupt_handler() {
    int raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature in interrupt handler\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure in interrupt handler\n");
        return;
    }

    temperature = calculate_temperature(raw_temp);
    pressure = calculate_pressure(raw_pressure, temperature);

    log_data(temperature, pressure);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    // Main loop (keep the program running until a signal is received)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

