#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "fan_log.txt"

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
float read_cpu_temperature();
int map_temperature_to_duty_cycle(float temperature);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping fan...\n", signal);
    set_pwm_duty_cycle(0); // Stop the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU temperature from file
float read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = -1.0f; // Default error value

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1.0f;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1.0f;
    }

    fclose(fp);

    // Convert temperature from millidegrees to degrees Celsius
    temperature = (float)atoi(buffer) / 1000.0f;

    return temperature;
}

// Function to map temperature to duty cycle
int map_temperature_to_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 40.0f) {
        duty_cycle = 0;
    } else if (temperature > 70.0f) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((temperature - 40.0f) / (70.0f - 40.0f)) * 255.0f);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    gpioPWM(GPIO_PIN, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not open log file.\n");
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately

