#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMPERATURE_THRESHOLD 28.0
#define SAMPLE_INTERVAL_MS 1000

// Data Structures
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
static int i2c_handle;
static CircularBuffer temp_buffer;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c();
float read_temperature();
void init_gpio();
void control_led(float temperature);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void *sensor_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function Implementations

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read Temperature from LM75
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    int raw_temp = (buf[0] << 8) | buf[1];
    // The LM75 returns a 9-bit temperature value, left-aligned.
    raw_temp = raw_temp >> 5; // Shift right by 5 bits to get the 9-bit value

    // Convert to Celsius (0.125 degrees per bit)
    float temperature = raw_temp * 0.125;
    return temperature;
}

// Initialize GPIO
void init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        cleanup();
        exit(1);
    }
    gpioWrite(GPIO_LED, 0); // Initially turn off the LED
}

// Control LED based on Temperature
void control_led(float temperature) {
    if (temperature > TEMPERATURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn on LED
    } else {
        gpioWrite(GPIO_LED, 0); // Turn off LED
    }
}

// Add Value to Circular Buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

// Calculate Running Average
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Sensor Reading Thread
void *sensor_thread(void *arg) {
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(&temp_buffer, temperature);
            float average_temp = calculate_average(&temp_buffer);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temp);
            control_led(average_temp);
        } else {
            fprintf(stderr, "Error reading temperature in sensor thread\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 1 second
    }
    return NULL;
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Release GPIO
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    init_gpio();

    // Initialize Mutex
    pthread_mutex_init(&temp_buffer.mutex, NULL);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create sensor reading thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Error creating sensor thread\n");
        cleanup();
        return 1;
    }

    // Main loop (can be used for other tasks)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Wait for sensor thread to finish
    pthread_join(sensor_thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

