#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define MAX_RTD 100.0
#define MAX_FAULT 0.1
#define LOG_FILE "heater.log"

// Global variables
static int spi_handle;
static struct mosquitto *mosq = NULL;
static FILE *log_file = NULL;
static volatile int running = 1;

// PID parameters
static float Kp = 1.0;
static float Ki = 0.1;
static float Kd = 0.01;
static float target_temperature = 25.0;
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
int read_rtd_temperature();
float calculate_pid(float current_temperature);
void set_heater_pwm(float duty_cycle);
void log_message(const char *message);
void signal_handler(int signal);
int load_configuration(const char *filename);
void publish_temperature(float temperature);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);

// Function to read RTD temperature from MAX31865
int read_rtd_temperature() {
    unsigned char buffer[5];
    int raw_rtd, raw_fault;

    // Read RTD data (registers 0x01 to 0x05)
    if (spiRead(spi_handle, (char *)buffer, 5) != 5) {
        log_message("Error reading RTD data from MAX31865");
        return -1;
    }

    // Extract RTD value (bits 13-18 of register 0x01)
    raw_rtd = ((buffer[1] << 6) | (buffer[2] >> 2)) >> 3;

    // Extract fault status (bits 15-18 of register 0x01)
    raw_fault = ((buffer[1] >> 6) | (buffer[2] >> 2)) & 0x07;

    // Check for fault conditions
    if (raw_fault != 0) {
        char message[100];
        snprintf(message, sizeof(message), "MAX31865 fault detected: 0x%02X", raw_fault);
        log_message(message);
        return -1;
    }

    // Convert raw RTD value to temperature (Celsius)
    float rtd_resistance = (float)raw_rtd * 430.0; // Using 430 ohm reference resistor
    float temperature = (rtd_resistance - 100.0) / 0.385; // PT100 resistance at 0°C is 100 ohms

    // Clamp temperature to reasonable range
    if (temperature < -50.0) temperature = -50.0;
    if (temperature > 150.0) temperature = 150.0;

    return (int)(temperature * 100); // Return temperature in hundredths of a degree Celsius
}

// Function to calculate PID output
float calculate_pid(float current_temperature) {
    float error = target_temperature - current_temperature;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, shutting down...");
    running = 0;
    set_heater_pwm(0.0); // Turn off heater
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

// Load configuration from JSON file
int load_configuration(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        return -1;
    }

    json_t *pid = json_object_get(root, "pid");
    if (json_is_object(pid)) {
        json_t *kp = json_object_get(pid, "Kp");
        json_t *ki = json_object_get(pid, "Ki");
        json_t *kd = json_object_get(pid, "Kd");

        if (json_is_real(kp)) {
            Kp = json_real_value(kp);
        }
        if (json_is_real(ki)) {
            Ki = json_real_value(ki);
        }
        if (json_is_real(kd)) {
            Kd = json_real_value(kd);
        }
    } else {
        Kp = 1.0;
        Ki = 0.1;
        Kd = 0.01;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (json_is_real(target_temp)) {
        target_temperature = json_real_value(target_temp);
    } else {
        target_temperature = 25.0;
    }

    json_t *mqtt = json_object_get(root, "mqtt");
    if (json_is_object(mqtt)) {
        json_t *host = json_object_get(mqtt, "host");
        json_t *port = json_object_get(mqtt, "port");
        json_t *client_id = json_object_get(mqtt, "client_id");

        if (json_is_string(host)) {
            char *mqtt_host = strdup(json_string_value(host));
        } else {
            mqtt_host = NULL;
        }

        if (json_is_integer(port)) {
            int mqtt_port = json_integer_value(port);
        } else {
            mqtt_port = 1883;
        }

        if (json_is_string(client_id)) {
            char *mqtt_client_id = strdup(json_string_value(client_id));
        } else {
            mqtt_client_id = NULL;
        }
    } else {
        mqtt_host = NULL;
        mqtt_port = 1883;
        mqtt_client_id = NULL;
    }

    if (mqtt_host) free(mqtt_host);
    if (mqtt_client_id) free(mqtt_client_id);

    return 0;
}

// Publish temperature to MQTT broker
void publish_temperature(float temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    if (mosq) {
        int ret = mosquitto_publish(mosq, NULL, "home/heater/temperature", strlen(payload), payload, 0, false);
        if (ret != MOSQ_ERR_SUCCESS) {
            log_message("Error publishing temperature to MQTT: ");
            fprintf(stderr, "MOSQ_ERR_%d\n", ret);
        }
    } else {
        log_message("MQTT not initialized, cannot publish temperature.");
    }
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        log_message("MQTT connected");
        mosquitto_subscribe(mosq, NULL, "home/heater/temperature", 0);
    } else {
        log_message("MQTT connection error: ");
        fprintf(stderr, "MOSQ_ERR_%d\n", result);
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message("MQTT disconnected unexpectedly");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Load configuration
    if (load_configuration("config.json") != 0) {
        fprintf(stderr, "Failed to load configuration, using defaults.\n");
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        log_message("Error opening SPI channel");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message("Error creating mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);

    int rc = mosquitto_connect(mosq, "localhost", 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("Error connecting to MQTT broker");
        fprintf(stderr, "MOSQ_ERR_%d\n", rc);
        spiClose(spi_handle);
        gpioTerminate();
        fclose(log_file);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set GPIO18 as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Set PWM range to 0-1000
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0); // Turn off heater initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read RTD temperature
        int rtd_raw = read_rtd_temperature();
        if (rtd_raw == -1) {
            log_message("Failed to read RTD temperature, using previous value.");
            continue; // Skip to the next iteration
        }

        // Calculate PID output
        float pid_output = calculate_pid((float)rtd_raw / 100.0); // Convert raw to temperature

        // Clamp PID output to 0-100%
        if (pid_output < 0.0) pid_output = 0.0;
        if (pid_output > 100.0) pid_output = 100.0;

        // Set heater PWM
        set_heater_pwm(pid_output);

        // Publish temperature to MQTT
        float temperature = (float)rtd_raw / 100.0;
        publish_temperature(temperature);

        // Failsafe mechanism
        if (temperature > MAX_TEMP || rtd_raw > MAX_RTD || rtd_raw < -MAX_RTD) {
            log_message("Failsafe triggered!");
            set_heater_pwm(0.0); // Turn off heater
            running = 0; // Exit the loop
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    set_heater_pwm(0.0); // Turn off heater
    spiClose(spi_handle);
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    fclose(log_file);

    return 0;
}

