int log_breach(double temperature, double pressure);
void signal_handler(int signal);

// I2C initialization function
int init_i2c(int bus) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buffer[22];
    if (read(fd, buffer, 22) != 22) {
        perror("Error reading calibration data");
        return -1;
    }

    *ac1 = (buffer[0] << 8) | buffer[1];
    *ac2 = (buffer[2] << 8) | buffer[3];
    *ac3 = (buffer[4] << 8) | buffer[5];
    *ac4 = (buffer[6] << 8) | buffer[7];
    *ac5 = (buffer[8] << 8) | buffer[9];
    *ac6 = (buffer[10] << 8) | buffer[11];
    *b1 = (buffer[12] << 8) | buffer[13];
    *b2 = (buffer[14] << 8) | buffer[15];
    *mb = (buffer[16] << 8) | buffer[17];
    *mc = (buffer[18] << 8) | buffer[19];
    *md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int fd, int16_t *ut) {
    char write_buffer[2];
    char read_buffer[2];
    write_buffer[0] = BMP180_REG_CONTROL;
    write_buffer[1] = 0x2E; // Temperature measurement command

    if (write(fd, write_buffer, 2) != 2) {
        perror("Error writing temperature command");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    write_buffer[0] = BMP180_REG_MSB;
    if (write(fd, write_buffer, 1) != 1) {
        perror("Error writing temperature register address");
        return -1;
    }

    if (read(fd, read_buffer, 2) != 2) {
        perror("Error reading raw temperature");
        return -1;
    }

    *ut = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int fd, int16_t *up) {
    char write_buffer[2];
    char read_buffer[2];
    write_buffer[0] = BMP180_REG_CONTROL;
    write_buffer[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (write(fd, write_buffer, 2) != 2) {
        perror("Error writing pressure command");
        return -1;
    }
    gpioDelay(26000); // Wait 26ms for OSS = 3

    write_buffer[0] = BMP180_REG_MSB;
    if (write(fd, write_buffer, 1) != 1) {
        perror("Error writing pressure register address");
        return -1;
    }

    if (read(fd, read_buffer, 2) != 2) {
        perror("Error reading raw pressure");
        return -1;
    }

    *up = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int16_t ut, int16_t ac5, int16_t ac6, int16_t mc, int16_t md) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int16_t up, int16_t ac1, int16_t ac2, int16_t ac3, uint16_t ac4, int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md, int oss) {
    int32_t x1 = (((int32_t)up - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << oss) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p / 100.0; // Return pressure in hPa
}

// Function to log a breach to the log file
int log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("breach_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(1) != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) != 0) {
