    printf("BMP180 sensor monitoring started...\n");

    while (!terminate) {
        int16_t ut, up;
        double temperature, pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(i2c_fd, &ut) != 0) {
            fprintf(stderr, "Error reading raw temperature, retrying...\n");
            continue; // Retry the loop
        }
        if (read_raw_pressure(i2c_fd, &up) != 0) {
            fprintf(stderr, "Error reading raw pressure, retrying...\n");
            continue; // Retry the loop
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(ut, ac5, ac6, mc, md);
        pressure = calculate_pressure(up, ac1, ac2, ac3, ac4, b1, b2, mb, mc, md, BMP180_OSS);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0) {
            printf("Breach detected: Temperature = %.2f°C, Pressure = %.2f hPa\n", temperature, pressure);
            log_breach(temperature, pressure);
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

