void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    uint8_t buffer[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buffer, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->ac1 = (buffer[0] << 8) | buffer[1];
    calibration_data->ac2 = (buffer[2] << 8) | buffer[3];
    calibration_data->ac3 = (buffer[4] << 8) | buffer[5];
    calibration_data->ac4 = (buffer[6] << 8) | buffer[7];
    calibration_data->ac5 = (buffer[8] << 8) | buffer[9];
    calibration_data->ac6 = (buffer[10] << 8) | buffer[11];
    calibration_data->b1 = (buffer[12] << 8) | buffer[13];
    calibration_data->b2 = (buffer[14] << 8) | buffer[15];
    calibration_data->mb = (buffer[16] << 8) | buffer[17];
    calibration_data->mc = (buffer[18] << 8) | buffer[19];
    calibration_data->md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms
    return i2cReadWordData(i2c_handle, BMP180_REG_MSB);
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }
    gpioDelay(2 + (3 << OSS)) ; // Wait for conversion
    uint8_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    uint8_t xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long x1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long x2 = ((long)calibration_data.mc * pow(2, 11)) / (x1 + calibration_data.md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long x1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long x2 = ((long)calibration_data.mc * pow(2, 11)) / (x1 + calibration_data.md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration_data.b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)calibration_data.ac2 * b6) / pow(2, 11);
    long b3 = (((long)calibration_data.ac1 * 4 + x3 + x4 + 2) / 4);

    unsigned long b4 = ((unsigned long)calibration_data.ac4 * (unsigned long)(x3 + x4 + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);

    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

