    if (temperature > 30.0) {
        if (!fan_state) {
            gpioWrite(FAN_PIN, 1); // Turn fan on
            fan_state = 1;
            printf("Fan turned ON (Temperature: %.2f C)\n", temperature);
        }
    } else {
        if (fan_state) {
            gpioWrite(FAN_PIN, 0); // Turn fan off
            fan_state = 0;
            printf("Fan turned OFF (Temperature: %.2f C)\n", temperature);
        }
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int raw_temperature = read_raw_temperature(i2c_handle);
    int raw_pressure = read_raw_pressure(i2c_handle);

