        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL); // Timer 0, every 500ms

    printf("BMP180 sensor program running. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        sleep(1); // Sleep to reduce CPU usage
    }

    return 0;
}

