#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 0.8
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_baud;
    int heater_gpio;
    float target_temperature;
    float max_duty_cycle;
    char *log_file;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int baud);
int read_max31855(int spi_handle, float *temperature);
void set_heater_duty_cycle(int gpio, float duty_cycle);
float calculate_duty_cycle(float current_temperature, float target_temperature, float max_duty_cycle);
void log_data(float temperature, float duty_cycle, const char *timestamp);
void handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    // Check for fault bits
    if (buffer[3] & 0x04) {
        fprintf(stderr, "Thermocouple open circuit\n");
        handle_error("Thermocouple open circuit");
        return -1;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "Thermocouple short to ground\n");
        handle_error("Thermocouple short to ground");
        return -1;
    }
    if (buffer[3] & 0x01) {
        fprintf(stderr, "Thermocouple short to VCC\n");
        handle_error("Thermocouple short to VCC");
        return -1;
    }

    // Extract temperature data
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 10000.0); // pigpio range is 0-1000000
    gpioPWM(gpio, pwm_value);
}

// Function to calculate duty cycle using PI controller
