    float proportional = 0.5 * error; // Adjust proportional gain as needed

    integral += error;
    float derivative = error;

    float output = proportional + 0.1 * integral + 0.01 * derivative; // PI controller parameters

    // Anti-windup
    if (output > max_duty_cycle) {
        output = max_duty_cycle;
