#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define temperature thresholds
#define TEMP_THRESHOLD_1 40000
#define TEMP_THRESHOLD_2 60000

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, turning off LED and exiting...\n");
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();
    exit(0);
}

// Function to set PWM duty cycle
int set_pwm_duty(int pin, int duty_cycle) {
    int result = gpioPWM(pin, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for pin %d: %d\n", pin, result);
        return -1;
    }
    return 0;
}

// Function to read CPU temperature from file
int read_cpu_temp(const char *filename, long *temperature) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading temperature from file %s\n", filename);
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "%ld", temperature) != 1) {
        fprintf(stderr, "Error parsing temperature from file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to map temperature to RGB color
void map_temperature_to_color(long temperature, int *red, int *green, int *blue) {
    if (temperature < TEMP_THRESHOLD_1) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temperature < TEMP_THRESHOLD_2) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    long temperature;
    int red, green, blue;

    // Main loop
    while (program_running) {
        // Read CPU temperature
        if (read_cpu_temp("/sys/class/thermal/thermal_zone0/temp", &temperature) == 0) {
            // Map temperature to RGB color
            map_temperature_to_color(temperature, &red, &green, &blue);

            // Set PWM values
            if (set_pwm_duty(RED_PIN, red) != 0) {
                program_running = 0; // Exit on error
            }
            if (set_pwm_duty(GREEN_PIN, green) != 0) {
                program_running = 0; // Exit on error
            }
            if (set_pwm_duty(BLUE_PIN, blue) != 0) {
                program_running = 0; // Exit on error
            }

            // Print temperature and PWM values
            printf("Temperature: %ld m°C, Red: %d, Green: %d, Blue: %d\n", temperature, red, green, blue);
        } else {
            program_running = 0; // Exit on error
        }

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

    // Cleanup (should not be reached if signal handler works correctly)
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();

    return 0;
}

