#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 5 // seconds
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set GPIO mode
int set_gpio_mode(int gpio, int mode) {
    gpioSetMode(gpio, mode);
    return 0;
}

// Function to send start signal to DHT22
int send_start_signal(int gpio) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1000); // 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30us
    gpioSetMode(gpio, PI_INPUT);
    return 0;
}

// Function to read data from DHT22 sensor
int read_dht22_data(int gpio, DHT22Data *data) {
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    int i, j;

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for low signal
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Wait 1us
        }

        // Measure high signal duration
        struct timeval start, end;
        gettimeofday(&start, NULL);
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // Wait 1us
        }
        gettimeofday(&end, NULL);
        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);

        // Determine if bit is 0 or 1 based on duration
        if (duration > 40) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF != raw_data[4]) {
        fprintf(stderr, "Checksum mismatch\n");
        return -1;
    }

    // Extract temperature and humidity
    data->humidity = (float)((raw_data[0] << 8) | raw_data[1]) / 10.0;
    data->temperature = (float)(((raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1.0;
    }

    // Store data
    data->checksum = raw_data[4];
    return 0;
}

// Function to format data as JSON
int format_json(float temperature, float humidity, char *json_buffer, size_t buffer_size) {
    int ret = snprintf(json_buffer, buffer_size, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
    if (ret < 0 || ret >= buffer_size) {
        fprintf(stderr, "Error formatting JSON\n");
        return -1;
    }
    return 0;
}

// Function to post data to server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    DHT22Data dht22_data;
    int retries = 0;
    char json_buffer[JSON_BUFFER_SIZE];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set GPIO mode
    if (set_gpio_mode(DHT22_GPIO, PI_INPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Send start signal
        if (send_start_signal(DHT22_GPIO) != 0) {
            fprintf(stderr, "Failed to send start signal, retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
