#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling setting (OSS)
#define OSS 3

// GPIO pin for button interrupt
#define BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
int i2c_handle;
volatile sig_atomic_t logging_enabled = 0;
volatile unsigned long last_interrupt_time = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_bmp180();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, double temperature);
void log_pressure(double pressure);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Function to initialize the BMP180 sensor
int init_bmp180() {
    // Check if the sensor is present
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error: BMP180 not found\n");
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t data[22];
    if (i2cReadI2CBlockData(i2c_handle, 0xAA, (char *)data, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data block\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error: Failed to write temperature read command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms

    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) {
        fprintf(stderr, "Error: Failed to write pressure read command\n");
        return -1;
    }
    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    uint8_t data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * (long)ac5 / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, double temperature) {
    long x1 = ((long)temperature * 10 - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) / 4;

    unsigned long x1_pressure = ((unsigned long)ac3 * b6) / pow(2, 13);
    unsigned long x2_pressure = ((unsigned long)b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) * 4) / 16;
    unsigned long b4 = ((unsigned long)ac4 * (x3_pressure + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    long pressure;
    if (b7 < 0x80000000) {
        pressure = (b7 * 2) / b4;
    } else {
        pressure = (b7 / b4) * 2;
    }

    x1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    x1_pressure = (x1_pressure * 3038) / pow(2, 16);
    x2_pressure = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (x1_pressure + x2_pressure + 3791) / pow(2, 4);

    return (double)pressure / 100.0; // Convert to hPa
}

// Function to log pressure data to a file
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open pressure_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);

    printf("%s, %.2f hPa\n", timestamp, pressure);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce the interrupt
    if (current_time - last_interrupt_time < DEBOUNCE_TIME) {
        return;
    }

    last_interrupt_time = current_time;

    // Toggle logging state
    logging_enabled = !logging_enabled;

    if (logging_enabled) {
        printf("Logging started\n");
    } else {
        printf("Logging stopped\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize BMP180 sensor
    if (init_bmp180() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for button
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_temp, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, temperature);

                // Log pressure data
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error: Failed to read sensor data\n");
            }
        } else {
            printf("Logging disabled\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    return 0;
}

