#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Structure to hold configuration
typedef struct {
    char *api_url;
} Config;

// Global variables
static volatile int running = 1;
static Config config = {NULL};

// Function prototypes
int init_pigpio();
DHT22Data read_dht22();
char *format_json(DHT22Data data);
int post_data(const char *json_data);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to write received data
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    char *response = (char *)userp;
    strncat(response, contents, real_size);
    return real_size;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    return 0;
}

// Read data from DHT22 sensor
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(20); // 20-40us
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Wait for response (low for at least 1ms, then high)
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // Check every 1us
            timeout++;
        }
        if (timeout >= 100) {
            syslog(LOG_ERR, "DHT22: Timeout waiting for response (low)");
            retries++;
            sleep(1 << retries); // Exponential backoff
            continue;
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }
        if (timeout >= 100) {
            syslog(LOG_ERR, "DHT22: Timeout waiting for response (low)");
            retries++;
            sleep(1 << retries); // Exponential backoff
            continue;
        }

        // Read 40 bits of data
        unsigned int data_bits[5] = {0};
        for (int i = 0; i < 5; i++) {
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
                gpioDelay(1);
                timeout++;
            }
            if (timeout >= 100) {
                syslog(LOG_ERR, "DHT22: Timeout waiting for response (high start)");
                retries++;
                sleep(1 << retries); // Exponential backoff
                continue;
            }

            long start = gpioTick();
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
                gpioDelay(1);
                timeout++;
            }
            if (timeout >= 100) {
                syslog(LOG_ERR, "DHT22: Timeout waiting for response (high start)");
                retries++;
                sleep(1 << retries); // Exponential backoff
                continue;
            }

            long end = gpioTick();
            data_bits[i] = end - start;
        }

        // Convert data to humidity and temperature
        unsigned int humidity = (data_bits[0] << 0) | (data_bits[1] << 1) | (data_bits[2] << 2) | (data_bits[3] << 3) | (data_bits[4] << 4);
        unsigned int temperature = (data_bits[0] << 0) | (data_bits[1] << 1) | (data_bits[2] << 2) | (data_bits[3] << 3) | (data_bits[4] << 4);

        // Validate checksum
        unsigned int checksum = (data_bits[0] << 0) | (data_bits[1] << 1) | (data_bits[2] << 2) | (data_bits[3] << 3) | (data_bits[4] << 4);
        unsigned int calculated_checksum = (temperature >> 8) | (temperature << 8);
        unsigned int calculated_checksum2 = (humidity >> 8) | (humidity << 8);

        if ((checksum & 0xFF) != (calculated_checksum & 0xFF)) {
            syslog(LOG_ERR, "DHT22: Checksum error (first)");
            retries++;
            sleep(1 << retries); // Exponential backoff
            continue;
        }

        if ((checksum2 & 0xFF) != (calculated_checksum2 & 0xFF)) {
            syslog(LOG_ERR, "DHT22: Checksum error (second)");
            retries++;
            sleep(1 << retries); // Exponential backoff
            continue;
        }

        // Convert to float
        data.humidity = (float)humidity / 10.0;
        data.temperature = (float)temperature / 10.0;
        data.valid = 1;

        return data;
    }

    syslog(LOG_ERR, "DHT22: Failed to read sensor after %d retries", MAX_RETRIES);
    return data; // Return invalid data
}

// Format data as JSON
char *format_json(DHT22Data data) {
    char *json_string = (char *)malloc(JSON_BUFFER_SIZE);
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, JSON_BUFFER_SIZE, "{\"temperature\": %.2f, \"humidity\": %.2f}", data.temperature, data.humidity);
    return json_string;
}

// Post data to API endpoint
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    char response[256] = {0}; // Buffer to store the response

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, config.api_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

        // Set Content-Type header
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        // Check response code
        long response_code;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
        if (response_code >= 200 && response_code < 300) {
            syslog(LOG_INFO, "API call successful (status code: %ld)", response_code);
        } else {
            syslog(LOG_ERR, "API call failed (status code: %ld)", response_code);
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioTerminate();
    if (config.api_url != NULL) {
        curl_global_cleanup();
    }
    closelog();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        config.api_url = strdup(argv[1]);
    } else {
        config.api_url = NULL;
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "DHT22 monitor started");

    // Main loop
    while (running) {
        DHT22Data data = read_dht22();
        if (data.valid) {
            char *json_data = format_json(data);
            if (json_data != NULL) {
                syslog(LOG_INFO, "Temperature: %.2f, Humidity: %.2f", data.temperature, data.humidity);
                if (post_data(json_data) != 0) {
                    syslog(LOG_ERR, "Failed to post data to API");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Invalid DHT22 data, skipping");
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

