#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int fan_state = 0; // Initial fan state

// Function prototypes
int read_temperature();
int read_fan_state();
int set_fan_state(int state);
int log_event(const char *message);
int validate_fan_state(int state);
int map_temperature_to_fan_speed(int temperature);
void signal_handler(int signal);

// Function to read temperature from file
int read_temperature() {
    int temperature = -1;
    int retries = 0;
    char buffer[10];

    while (retries < MAX_RETRIES) {
        if (read(FAN_FILE, buffer, sizeof(buffer) - 1) == -1) {
            if (errno == ENOENT) {
                log_event("Error: Temperature file not found.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else if (errno == EIO) {
                log_event("Error reading temperature file.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else {
                log_event("Error reading temperature file (errno):");
                perror("errno");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            }
        } else {
            temperature = atoi(buffer);
            break; // Exit loop if read is successful
        }
    }

    if (temperature == -1) {
        log_event("Failed to read temperature after multiple retries.");
        return -1; // Indicate failure
    }

    return temperature;
}

// Function to read fan state from file
int read_fan_state() {
    int fan_state = -1;
    int retries = 0;
    char buffer[2];

    while (retries < MAX_RETRIES) {
        if (read(FAN_FILE, buffer, sizeof(buffer) - 1) == -1) {
            if (errno == ENOENT) {
                log_event("Error: Fan state file not found.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else if (errno == EIO) {
                log_event("Error reading fan state file.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else {
                log_event("Error reading fan state file (errno):");
                perror("errno");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            }
        } else {
            fan_state = atoi(buffer);
            break; // Exit loop if read is successful
        }
    }

    if (fan_state == -1) {
        log_event("Failed to read fan state after multiple retries.");
        return -1; // Indicate failure
    }

    return fan_state;
}

// Function to set fan state
int set_fan_state(int state) {
    int retries = 0;
    char buffer[2];
    ssize_t bytes_written;

    while (retries < MAX_RETRIES) {
        snprintf(buffer, sizeof(buffer), "%d", state);
        bytes_written = write(FAN_FILE, buffer, strlen(buffer));

        if (bytes_written == -1) {
            if (errno == ENOENT) {
                log_event("Error: Fan state file not found.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else if (errno == EIO) {
                log_event("Error writing to fan state file.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else {
                log_event("Error writing to fan state file (errno):");
                perror("errno");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            }
        } else {
            break; // Exit loop if write is successful
        }
    }

    if (retries == MAX_RETRIES) {
        log_event("Failed to set fan state after multiple retries.");
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log events
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to validate fan state
int validate_fan_state(int state) {
    if (state < 0 || state > 3) {
        log_event("Invalid fan state. State must be between 0 and 3.");
        return -1;
    }
    return 0;
}

// Function to map temperature to fan speed
int map_temperature_to_fan_speed(int temperature) {
    if (temperature < 45000) {
        return 0; // Fan off
    } else if (temperature < 55000) {
        return 1; // Fan 1
    } else if (temperature < 65000) {
        return 2; // Fan 2
    } else {
        return 3; // Fan 3
    }
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        set_fan_state(0); // Set fan to 0 (off)
        program_running = 0;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Fan control program started.");

    while (program_running) {
        int temperature = read_temperature();
