// Function to read temperature from file
int read_temperature() {
    int temperature = -1;
    int retries = 0;
    char buffer[10];

    while (retries < MAX_RETRIES) {
        if (read(FAN_FILE, buffer, sizeof(buffer) - 1) == -1) {
            if (errno == ENOENT) {
                log_event("Error: Temperature file not found.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else if (errno == EIO) {
                log_event("Error reading temperature file.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else {
                log_event("Error reading temperature file (errno):");
                perror("errno");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            }
        } else {
            temperature = atoi(buffer);
            break; // Exit loop if read is successful
        }
    }

    if (temperature == -1) {
        log_event("Failed to read temperature after multiple retries.");
        return -1; // Indicate failure
    }

    return temperature;
}

// Function to read fan state from file
int read_fan_state() {
