        if (read(FAN_FILE, buffer, sizeof(buffer) - 1) == -1) {
            if (errno == ENOENT) {
                log_event("Error: Fan state file not found.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else if (errno == EIO) {
                log_event("Error reading fan state file.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else {
