                perror("errno");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            }
        } else {
            fan_state = atoi(buffer);
            break; // Exit loop if read is successful
        }
    }

    if (fan_state == -1) {
        log_event("Failed to read fan state after multiple retries.");
        return -1; // Indicate failure
    }

    return fan_state;
}

// Function to set fan state
int set_fan_state(int state) {
    int retries = 0;
    char buffer[2];
    ssize_t bytes_written;

    while (retries < MAX_RETRIES) {
        snprintf(buffer, sizeof(buffer), "%d", state);
        bytes_written = write(FAN_FILE, buffer, strlen(buffer));

        if (bytes_written == -1) {
            if (errno == ENOENT) {
                log_event("Error: Fan state file not found.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else if (errno == EIO) {
                log_event("Error writing to fan state file.");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            } else {
                log_event("Error writing to fan state file (errno):");
                perror("errno");
                retries++;
                sleep(1); // Wait before retrying
                continue;
            }
        } else {
            break; // Exit loop if write is successful
        }
    }

    if (retries == MAX_RETRIES) {
        log_event("Failed to set fan state after multiple retries.");
        return -1; // Indicate failure
    }

    return 0; // Indicate success
