#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HEATER_PIN 18
#define CS_PIN 8 // GPIO8/CE0

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Define temperature limits
#define MIN_TEMP 0.0
#define MAX_TEMP 100.0

// Define fault thresholds
#define FAULT_THRESHOLD 100.0
#define FAULT_MIN 0.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID variables
double integral = 0.0;
double previous_error = 0.0;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_heater_duty_cycle(int duty_cycle);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bits
    if (buffer[3] & 0x07) {
        fprintf(log_file, "Fault detected: ");
        if (buffer[3] & 0x01) fprintf(log_file, "Open circuit\n");
        if (buffer[3] & 0x02) fprintf(log_file, "Short to GND\n");
        if (buffer[3] & 0x04) fprintf(log_file, "Short to VCC\n");
        fflush(log_file);
        gpioPWM(HEATER_PIN, 0); // Disable heater
        return -273.15; // Return absolute zero on fault
    }

    // Extract temperature data
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(int duty_cycle) {
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    set_heater_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    double setpoint = 50.0;
    double actual_temperature;
    int duty_cycle;
    double pid_output;

    while (!terminate) {
        actual_temperature = read_temperature();

        if (actual_temperature > MAX_TEMP || actual_temperature < FAULT_MIN) {
            fprintf(stderr, "Temperature out of range, disabling heater\n");
            set_heater_duty_cycle(0);
            break;
        }

        pid_output = calculate_pid(setpoint, actual_temperature, &integral, &previous_error);
        duty_cycle = (int)(pid_output * 100.0); // Scale PID output to 0-100
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        set_heater_duty_cycle(duty_cycle);
        log_data(actual_temperature, duty_cycle, pid_output);

        gpioDelay(1000); // Delay for 1 second
    }

    cleanup();
    return 0;
}

