#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
double read_cpu_temperature();
double map_temperature_to_duty_cycle(double temperature);
int set_fan_speed(double duty_cycle);
int log_data(double temperature, double duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_fan_speed(0.0); // Turn off the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
double read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    double temperature = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading temperature");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);

    temperature = atof(buffer) / 1000.0; // Convert to degrees Celsius
    return temperature;
}

// Function to map temperature to duty cycle
double map_temperature_to_duty_cycle(double temperature) {
    if (temperature < 40.0) {
        return 0.0;
    } else if (temperature > 70.0) {
        return 100.0;
    } else {
        return 100.0 - ((temperature - 40.0) / (70.0 - 40.0)) * 100.0;
    }
}

// Function to set fan speed using pigpio
int set_fan_speed(double duty_cycle) {
    if (duty_cycle < 0.0 || duty_cycle > 100.0) {
        fprintf(stderr, "Invalid duty cycle: %.2f\n", duty_cycle);
        return -1; // Indicate error
    }

    int pwm_value = (int)(duty_cycle * 255.0); // pigpio uses 0-255 range
    gpioPWM(FAN_GPIO, pwm_value);
    return 0;
}

// Function to log data to a file
int log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1; // Indicate error
        }
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255); // Set PWM range to 0-255

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double temperature = read_cpu_temperature();
        if (temperature < 0.0) {
            fprintf(stderr, "Error reading temperature, using default value.\n");
            temperature = 50.0; // Default temperature
        }

        double duty_cycle = map_temperature_to_duty_cycle(temperature);
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed.\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);
        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0.0);
    gpioTerminate();
    return 0;
}

