    unsigned int flow1;
    unsigned int flow2;
} sensor_data_t;

// Function to read sensor data with retry
int read_sensor_data(int i2c_handle, unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
