#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the number of bits to decode the quadrature signal
#define NUM_BITS 2

// Define the delay between readings in milliseconds
#define READ_DELAY_MS 10

// Global variables
static volatile int pulse_count = 0;
static volatile int last_state[NUM_BITS] = {0, 0};
static volatile int current_state[NUM_BITS] = {0, 0};
static volatile int encoder_state = 0; // 0: A high, B low; 1: A low, B high
static volatile int last_encoder_state = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void encoder_interrupt(int gpio, int level, uint32_t tick, void *user_data);
double calculate_position();
void log_position(double position);
void signal_handler(int signal);

// Structure to hold encoder state
typedef struct {
    int a;
    int b;
} EncoderState;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_PIN, RISING_EDGE | FALLING_EDGE, 0, encoder_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_A_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PIN, RISING_EDGE | FALLING_EDGE, 0, encoder_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_B_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

// Interrupt handler function
void encoder_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    EncoderState *state = (EncoderState *)user_data;

    if (gpio == ENCODER_A_PIN) {
        if (level == 1) {
            state->a = 1;
        } else {
            state->a = 0;
        }
    } else if (gpio == ENCODER_B_PIN) {
        if (level == 1) {
            state->b = 1;
        } else {
            state->b = 0;
        }
    }

    EncoderState current = {state->a, state->b};
    int diff = (current.a != state->a) + (current.b != state->b);

    if (diff == 2) {
        encoder_state = (encoder_state + 1) % 2; // Toggle encoder state
        last_encoder_state = encoder_state;
    }

    pulse_count++;
}

// Function to calculate the angular position in degrees
double calculate_position() {
    double position = ((double)pulse_count / PULSES_PER_REVOLUTION) * 360.0;
    pulse_count = 0; // Reset pulse count after calculation
    return position;
}

// Function to log the position to a file
void log_position(double position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    EncoderState state = {0, 0};
    double position;

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        position = calculate_position();
        log_position(position);
        gpioDelay(READ_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

