#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define PULSES_PER_REVOLUTION 1
#define SAMPLE_INTERVAL_SEC 1

// Structure to hold program state
typedef struct {
    pthread_mutex_t mutex;
    FILE *log_file;
    volatile int running;
} ProgramState;

// Function prototypes
int initialize_gpio();
void interrupt_service_routine(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulses);
void log_rpm(double rpm);
void signal_handler(int signal);
void cleanup(ProgramState *state);

// Global program state
ProgramState state = {0};

int main() {
    // Initialize program state
    state.running = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (state.log_file == NULL) {
        perror("Failed to open log file");
        cleanup(&state);
        return 1;
    }

    // Main loop
    while (state.running) {
        // Calculate RPM
        double rpm = calculate_rpm(0); // Pass 0 as pulses to avoid race conditions

        // Log RPM
        log_rpm(rpm);

        // Sleep for 1 second
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup
    cleanup(&state);

    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_service_routine, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine
void interrupt_service_routine(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&state.mutex);
    state.pulses++;
    pthread_mutex_unlock(&state.mutex);
}

// Calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0 / SAMPLE_INTERVAL_SEC;
}

// Log RPM to file
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state.log_file != NULL) {
        fprintf(state.log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(state.log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    state.running = 0;
}

// Cleanup function
void cleanup(ProgramState *state) {
    printf("Cleaning up...\n");

    // Destroy mutex
    pthread_mutex_destroy(&state->mutex);

    // Close log file
    if (state->log_file != NULL) {
        fclose(state->log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

