    if (result != 2) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR data
    result = i2cReadI2CBlockData(handle, IR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading IR data: %d\n", result);
        return -1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

