#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t raw_flow;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int read_sensor_data(int handle, sensor_data_t *data);
float convert_to_flow_rate(uint16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[4];
    int result = i2cReadDevice(handle, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    data->raw_flow = (buf[0] << 8) | buf[1];
    data->crc = buf[3];

    return 0;
}

// Function to convert raw flow rate to uL/min
float convert_to_flow_rate(uint16_t raw_flow) {
    // Calibration parameters (adjust based on sensor datasheet)
    float flow_rate = (float)raw_flow * 0.01; // Example: 0.01 uL/min per unit
    return flow_rate;
}

// Function to log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, SLF3S_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float flow_rate;
    int retry_count = 0;
    const int max_retries = 3;

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // CRC validation
            uint8_t crc_calculated = 0;
            for (int i = 0; i < 8; i++) {
                crc_calculated ^= (sensor_data.raw_flow & 0x01);
                sensor_data.raw_flow >>= 1;
                if (crc_calculated & 0x80) {
                    crc_calculated ^= CRC_POLYNOMIAL;
                }
            }

            if (crc_calculated != sensor_data.crc) {
                fprintf(stderr, "CRC validation failed\n");
                retry_count++;
                if (retry_count > max_retries) {
                    fprintf(stderr, "Too many CRC failures, skipping this reading\n");
                    retry_count = 0; // Reset retry count after a failure
                    continue;
                }
                continue; // Skip to the next iteration
            }

            // Convert to flow rate
            flow_rate = convert_to_flow_rate(sensor_data.raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Too many read failures, skipping this iteration\n");
                retry_count = 0; // Reset retry count after a failure
                continue; // Skip to the next iteration
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

