    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ index
            int iaq_index = calculate_iaq_index(sensor_data.tvoc, sensor_data.eco2);

            // Log data
