#define GPIO_PIN 17
#define POLL_INTERVAL_MS 100
#define TAMPER_THRESHOLD_SEC 5

volatile sig_atomic_t program_running = 1;
int tamper_count = 0;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    time_t last_touch_time;
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO pin status
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO pin: %s\n", strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Check for tamper event
        if (gpio_status == 1) {
            // Get current timestamp
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                gpioTerminate();
                return EXIT_FAILURE;
            }

            // Increment tamper count
            tamper_count++;

            // Check if tamper threshold is exceeded
            if (tamper_count >= TAMPER_THRESHOLD_SEC) {
