                // Reset tamper count
                tamper_count = 0;
            }
        } else {
            // Reset tamper count
            tamper_count = 0;
        }

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Tamper detection system stopped.\n");
    return EXIT_SUCCESS;
}

