#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // bytes per sample (16-bit)
#define GPIO_PIN 17
#define FILENAME "audio_capture.pcm"

// Global variables for signal handling
static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *audio_file = NULL;

// Structure to hold ALSA parameters
typedef struct {
    int sample_rate;
    int num_channels;
    int buffer_size;
} alsa_params_t;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;
}

// Function to initialize ALSA
int init_alsa(alsa_params_t *params) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set format to 16-bit little-endian
    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = params->sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }
    if (rate != params->sample_rate) {
        fprintf(stderr, "Warning: Sample rate changed to %d\n", rate);
    }

    // Set buffer size (adjust as needed)
    params->buffer_size = 1024; // Adjust this value
    if ((err = snd_pcm_hw_params_set_buffer_size_near(pcm_handle, hw_params, &params->buffer_size)) < 0) {
        fprintf(stderr, "Error setting buffer size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to capture audio data
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int err = snd_pcm_readi(pcm_handle, buffer, buffer_size);
    if (err == -EPIPE) {
        /* EPIPE means overrun */
        fprintf(stderr, "Overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
    } else if (err < 0) {
        fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
        return -1;
    } else if (err != buffer_size) {
        fprintf(stderr, "Short read, read %d frames\n", err);
    }
    return err;
}

// Function to write audio data to file
int write_to_file(FILE *file, short *buffer, int num_samples) {
    size_t bytes_written = fwrite(buffer, 1, num_samples * SAMPLE_SIZE, file);
    if (bytes_written != num_samples * SAMPLE_SIZE) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

// Function to set GPIO pin
int set_gpio_pin(int pin, int value) {
    gpioWrite(pin, value);
    return 0;
}

// Function to cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }

    if (audio_file) {
        fclose(audio_file);
    }

    gpioTerminate();
}

int main() {
    alsa_params_t params = {SAMPLE_RATE, NUM_CHANNELS, 1024};
    short *buffer;
    int num_samples;
    int err;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open audio file for writing
    audio_file = fopen(FILENAME, "wb");
    if (!audio_file) {
        fprintf(stderr, "Error opening file for writing\n");
        cleanup();
        return 1;
    }

    // Initialize ALSA
    if (init_alsa(&params) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup();
        return 1;
    }

    // Allocate buffer
    buffer = (short *)malloc(params.buffer_size * SAMPLE_SIZE);
    if (!buffer) {
        fprintf(stderr, "Error allocating buffer\n");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Audio capture started...\n");

    // Main loop
    while (keep_running) {
        // Capture audio data
        if (capture_audio(pcm_handle, buffer, params.buffer_size) == params.buffer_size) {
            // Write to file
            if (write_to_file(audio_file, buffer, params.buffer_size) != 0) {
                fprintf(stderr, "Error writing to file, exiting\n");
                break;
            }

            // Set GPIO pin (left channel select)
            set_gpio_pin(GPIO_PIN, 1); // Set GPIO high
            gpioDelay(1); // Small delay to ensure signal is stable
            set_gpio_pin(GPIO_PIN, 0); // Set GPIO low
            gpioDelay(1); // Small delay to ensure signal is stable
        } else {
            fprintf(stderr, "Error capturing audio, retrying...\n");
        }
    }

    // Cleanup resources
    cleanup();

    fprintf(stderr, "Audio capture stopped.\n");

    return 0;
}

