#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 1000

// Global variables
FILE *log_file = NULL;
int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    pigpio_initialized = 1;

    // Set flame sensor pin as input
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    // Set fan pin as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_PIN);
    if (reading < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return reading;
}

// Function to control the fan
void control_fan(int state) {
    gpioWrite(FAN_PIN, state);
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s: %s\n", timestamp, event_type, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input

    // Terminate pigpio
    if (pigpio_initialized) {
        gpioTerminate();
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("SYSTEM_START", "System started");

    int last_reading = 1; // Assume no flame initially
    int timeout_counter = 0;

    // Main loop
    while (1) {
        int current_reading = read_flame_sensor();

        if (current_reading < 0) {
            // Error reading sensor, log and exit
            log_event("ERROR", "Failed to read flame sensor");
            signal_handler(SIGTERM); // Simulate a signal to exit gracefully
            return 1;
        }

        if (current_reading == 0 && last_reading == 1) {
            // Flame detected
            log_event("FLAME_DETECTED", "Flame detected");
            control_fan(1); // Turn fan on
            timeout_counter = 0; // Reset timeout
        } else if (current_reading == 1 && last_reading == 0) {
            // Flame gone
            log_event("FLAME_ENDED", "Flame ended");
            control_fan(0); // Turn fan off
            timeout_counter = 0; // Reset timeout
        } else {
            // No change in flame state
            timeout_counter++;
            if (timeout_counter > TIMEOUT_DURATION) {
                log_event("SENSOR_ABSENT", "Sensor absent");
                control_fan(0); // Turn fan off
                timeout_counter = 0; // Reset timeout
            }
        }

        last_reading = current_reading;

        // Debounce delay
        gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

