        return 1;
    }

    log_event("SYSTEM_START", "System started");

    int last_reading = 1; // Assume no flame initially
    int timeout_counter = 0;

    // Main loop
    while (1) {
        int current_reading = read_flame_sensor();

        if (current_reading < 0) {
            // Error reading sensor, log and exit
            log_event("ERROR", "Failed to read flame sensor");
            signal_handler(SIGTERM); // Simulate a signal to exit gracefully
            return 1;
        }

        if (current_reading == 0 && last_reading == 1) {
            // Flame detected
            log_event("FLAME_DETECTED", "Flame detected");
            control_fan(1); // Turn fan on
            timeout_counter = 0; // Reset timeout
        } else if (current_reading == 1 && last_reading == 0) {
            // Flame gone
            log_event("FLAME_ENDED", "Flame ended");
            control_fan(0); // Turn fan off
            timeout_counter = 0; // Reset timeout
        } else {
            // No change in flame state
            timeout_counter++;
            if (timeout_counter > TIMEOUT_DURATION) {
