            data = NULL;
            data_size = 0;
            frame_num = 0;
        }

        free(data);
        data = NULL;
        data_size = 0;
        frame_num = 0;

        // Sleep for 100ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

