                    fprintf(stderr, "Error getting timestamp.\n");
                }
            } else { // Flame cleared (HIGH signal)
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_flame_state(timestamp, sensor_value) == 0) {
                        printf("Flame cleared at %s\n", timestamp);
                    } else {
                        fprintf(stderr, "Error logging flame cleared event.\n");
                    }
                    free(timestamp); // Free the allocated memory
                } else {
                    fprintf(stderr, "Error getting timestamp.\n");
                }
            }
            previous_state = sensor_value;
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

