#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_lux();
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor configuration
typedef struct {
    uint16_t config_value;
} sensor_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    // Continuous conversion mode with automatic full-scale range
    sensor_config_t config = {0x0200}; // Continuous conversion, auto range
    uint8_t buffer[2];
    buffer[0] = (config.config_value >> 8) & 0xFF;
    buffer[1] = config.config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)buffer, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the lux value from the OPT3001
int read_lux() {
    int raw_value = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading result register: %d\n", raw_value);
        return -1;
    }

    // Convert raw value to lux (refer to OPT3001 datasheet)
    float lux = (float)raw_value / 65536.0 * 1000.0; // Example conversion
    return (int)lux;
}

// Function to log the data to a file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int lux = read_lux();
        if (lux >= 0) {
            log_data((float)lux);
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
        }
        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

