#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DOUT_PIN 4
#define LINE_REQUEST_NAME "flame_sensor_line"

volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO chip and line context
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_context_t;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame sensor value
int read_flame_sensor(gpio_context_t *ctx) {
    int value = gpiod_line_get_value(ctx->line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log the sensor status
void log_status(const char *timestamp, int sensor_value) {
    if (sensor_value == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to release GPIO resources
void cleanup(gpio_context_t *ctx) {
    if (ctx->line) {
        gpiod_line_release(ctx->line);
    }
    if (ctx->chip) {
        gpiod_chip_close(ctx->chip);
    }
}

int main() {
    gpio_context_t ctx;
    struct gpiod_line_request_config config;
    int ret;

    // Initialize GPIO chip
    ctx.chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!ctx.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO line
    ctx.line = gpiod_chip_get_line(ctx.chip, GPIO_LINE);
    if (!ctx.line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup(&ctx);
        return 1;
    }

    // Request GPIO line for input
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    ret = gpiod_line_request(ctx.line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        cleanup(&ctx);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_flame_sensor(&ctx);

        if (sensor_value == -1) {
            // Error reading sensor, exit loop
            break;
        }

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log status
        log_status(timestamp, sensor_value);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup resources
    cleanup(&ctx);

    return 0;
}

