#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensor outputs
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the sensor values
int read_sensor_values(int left_pin, int center_pin, int right_pin) {
    int left_value = gpioRead(left_pin);
    int center_value = gpioRead(center_pin);
    int right_value = gpioRead(right_pin);

    if (left_value < 0 || center_value < 0 || right_value < 0) {
        fprintf(stderr, "Error reading GPIO values.\n");
        return -1; // Indicate an error
    }

    return (left_value << 2) | (center_value << 1) | right_value;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_PIN, PI_INPUT);
    gpioSetMode(CENTER_PIN, PI_INPUT);
    gpioSetMode(RIGHT_PIN, PI_INPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int sensor_values = read_sensor_values(LEFT_PIN, CENTER_PIN, RIGHT_PIN);

        if (sensor_values >= 0) {
            printf("Left: %d, Center: %d, Right: %d\n", sensor_values >> 2, (sensor_values >> 1) & 0x03, sensor_values & 0x01);
        } else {
            fprintf(stderr, "Failed to read sensor values.\n");
        }

        // Delay for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

