    // Set the GPIO pins as outputs
    gpioSetMode(OUT1, PI_OUTPUT);
    gpioSetMode(OUT2, PI_OUTPUT);
    gpioSetMode(OUT3, PI_OUTPUT);
    gpioSetMode(OUT4, PI_OUTPUT);
    gpioSetMode(OUT5, PI_OUTPUT);
    gpioSetMode(OUT6, PI_OUTPUT);
    gpioSetMode(OUT7, PI_OUTPUT);
    gpioSetMode(OUT8, PI_OUTPUT);

    return 0;
}

// Function to read the state of a single channel
int read_channel(int channel) {
