    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s ", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("%d", channel_states[i]);
        if (i < NUM_CHANNELS - 1) {
            printf(",");
        }
    }
    printf("\n");
}

