    while (program_running) {
        int channel_states[NUM_CHANNELS];

        // Read the state of each channel
        for (int i = 0; i < NUM_CHANNELS; i++) {
            channel_states[i] = read_channel(i);
            if (channel_states[i] == -1) {
                // Handle the error from read_channel
                channel_states[i] = -1; // Set to -1 to indicate an error
            }
        }

        // Log the channel states
        log_channel_states(channel_states);

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

