#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 output pins
#define OUT1 2
#define OUT2 3
#define OUT3 4
#define OUT4 5
#define OUT5 6
#define OUT6 7
#define OUT7 8
#define OUT8 9

// Define the sampling interval in microseconds
#define SAMPLE_INTERVAL 100000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
    gpioSetMode(OUT1, PI_INPUT);
    gpioSetPullUpDown(OUT1, PI_PUD_DOWN);
    gpioSetMode(OUT2, PI_INPUT);
    gpioSetPullUpDown(OUT2, PI_PUD_DOWN);
    gpioSetMode(OUT3, PI_INPUT);
    gpioSetPullUpDown(OUT3, PI_PUD_DOWN);
    gpioSetMode(OUT4, PI_INPUT);
    gpioSetPullUpDown(OUT4, PI_PUD_DOWN);
    gpioSetMode(OUT5, PI_INPUT);
    gpioSetPullUpDown(OUT5, PI_PUD_DOWN);
    gpioSetMode(OUT6, PI_INPUT);
    gpioSetPullUpDown(OUT6, PI_PUD_DOWN);
    gpioSetMode(OUT7, PI_INPUT);
    gpioSetPullUpDown(OUT7, PI_PUD_DOWN);
    gpioSetMode(OUT8, PI_INPUT);
    gpioSetPullUpDown(OUT8, PI_PUD_DOWN);

    return 0;
}

// Function to read the sensor data from the TTP226
int read_sensor_data(unsigned int *data)
{
    // Read the digital values from the GPIO pins
    data[0] = gpioRead(OUT1);
    data[1] = gpioRead(OUT2);
    data[2] = gpioRead(OUT3);
    data[3] = gpioRead(OUT4);
    data[4] = gpioRead(OUT5);
    data[5] = gpioRead(OUT6);
    data[6] = gpioRead(OUT7);
    data[7] = gpioRead(OUT8);

    return 0;
}

// Function to print the sensor data in a formatted string
void print_sensor_data(unsigned int data[], int num_channels)
{
    printf("[%u ms] ", (unsigned int)(gpioTick() / 1000)); // Print the timestamp in milliseconds

    for (int i = 0; i < num_channels; i++)
    {
        printf("CH%d=%d ", i + 1, data[i]);
    }
    printf("\n");
}

int main()
{
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure the GPIO pins
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Main loop to read and print the sensor data
    unsigned int sensor_data[8];
    while (!terminate)
    {
        // Read the sensor data
        if (read_sensor_data(sensor_data) != 0)
        {
            fprintf(stderr, "Error reading sensor data\n");
        }
        else
        {
            // Print the sensor data
            print_sensor_data(sensor_data, 8);
        }

        // Delay for the specified sampling interval
        gpioDelay(SAMPLE_INTERVAL);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

