#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 sensor array
#define SENSOR1_PIN 2
#define SENSOR2_PIN 3
#define SENSOR3_PIN 4
#define SENSOR4_PIN 17
#define SENSOR5_PIN 27
#define SENSOR6_PIN 22
#define SENSOR7_PIN 10
#define SENSOR8_PIN 9

// Define the number of sensor channels
#define NUM_CHANNELS 8

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Configure each sensor pin as an input with pull-down resistor
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR4_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR5_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR5_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR6_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR6_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR7_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR7_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR8_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR8_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read the state of all sensor channels
int read_sensor_channels(int *channels) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        channels[i] = gpioRead(SENSOR1_PIN + i);
    }
    return 0;
}

// Function to format the sensor data into a CSV string
char *format_csv_data(int *channels) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char *csv_string = (char *)malloc(100 * sizeof(char)); // Allocate memory for the CSV string

    if (csv_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(csv_string, 100, "%s,%d,%d,%d,%d,%d,%d,%d\n",
             timestamp,
             channels[0],
             channels[1],
             channels[2],
             channels[3],
             channels[4],
             channels[5],
             channels[6]);

    return csv_string;
}

// Function to print the CSV data to the console
void print_csv_data(const char *csv_string) {
    if (csv_string != NULL) {
        printf("%s", csv_string);
        free(csv_string); // Free the allocated memory
    }
}

// Function to release GPIO resources and terminate the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor_channels[NUM_CHANNELS];

    // Main loop
    while (program_running) {
        // Read sensor channels
        if (read_sensor_channels(sensor_channels) != 0) {
            fprintf(stderr, "Error reading sensor channels\n");
        } else {
            // Format CSV data
            char *csv_data = format_csv_data(sensor_channels);

            if (csv_data != NULL) {
                // Print CSV data
                print_csv_data(csv_data);
            } else {
                fprintf(stderr, "Error formatting CSV data\n");
            }

            free(csv_data); // Free the allocated memory
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

