    char *csv_string = (char *)malloc(100 * sizeof(char)); // Allocate memory for the CSV string

    if (csv_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(csv_string, 100, "%s,%d,%d,%d,%d,%d,%d,%d\n",
             timestamp,
             channels[0],
             channels[1],
             channels[2],
             channels[3],
             channels[4],
             channels[5],
             channels[6]);

    return csv_string;
}

// Function to print the CSV data to the console
void print_csv_data(const char *csv_string) {
    if (csv_string != NULL) {
        printf("%s", csv_string);
        free(csv_string); // Free the allocated memory
    }
}

// Function to release GPIO resources and terminate the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor_channels[NUM_CHANNELS];

    // Main loop
    while (program_running) {
        // Read sensor channels
        if (read_sensor_channels(sensor_channels) != 0) {
            fprintf(stderr, "Error reading sensor channels\n");
        } else {
            // Format CSV data
            char *csv_data = format_csv_data(sensor_channels);

            if (csv_data != NULL) {
                // Print CSV data
                print_csv_data(csv_data);
            } else {
                fprintf(stderr, "Error formatting CSV data\n");
            }

            free(csv_data); // Free the allocated memory
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

