#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TILT_SENSOR_GPIO 4 // BCM pin 7

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int tilt_state;
    int result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Print startup banner
    printf("Tilt Sensor Monitoring\n");

    // Main loop
    while (program_running) {
        // Read the tilt sensor state
        tilt_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the GPIO read
        if (tilt_state != 0 && tilt_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read: %d\n", tilt_state);
            gpioTerminate();
            return 1;
        }

        // Check for tilt state change
        if (tilt_state != gpioRead(TILT_SENSOR_GPIO)) {
            // Flush stdout
            fflush(stdout);

            // Log tilt state
            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

