// Initialize the Si1145 sensor
int si1145_init() {
    int status;

    // Reset the sensor
    status = i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_RESET_CMD);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145 (status = %d)\n", status);
        return -1;
    }
