    if (status < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF1 (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_UCOEF2, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF2 (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_UCOEF3, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF3 (status = %d)\n", status);
        return -1;
    }

    // Enable UV and ALS measurements
    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, SI1145_UV_EN | SI1145_ALS_EN);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to enable UV and ALS (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, SI1145_IRQ_EN);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to enable IRQ (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, SI1145_ALS_VIS_ADC_GAIN);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set ALS_VIS_ADC_GAIN (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, SI1145_ALS_VIS_ADC_MUX);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set ALS_VIS_ADC_MUX (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, SI1145_ALS_VIS_ADC_RANGE);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set ALS_VIS_ADC_RANGE (status = %d)\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, SI1145_ALS_VIS_ADC_RESOLUTION);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set ALS_VIS_ADC_RESOLUTION (status = %d)\n", status);
        return -1;
