        return -1;
    }

    return 0;
}

// Read the UV index from the sensor
int read_uv_index(int *uv_index) {
    int status;
    uint8_t data[2];

    status = i2cReadI2CBlockData(i2c_handle, SI1145_REG_UV_INDEX0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read UV index (status = %d)\n", status);
        return -1;
    }

    *uv_index = (data[1] << 8) | data[0];
    return 0;
}

// Read the visible ambient light reading from the sensor
int read_als_visible(int *als_visible) {
    int status;
    uint8_t data[2];

    status = i2cReadI2CBlockData(i2c_handle, SI1145_REG_ALS_VIS_DATA0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read ALS visible data (status = %d)\n", status);
        return -1;
    }

    *als_visible = (data[1] << 8) | data[0];
    return 0;
}

// Log the data to a CSV file
void log_data(int uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int uv_index, als_visible;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (status = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header to the log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
    }
    rewind(log_file);

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_uv_index(&uv_index);
        if (status != 0) {
            fprintf(stderr, "Error: Failed to read UV index\n");
        }

        status = read_als_visible(&als_visible);
        if (status != 0) {
            fprintf(stderr, "Error: Failed to read ALS visible data\n");
        }

        // Log the data
        log_data(uv_index, als_visible);

        // Print the data to the console
        printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_visible);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

