#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define LOG_FILE "flow_log.txt"
#define START_COMMAND 0x3608 // Example start command, adjust based on datasheet
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor(int i2c_handle);
int read_flow_rate(int i2c_handle);
float calculate_average_flow(float flow1, float flow2);
void control_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int signal);
int crc8(const uint8_t *data, int len);

// CRC-8 calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the sensor
int init_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = (START_COMMAND >> 8) & 0xFF;
    buf[1] = START_COMMAND & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start command to sensor.\n");
        return -1;
    }

    gpioDelay(100); // Wait for 100ms after sending the start command
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int i2c_handle) {
    char buf[3];
    int flow_raw;
    uint8_t crc;

    // Read 3 bytes from the sensor
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read data from sensor.\n");
        return -1;
    }

    // Extract flow rate and CRC
    flow_raw = (buf[0] << 8) | buf[1];
    crc = buf[2];

    // CRC validation
    if (crc8(buf, 2) != crc) {
        fprintf(stderr, "Error: CRC validation failed.\n");
        return -1;
    }

    // Convert to ml/min (adjust scaling factor as needed)
    float flow_rate = (float)flow_raw / 100.0; // Example scaling factor

    return (int)flow_rate;
}

// Calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Control the alarm based on the average flow rate
void control_alarm(float average_flow) {
    if (average_flow < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Activate alarm
    } else {
        gpioWrite(ALARM_GPIO, 0); // Deactivate alarm
    }
}

// Log the data to a file
void log_data(float flow1, float flow2, float average_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error: Failed to initialize sensor 1.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error: Failed to initialize sensor 2.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1, flow2, average_flow;

        // Read flow rates from sensors
        flow1 = read_flow_rate(i2c_handle1);
        flow2 = read_flow_rate(i2c_handle2);

        // Validate sensor readings
        if (flow1 != -1 && flow2 != -1) {
            average_flow = calculate_average_flow(flow1, flow2);
            control_alarm(average_flow);
            log_data(flow1, flow2, average_flow);
        } else {
            fprintf(stderr, "Error: Invalid sensor reading, skipping logging.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

