#include <time.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 50

// Structure to hold sensor data and timestamp
typedef struct {
    int sensor_value;
    time_t timestamp;
} SensorData;

// Circular buffer
SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int sensor_value);
void print_buffer();
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        int sensor_value = read_sensor();
        if (sensor_value == -1) {
            fprintf(stderr, "Error reading sensor. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        add_to_buffer(sensor_value);

        // Check for obstacle detection
        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

