    return gpioRead(GPIO_PIN);
}

// Add sensor data to circular buffer
void add_to_buffer(int sensor_value) {
    circular_buffer[buffer_index].sensor_value = sensor_value;
    circular_buffer[buffer_index].timestamp = time(NULL);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&circular_buffer[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Sensor Value: %d\n", timestamp_str, circular_buffer[i].sensor_value);
    }
    printf("--- End of Data ---\n");
}

