#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as input or output
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors(int sensor1_pin, int sensor2_pin) {
    int sensor1_value = gpioRead(sensor1_pin);
    int sensor2_value = gpioRead(sensor2_pin);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return 1; // Indicate failure
    }

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // Return 1 if either sensor detects an obstacle
}

// Function to control the LED
void control_led(int led_pin, int state) {
    gpioWrite(led_pin, state);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_sensors(SENSOR1_PIN, SENSOR2_PIN)) {
            control_led(LED_PIN, 1); // Turn LED on if an obstacle is detected
        } else {
            control_led(LED_PIN, 0); // Turn LED off if no obstacle is detected
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Obstacle avoidance system stopped.\n");

    return 0;
}

