#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the stall duration threshold (in seconds)
#define STALL_DURATION_THRESHOLD 2

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_number;
} sensor_t;

// Global variables
static volatile int running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int is_stall_confirmed(int sensor1_value, int sensor2_value, int duration);
int log_stall(int sensor1_gpio, int sensor2_gpio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the value from a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to check if a stall is confirmed based on sensor readings and duration
int is_stall_confirmed(int sensor1_value, int sensor2_value, int duration) {
    return (sensor1_value == 0 && sensor2_value == 0) && duration >= STALL_DURATION_THRESHOLD;
}

// Function to log a stall event to the log file
int log_stall(int sensor1_gpio, int sensor2_gpio) {
    pthread_mutex_lock(&log_mutex);
    if (log_file == NULL) {
        pthread_mutex_unlock(&log_mutex);
        return 1; // Indicate failure
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Stall confirmed on GPIO %d and GPIO %d\n", timestamp, sensor1_gpio, sensor2_gpio);
    fflush(log_file); // Ensure the data is written to the file immediately

    pthread_mutex_unlock(&log_mutex);
    return 0; // Indicate success
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate(); // Clean up GPIO before exiting
        return 1; // Exit if log file opening fails
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            // Attempt to recover, but continue monitoring
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Stall detection logic
        if (is_stall_confirmed(sensor1_value, sensor2_value, 0)) {
            printf("Stall confirmed!\n");
            if (log_stall(SENSOR1_GPIO, SENSOR2_GPIO) != 0) {
                fprintf(stderr, "Error logging stall event\n");
            }
            gpioDelay(STALL_DURATION_THRESHOLD * 1000); // Wait for the stall duration
        }

        gpioDelay(100); // Small delay to avoid excessive CPU usage
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

