#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170-Q1 register addresses
#define TMAG5170_REG_XOUT 0x00
#define TMAG5170_REG_YOUT 0x02
#define TMAG5170_REG_ZOUT 0x04
#define TMAG5170_REG_CONFIG 0x06
#define TMAG5170_REG_RANGE 0x08
#define TMAG5170_REG_MODE 0x09

// Configuration values
#define TMAG5170_CONFIG_DEFAULT 0x00 // Continuous conversion mode, all axes enabled

// Range value for 50 mT
#define TMAG5170_RANGE_50MT 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // I2C bus 1, address 0x0E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Sensor configuration function
int configure_sensor() {
    // Configure for continuous conversion mode and 50 mT range
    int status = i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_DEFAULT);
    if (status < 0) {
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, TMAG5170_REG_RANGE, TMAG5170_RANGE_50MT);
    if (status < 0) {
        fprintf(stderr, "Failed to write to range register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Sensor data reading function
int read_sensor_data(sensor_data_t *data) {
    int status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_XOUT);
    if (status < 0) {
        fprintf(stderr, "Failed to read X data: %s\n", strerror(errno));
        return -1;
    }
    data->x = (int16_t)status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_YOUT);
    if (status < 0) {
        fprintf(stderr, "Failed to read Y data: %s\n", strerror(errno));
        return -1;
    }
    data->y = (int16_t)status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_ZOUT);
    if (status < 0) {
        fprintf(stderr, "Failed to read Z data: %s\n", strerror(errno));
        return -1;
    }
    data->z = (int16_t)status;

    return 0;
}

// Data logging function
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
