void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Main loop
    while (running) {
        if (check_water_level()) {
            handle_alert();
            // Schedule re-initialization after 60 seconds
            gpioDelay(REINIT_DELAY * 1000); // pigpioDelay takes milliseconds
        } else {
            gpioDelay(2000); // Check every 2 seconds
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

