#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

// Configuration
#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_WINDOW_US 1000000 // 1 second
#define PULSE_COUNT_THRESHOLD 100 // Minimum number of pulses to consider rotation
#define DEBOUNCE_DELAY_US 5000    // Debounce delay in microseconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_count_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile int running = 1; // Flag to control the main loop

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count);
void log_rpm(double rpm);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int gpio_pin;
    char *log_file;
    double rpm;
} program_state_t;

// Function to initialize the program state
program_state_t initialize_program() {
    program_state_t state;
    state.gpio_pin = GPIO_PIN;
    state.log_file = LOG_FILE;
    state.rpm = 0.0;
    return state;
}

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_count_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_count_mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    double time_taken = (double)pulse_count / 1000.0; // pulses per second
    if (time_taken > 0) {
        return (60.0 / time_taken) * 1000.0; // RPM
    } else {
        return 0.0;
    }
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s %.2f\n", timestamp, rpm);
    fflush(fp); // Ensure data is written to disk immediately
    printf("%s %.2f\n", timestamp, rpm);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
}

// Cleanup function
void cleanup() {
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&pulse_count_mutex);
    printf("Cleanup complete.\n");
}

int main() {
    program_state_t state = initialize_program();
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(state.gpio_pin, PI_INPUT);
    gpioSetPullUpDown(state.gpio_pin, PI_PUD_UP);

    // Set interrupt callback
    result = gpioSetAlertFuncEx(state.gpio_pin, pulse_callback, NULL);
    if (result != 0) {
        fprintf(stderr, "Error setting alert function: %d\n", result);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Calculate RPM
        double rpm = calculate_rpm(pulse_count);

        // Log RPM
        log_rpm(rpm);

        // Reset pulse count
        pthread_mutex_lock(&pulse_count_mutex);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_count_mutex);

        // Wait for 1 second
        gpioDelay(SAMPLE_WINDOW_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

