#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of pulses to wait for before checking direction
#define PULSES_TO_WAIT 4

// Define the quadrature state machine states
typedef enum {
    STATE_NONE,
    STATE_A_HIGH,
    STATE_A_LOW,
    STATE_B_HIGH,
    STATE_B_LOW
} QuadratureState;

// Global variables
static volatile int running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static QuadratureState current_state = STATE_NONE;
static int last_a_state = 0;
static int last_b_state = 0;
static int last_a_pulse_time = 0;
static int last_b_pulse_time = 0;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void *log_data(void *arg);
void signal_handler(int signal);
int initialize_gpio();
int initialize_log_file();
void cleanup();

// Structure to pass data to the ISR
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} isr_data_t;

// ISR function for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        last_a_pulse_time = tick;
        current_state = STATE_A_HIGH;
        last_a_state = gpioRead(SENSOR_A_GPIO);
    } else if (level == PI_LOW) {
        if (current_state == STATE_A_HIGH) {
            if (last_a_state == 1 && gpioRead(SENSOR_A_GPIO) == 1) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_A_LOW;
            }
            last_a_pulse_time = tick;
        } else if (current_state == STATE_A_LOW) {
            if (last_a_state == 0 && gpioRead(SENSOR_A_GPIO) == 0) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_B_HIGH;
            }
            last_a_pulse_time = tick;
        }
        last_a_state = gpioRead(SENSOR_A_GPIO);
    }
}

// ISR function for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        last_b_pulse_time = tick;
        current_state = STATE_B_HIGH;
        last_b_state = gpioRead(SENSOR_B_GPIO);
    } else if (level == PI_LOW) {
        if (current_state == STATE_B_HIGH) {
            if (last_b_state == 1 && gpioRead(SENSOR_B_GPIO) == 1) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_B_LOW;
            }
            last_b_pulse_time = tick;
        } else if (current_state == STATE_B_LOW) {
            if (last_b_state == 0 && gpioRead(SENSOR_B_GPIO) == 0) {
                current_state = STATE_NONE;
            } else {
                current_state = STATE_A_HIGH;
            }
            last_b_pulse_time = tick;
        }
        last_b_state = gpioRead(SENSOR_B_GPIO);
    }
}

// Function to log the rotation data
void *log_data(void *arg) {
    struct timespec ts;
    char timestamp[30];
    int a_state, b_state;
    int a_high, b_high;
    int a_low, b_low;
    int a_pulse_time, b_pulse_time;
    int a_state_history[5] = {0, 0, 0, 0, 0};
    int b_state_history[5] = {0, 0, 0, 0, 0};
    int a_pulse_history[5] = {0, 0, 0, 0, 0};
    int b_pulse_history[5] = {0, 0, 0, 0, 0};
    int i;

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        long milliseconds = ts.tv_nsec / 1000000;

        a_state = gpioRead(SENSOR_A_GPIO);
