// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of pulses to wait for before checking direction
#define PULSES_TO_WAIT 4

// Define the quadrature state machine states
typedef enum {
    STATE_NONE,
    STATE_A_HIGH,
    STATE_A_LOW,
    STATE_B_HIGH,
    STATE_B_LOW
} QuadratureState;

// Global variables
static volatile int running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static QuadratureState current_state = STATE_NONE;
static int last_a_state = 0;
static int last_b_state = 0;
static int last_a_pulse_time = 0;
static int last_b_pulse_time = 0;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void *log_data(void *arg);
void signal_handler(int signal);
int initialize_gpio();
int initialize_log_file();
