#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 200

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        closelog(); // Close syslog
        exit(0); // Exit program
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        log_event("Failed to set touch sensor pin as input");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set LED pin as output");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main() {
    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            control_led(1); // Turn on LED
            log_event("Touch detected, LED turned on");
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else {
            control_led(0); // Turn off LED
            log_event("No touch detected, LED turned off");
        }

        gpioDelay(50000); // Poll every 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog

    return 0;
}

