#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(LED_PIN, 0); // Initialize LED to LOW

    return 0;
}

// Function to read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED state
void toggle_led() {
    gpioWrite(LED_PIN, !gpioRead(LED_PIN));
}

// Function to debounce the touch sensor
void debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch sensor value
        int touch_detected = read_touch_sensor();

        // Check for rising edge
        if (touch_detected == 1) {
            printf("Touch detected!\n");
            toggle_led();
            debounce();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // Delay in microseconds
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated.\n");
    return 0;
}

