#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define circular buffer size
#define BUFFER_SIZE 100

// Define log file name
#define LOG_FILE "touch_log.txt"

// Structure to store touch events
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int new_state;
} TouchEvent;

// Circular buffer structure
typedef struct {
    TouchEvent buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow;
} CircularBuffer;

// Global variables
CircularBuffer log_buffer;
FILE *log_file;
int running = 1;

// Function prototypes
int init_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void add_to_log(int sensor_pin, int new_state);
void print_log();
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->overflow = 0;
}

// Add event to circular buffer
void add_to_log(int sensor_pin, int new_state) {
    TouchEvent event;
    event.sensor_pin = sensor_pin;
    event.timestamp = time(NULL);
    event.new_state = new_state;

    log_buffer.buffer[log_buffer.head] = event;
    log_buffer.head = (log_buffer.head + 1) % BUFFER_SIZE;

    if (log_buffer.count == BUFFER_SIZE) {
        log_buffer.tail = (log_buffer.tail + 1) % BUFFER_SIZE;
        log_buffer.count++;
    } else {
        log_buffer.count++;
    }

    if (log_buffer.count > BUFFER_SIZE) {
        log_buffer.overflow = 1;
    }
}

// Print the contents of the log buffer
void print_log() {
    if (log_buffer.overflow) {
        printf("Overflow detected in log buffer!\n");
    }

    int i = log_buffer.tail;
    for (int j = 0; j < log_buffer.count; j++) {
        printf("Sensor: %d, Timestamp: %ld, New State: %d\n",
               log_buffer.buffer[i].sensor_pin,
               log_buffer.buffer[i].timestamp,
               log_buffer.buffer[i].new_state);
        i = (i + 1) % BUFFER_SIZE;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(LED1_PIN, 0);
    control_led(LED2_PIN, 0);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

int main() {
    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&log_buffer);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == 1) {
            control_led(LED1_PIN, 1);
            add_to_log(SENSOR1_PIN, 1);
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            control_led(LED1_PIN, 0);
        } else if (sensor1_value == 0) {
            control_led(LED1_PIN, 0);
            add_to_log(SENSOR1_PIN, 0);
        }

        if (sensor2_value == 1) {
            control_led(LED2_PIN, 1);
            add_to_log(SENSOR2_PIN, 1);
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            control_led(LED2_PIN, 0);
        } else if (sensor2_value == 0) {
            control_led(LED2_PIN, 0);
            add_to_log(SENSOR2_PIN, 0);
        }

        gpioDelay(10000); // Check sensors every 10ms
    }

    // Print log before exiting
    print_log();

    return 0;
}

