    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
    free(timestamp);
    return 0;
}

// Function to read the rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_GPIO);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_rain_sensor();

        if (sensor_value == 0) { // Active-low condition: LOW indicates rain
            if (log_message("Rain Detected") != 0) {
                fprintf(stderr, "Failed to log rain detection.\n");
            }
        } else { // No rain
            if (log_message("No Rain") != 0) {
                fprintf(stderr, "Failed to log no rain.\n");
            }
