#include <errno.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables to store the last state of each sensor
static volatile int sensor1_last_state = 0;
static volatile int sensor2_last_state = 0;

// File pointer for the log file
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
void log_transition(int sensor1_state, int sensor2_state);
double calculate_rpm(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Function to read the state of a sensor with debouncing
int read_sensor(int gpio) {
    int current_state = gpioRead(gpio);
    int last_state = sensor1_last_state; // Use sensor1_last_state for both sensors

    if (current_state != last_state) {
        gpioDelay(DEBOUNCE_TIME * 1000); // Delay for debounce time
        current_state = gpioRead(gpio);
        if (current_state == last_state) {
            return current_state; // Return the state after debounce
        }
    }
    return last_state; // Return the last state if debounce fails
}

// Function to log a transition to the CSV file
void log_transition(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate the RPM
double calculate_rpm(int sensor1_state, int sensor2_state) {
    // This is a simplified RPM calculation.  A more accurate
    // calculation would involve measuring the time between transitions
    // and dividing by the number of revolutions.
    // For this example, we'll just count the number of transitions per second.
    static int last_transition_time = 0;
    static int last_rpm = 0;
    static int last_sensor1_state = 0;
    static int last_sensor2_state = 0;

    int current_sensor1_state = read_sensor(SENSOR1_GPIO);
    int current_sensor2_state = read_sensor(SENSOR2_GPIO);

    if (current_sensor1_state != last_sensor1_state) {
        last_transition_time = time(NULL);
        last_sensor1_state = current_sensor1_state;
    }
    if (current_sensor2_state != last_sensor2_state) {
        last_transition_time = time(NULL);
        last_sensor2_state = current_sensor2_state;
    }

    double current_time = time(NULL);
    double time_diff = difftime(current_time, last_transition_time);

    if (time_diff > 0) {
        int rpm = 60.0 / time_diff; // Calculate RPM per second
        return rpm;
    } else {
        return 0.0; // Avoid division by zero
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Open the log file for appending
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        log_transition(sensor1_state, sensor2_state);

        double rpm = calculate_rpm(sensor1_state, sensor2_state);
        printf("RPM: %.2f\n", rpm);

        gpioDelay(100000); // Delay for 100ms (10 times per second)
    }

    return 0;
}

