#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27

// Define constants
#define THRESHOLD_DURATION 2000 // milliseconds
#define LOG_FILE "bridge_integrity.log"

// Global variables
FILE *log_file = NULL;
int alarm_active = 0;
int sensor1_state = 0;
int sensor2_state = 0;
time_t last_tilt_start = 0;
time_t last_tilt_end = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, int sensor_number);
int check_threshold(int sensor_number, int state, time_t last_tilt_start, time_t last_tilt_end);
void activate_alarm();
void deactivate_alarm();
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Function to read sensor state
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log events to file
int log_event(const char *event_type, int sensor_number) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (strcmp(event_type, "tilt_start") == 0) {
        fprintf(log_file, "%s - Sensor %d - Tilt Start\n", timestamp, sensor_number);
        fflush(log_file);
    } else if (strcmp(event_type, "threshold_exceeded") == 0) {
        fprintf(log_file, "%s - Sensor %d - Threshold Exceeded\n", timestamp, sensor_number);
        fflush(log_file);
    } else if (strcmp(event_type, "tilt_end") == 0) {
        fprintf(log_file, "%s - Sensor %d - Tilt End\n", timestamp, sensor_number);
        fflush(log_file);
    } else {
        fprintf(stderr, "Invalid event type: %s\n", event_type);
        return 1;
    }

    return 0;
}

// Function to check if threshold is exceeded
int check_threshold(int sensor_number, int state, time_t last_tilt_start, time_t last_tilt_end) {
    time_t now = time(NULL);

    if (sensor_number == 1) {
        if (state == 1 && last_tilt_start == 0) {
            last_tilt_start = now;
        } else if (state == 0 && last_tilt_start != 0) {
            last_tilt_end = now;
            last_tilt_start = 0; // Reset start time
        }

        if (last_tilt_end != 0 && (now - last_tilt_end) >= THRESHOLD_DURATION) {
            return 1; // Threshold exceeded
        }
    } else if (sensor_number == 2) {
        if (state == 1 && last_tilt_start == 0) {
            last_tilt_start = now;
        } else if (state == 0 && last_tilt_start != 0) {
            last_tilt_end = now;
            last_tilt_start = 0; // Reset start time
        }

        if (last_tilt_end != 0 && (now - last_tilt_end) >= THRESHOLD_DURATION) {
            return 1; // Threshold exceeded
        }
    }

    return 0; // Threshold not exceeded
}

// Function to activate the alarm (buzzer/LED)
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
    alarm_active = 1;
}

// Function to deactivate the alarm (buzzer/LED)
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
    alarm_active = 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to perform cleanup tasks
void cleanup() {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        if (sensor1_state != sensor1_state) {
            sensor1_state = sensor1_state; // Ensure consistent state
        }
        if (sensor2_state != sensor2_state) {
            sensor2_state = sensor2_state; // Ensure consistent state
        }

        if (sensor1_state == 1) {
            if (log_event("tilt_start", 1) != 0) {
                fprintf(stderr, "Error logging tilt start event\n");
            }
            last_tilt_start = time(NULL);
        } else if (sensor1_state == 0) {
            if (log_event("tilt_end", 1) != 0) {
                fprintf(stderr, "Error logging tilt end event\n");
            }
            last_tilt_start = 0;
        }

        if (sensor2_state == 1) {
            if (log_event("tilt_start", 2) != 0) {
                fprintf(stderr, "Error logging tilt start event\n");
            }
            last_tilt_start = time(NULL);
        } else if (sensor2_state == 0) {
            if (log_event("tilt_end", 2) != 0) {
                fprintf(stderr, "Error logging tilt end event\n");
            }
            last_tilt_start = 0;
        }

        if (check_threshold(1, sensor1_state, last_tilt_start, last_tilt_end) || check_threshold(2, sensor2_state, last_tilt_start, last_tilt_end)) {
            if (alarm_active) {
                deactivate_alarm();
            }
            activate_alarm();
        }

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

