#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define constants
#define I2C_ADDR 0x4C  // Omron D7S-A0011 I2C address
#define CTRL1_REG 0x00  // Control register address
#define CTRL1_VAL 0x00  // Power-up value
#define LED_PIN 17       // GPIO pin for the alert LED
#define THRESHOLD 500   // Vibration magnitude threshold
#define POLL_INTERVAL_MS 100 // Polling interval in milliseconds

// Global variables
int i2c_fd;             // I2C file descriptor
FILE *log_file;         // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int init_sensor();
int read_sensor_data(int *x, int *y, int *z);
double calculate_magnitude(int x, int y, int z);
int detect_event(double magnitude);
int log_event(int x, int y, int z);
int control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0; // Set the flag to exit the main loop
    }
}

// Initialize the sensor
int init_sensor() {
    int retries = 3;
    while (retries > 0) {
        i2c_fd = wiringPiI2CSetup(I2C_ADDR);
        if (i2c_fd == -1) {
            fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
            retries--;
            delay(100); // Wait before retrying
        } else {
            // Verify sensor presence by reading CTRL1 register
            int sensor_present = wiringPiI2CReadReg8(i2c_fd, CTRL1_REG);
            if (sensor_present == -1) {
                fprintf(stderr, "Error reading CTRL1 register: %s\n", strerror(errno));
                close(i2c_fd);
                i2c_fd = -1;
                retries--;
                delay(100);
            } else {
                // Clear power-down bit
                if (wiringPiI2CWriteReg8(i2c_fd, CTRL1_REG, CTRL1_VAL) == -1) {
                    fprintf(stderr, "Error writing to CTRL1 register: %s\n", strerror(errno));
                    close(i2c_fd);
                    i2c_fd = -1;
                    retries--;
                    delay(100);
                } else {
                    printf("Sensor initialized successfully.\n");
                    return 0; // Success
                }
            }
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(int *x, int *y, int *z) {
    int retries = 3;
    while (retries > 0) {
        int x_val = wiringPiI2CReadReg8(i2c_fd, 0x02); // X-axis data register
        int y_val = wiringPiI2CReadReg8(i2c_fd, 0x04); // Y-axis data register
        int z_val = wiringPiI2CReadReg8(i2c_fd, 0x06); // Z-axis data register

        if (x_val == -1 || y_val == -1 || z_val == -1) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            retries--;
            delay(100);
        } else {
            *x = x_val;
            *y = y_val;
            *z = z_val;
            return 0; // Success
        }
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Calculate Euclidean magnitude
double calculate_magnitude(int x, int y, int z) {
    return sqrt(x * x + y * y + z * z);
}

// Detect earthquake-like event
int detect_event(double magnitude) {
    return (magnitude > THRESHOLD);
}

// Log event to file
int log_event(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control the alert LED
int control_led(int state) {
    digitalWrite(LED_PIN, state);
    return 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int x, y, z;
    double magnitude;

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect event
            if (detect_event(magnitude)) {
                printf("Event detected! Magnitude: %.2f\n", magnitude);

                // Log the event
                log_event(x, y, z);

                // Control the LED
                control_led(HIGH);
                delay(1000); // LED on for 1 second
                control_led(LOW);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying.\n");
        }

        delay(POLL_INTERVAL_MS); // Wait before next poll
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

