#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <stdbool.h>

// Configuration
#define NUM_SENSORS 5
#define DEBOUNCE_DELAY_MS 50
#define I2C_BUS 1
#define DHT22_GPIO 4
#define DHT22_RETRY_COUNT 3
#define DHT22_RETRY_DELAY_MS 10
#define DHT22_DATA_LENGTH 5
#define LOG_FILE "/var/log/flame_events.log"
#define I2C_DEVICE "/dev/i2c-1"

// Sensor IDs
const char *sensor_ids[NUM_SENSORS] = {
    "Sensor 1 (GPIO 2)",
    "Sensor 2 (GPIO 3)",
    "Sensor 3 (GPIO 4)",
    "Sensor 4 (GPIO 17)",
    "Sensor 5 (GPIO 27)"
};

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    int last_state;
    int current_state;
    int line;
} sensor_data_t;

sensor_data_t sensors[NUM_SENSORS];

// Function prototypes
void signal_handler(int sig);
int init_gpio();
int init_i2c();
int read_dht22(float *temperature, float *humidity);
int read_flame_sensor(int gpio_pin);
void log_event(const char *sensor_id, const char *event);
void cleanup();
void log_error(const char *message);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].gpio_pin = gpioGetMode(sensors[i].gpio_pin);
        if (gpioGetMode(sensors[i].gpio_pin) != PI_INPUT) {
            log_error("Invalid GPIO mode");
            return -1;
        }
        gpioSetMode(sensors[i].gpio_pin, PI_INPUT);
        gpioSetPullUpDown(sensors[i].gpio_pin, PI_PUD_DOWN); // Use pull-down resistor
        sensors[i].last_state = gpioRead(sensors[i].gpio_pin);
        sensors[i].current_state = sensors[i].last_state;
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x48) < 0) {
        log_error("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read DHT22 sensor
int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0};
    int bit_count = 0;
    int i;

    // Send start signal
    if (write(i2c_fd, "\0", 1) != 1) {
        log_error("Failed to send start signal");
        return -1;
    }

    // Wait for response (DHT22 pulls low for ~80us, then high for ~80us)
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (read(i2c_fd, "\0", 1) != 1) {
            log_error("Failed to read start signal");
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        if (elapsed > 0.2) {
            break;
        }
    }

    // Send read request (0x00)
    if (write(i2c_fd, "\0", 1) != 1) {
        log_error("Failed to send read request");
        return -1;
    }

    // Wait for data (DHT22 sends 40 bits of data)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (read(i2c_fd, "\0", 1) != 1) {
            log_error("Failed to read data");
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        if (elapsed > 0.5) {
            break;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < DHT22_DATA_LENGTH; i++) {
        if (read(i2c_fd, &data[i], 1) != 1) {
            log_error("Failed to read data bit");
            return -1;
        }
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1]) / 10.0);
    *temperature = (float)(((data[2] << 8) | data[3]) / 10.0);
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

// Read flame sensor
int read_flame_sensor(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    if (current_state != sensors[gpio_pin - 1].current_state) {
        sensors[gpio_pin - 1].current_state = current_state;
        if (current_state == 0) { // Flame detected (LOW signal)
            return 1;
        }
        return 0;
    }
    return 0;
}

// Log event
void log_event(const char *sensor_id, const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %s - Sensor ID: %s - %s\n", timestamp, event, sensor_id, event);
    fflush(log_file);
    syslog(LOG_INFO, "%s - %s - Sensor ID: %s - %s", timestamp, event, sensor_id, event);
}

// Log error
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - ERROR: %s\n", timestamp, message);
    fflush(log_file);
    syslog(LOG_ERR, "%s - ERROR: %s", timestamp, message);
}

// Cleanup
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line != NULL) {
            flock(sensors[i].line, LOCK_UN);
            close(sensors[i].line);
        }
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_error("GPIO initialization failed");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int sensor_id = sensors[i].sensor_id;
            int gpio_pin = sensors[i].gpio_pin;
            int current_state = sensors[i].current_state;
            int last_state = sensors[i].last_state;
            int line = sensors[i].line;

            if (read_flame_sensor(gpio_pin)) {
                if (current_state == 0 && last_state == 1) {
                    // Flame detected
                    log_event(sensor_id, "Flame Detected");
                    if (line != NULL) {
                        flock(line, LOCK_EX);
                        fprintf(line, "%s - %s - Sensor ID: %s - Flame Detected\n", get_timestamp(), "Flame Detected", sensor_id);
                        fflush(line);
                        flock(line, LOCK_UN);
                    }
                }
            }

            // Read DHT22 sensor
            float temperature = 0.0;
            float humidity = 0.0;
            if (read_dht22(&temperature, &humidity) == 0) {
                char event_message[64];
                snprintf(event_message, sizeof(event_message), "Temperature: %.1f\u00b0C, Humidity: %.1f%%", temperature, humidity);
                log_event(sensor_id, event_message);
            } else {
                log_error("Failed to read DHT22 sensor");
            }
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Helper function to get current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    return timestamp;
}

