#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 sensor
#define OUT0 5
#define OUT1 6
#define OUT2 13
#define OUT3 19
#define OUT4 26
#define OUT5 12
#define OUT6 16
#define OUT7 20

// Structure to hold sensor data
typedef struct {
    int pin;
    int state;
} sensor_data_t;

// Global array to store sensor data
sensor_data_t sensors[8];

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void log_touch_event(int sensor_index, int pin, const char *event);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < 8; i++) {
        gpioSetMode(sensors[i].pin, PI_INPUT);
        gpioSetPullUpDown(sensors[i].pin, PI_PUD_DOWN); // Use pull-down resistor
    }

    return 0; // Indicate success
}

// Function to read the state of a single sensor pin
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log a touch event to the console
void log_touch_event(int sensor_index, int pin, const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Sensor %d (Pin %d) %s\n", timestamp, sensor_index, pin, event);
}

// Function to cleanup GPIO resources before exiting
void cleanup_gpio() {
    for (int i = 0; i < 8; i++) {
        gpioSetMode(sensors[i].pin, PI_INPUT); // Set to input to avoid issues
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Initialize sensor data
    sensors[0].pin = OUT0;
    sensors[0].state = 0;
    sensors[1].pin = OUT1;
    sensors[1].state = 0;
    sensors[2].pin = OUT2;
    sensors[2].state = 0;
    sensors[3].pin = OUT3;
    sensors[3].state = 0;
    sensors[4].pin = OUT4;
    sensors[4].state = 0;
    sensors[5].pin = OUT5;
    sensors[5].state = 0;
    sensors[6].pin = OUT6;
    sensors[6].state = 0;
    sensors[7].pin = OUT7;
    sensors[7].state = 0;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        for (int i = 0; i < 8; i++) {
            int current_state = read_sensor(sensors[i].pin);

            if (current_state != sensors[i].state) {
                if (current_state == 1) {
                    log_touch_event(i, sensors[i].pin, "Touched");
                } else {
                    log_touch_event(i, sensors[i].pin, "Released");
                }
                sensors[i].state = current_state;
            }
        }
        gpioDelay(50000); // Delay for 50ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

