#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// GPIO pin for PWM output
#define PWM_PIN 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int init_pwm(int pin, int frequency);
int read_lux(int fd);
int map_lux_to_brightness(int lux);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_data(FILE *fp, int lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    set_pwm_duty_cycle(PWM_PIN, 0); // Turn off LED
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Initialize PWM on a GPIO pin
int init_pwm(int pin, int frequency) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(pin, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock for desired frequency
    pwmSetRange(1000); // Adjust range for desired duty cycle resolution
    pwmSetClock(192); // Adjust clock for desired frequency
    return 0;
}

// Read lux value from VEML7700 sensor
int read_lux(int fd) {
    int lux = wiringPiI2CReadReg16(fd, VEML7700_ALS_DATA);
    if (lux == -1) {
        fprintf(stderr, "Error reading lux value: %s\n", strerror(errno));
        return -1;
    }
    return lux;
}

// Map lux value to PWM duty cycle
int map_lux_to_brightness(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Duty cycle out of range (0-100).\n");
        return -1;
    }
    pwmWrite(pin, duty_cycle);
    return 0;
}

// Log data to file
int log_data(FILE *fp, int lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(VEML7700_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize PWM
    if (init_pwm(PWM_PIN, PWM_FREQUENCY) == -1) {
        fprintf(stderr, "Failed to initialize PWM. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read lux value
        int lux = read_lux(i2c_fd);
        if (lux == -1) {
            fprintf(stderr, "Error reading lux value. Using default brightness.\n");
            set_pwm_duty_cycle(PWM_PIN, 50); // Set default brightness
            log_data(log_file, -1, 50, -1); // Log error
        } else {
            // Map lux to brightness
            int brightness = map_lux_to_brightness(lux);

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(PWM_PIN, brightness) == -1) {
                fprintf(stderr, "Error setting PWM duty cycle.\n");
                log_data(log_file, lux, brightness, -1); // Log error
            } else {
                // Log data
                log_data(log_file, lux, brightness, 0); // Log data
            }
        }

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_pwm_duty_cycle(PWM_PIN, 0); // Turn off LED
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

