#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for touch sensors and alert LED
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9
#define ALERT_LED 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variable to track the state of the touch sensors
int touch_sensors[8] = {0};

// File pointer for the log file
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int channel);
int log_touch_event(int channel);
int control_alert_led(int all_released);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_alert_led(1); // Turn off the LED
    gpioTerminate();       // Terminate the pigpio library
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(TOUCH_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_8, PI_PUD_DOWN);

    // Set GPIO pin for alert LED as output
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    return 0;
}

// Function to read the state of a touch sensor
int read_touch_sensor(int channel) {
    return gpioRead(channel);
}

// Function to log a touch event to the file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s – Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

// Function to control the alert LED
int control_alert_led(int all_released) {
    if (all_released) {
        gpioWrite(ALERT_LED, 0); // Turn off the LED
    } else {
        gpioWrite(ALERT_LED, 1); // Turn on the LED
    }
    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensors
        int sensor1_touched = read_touch_sensor(TOUCH_SENSOR_1);
        int sensor2_touched = read_touch_sensor(TOUCH_SENSOR_2);
        int sensor3_touched = read_touch_sensor(TOUCH_SENSOR_3);
        int sensor4_touched = read_touch_sensor(TOUCH_SENSOR_4);
        int sensor5_touched = read_touch_sensor(TOUCH_SENSOR_5);
        int sensor6_touched = read_touch_sensor(TOUCH_SENSOR_6);
        int sensor7_touched = read_touch_sensor(TOUCH_SENSOR_7);
        int sensor8_touched = read_touch_sensor(TOUCH_SENSOR_8);

        // Debounce and log touch events
        if (sensor1_touched && !touch_sensors[0]) {
            log_touch_event(1);
            touch_sensors[0] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor1_touched && touch_sensors[0]) {
            touch_sensors[0] = 0;
        }

        if (sensor2_touched && !touch_sensors[1]) {
            log_touch_event(2);
            touch_sensors[1] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor2_touched && touch_sensors[1]) {
            touch_sensors[1] = 0;
        }

        if (sensor3_touched && !touch_sensors[2]) {
            log_touch_event(3);
            touch_sensors[2] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor3_touched && touch_sensors[2]) {
            touch_sensors[2] = 0;
        }

        if (sensor4_touched && !touch_sensors[3]) {
            log_touch_event(4);
            touch_sensors[3] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor4_touched && touch_sensors[3]) {
            touch_sensors[3] = 0;
        }

        if (sensor5_touched && !touch_sensors[4]) {
            log_touch_event(5);
            touch_sensors[4] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor5_touched && touch_sensors[4]) {
            touch_sensors[4] = 0;
        }

        if (sensor6_touched && !touch_sensors[5]) {
            log_touch_event(6);
            touch_sensors[5] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor6_touched && touch_sensors[5]) {
            touch_sensors[5] = 0;
        }

        if (sensor7_touched && !touch_sensors[6]) {
            log_touch_event(7);
            touch_sensors[6] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor7_touched && touch_sensors[6]) {
            touch_sensors[6] = 0;
        }

        if (sensor8_touched && !touch_sensors[7]) {
            log_touch_event(8);
            touch_sensors[7] = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        } else if (sensor8_touched && touch_sensors[7]) {
            touch_sensors[7] = 0;
        }

        // Control the alert LED
        control_alert_led(0); // All channels released

        gpioDelay(50000); // Poll every 50ms
    }

    return 0;
}

