#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00

int i2c_handle;
FILE *log_file;

// Function to write a 16-bit value to the OPT3001 configuration register
int opt3001_write_config(int handle, unsigned short config_value) {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to OPT3001 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the OPT3001 result register
int opt3001_read_result(int handle, unsigned short *result) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);

    if (result != 0) {
        fprintf(stderr, "Error reading from OPT3001 result register: %d\n", result);
        return -1;
    }

    // Byte swap the result
    *result = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to convert raw lux value to lux
float convert_lux(unsigned short raw_lux) {
    return (float)raw_lux / 65536.0 * 100.0;
}

// Function to format the data into a string
int format_data(char *buffer, size_t buffer_size, int lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, buffer_size, "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ", %d", lux_value);
    return 0;
}

// Function to write the data to the log file
int write_to_log(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", data) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        unsigned short raw_lux;
        if (opt3001_read_result(i2c_handle, &raw_lux) == 0) {
            float lux_value = convert_lux(raw_lux);
            char data[100];
            format_data(data, sizeof(data), (int)(lux_value * 100)); // Format to two decimal places

            if (write_to_log(data) != 0) {
                fprintf(stderr, "Error writing data to log.\n");
            }

            printf("%s\n", data);
        } else {
            fprintf(stderr, "Error reading lux value.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (never reached in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

