void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int alert_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read flame sensor value
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Set alert pin state
int set_alert_pin(int state) {
    if (gpioWrite(ALERT_PIN, state) != 0) {
        fprintf(stderr, "Error writing to alert pin\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Log event to file
int log_event(int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1; // Indicate failure
    }

    fprintf(log_file, "%s, Flame Detected: %d\n", timestamp, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0; // Indicate success
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d\n", signal);
    running = 0; // Stop the main loop
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1; // Exit if log file opening fails
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            printf("Flame detected!\n");
            if (set_alert_pin(1) == 0) {
                log_event(1);
                gpioDelay(1000); // Keep alert pin HIGH for 1 second
                if (set_alert_pin(0) == 0) {
                    log_event(0);
                } else {
                    fprintf(stderr, "Error resetting alert pin\n");
                }
            } else {
                fprintf(stderr, "Error setting alert pin HIGH\n");
            }
        } else if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping this iteration\n");
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

