FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and status
typedef struct {
    float flow_rate;
    int raw_flags;
    char status[20];
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint16_t *flow, uint8_t *crc);
float convert_flow_rate(uint16_t raw_flow);
int validate_flow_rate(float flow_rate);
int log_data(FILE *fp, float flow_rate, int raw_flags, const char *status);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint16_t *flow, uint8_t *crc) {
    char buf[4];
    int result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *flow = (buf[0] << 8) | buf[1];
    *crc = buf[3];

    return 0;
}

// Function to convert raw flow rate to ml/min
float convert_flow_rate(uint16_t raw_flow) {
    return (float)raw_flow * FLOW_SCALE + FLOW_OFFSET;
}

// Function to validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < MIN_FLOW || flow_rate > MAX_FLOW) {
        return -1; // INVALID
    }
    return 0; // VALID
}

// Function to log data to file
int log_data(FILE *fp, float flow_rate, int raw_flags, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%d,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow_rate, raw_flags, status);
    fflush(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t raw_flow;
        uint8_t crc;
        int retry_count = 0;
        int read_success = 0;

        // Retry loop for reading sensor data
        while (retry_count < 3 && !read_success) {
            if (send_command(i2c_handle, MEASURE_CMD) == 0) {
                gpioDelay(2000); // Wait 2ms
                if (read_sensor_data(i2c_handle, &raw_flow, &crc) == 0) {
                    // CRC validation
                    uint8_t calculated_crc = crc8((uint8_t *)&raw_flow, 2);
                    if (calculated_crc != crc) {
                        fprintf(stderr, "CRC validation failed, retrying...\n");
                        retry_count++;
                        gpioDelay(100); // Small delay before retry
                        continue;
                    }

                    // Flow rate validation
                    float flow_rate = convert_flow_rate(raw_flow);
                    if (validate_flow_rate(flow_rate) == 0) {
                        read_success = 1;
                    } else {
                        fprintf(stderr, "Flow rate out of range, retrying...\n");
                        retry_count++;
                        gpioDelay(100); // Small delay before retry
                        continue;
                    }
                } else {
                    fprintf(stderr, "Failed to read sensor data, retrying...\n");
                    retry_count++;
                    gpioDelay(100); // Small delay before retry
                    continue;
                }
            } else {
                fprintf(stderr, "Failed to send command, retrying...\n");
                retry_count++;
                gpioDelay(100); // Small delay before retry
                continue;
            }
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
            // Attempt recovery by re-initializing I2C
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Get raw flags
        uint16_t raw_flags = 0;
        if (send_command(i2c_handle, MEASURE_CMD) == 0) {
            gpioDelay(2000); // Wait 2ms
            if (read_sensor_data(i2c_handle, &raw_flow, &crc) == 0) {
                raw_flags = raw_flow;
            } else {
                fprintf(stderr, "Failed to read raw flags\n");
            }
        } else {
            fprintf(stderr, "Failed to send command for raw flags\n");
        }

        // Log data
        char status[20] = "VALID";
        if (validate_flow_rate(flow_rate) == -1) {
            strcpy(status, "INVALID");
        }

        log_data(log_file, flow_rate, raw_flags, status);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

