    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() == -1) {
        return 1;
    }

    // Initialize SPI
    if (setup_spi() == -1) {
        return 1;
    }

    // Open the log file
    log_file = fopen("path_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    printf("Starting data logging. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Read ADC values from MCP3008 channels 0 and 1
        int left_adc = read_mcp3008(0);
        int right_adc = read_mcp3008(1);

        // Log the data
        log_data(left_value, middle_value, right_adc);

        // Delay for 50 milliseconds
        delay(50);
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close the SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    printf("Exiting.\n");
    return 0;
}

