        if (sensor_value == 0) { // Flame detected (active-low)
            log_flame_event();
            printf("Flame detected! Logged to file.\n");
        }

        gpioDelay(100); // Check every 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

