// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIO_CHIP "gpiochip4"

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variable to track LED state
static volatile int led_state = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int log_event(const char *timestamp, int led_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, cleaning up and exiting...\n", signal);
        gpio_write(LED_PIN, 0); // Turn off LED
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        exit(0);
    }
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to log an event to a file
int log_event(const char *timestamp, int led_state) {
    FILE *fp;

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, LED State: %d\n", timestamp, led_state);
    fclose(fp);
    return 0;
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    int touch_value;
    int previous_touch_value = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(TOUCH_SENSOR_PIN) < 0) return 1;
    if (gpio_export(LED_PIN) < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(TOUCH_SENSOR_PIN, "in") < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        return 1;
    }
    if (gpio_set_direction(LED_PIN, "out") < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch sensor value
        touch_value = gpio_read(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor value\n");
            break; // Exit loop on error
        }

        // Check for rising edge (touch)
        if (touch_value == 1 && previous_touch_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Toggle LED state
            led_state = !led_state;
            gpio_write(LED_PIN, led_state);

            // Log the event
            if (log_event(timestamp, led_state) < 0) {
                fprintf(stderr, "Error logging event\n");
                break; // Exit loop on error
            }

            printf("Touch detected at %s, LED state: %d\n", timestamp, led_state);
        }

        // Update previous touch value
        previous_touch_value = touch_value;

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup GPIO pins before exiting
    gpio_unexport(TOUCH_SENSOR_PIN);
    gpio_unexport(LED_PIN);

    return 0;
}

