#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define BUZZER_DURATION 2 // seconds
#define POLL_INTERVAL_MS 500
#define LOG_FILE "alert_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    return 0;
}

// Read flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(BUZZER_DURATION * 1000); // Delay in microseconds
    deactivate_buzzer();
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0);
}

// Log event to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Log system start event
    log_event("System started");

    int last_sensor_state = read_flame_sensor();

    // Main loop
    while (running) {
        int current_sensor_state = read_flame_sensor();

        if (current_sensor_state != last_sensor_state) {
            if (current_sensor_state == 0) { // Flame detected (active-low)
                log_event("FLAME DETECTED");
