        cleanup_gpio();
        return 1;
    }

    int last_state = 0; // Store the last state of the touch sensor
    int current_state;
    int last_touch_time = 0;

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_touch_sensor();

        if (current_state == 1 && last_state == 0) {
            // Rising edge detected
            last_touch_time = time(NULL);

            if (time(NULL) - last_touch_time >= (DEBOUNCE_TIME / 1000.0)) {
                toggle_led();
                log_touch_event();
                last_state = current_state;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Poll every 10ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

