#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Structure to hold sensor data
typedef struct {
    int pin;
    int initial_state;
    int current_state;
} sensor_data_t;

// Global variables
FILE *log_file = NULL;
sensor_data_t sensors[3];

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void log_event(int sensor_id, int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
void log_event(int sensor_id, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, State: %d\n", timestamp, sensor_id, state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Closing log file...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize sensors
    sensors[0].pin = SENSOR1_PIN;
    sensors[0].initial_state = -1; // Initialize to an invalid state
    sensors[0].current_state = read_sensor(SENSOR1_PIN);
    if (sensors[0].current_state == -1) {
        cleanup();
        return 1;
    }
    sensors[0].initial_state = sensors[0].current_state;

    sensors[1].pin = SENSOR2_PIN;
    sensors[1].initial_state = -1;
    sensors[1].current_state = read_sensor(SENSOR2_PIN);
    if (sensors[1].current_state == -1) {
        cleanup();
        return 1;
    }
    sensors[1].initial_state = sensors[1].current_state;

    sensors[2].pin = SENSOR3_PIN;
    sensors[2].initial_state = -1;
    sensors[2].current_state = read_sensor(SENSOR3_PIN);
    if (sensors[2].current_state == -1) {
        cleanup();
        return 1;
    }
    sensors[2].initial_state = sensors[2].current_state;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 3; i++) {
            int new_state = read_sensor(sensors[i].pin);
            if (new_state == -1) {
                // Error reading sensor, skip this iteration
                continue;
            }

            if (new_state != sensors[i].current_state) {
                // State changed, log the event
                log_event(i + 1, new_state);
                sensors[i].current_state = new_state;
            }
        }
        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

