#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define CONFIG_REG 0x02
#define HR_REG 0x24
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t part_id;
    uint8_t hw_rev;
    uint16_t config;
} sensor_config_t;

// Function prototypes
int init_sensor(sensor_config_t *config);
int read_sensor_data(int *raw_data);
int apply_moving_average(int *raw_data, int *filtered_data, int size);
int validate_bpm(int bpm);
int log_bpm(int bpm);
void signal_handler(int signal);
int check_sensor_id(sensor_config_t *config);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1182-A-GM sensor
int init_sensor(sensor_config_t *config) {
    // Check sensor ID
    if (check_sensor_id(config)) {
        fprintf(stderr, "Error: Invalid sensor ID. Aborting initialization.\n");
        return -1;
    }

    // Configure the sensor (example configuration)
    config->config = 0x03; // Example configuration value
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, config->config) != 0) {
        fprintf(stderr, "Error: Failed to write configuration to sensor.\n");
        return -1;
    }

    return 0;
}

// Read raw data from the Si1182-A-GM sensor
int read_sensor_data(int *raw_data) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, HR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read sensor data. I2C error code: %d\n", result);
        return -1;
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0;
}

// Apply a moving average filter to the raw data
int apply_moving_average(int *raw_data, int *filtered_data, int size) {
    if (size <= 0) return -1; // Invalid size

    filtered_data[0] = raw_data[0];
    for (int i = 1; i < size; i++) {
        filtered_data[i] = (filtered_data[i - 1] + raw_data[i]) / size;
    }
    return 0;
}

// Validate the BPM value
int validate_bpm(int bpm) {
    return (bpm >= 30 && bpm <= 220);
}

// Log the BPM value to a file
int log_bpm(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Check the sensor ID
