    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PART_ID_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read PART_ID. I2C error code: %d\n", result);
        return -1;
    }

    config->part_id = buf[0] << 8 | buf[1];

    result = i2cReadI2CBlockData(i2c_handle, HW_REV_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read HW_REV. I2C error code: %d\n", result);
        return -1;
    }

    config->hw_rev = buf[0] << 8 | buf[1];

    return 0;
}

