#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"

static volatile int terminate = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s: %s\n", timestamp, message);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

// Function to detect a falling edge on the GPIO pin
int detect_falling_edge(int gpio_pin) {
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, level);
        return -1;
    }
    return level;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with internal pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int edge_level = detect_falling_edge(GPIO_PIN);
        if (edge_level < 0) {
            fprintf(stderr, "Error detecting falling edge, exiting...\n");
            break;
        }

        if (edge_level == 0) { // Flame detected (active-low)
            printf("FLAME DETECTED\n");
            if (log_message("FLAME DETECTED") != 0) {
                fprintf(stderr, "Error logging message\n");
            }
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    return 0;
}

