#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for sensor inputs and output
#define SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define OUTPUT_PINS {17, 18, 19, 20, 21, 22, 23, 24}

// Define the number of channels and bits
#define NUM_CHANNELS 8
#define NUM_BITS 8

// Define the delay between sensor readings (in milliseconds)
#define SENSOR_DELAY_MS 10

// Define the stabilization delay (in milliseconds)
#define STABILIZATION_DELAY_MS 200

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Structure to hold sensor and output pin data
typedef struct {
    int sensor_pins[NUM_CHANNELS];
    int output_pins[NUM_CHANNELS];
    int current_counter[NUM_CHANNELS];
    int last_state[NUM_CHANNELS];
    int last_touch[NUM_CHANNELS];
} SensorOutputData;

// Global variables
SensorOutputData data;
FILE *log_file;
int running = 1;

// Function prototypes
void initialize_gpio();
void cleanup_gpio();
void set_output_pin(int pin, int value);
void update_output_pins();
void log_event(int channel, int counter);
void handle_error(const char *message);
void signal_handler(int signal);
int read_sensor(int pin);
void reset_output_pins();

// Function to initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        handle_error("pigpio initialisation failed");
        exit(1);
    }

    // Set sensor pins as inputs with pull-down resistors
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(SENSOR_PINS[i], PI_INPUT);
        gpioSetPullUpDown(SENSOR_PINS[i], PI_PUD_DOWN);
    }

    // Set output pins as outputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(OUTPUT_PINS[i], PI_OUTPUT);
        set_output_pin(OUTPUT_PINS[i], 0); // Initialize all output pins to 0
    }

    // Initialize sensor and output data
    for (int i = 0; i < NUM_CHANNELS; i++) {
        data.sensor_pins[i] = SENSOR_PINS[i];
        data.output_pins[i] = OUTPUT_PINS[i];
        data.current_counter[i] = 0;
        data.last_state[i] = 0;
        data.last_touch[i] = 0;
    }
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Reset all output pins to 0
    for (int i = 0; i < NUM_CHANNELS; i++) {
        set_output_pin(OUTPUT_PINS[i], 0);
    }

    gpioTerminate();
}

// Function to set the value of an output pin
void set_output_pin(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        handle_error("Failed to write to output pin");
    }
}

// Function to update all output pins based on the current counter values
void update_output_pins() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        set_output_pin(data.output_pins[i], data.current_counter[i]);
    }
}

// Function to log an event to the log file
void log_event(int channel, int counter) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", buf, channel + 1, counter);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d)\n", message, errno);
    // Attempt to close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }
    cleanup_gpio();
    exit(1);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    reset_output_pins();
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read the state of a sensor pin
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor pin %d: %s (errno: %d)\n", pin, strerror(errno), errno);
        return -1; // Indicate an error
    }
    return value;
}

// Function to reset all output pins to 0
void reset_output_pins() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        set_output_pin(data.output_pins[i], 0);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: Could not open log file %s\n", LOG_FILE);
    }

    // Main loop
    while (running) {
        // Stabilization delay
        gpioDelay(STABILIZATION_DELAY_MS * 1000); // Convert ms to microseconds

        // Read sensor values
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_sensor(data.sensor_pins[i]);
            if (sensor_value < 0) {
                // Skip this channel if there's an error reading the sensor
                continue;
            }

            // Check for rising edge (touch)
            if (sensor_value == 1 && data.last_touch[i] == 0) {
                // Increment the counter
                data.current_counter[i] = (data.current_counter[i] + 1) % 256;

                // Update the last touch state
                data.last_touch[i] = 1;

                // Log the event
                log_event(i, data.current_counter[i]);

                // Update output pins
                update_output_pins();
            } else if (sensor_value == 0 && data.last_touch[i] == 1) {
                // Reset the last touch state
                data.last_touch[i] = 0;
            }

            // Update the last state
            data.last_state[i] = sensor_value;
        }

        // Delay before next reading
        gpioDelay(SENSOR_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup (should not reach here if signal handler is working)
    reset_output_pins();
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

