        int sensor4_value = read_sensor(SENSOR4_PIN);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping log entry\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
