// Define GPIO pins for the tilt sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables to store the last state of each sensor
int sensor1_last_state = 1; // Initialize to inactive (HIGH)
int sensor2_last_state = 1; // Initialize to inactive (HIGH)

// File pointer for the log file
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
void log_event(int sensor_number);
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log a tilt event
void log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Release GPIO resources
    gpioSetMode(SENSOR1_GPIO, PI_INPUT); // Set back to input
    gpioSetMode(SENSOR2_GPIO, PI_INPUT); // Set back to input
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP); // Set pull-up back
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP); // Set pull-up back

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the sensors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up resistors for the sensors
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the state of sensor 1
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        if (sensor1_state < 0) {
            fprintf(stderr, "Error reading sensor 1, exiting...\n");
            break; // Exit the loop on error
        }

        // Read the state of sensor 2
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        if (sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor 2, exiting...\n");
            break; // Exit the loop on error
        }

