                log_event(2);
            }
            sensor2_last_state = sensor2_state;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        }

        gpioDelay(100 * 1000); // Poll every 100ms
    }

    // Cleanup (should not reach here if signal handler is working)
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

