#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_TIME_MS 100
#define SAMPLE_PERIOD_US 125

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_microphone();
void handle_peak();
void turn_on_led();
void turn_off_led();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state; // 0 = off, 1 = on
} program_state_t;

program_state_t state = {0}; // Initialize LED to off

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    printf("Microphone peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read microphone data
        int peak_detected = read_microphone();

        // If a peak is detected, handle it
        if (peak_detected) {
            handle_peak();
        }

        // Delay to achieve approximately 8kHz sampling rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    turn_off_led();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set microphone pin as input
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read microphone data (digital read)
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Handle a peak event
void handle_peak() {
    // Get current time in milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    // Turn on the LED
    turn_on_led();

    // Wait for 100ms
    gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

    // Turn off the LED
    turn_off_led();
}

// Turn on the LED
void turn_on_led() {
    if (state.led_state == 0) {
        gpioWrite(LED_PIN, 1); // Set LED pin HIGH
        state.led_state = 1;
        printf("LED ON\n");
    }
}

// Turn off the LED
void turn_off_led() {
    if (state.led_state == 1) {
        gpioWrite(LED_PIN, 0); // Set LED pin LOW
        state.led_state = 0;
        printf("LED OFF\n");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Cleaning up and exiting.\n");
        program_running = 0;
    }
}

