#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler_int(int signal) {
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (Termination signal)
void signal_handler_term(int signal) {
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int sensor_state = gpioRead(gpio_pin);
    if (sensor_state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, sensor_state);
        return -1; // Indicate an error
    }
    return sensor_state;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler_int);
    signal(SIGTERM, signal_handler_term);

    // Main loop to read and log sensor data
    while (program_running) {
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int center_state = read_sensor(CENTER_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state == -1 || center_state == -1 || right_state == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            // Attempt to re-initialize the pigpio library
            gpioTerminate();
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialisation failed\n");
                program_running = 0; // Exit if re-initialization fails
            } else {
                // Re-configure GPIO pins
                gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
                gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
                gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
                gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);
                gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
                gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);
            }
            sleep(1); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Log the sensor states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate the pigpio library before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

