#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read ALS data from Si1175
int read_als_data()
{
    int als_data0, als_data1, als_data;

    // Read LSB register
    als_data0 = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA0);
    if (als_data0 < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %d\n", als_data0);
        return -1; // Indicate error
    }

    // Read MSB register
    als_data1 = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA1);
    if (als_data1 < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1: %d\n", als_data1);
        return -1; // Indicate error
    }

    // Combine LSB and MSB to form 16-bit raw value
    als_data = (als_data1 << 8) | als_data0;

    return als_data;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int als_data = read_als_data();

        if (als_data >= 0) {
            printf("Raw ALS Data: %d\n", als_data);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

