#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 sensors
#define TP1_PIN 5
#define TP2_PIN 6
#define TP3_PIN 13
#define TP4_PIN 19
#define TP5_PIN 26
#define TP6_PIN 12
#define TP7_PIN 16
#define TP8_PIN 20

// Structure to hold sensor data
typedef struct {
    int pin;
    int value;
} sensor_data_t;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read the value from a specific GPIO pin
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to format the sensor data into a string
char* format_sensor_data(sensor_data_t sensors[], int num_sensors) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    static char timestamp[20]; // Static to preserve value between calls
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    char *result = (char*)malloc(100 * sizeof(char)); // Allocate memory for the string
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_sensors; i++) {
        result = snprintf(result, 100, "%s CH%d=%d ", timestamp, i + 1, sensors[i].value);
    }
    return result;
}

// Function to log the sensor data to the console
void log_sensor_data(const char *data) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", data);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

// Function to cleanup resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TP1_PIN, PI_INPUT);
    gpioSetMode(TP2_PIN, PI_INPUT);
    gpioSetMode(TP3_PIN, PI_INPUT);
    gpioSetMode(TP4_PIN, PI_INPUT);
    gpioSetMode(TP5_PIN, PI_INPUT);
    gpioSetMode(TP6_PIN, PI_INPUT);
    gpioSetMode(TP7_PIN, PI_INPUT);
    gpioSetMode(TP8_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Define the array of sensor data
    sensor_data_t sensors[] = {
        {TP1_PIN, 0},
        {TP2_PIN, 0},
        {TP3_PIN, 0},
        {TP4_PIN, 0},
