#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17  // BCM GPIO 17
#define GREEN_PIN 18  // BCM GPIO 18
#define BLUE_PIN  27  // BCM GPIO 27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255      // 8-bit range

// Define number of steps for linear interpolation
#define NUM_STEPS 50

// Define log file path
#define LOG_FILE "/var/log/rgb_led.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold RGB color data
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function prototypes
int initialize_gpio();
RGBColor generate_random_hue();
void set_led_color(RGBColor color);
void fade_to_color(RGBColor start_color, RGBColor end_color, int num_steps);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    return 0;
}

// Function to generate a random hue value
RGBColor generate_random_hue() {
    RGBColor hue;
    hue.red = rand() % 256;
    hue.green = rand() % 256;
    hue.blue = rand() % 256;
    return hue;
}

// Function to set the RGB LED color using PWM
void set_led_color(RGBColor color) {
    // Common anode, so invert the color values
    int red_value = 255 - color.red;
    int green_value = 255 - color.green;
    int blue_value = 255 - color.blue;

    // Clamp values to 0-255 range
    if (red_value < 0) red_value = 0;
    if (green_value < 0) green_value = 0;
    if (blue_value < 0) blue_value = 0;
    if (red_value > 255) red_value = 255;
    if (green_value > 255) green_value = 255;
    if (blue_value > 255) blue_value = 255;

    gpioPWM(RED_PIN, red_value);
    gpioPWM(GREEN_PIN, green_value);
    gpioPWM(BLUE_PIN, blue_value);
}

// Function to perform linear interpolation between two RGB colors
void fade_to_color(RGBColor start_color, RGBColor end_color, int num_steps) {
    float red_step = (float)(end_color.red - start_color.red) / num_steps;
    float green_step = (float)(end_color.green - start_color.green) / num_steps;
    float blue_step = (float)(end_color.blue - start_color.blue) / num_steps;

    RGBColor current_color = start_color;
    for (int i = 0; i < num_steps; i++) {
        current_color.red += red_step;
        current_color.green += green_step;
        current_color.blue += blue_step;

        // Clamp values to 0-255 range
        if (current_color.red < 0) current_color.red = 0;
        if (current_color.green < 0) current_color.green = 0;
        if (current_color.blue < 0) current_color.blue = 0;
        if (current_color.red > 255) current_color.red = 255;
        if (current_color.green > 255) current_color.green = 255;
        if (current_color.blue > 255) current_color.blue = 255;

        set_led_color(current_color);
        gpioDelay(10000 / num_steps); // Delay for each step (microseconds)
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    // Turn off the LED
    set_led_color(RGBColor{0, 0, 0});

    // Release GPIO resources
    gpioTerminate();

    // Close syslog
    closelog();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    syslog(LOG_INFO, "Shutdown complete.");
}

int main() {
    // Open syslog
    openlog("rgb_led", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "RGB LED program started.");

    // Main loop
    while (running) {
        // Generate random hue
        RGBColor hue = generate_random_hue();
        syslog(LOG_INFO, "Random hue: R=%d, G=%d, B=%d", hue.red, hue.green, hue.blue);

        // Generate a new random hue
        RGBColor new_hue = generate_random_hue();
        syslog(LOG_INFO, "New random hue: R=%d, G=%d, B=%d", new_hue.red, new_hue.green, new_hue.blue);

        // Fade to the new hue
        fade_to_color(hue, new_hue, NUM_STEPS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

