#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// Configuration
#define INTEGRATION_TIME         154 // ms
#define RED_THRESHOLD            200
#define LED_GPIO                 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init();
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void control_led(uint16_t red);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// TCS34725 Initialization
int tcs34725_init() {
    // Enable power and RGBC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable sensor. Error code: %d\n", errno);
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, (INTEGRATION_TIME & 0xFF)) < 0) {
        fprintf(stderr, "Error: Could not set integration time. Error code: %d\n", errno);
        return -1;
    }

    return 0;
}

// TCS34725 Data Reading
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buffer[8];

    // Read all color data in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) != 8) {
        fprintf(stderr, "Error: Could not read data from sensor. Error code: %d\n", errno);
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// LED Control
void control_led(uint16_t red) {
    if (red > RED_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // HIGH
    } else {
        gpioWrite(LED_GPIO, 0); // LOW
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0); // I2C bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue, clear;

    // Main loop
    while (!terminate) {
        if (tcs34725_read_data(&red, &green, &blue, &clear) == 0) {
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", red, green, blue, clear);
            control_led(red);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Attempting re-initialization...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before re-initializing
            i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus. Error code: %d\n", errno);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (tcs34725_init() < 0) {
                    fprintf(stderr, "Error: TCS34725 re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(200); // 200ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

