#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x23
#define GPIO_PIN 18
#define NUM_LEDS 10
#define PWM_RANGE 255
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
float map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buf[2];
    int result;

    // Send measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180);

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Map lux value to brightness level (logarithmic)
float map_lux_to_brightness(float lux) {
    // Ensure lux is not negative
    if (lux < 0) {
        lux = 0;
    }

    // Apply logarithmic mapping
    float brightness = log10(lux + 1) / log10(1000) * PWM_RANGE; // Assuming max lux is 1000
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    return brightness;
}

// Set LED brightness using PWM
void set_led_brightness(int brightness) {
    gpioPWM(GPIO_PIN, brightness);
}

int main() {
    float lux;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);
    gpioSetPWMfrequency(GPIO_PIN, 800000); // 800kHz

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting ambient light sensor and LED strip...\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_bh1750(&lux) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read error, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS);
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read from BH1750 after %d retries, skipping...\n", RETRY_COUNT);
            gpioDelay(100); // Small delay before next attempt
            continue;
        }

        // Map lux to brightness
        int brightness = (int)map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        gpioDelay(50); // Delay between readings
    }

    // Cleanup
    set_led_brightness(0); // Turn off LEDs
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

