#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SPI_BUS "/dev/spidev0.0"
#define NUM_LEDS 10
#define NUM_BYTES_PER_LED 4
#define ZERO_START_FRAME_SIZE 4
#define END_FRAME_SIZE 4
#define LED_FRAME_SIZE (NUM_BYTES_PER_LED * 4)
#define NUM_FRAMES (ZERO_START_FRAME_SIZE + NUM_LEDS * LED_FRAME_SIZE + END_FRAME_FRAME_SIZE)
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t addr, uint8_t data);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
void construct_apa102_frame(uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red, uint8_t *frame, int frame_size);
void send_apa102_frame(int fd, uint8_t *frame, int frame_size);
void signal_handler(int sig);
int initialize_i2c(int bus, int addr);
int initialize_spi(int bus, int speed);
int initialize_apa102(int num_leds);
void cleanup(int i2c_fd, int spi_fd);

// I2C read function
int i2c_read_bytes(int fd, uint8_t addr, uint8_t *data, int len) {
    if (fd < 0 || addr < 0 || data == NULL || len < 0) {
        fprintf(stderr, "Error: Invalid arguments to i2c_read_bytes\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Could not acquire bus access and/or talk to slave. %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error: I2C read failed. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t addr, uint8_t data) {
    if (fd < 0 || addr < 0 || data < 0) {
        fprintf(stderr, "Error: Invalid arguments to i2c_write_byte\n");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = addr;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    if (fd < 0 || tx_buf == NULL || rx_buf == NULL || len < 0) {
        fprintf(stderr, "Error: Invalid arguments to spi_transfer\n");
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error: SPI transfer failed. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// APA102 frame construction function
void construct_apa102_frame(uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red, uint8_t *frame, int frame_size) {
    if (frame == NULL || frame_size < 4) {
        fprintf(stderr, "Error: Invalid arguments to construct_apa102_frame\n");
        return;
    }

    frame[0] = 0xE0 | (brightness & 0x1F); // Global brightness
    frame[1] = blue;
    frame[2] = green;
    frame[3] = red;
}

// APA102 frame sending function
void send_apa102_frame(int fd, uint8_t *frame, int frame_size) {
    if (fd < 0 || frame == NULL || frame_size < 4) {
        fprintf(stderr, "Error: Invalid arguments to send_apa102_frame\n");
        return;
    }

    spi_transfer(fd, frame, NULL, frame_size);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, cleaning up...\n", sig);
}

// I2C initialization function
int initialize_i2c(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s. %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Could not acquire bus access and/or talk to slave. %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int initialize_spi(int bus, int speed) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open SPI bus %s. %s\n", bus, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Could not set SPI mode. %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Could not set SPI bits per word. %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed_hz = SPI_MAX_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        fprintf(stderr, "Error: Could not set SPI max speed Hz. %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// APA102 initialization function
int initialize_apa102(int num_leds) {
    uint8_t *frame = malloc(NUM_LEDS * LED_FRAME_SIZE);
    if (frame == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for APA102 frame\n");
        return -1;
    }

    // Initialize all LEDs to off (0 brightness, 0 blue, 0 green, 0 red)
    for (int i = 0; i < num_leds; i++) {
        construct_apa102_frame(0, 0, 0, 0, &frame[i * LED_FRAME_SIZE], LED_FRAME_SIZE);
    }

    // Add zero start frame
    construct_apa102_frame(0, 0, 0, 0, &frame[0], ZERO_START_FRAME_SIZE);
    for (int i = 0; i < num_leds; i++) {
        send_apa102_frame(spi_fd, &frame[(i * LED_FRAME_SIZE) + ZERO_START_FRAME_SIZE], LED_FRAME_SIZE);
    }
    construct_apa102_frame(0, 0, 0, 0, &frame[(num_leds * LED_FRAME_SIZE) + ZERO_START_FRAME_SIZE], END_FRAME_SIZE);
    send_apa102_frame(spi_fd, &frame[(num_leds * LED_FRAME_SIZE) + ZERO_START_FRAME_SIZE + END_FRAME_SIZE], END_FRAME_SIZE);

    free(frame);
    return 0;
}

// Cleanup function
void cleanup(int i2c_fd, int spi_fd) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = initialize_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = initialize_spi(SPI_BUS, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        cleanup(i2c_fd, -1);
        return 1;
    }

    // Initialize APA102
    if (initialize_apa102(NUM_LEDS) < 0) {
        cleanup(i2c_fd, spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read light level from BH1750
        uint8_t data[2];
        if (i2c_read_bytes(i2c_fd, BH1750_ADDR, data, 2) < 0) {
            fprintf(stderr, "Error reading light level, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to lux (example, adjust as needed)
        float lux = (float)((data[0] << 8) | data[1]) / 1.2; // Example conversion

        // Scale lux to brightness (0-255)
        uint8_t brightness = (uint8_t)(lux * 2.55); // Example scaling

        // Construct APA102 frame
        uint8_t *frame = malloc(NUM_LEDS * LED_FRAME_SIZE);
        if (frame == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for APA102 frame\n");
            program_running = 0; // Stop the loop
            cleanup(i2c_fd, spi_fd);
            return 1;
        }

        for (int i = 0; i < NUM_LEDS; i++) {
            construct_apa102_frame(brightness, 0, 0, 0, &frame[(i * LED_FRAME_SIZE)], LED_FRAME_SIZE);
        }

        // Add zero start frame
        construct_apa102_frame(0, 0, 0, 0, &frame[0], ZERO_START_FRAME_SIZE);
        for (int i = 0; i < NUM_LEDS; i++) {
            send_apa102_frame(spi_fd, &frame[(i * LED_FRAME_SIZE) + ZERO_START_FRAME_SIZE], LED_FRAME_SIZE);
        }
        construct_apa102_frame(0, 0, 0, 0, &frame[(NUM_LEDS * LED_FRAME_SIZE) + ZERO_START_FRAME_SIZE], END_FRAME_SIZE);
        send_apa102_frame(spi_fd, &frame[(NUM_LEDS * LED_FRAME_SIZE) + ZERO_START_FRAME_SIZE + END_FRAME_SIZE], END_FRAME_SIZE);

        free(frame);

        // Wait before next reading
        usleep(50000); // 50ms
    }

    // Cleanup
    cleanup(i2c_fd, spi_fd);

    return 0;
}

