#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x23
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 1
#define NUM_SENSORS 3
#define NUM_READINGS 5
#define AVG_READINGS 3
#define TARGET_BRIGHTNESS 255
#define FADING_TIME 500 // milliseconds
#define DELAY_TIME 100  // milliseconds

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int i2c_handle_3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int init_spi();
int read_bh1750(int i2c_handle);
float average_light_sensors();
int set_apa102_brightness(int brightness);
void fade_to_target(int brightness);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", address, handle);
        return -1;
    }
    return handle;
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Function to average light sensor readings
float average_light_sensors() {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        int sensor_index = (i == 0 || i == 1) ? i : 2; // Cycle through sensors 1, 2, 3
        int reading = read_bh1750((i == 0 || i == 1) ? i2c_handle_1 : (i == 2) ? i2c_handle_3 : -1); // Read from appropriate handle

        if (reading >= 0) {
            sum += reading;
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Function to set APA102 brightness
int set_apa102_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    // Send start frame (4 bytes of 0x00)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, start_frame, 4);

    // Send LED data (4 bytes per LED: 0xE0 + brightness + 0x00 + 0x00)
    char led_data[NUM_LEDS * 4];
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i * 4] = 0xE0 | (brightness & 0xFF); // Global brightness
        led_data[i * 4 + 1] = 0x00;
        led_data[i * 4 + 2] = 0x00;
        led_data[i * 4 + 3] = 0x00;
    }
    spiWrite(spi_handle, led_data, NUM_LEDS * 4);

    // Send end frame (4 bytes of 0xFF)
    char end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    spiWrite(spi_handle, end_frame, 4);

    return 0;
}

// Function to fade to target brightness
void fade_to_target(int brightness) {
    int delta = (brightness - 128) / FADING_TIME;
    int current_brightness = 128;

    for (int i = 0; i < FADING_TIME; i++) {
        set_apa102_brightness(current_brightness);
        gpioDelay(1000); // 1 ms delay
        current_brightness += delta;
        if (current_brightness > 255) current_brightness = 255;
        if (current_brightness < 0) current_brightness = 0;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle_1 = init_i2c(BH1750_ADDR_1);
    i2c_handle_2 = init_i2c(BH1750_ADDR_2);
    i2c_handle_3 = init_i2c(BH1750_ADDR_3);

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float average_light = average_light_sensors();

        if (average_light > 0) {
            int brightness = (int)(average_light * 0.5); // Scale to 0-255
            set_apa102_brightness(brightness);
        } else {
            set_apa102_brightness(0); // Turn off LED if no valid readings
        }

        gpioDelay(DELAY_TIME * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

