#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// GPIO pin for WS2812B data line
#define WS2812B_GPIO 18

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_als_data(uint16_t *als_data);
float calculate_lux(uint16_t als_data);
int map_lux_to_brightness(float lux);
void drive_led(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Default configuration
    int result = i2cWriteWordData(i2c_handle, VEML7700_CONFIG, config_value);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_als_data(uint16_t *als_data) {
    int result = i2cReadWordData(i2c_handle, VEML7700_ALS_DATA);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }
    *als_data = (uint16_t)result;
    return 0;
}

// Calculate lux value from ALS data (simplified formula)
float calculate_lux(uint16_t als_data) {
    // This is a placeholder.  A real implementation would use
    // the sensor's calibration data and the integration time.
    // The formula is simplified and may not be accurate.
    return (float)als_data * 0.0576; // Example conversion
}

// Map lux value to brightness level (0-255)
int map_lux_to_brightness(float lux) {
    // Simple linear mapping
    return (int)(lux / 100.0); // Adjust the divisor as needed
}

// Drive WS2812B LED strip
void drive_led(int brightness) {
    // Simple on/off control (replace with bit-banging for precise timing)
    gpioWrite(WS2812B_GPIO, brightness > 127 ? 1 : 0); // Simplified control
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als_data;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&als_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(als_data);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Drive LED strip
            drive_led(brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
        }

        // Pause for 200ms
        gpioDelay(200000); // 200ms = 200000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(WS2812B_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

