#define BUZZER_PIN 17
#define LED_PIN 18

// Define error codes
#define ERROR_FLAME_DETECTED 1
#define ERROR_FLAME_CLEARED 2
#define ERROR_GPIO_INIT 3
#define ERROR_FILE_OPEN 4
#define ERROR_FILE_WRITE 5
#define ERROR_FILE_READ 6

// Define buzzer and LED patterns
#define BUZZER_PATTERN_1 200 200 600 200
#define BUZZER_PATTERN_2 200 200 600 200
#define LED_BLINK 500 500

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_buzzer(int pattern);
void control_led(int blink_time);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return ERROR_GPIO_INIT;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Success
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to control the buzzer
void control_buzzer(int pattern) {
    for (int i = 0; i < 3; i++) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
        gpioDelay(pattern[0]);
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
        gpioDelay(pattern[1]);
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
        gpioDelay(pattern[2]);
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
        gpioDelay(pattern[3]);
    }
}

// Function to control the LED
void control_led(int blink_time) {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(blink_time);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(blink_time);
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        printf("Error: Log file not opened.\n");
    }
}

