void startup_self_test() {
    log_event("Starting startup self-test...");

    // Blink LED 500ms on/500ms off twice
    for (int i = 0; i < 2; i++) {
        control_led(LED_BLINK);
    }

    // Read flame sensor five times
    for (int i = 0; i < 5; i++) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
