        } else {
            gpioWrite(LED_PIN, 0); // Turn LED off
            gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
        }

        gpioDelay(50); // 50ms delay
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    log_event("Cleaning up...");
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

