    int result = initialize_gpio();
    if (result != 0) {
        log_event("GPIO initialization failed. Exiting.");
        fclose(log_file);
        return 1;
    }

    // Perform startup self-test
    startup_self_test();

    // Start the main loop
    main_loop();

    // Cleanup and exit
    cleanup();
    return 0;
}

