#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MAX_LUX 1000.0
#define MIN_LUX 0.0
#define MAX_FREQUENCY 5.0
#define MIN_FREQUENCY 0.5
#define SLEEP_SECONDS 1

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_read(int fd, uint8_t addr, uint16_t *data);
float bh1750_read_lux(int fd);
void gpio_set_frequency(int pin, float frequency);
void gpio_blink(int pin, float frequency);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
void signal_handler(int signal);

// I2C read function
int i2c_read(int fd, uint8_t addr, uint16_t *data) {
    uint8_t buf[2];
    if (write(fd, &addr, 1) != 1) {
        perror("Failed to write address to I2C");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data from I2C");
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// BH1750 read lux function
float bh1750_read_lux(int fd) {
    uint16_t raw_value;
    if (i2c_read(fd, BH1750_ADDR, &raw_value) != 0) {
        fprintf(stderr, "Error reading BH1750 sensor.\n");
        return -1.0;
    }

    // BH1750 returns big-endian data, so swap bytes
    uint16_t swapped_value = (raw_value >> 8) | (raw_value << 8);

    return (float)swapped_value / 1.2; // Convert to lux
}

// GPIO set frequency function
void gpio_set_frequency(int pin, float frequency) {
    // This is a placeholder.  A real implementation would use
    // system calls to set the GPIO pin frequency.
    // For example, using the 'setsysfsfrequency' command.
    // This is just a dummy implementation for demonstration.
    printf("Setting GPIO %d frequency to %.2f Hz\n", pin, frequency);
}

// GPIO blink function
void gpio_blink(int pin, float frequency) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = 500000000 / frequency; // 0.5 us
    off_time.tv_sec = 0;
    off_time.tv_nsec = 500000000 / frequency; // 0.5 us

    while (program_running) {
        nanosleep(&on_time, NULL);
        nanosleep(&off_time, NULL);
    }
}

// Circular buffer initialization function
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Circular buffer add function
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Circular buffer average function
float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize circular buffer
    CircularBuffer lux_buffer;
    circular_buffer_init(&lux_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure GPIO pin as output
    int gpio_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO value file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        float lux = bh1750_read_lux(i2c_fd);
        if (lux >= 0) {
            circular_buffer_add(&lux_buffer, lux);
            float average_lux = circular_buffer_average(&lux_buffer);
            printf("Lux: %.2f, Average Lux: %.2f\n", lux, average_lux);

            // Calculate frequency based on lux value
            float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (1.0 - (average_lux / MAX_LUX));
            if (frequency < MIN_FREQUENCY) {
                frequency = MIN_FREQUENCY;
            }

            gpio_set_frequency(GPIO_PIN, frequency);
            gpio_blink(GPIO_PIN, frequency);
        } else {
            fprintf(stderr, "Failed to read lux value. Skipping this sample.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    close(i2c_fd);
    close(gpio_fd);
    gpio_blink(GPIO_PIN, 0.0); // Turn off LED

    return 0;
}

