#define CLOCK_PIN 18 // GPIO18 (BCM)
#define LATCH_PIN 27 // GPIO27 (BCM)

// Define segment patterns for digits 0-9
const uint8_t segments[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi.\n");
        return -1;
    }

    pinMode(DATA_PIN, OUTPUT);
    pinMode(CLOCK_PIN, OUTPUT);
    pinMode(LATCH_PIN, OUTPUT);

    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(uint8_t data) {
    for (int i = 0; i < 8; i++) {
        digitalWrite(CLOCK_PIN, HIGH);
        digitalWrite(DATA_PIN, (data & 0x80) ? 1 : 0);
        data <<= 1;
        digitalWrite(CLOCK_PIN, LOW);
    }
}

// Function to latch the data to the 74HC595
void latch_data() {
    digitalWrite(LATCH_PIN, HIGH);
    digitalWrite(LATCH_PIN, LOW);
}

// Function to display a digit on the 7-segment display
void display_digit(uint8_t digit) {
    shift_out(segments[digit]);
    latch_data();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Display digit 5
        display_digit(5);

        // Blink for 500ms
        delay(500);

        // Display digit 5 again
        display_digit(5);

        // Blink for 500ms
        delay(500);
    }

    // Clean up GPIO pins before exiting
    digitalWrite(DATA_PIN, LOW);
    digitalWrite(CLOCK_PIN, LOW);
    digitalWrite(LATCH_PIN, LOW);

    printf("Program finished.\n");
    return 0;
}

