#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Request LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return -1;
    }

    // Request button pin as input with pull-up resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on button pin\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led(int pin, int period_ms) {
    gpioWrite(pin, 1); // Turn LED on
    gpioDelay(period_ms * 1000); // Delay for period_ms milliseconds
    gpioWrite(pin, 0); // Turn LED off
    gpioDelay(period_ms * 1000); // Delay for period_ms milliseconds
}

// Function to handle button press
void handle_button_press(int pin) {
    printf("Button pressed!\n");
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Blinking LED and waiting for button press...\n");

    // Main loop
    while (program_running) {
        // Blink LED with a 2-second period
        blink_led(LED_PIN, 2);

        // Wait for a falling edge on the button pin
        if (gpioSetAlertFuncEx(BUTTON_PIN, NULL, NULL) != 0) {
            fprintf(stderr, "Failed to set alert function for button pin\n");
            cleanup_gpio();
            return 1;
        }

        // Handle button press
        handle_button_press(BUTTON_PIN);

        // Stop blinking and turn off LED
        gpioSetAlertFuncEx(BUTTON_PIN, NULL, NULL); // Disable alert function
        gpioWrite(LED_PIN, 0);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

