// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define constants
#define BLINK_DELAY_MS 500

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set button pin pull-down\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(BLINK_DELAY_MS * 1000); // Delay for 500ms
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(BLINK_DELAY_MS * 1000); // Delay for 500ms
}

// Function to handle button press
void handle_button_press() {
    blink_led();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button state
        int button_state = gpioRead(BUTTON_PIN);

        // Check if button is pressed (low due to pull-down)
        if (button_state == 0) {
            handle_button_press();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100 * 1000); // 100ms
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    printf("Program exited.\n");
    return 0;
}

