#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Function to set the RGB LED color using software PWM
void set_led_color(int red, int green, int blue) {
    // Clamp intensity values to 0-100
    if (red < 0) red = 0;
    if (red > 100) red = 100;
    if (green < 0) green = 0;
    if (green > 100) green = 100;
    if (blue < 0) blue = 0;
    if (blue > 100) blue = 100;

    // Calculate duty cycle (0-1000000 for 1ms period)
    int red_duty = (int)((red / 100.0) * 1000000.0);
    int green_duty = (int)((green / 100.0) * 1000000.0);
    int blue_duty = (int)((blue / 100.0) * 1000000.0);

    // Set PWM duty cycles for each color
    gpioPWM(RED_PIN, red_duty);
    gpioPWM(GREEN_PIN, green_duty);
    gpioPWM(BLUE_PIN, blue_duty);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator with current time
    srand(time(NULL));

    // Set PWM frequency to 100 Hz (10 ms period)
    gpioSetPWMfrequency(RED_PIN, 100);
    gpioSetPWMfrequency(GREEN_PIN, 100);
    gpioSetPWMfrequency(BLUE_PIN, 100);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate random intensity values
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        // Set the LED color
        set_led_color(red, green, blue);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and exit (should not reach here if signal handler works)
    gpioTerminate();
    return 0;
}

