    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C for address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    // Accelerometer initialization
    if (wiringPiI2CWriteReg8(fd, CTRL_REG1_A, 0x27) == -1) { // Enable all axes, 50Hz ODR
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, CTRL_REG4_A, 0x00) == -1) { // +/- 2G range
        fprintf(stderr, "Error writing to CTRL_REG4_A: %s\n", strerror(errno));
        return -1;
    }

    // Magnetometer initialization
    if (wiringPiI2CWriteReg8(fd, CTRL_REG1_M, 0x14) == -1) { // Enable all axes, 50Hz ODR
        fprintf(stderr, "Error writing to CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, CTRL_REG2_M, 0x20) == -1) { // Continuous conversion mode
        fprintf(stderr, "Error writing to CTRL_REG2_M: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, CTRL_REG3_M, 0x00) == -1) { // High resolution
        fprintf(stderr, "Error writing to CTRL_REG3_M: %s\n", strerror(errno));
        return -1;
    }

    return fd;
