    x_l = wiringPiI2CReadReg8(fd, OUT_X_L_A);
    x_h = wiringPiI2CReadReg8(fd, OUT_X_H_A);
    y_l = wiringPiI2CReadReg8(fd, OUT_Y_L_A);
    y_h = wiringPiI2CReadReg8(fd, OUT_Y_H_A);
    z_l = wiringPiI2CReadReg8(fd, OUT_Z_L_A);
    z_h = wiringPiI2CReadReg8(fd, OUT_Z_H_A);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
