    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Function to read magnetometer data
int read_mag_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_l, x_h, y_l, y_h, z_l, z_h;

