int read_adpd188bi_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
void process_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue, float *brightness);
int log_data(float brightness, uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
void cleanup();

