int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        fprintf(stderr, "PWM initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize ADPD188BI
    if (init_adpd188bi() != 0) {
        fprintf(stderr, "ADPD188BI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Write header row
    fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue,Brightness\n");

    // Main loop
    while (!terminate) {
        uint16_t als, red, green, blue;
        float brightness;

        // Read sensor data
        if (read_adpd188bi_data(&als, &red, &green, &blue) == 0) {
            // Process data
