#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_fxos8700cq();
int read_fxos8700cq_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    int status;

    // Set CTRL_REG1 to active mode and 200 Hz output data rate
    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01 | (0x02 << 1)); // Active mode, 200Hz ODR
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Set XYZ_DATA_CFG to +/- 2g range
    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00); // +/- 2g range
    if (status < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", status);
        return -1;
    }

    return 0;
}

// Read accelerometer data from the FXOS8700CQ
int read_fxos8700cq_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0f; // Convert to g
    float y_g = (float)y / 4096.0f;
    float z_g = (float)z / 4096.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to file
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int16_t x, y, z;
    float magnitude;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        status = read_fxos8700cq_data(&x, &y, &z);
        if (status == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 50ms
        gpioDelay(50); // pigpio's delay function
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

