    return 0;
}

// Read accelerometer data from the FXOS8700CQ
int read_fxos8700cq_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0f; // Convert to g
    float y_g = (float)y / 4096.0f;
    float z_g = (float)z / 4096.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to file
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
