#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDRESS 0x69

// Gyroscope register addresses
#define GYRO_WHO_AM_I 0x0F
#define GYRO_CTRL_REG1 0x20
#define GYRO_OUT_X_L 0x28
#define GYRO_OUT_X_H 0x29
#define GYRO_OUT_Y_L 0x2A
#define GYRO_OUT_Y_H 0x2B
#define GYRO_OUT_Z_L 0x2C
#define GYRO_OUT_Z_H 0x2D

// Calibration sample size
#define CALIBRATION_SAMPLES 100

// Alert threshold (dps)
#define ALERT_THRESHOLD 50.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the gyroscope
int init_gyro() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, GYRO_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x33) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set CTRL_REG1 to enable gyroscope and set data rate (100 Hz)
    if (i2cWriteByteData(i2c_handle, GYRO_CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate the gyroscope
int calibrate_gyro(gyro_data_t *offsets) {
    int16_t x, y, z;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;
    int i;

    printf("Calibrating gyroscope...\n");

    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return -1;
        }

        x_sum += x;
        y_sum += y;
        z_sum += z;
        gpioDelay(10000); // 10ms delay
    }

    offsets->x = x_sum / CALIBRATION_SAMPLES;
    offsets->y = y_sum / CALIBRATION_SAMPLES;
    offsets->z = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets->x, offsets->y, offsets->z);

    return 0;
}

// Function to process gyroscope data
gyro_data_t process_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, gyro_data_t offsets) {
    gyro_data_t processed_data;
    processed_data.x = (float)(raw_x - offsets.x);
    processed_data.y = (float)(raw_y - offsets.y);
    processed_data.z = (float)(raw_z - offsets.z);
    return processed_data;
}

// Function to log data to file
int log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately

    if (abs(data.x) > ALERT_THRESHOLD || abs(data.y) > ALERT_THRESHOLD || abs(data.z) > ALERT_THRESHOLD) {
        fprintf(stderr, "WARNING: High angular velocity detected!\n");
        fprintf(log_file, "%s,ALERT: High angular velocity detected!\n", timestamp);
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t offsets = {0.0, 0.0, 0.0};
    gyro_data_t processed_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&processed_data.x_raw, &processed_data.y_raw, &processed_data.z_raw) == 0) {
            processed_data = process_gyro_data(processed_data.x_raw, processed_data.y_raw, processed_data.z_raw, offsets);
            log_data(processed_data);
        } else {
            fprintf(stderr, "Error reading gyro data in main loop\n");
        }

        gpioDelay(50000); // 50ms delay (20Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

