#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

// GPIO pin for LED
#define LED_PIN 17

// Acceleration threshold for LED control
#define ACCEL_THRESHOLD 2.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init();
int read_acceleration(accelerometer_data_t *data);
int log_data(accelerometer_data_t data);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// ADXL345 initialization function
int adxl345_init() {
    // Set data format to full resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to ADXL345_REG_DATA_FORMAT\n");
        return -1;
    }

    // Set bandwidth rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error writing to ADXL345_REG_BW_RATE\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to ADXL345_REG_POWER_CTL\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from ADXL345
int read_acceleration(accelerometer_data_t *data) {
    char raw_data[6];
    int16_t x, y, z;

    // Read 6 bytes of data (X, Y, Z axes)
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (assuming +/- 2g range and full resolution)
    data->x = (float)x / 256.0;
    data->y = (float)y / 256.0;
    data->z = (float)z / 256.0;

    return 0;
}

// Function to log data to file
int log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Function to control the LED based on acceleration
void control_led(float x, float y, float z) {
    float abs_x = abs(x);
    float abs_y = abs(y);
    float abs_z = abs(z);

    if (abs_x > ACCEL_THRESHOLD || abs_y > ACCEL_THRESHOLD || abs_z > ACCEL_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    accelerometer_data_t data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Accelerometer data logging started. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        result = read_acceleration(&data);
        if (result == 0) {
            // Log data
            log_data(data);

            // Control LED
            control_led(data.x, data.y, data.z);
        } else {
            fprintf(stderr, "Error reading or logging data, retrying...\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

