#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A  0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M    0x03

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accel_data_t;

// Structure to hold magnetometer data
typedef struct {
    int16_t x, y, z;
} mag_data_t;

// Function prototypes
int init_i2c();
int init_accel();
int init_mag();
accel_data_t read_accel();
mag_data_t read_mag();
float calculate_heading(accel_data_t accel, mag_data_t mag);
void log_data(accel_data_t accel, mag_data_t mag, float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize accelerometer
int init_accel() {
    // Enable accelerometer, 50 Hz data rate
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer control register\n");
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_mag() {
    // Set magnetometer to continuous conversion mode
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer mode register\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
accel_data_t read_accel() {
    accel_data_t accel;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        accel.x = accel.y = accel.z = 0; // Return 0s on error
        return accel;
    }

    accel.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    accel.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    accel.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g (assuming +/- 2g sensitivity)
    accel.x = (int16_t)((accel.x * 0.001) - 0.0000001); // Corrected conversion
    accel.y = (int16_t)((accel.y * 0.001) - 0.0000001); // Corrected conversion
    accel.z = (int16_t)((accel.z * 0.001) - 0.0000001); // Corrected conversion

    return accel;
}

// Read magnetometer data
mag_data_t read_mag() {
    mag_data_t mag;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        mag.x = mag.y = mag.z = 0; // Return 0s on error
        return mag;
    }

    mag.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    mag.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    mag.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return mag;
}

// Calculate heading
float calculate_heading(accel_data_t accel, mag_data_t mag) {
    float heading = atan2(mag.y, mag.x) * 180 / M_PI;

    // Normalize accelerometer data to get acceleration vector
    float mag_x = mag.x * 0.00015; // Convert to gauss
    float mag_y = mag.y * 0.00015; // Convert to gauss
    float mag_z = mag.z * 0.00015; // Convert to gauss

    float ax = accel.x * 0.001; // Convert to g
    float ay = accel.y * 0.001; // Convert to g
    float az = accel.z * 0.001; // Convert to g

    float ax_mag = sqrt(ax * ax + ay * ay + az * az);
    float ay_mag = sqrt(mag_x * mag_x + mag_y * mag_y + mag_z * mag_z);

    float heading_rad = atan2(ay_mag, ax_mag) * 180 / M_PI;

    // Adjust heading to be within 0-360 degrees
    if (heading_rad < 0) {
        heading_rad += 360;
    }

    return heading_rad;
}

// Log data to file
void log_data(accel_data_t accel, mag_data_t mag, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, accel.x, accel.y, accel.z, mag.x, mag.y, mag.z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize accelerometer and magnetometer
    if (init_accel() < 0 || init_mag() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X(g),Accel_Y(g),Accel_Z(g),Mag_X(gauss),Mag_Y(gauss),Mag_Z(gauss)\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor data
        accel_data_t accel = read_accel();
        mag_data_t mag = read_mag();

        // Calculate heading
        float heading = calculate_heading(accel, mag);

        // Log data
        log_data(accel, mag, heading);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Close log file
    fclose(log_file);

    // Close I2C connection
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

