// VL6180X I2C address
#define VL6180X_ADDR 0x29

// VL6180X register addresses
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl6180x();
int read_distance();
void log_data(int distance);
void signal_handler(int signal);
int check_sensor_status();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// VL6180X initialization function
int init_vl6180x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xB4) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Recommended settings from datasheet
    if (i2cWriteByteData(i2c_handle, 0x0207, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0208, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0096, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0097, 0xfd) < 0) return -1;
