    if (i2cWriteByteData(i2c_handle, 0x00dc, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x00dd, 0xf8) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x00de, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x009f, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x00a3, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x00a4, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x00a5, 0x00) < 0) return -1;
