#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define REG_GYRO_X 0x04
#define REG_GYRO_Y 0x06
#define REG_GYRO_Z 0x08
#define REG_ACCEL_X 0x0A
#define REG_ACCEL_Y 0x0C
#define REG_ACCEL_Z 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0 //PI_SPI_FLAGS_MODE3 | PI_SPI_FLAGS_MODE0

// Gyroscope Sensitivity (deg/sec/LSB)
#define GYRO_SENSITIVITY 0.005

// Accelerometer Sensitivity (g/LSB)
#define ACCEL_SENSITIVITY 0.00025

// Stall Time (40 us)
#define STALL_TIME 40

// Sampling Rate (100 ms)
#define SAMPLING_RATE 100

// Global Variables
static int spi_handle;
static FILE *fp;
static volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function Prototypes
int spi_read_register(int reg_addr, uint16_t *data);
int spi_write_register(int reg_addr, uint16_t data);
int read_imu_data(imu_data_t *data);
void convert_imu_data(imu_data_t *data);
void log_imu_data(const imu_data_t *data);
void cleanup_handler(int signum);
void signal_handler(int signum);

// Helper function to install cleanup handler
void install_cleanup_handler() {
    atexit(cleanup_handler);
}

// Helper function to close SPI and file
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Signal handler function
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal %d received, terminating...\n", signum);
}

// Function to read a register from the ADIS16488A
int spi_read_register(int reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message
    tx_buf[0] = 0x80 | (reg_addr & 0x7F); // MSB = 1 for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Delay for stall time
    gpioDelay(STALL_TIME * 1000); // Convert us to ms

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Extract the data from the response
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Function to write a register to the ADIS16488A
int spi_write_register(int reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message
    tx_buf[0] = 0x80 | (reg_addr & 0x7F); // MSB = 1 for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    // Delay for stall time
    gpioDelay(STALL_TIME * 1000); // Convert us to ms

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(imu_data_t *data) {
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Read gyroscope data
    if (spi_read_register(REG_GYRO_X, &gyro_x) != 0) return -1;
    if (spi_read_register(REG_GYRO_Y, &gyro_y) != 0) return -1;
    if (spi_read_register(REG_GYRO_Z, &gyro_z) != 0) return -1;

    // Read accelerometer data
    if (spi_read_register(REG_ACCEL_X, &accel_x) != 0) return -1;
    if (spi_read_register(REG_ACCEL_Y, &accel_y) != 0) return -1;
    if (spi_read_register(REG_ACCEL_Z, &accel_z) != 0) return -1;

    // Convert the data
    data->gyro_x = (double)gyro_x * GYRO_SENSITIVITY;
    data->gyro_y = (double)gyro_y * GYRO_SENSITIVITY;
    data->gyro_z = (double)gyro_z * GYRO_SENSITIVITY;
    data->accel_x = (double)accel_x * ACCEL_SENSITIVITY;
    data->accel_y = (double)accel_y * ACCEL_SENSITIVITY;
    data->accel_z = (double)accel_z * ACCEL_SENSITIVITY;

    return 0;
}

// Function to convert IMU data
void convert_imu_data(imu_data_t *data) {
    // Get timestamp in milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data->timestamp = (double)ts.tv_sec * 1000.0 + (double)ts.tv_nsec / 1000000000.0;
}

// Function to log IMU data to a file
void log_imu_data(const imu_data_t *data) {
    if (fp == NULL) {
        fprintf(stderr, "Error: File not opened.\n");
        return;
    }

    fprintf(fp, "%.3f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            data->timestamp, data->gyro_x, data->gyro_y, data->gyro_z,
            data->accel_x, data->accel_y, data->accel_z);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register cleanup handler
    install_cleanup_handler();

    // Main loop
    imu_data_t imu_data;
    int running = 1;
    while (running) {
        // Read IMU data
        if (read_imu_data(&imu_data) == 0) {
            // Convert IMU data
            convert_imu_data(&imu_data);

            // Log IMU data
            log_imu_data(&imu_data);
        } else {
            fprintf(stderr, "Failed to read IMU data.\n");
        }

        // Delay for sampling rate
        gpioDelay(SAMPLING_RATE * 1000); // Convert ms to us
    }

    // Cleanup (should not reach here if signal handler works)
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

