#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting...\n");
}

// Function to initialize the MPU6886
int init_mpu6886()
{
    // Wake up the MPU6886 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6886\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_accel_gyro(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buf[14];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14);
    if (result < 0) {
        fprintf(stderr, "Error: I2C read failed (%d)\n", result);
        return -1;
    }

    // Combine high and low bytes for accelerometer and gyroscope
    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main()
{
    int result;
    int retry_count;
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6886
    if (init_mpu6886() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        retry_count = 0;
        while (retry_count < 3) {
            result = read_accel_gyro(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);
            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error: I2C read failed, retrying (%d/3)\n", retry_count + 1);
                gpioDelay(10000); // 10ms delay
                retry_count++;
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Error: I2C read failed after 3 retries. Exiting.\n");
            break; // Exit main loop if read fails after multiple retries
        }

        // Print accelerometer and gyroscope values
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        gpioDelay(50000); // 50ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

