#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_STATUS 0x0B
#define ADXL345_THRESH_TAP 0x1D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_FILTER_CTL 0x2C

// GPIO pin for LED
#define LED_PIN 17

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// I2C handle
int i2c_handle;

// File pointer for log file
FILE *log_file;

// Function prototypes
int adxl345_init();
int adxl345_read_register(uint8_t reg, uint8_t *value);
int adxl345_write_register(uint8_t reg, uint8_t value);
int adxl345_read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Structure to hold ADXL345 configuration
typedef struct {
    int i2c_address;
    int led_pin;
    float impact_threshold;
} adxl345_config_t;

// Global configuration
adxl345_config_t config = {
    .i2c_address = ADXL345_ADDRESS,
    .led_pin = LED_PIN,
    .impact_threshold = IMPACT_THRESHOLD
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float x, y, z, magnitude;

        // Read acceleration data
        if (adxl345_read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue; // Continue to the next iteration
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(x, y, z);

        // Check for impact
        if (magnitude > config.impact_threshold) {
            // Turn on LED
            gpioWrite(config.led_pin, 1);

            // Log impact
            log_impact(x, y, z, magnitude);

            // Wait for 500ms
            gpioDelay(500000); // 500ms

            // Turn off LED
            gpioWrite(config.led_pin, 0);
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms
    }

    return 0;
}

// Initialize ADXL345
int adxl345_init() {
    // Open I2C device
    i2c_handle = i2cOpen(1, config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify device ID
    uint8_t device_id;
    if (adxl345_read_register(ADXL345_POWER_CTL, &device_id) != 0) {
        fprintf(stderr, "Failed to read device ID\n");
        i2cClose(i2c_handle);
        return -1;
    }
    if (device_id != 0xAD) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Set power control register to measure mode
    if (adxl345_write_register(ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set data rate to 100Hz
    if (adxl345_write_register(ADXL345_FILTER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to write to FILTER_CTL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Enable tap detection
    if (adxl345_write_register(ADXL345_INT_ENABLE, 0x80) != 0) {
        fprintf(stderr, "Failed to write to INT_ENABLE register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read a register from ADXL345
int adxl345_read_register(uint8_t reg, uint8_t *value) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to write register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to read register value\n");
        return -1;
    }
    *value = buf[0];
    return 0;
}

// Write a register to ADXL345
int adxl345_write_register(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to write register value\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from ADXL345
int adxl345_read_acceleration(float *x, float *y, float *z) {
    char buf[7];
    buf[0] = ADXL345_DATAX0 | 0x80; // Read multiple bytes

    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to write register address for read\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 7) != 7) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((buf[2] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[4] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[6] << 8) | buf[5]);

    // Convert to g's (assuming scale factor of 256 LSB/g)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact event to file
void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);

    // Close I2C device
    i2cClose(i2c_handle);

    // Turn off LED
    gpioWrite(config.led_pin, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

