#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Scaling factors (adjust based on your configuration)
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE 131.0f    // +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_imu();
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x98) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    printf("IMU initialized successfully\n");
    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    char buffer[12];

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
        return data;
    }

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer + 6, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    int16_t gyro_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    int16_t gyro_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    int16_t gyro_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    // Convert to g and dps
    data.accel_x = (float)accel_x / ACCEL_SCALE;
    data.accel_y = (float)accel_y / ACCEL_SCALE;
    data.accel_z = (float)accel_z / ACCEL_SCALE;
    data.gyro_x = (float)gyro_x / GYRO_SCALE;
    data.gyro_y = (float)gyro_y / GYRO_SCALE;
    data.gyro_z = (float)gyro_z / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

