#define MMA8451Q_RANGE_4G 0x02
#define MMA8451Q_RANGE_8G 0x04
#define MMA8451Q_RANGE_16G 0x06
#define MMA8451Q_DATA_RATE 0x2B
#define MMA8451Q_DATA_RATE_100HZ 0x01
#define MMA8451Q_DATA_RATE_200HZ 0x03
#define MMA8451Q_DATA_RATE_400HZ 0x05
#define MMA8451Q_DATA_RATE_800HZ 0x07
#define MMA8451Q_POWER_CTL 0x2A
#define MMA8451Q_CTRL_REG1 0x2B
#define MMA8451Q_CTRL_REG2 0x2C
#define MMA8451Q_CTRL_REG3 0x2D
#define MMA8451Q_CTRL_REG4 0x2E
#define MMA8451Q_CTRL_REG5 0x2F
#define MMA8451Q_CTRL_REG6 0x30
#define MMA8451Q_CTRL_REG7 0x31
#define MMA8451Q_CTRL_REG8 0x32
#define MMA8451Q_CTRL_REG9 0x33
#define MMA8451Q_CTRL_REG10 0x34
#define MMA8451Q_CTRL_REG11 0x35
#define MMA8451Q_CTRL_REG12 0x36
#define MMA8451Q_CTRL_REG13 0x37
#define MMA8451Q_CTRL_REG14 0x38
#define MMA8451Q_CTRL_REG15 0x39

#define LED_GPIO 17
#define THRESHOLD 2048.0 // 2g * 1024 counts/g

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mma8451q();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int verify_sensor_id();
void control_led(int on);
void log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MMA8451Q sensor
int init_mma8451q() {
    // Verify sensor ID
    if (!verify_sensor_id()) {
        fprintf(stderr, "Error: Invalid sensor ID. Exiting.\n");
        return -1;
    }

    // Set range to ±2g
    if (i2cWriteByteData(i2c_handle, MMA8451Q_RANGE, MMA8451Q_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Failed to set range.\n");
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, MMA8451Q_DATA_RATE, MMA8451Q_DATA_RATE_100HZ) < 0) {
        fprintf(stderr, "Error: Failed to set data rate.\n");
        return -1;
    }

    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, MMA8451Q_POWER_CTL, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to wake up sensor.\n");
        return -1;
    }

    // Configure CTRL_REG1 (default settings)
    if (i2cWriteByteData(i2c_handle, MMA8451Q_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG1.\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from MMA8451Q
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char raw_data[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, MMA8451Q_REG_OUT_X_MSB, raw_data, 6);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read acceleration data. Error code: %d\n", result);
        return -1;
    }

    *x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    *y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    *z = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 1024.0; // Convert to g
}

// Verify the sensor ID
int verify_sensor_id() {
    char id;
    int result;

    result = i2cReadByteData(i2c_handle, MMA8451Q_REG_ID);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID. Error code: %d\n", result);
        return -1;
    }

    id = (char)result;

    if (id != MMA8451Q_ID_VALUE) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X (expected 0x%02X)\n", id, MMA8451Q_ID_VALUE);
        return -1;
    }

    return 0;
}

