#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_INT_MAP 0x1E

// GPIO pin for interrupt
#define INTERRUPT_PIN 17 // Physical pin 11, BCM numbering

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.3

// File to log free-fall data
#define LOG_FILE "freefall_log.csv"

// Global variables
int fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init();
int adxl345_read_register(int reg);
int adxl345_write_register(int reg, int value);
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void freefall_interrupt_handler();
void signal_handler(int signal);
void cleanup();

// Function to initialize the ADXL345
int adxl345_init() {
    // Verify device ID
    int device_id = adxl345_read_register(0x00);
    if (device_id != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", device_id);
        return -1;
    }

    // Set data format to +/- 2g range
    if (adxl345_write_register(ADXL345_POWER_CTL, 0x08) < 0) return -1; // Measurement mode

    // Enable free-fall interrupt
    if (adxl345_write_register(ADXL345_INT_ENABLE, 0x40) < 0) return -1; // Free-fall interrupt enable

    // Map free-fall interrupt to INT1 pin
    if (adxl345_write_register(ADXL345_INT_MAP, 0x40) < 0) return -1; // Free-fall interrupt map

    return 0;
}

// Function to read a register from the ADXL345
int adxl345_read_register(int reg) {
    int value = wiringPiI2CReadReg8(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a register to the ADXL345
int adxl345_write_register(int reg, int value) {
    int result = wiringPiI2CWriteReg8(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, x2, y0, y1, y2, z0, z1, z2;

    x0 = adxl345_read_register(ADXL345_DATAX0 + 0);
    x1 = adxl345_read_register(ADXL345_DATAX0 + 1);
    x2 = adxl345_read_register(ADXL345_DATAX0 + 2);
    y0 = adxl345_read_register(ADXL345_DATAX0 + 3);
    y1 = adxl345_read_register(ADXL345_DATAX0 + 4);
    y2 = adxl345_read_register(ADXL345_DATAX0 + 5);
    z0 = adxl345_read_register(ADXL345_DATAX0 + 6);
    z1 = adxl345_read_register(ADXL345_DATAX0 + 7);
    z2 = adxl345_read_register(ADXL345_DATAX0 + 8);

    if (x0 < 0 || x1 < 0 || x2 < 0 || y0 < 0 || y1 < 0 || y2 < 0 || z0 < 0 || z1 < 0 || z2 < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Interrupt handler function
void freefall_interrupt_handler() {
    int int_source = adxl345_read_register(ADXL345_INT_SOURCE);
    if (int_source & 0x40) { // Free-fall interrupt
        printf("Free-fall detected!\n");
        int16_t x, y, z;
        if (adxl345_read_acceleration(&x, &y, &z) == 0) {
            // Validate free-fall condition
            if (abs(x) < FREEFALL_THRESHOLD && abs(y) < FREEFALL_THRESHOLD && abs(z) < FREEFALL_THRESHOLD) {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log data to file
                fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, (float)x, (float)y, (float)z);
                fflush(log_file); // Ensure data is written to disk immediately
            }
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    // Disable interrupts
    adxl345_write_register(ADXL345_INT_ENABLE, 0x00); // Disable free-fall interrupt

    // Close I2C file descriptor
    if (fd >= 0) {
        close(fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO line
    pinMode(INTERRUPT_PIN, INPUT); // Set to input to avoid short circuit

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    fd = wiringPiI2CSetup(ADXL345_ADDRESS);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "Error initializing ADXL345\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, freefall_interrupt_handler) < 0) {
        fprintf(stderr, "Error setting up interrupt: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Poll for interrupt events
        delay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

