// LSM6DSR I2C address (check WHO_AM_I register)
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Configuration values
#define ACCEL_RANGE_2G 0x00 // ±2g
#define GYRO_RANGE_250DPS 0x00 // ±250 dps
#define ODR_104HZ 0x60 // 104 Hz output data rate

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_WINDOW 1.0f

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
sensor_data_t read_sensor_data();
float calculate_acceleration_magnitude(sensor_data_t data);
bool is_freefall(float acceleration_magnitude);
bool is_impact(float acceleration_magnitude);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
