int init_lsm6dsr() {
    // Check WHO_AM_I register
    char who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i != 0x69) {
        fprintf(stderr, "Error: WHO_AM_I check failed. Expected 0x69, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, ACCEL_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL2_G, GYRO_RANGE_250DPS) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL2_G\n");
        return -1;
    }

    // Configure output data rate
    if (i2cWriteByteData(i2c_handle, 0x0B, ODR_104HZ) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL1_XL (ODR)\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from the LSM6DSR
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12) < 0) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    // Combine high and low bytes for accelerometer data
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for gyroscope data
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert raw data to g and dps (sensitivity values from datasheet)
    data.accel_x = (float)raw_accel_x / 16384.0f; // 2g range
    data.accel_y = (float)raw_accel_y / 16384.0f;
    data.accel_z = (float)raw_accel_z / 16384.0f;
    data.gyro_x = (float)raw_gyro_x / 131.0f;   // 250 dps range
    data.gyro_y = (float)raw_gyro_y / 131.0f;
    data.gyro_z = (float)raw_gyro_z / 131.0f;

    return data;
