bool is_freefall(float acceleration_magnitude) {
    return acceleration_magnitude < FREEFALL_THRESHOLD;
}

// Check if the acceleration magnitude is above the impact threshold within the impact window
bool is_impact(float acceleration_magnitude) {
    static time_t impact_start_time = 0;
    static bool impact_detected = false;

    if (impact_detected) {
        time_t current_time = time(NULL);
        if (difftime(current_time, impact_start_time) <= IMPACT_WINDOW) {
