#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define WHO_AM_I 0x02
#define GYRO_XOUT 0x04
#define GYRO_YOUT 0x06
#define GYRO_ZOUT 0x08
#define SMPL_PRD  0x36
#define GLOB_CMD  0x68

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling Factor
#define SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t address, uint16_t *value);
int spi_write_register(int handle, uint8_t address, uint16_t value);
int verify_who_am_i(int handle);
int configure_gyro(int handle);
int read_gyro_data(int handle, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int handle, uint8_t address, uint16_t *value) {
    char tx[3];
    char rx[3];

    tx[0] = address | 0x80; // Set MSB for read operation
    tx[1] = 0x00; // Dummy byte
    tx[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI read failed for address 0x%02X\n", address);
        return -1;
    }

    *value = (rx[1] << 8) | rx[2];
    return 0;
}

// SPI Write Function
int spi_write_register(int handle, uint8_t address, uint16_t value) {
    char tx[3];
    char rx[3];

    tx[0] = address & 0x7F; // Clear MSB for write operation
    tx[1] = (value >> 8) & 0xFF; // MSB of value
    tx[2] = value & 0xFF; // LSB of value

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write failed for address 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I Register
int verify_who_am_i(int handle) {
    uint16_t who_am_i;

    if (spi_read_register(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x4A2) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%04X (expected 0x4A2)\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I check passed: 0x%04X\n", who_am_i);
    return 0;
}

// Configure Gyroscope
int configure_gyro(int handle) {
    // Set sample period to 10ms (adjust as needed)
    if (spi_write_register(handle, SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }

    // Set global command to reset (optional)
    if (spi_write_register(handle, GLOB_CMD, 0x0000) != 0) {
        fprintf(stderr, "Failed to reset gyro\n");
        return -1;
    }

    return 0;
}

// Read Gyro Data
int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint16_t x_raw, y_raw, z_raw;

    if (spi_read_register(handle, GYRO_XOUT, &x_raw) != 0) {
        fprintf(stderr, "Failed to read X gyro data\n");
        return -1;
    }
    if (spi_read_register(handle, GYRO_YOUT, &y_raw) != 0) {
        fprintf(stderr, "Failed to read Y gyro data\n");
        return -1;
    }
    if (spi_read_register(handle, GYRO_ZOUT, &z_raw) != 0) {
        fprintf(stderr, "Failed to read Z gyro data\n");
        return -1;
    }

    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;

    return 0;
}

// Log Data to CSV File
int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I
    if (verify_who_am_i(spi_handle) != 0) {
        fprintf(stderr, "Gyro initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure Gyroscope
    if (configure_gyro(spi_handle) != 0) {
        fprintf(stderr, "Gyro configuration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    // Close SPI channel and log file
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

