// Gyroscope I2C address
#define GYRO_ADDRESS 0x69

// Gyroscope registers
#define GYRO_WHO_AM_I 0x0F
#define GYRO_CTRL_REG1 0x20
#define GYRO_OUT_X_L 0x28
#define GYRO_OUT_X_H 0x29
#define GYRO_OUT_Y_L 0x2A
#define GYRO_OUT_Y_H 0x2B
#define GYRO_OUT_Z_L 0x2C
#define GYRO_OUT_Z_H 0x2D

// Sensitivity scale factor
#define GYRO_SENSITIVITY 8.75

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    while (retries > 0) {
        // Check WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, GYRO_WHO_AM_I);
        if (who_am_i == 0x69) {
            // Configure the gyroscope (e.g., 100 Hz, normal mode)
            if (i2cWriteByteData(i2c_handle, GYRO_CTRL_REG1, 0x0F) >= 0) { // 100Hz, normal mode
                printf("Gyroscope initialized successfully.\n");
                return 0; // Success
            } else {
                fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
                retries--;
                gpioDelay(100); // Wait before retrying
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }
    fprintf(stderr, "Failed to initialize gyroscope after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    int16_t x, y, z;

    // Read X axis data
    int x_l = i2cReadByteData(i2c_handle, GYRO_OUT_X_L);
    int x_h = i2cReadByteData(i2c_handle, GYRO_OUT_X_H);
    if (x_l < 0 || x_h < 0) {
        fprintf(stderr, "Error reading X axis data: %s\n", strerror(errno));
        data.x = 0.0; // Set to 0.0 in case of error
    } else {
        x = (int16_t)((x_h << 8) | x_l);
        data.x = (double)x * GYRO_SENSITIVITY / 114.285;
    }

    // Read Y axis data
    int y_l = i2cReadByteData(i2c_handle, GYRO_OUT_Y_L);
    int y_h = i2cReadByteData(i2c_handle, GYRO_OUT_Y_H);
    if (y_l < 0 || y_h < 0) {
        fprintf(stderr, "Error reading Y axis data: %s\n", strerror(errno));
        data.y = 0.0; // Set to 0.0 in case of error
    } else {
        y = (int16_t)((y_h << 8) | y_l);
