        data.z = 0.0; // Set to 0.0 in case of error
    } else {
        z = (int16_t)((z_h << 8) | z_l);
        data.z = (double)z * GYRO_SENSITIVITY / 114.285;
    }

    return data;
}

// Log data to CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

