#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500

static volatile int terminate = 0;

// Structure to hold program state
typedef struct {
    int log_file_handle;
} ProgramState;

ProgramState state = {0};

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log events to the file
void log_event(const char *message) {
    char *timestamp = get_timestamp();
    if (state.log_file_handle >= 0) {
        fprintf(state.log_file_handle, "%s – %s\n", timestamp, message);
        fflush(state.log_file_handle); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to cleanup resources before exiting
void cleanup() {
    if (state.log_file_handle >= 0) {
        fclose(state.log_file_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pin
    if (initialize() != 0) {
        return 1;
    }

    // Open the log file in append mode
    state.log_file_handle = fopen(LOG_FILE, "a");
    if (state.log_file_handle == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (active-low)
            log_event("FLAME DETECTED!");
            printf("FLAME DETECTED!\n");
        } else if (sensor_value == 1) { // No flame (HIGH)
            char *timestamp = get_timestamp();
            log_event("… NO");
            printf("… NO\n");
        } else {
            // Error reading sensor, log an error message
            char *timestamp = get_timestamp();
            log_event("Sensor read error");
            fprintf(stderr, "Sensor read error\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

