#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-effect sensors
#define HALL_SENSOR_1 17
#define HALL_SENSOR_2 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a Hall-effect sensor
int read_hall_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor states to a file
void log_sensor_states(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

// Function to halt the conveyor
void halt_conveyor() {
    printf("Conveyor halted!\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(HALL_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(HALL_SENSOR_1, PI_PUD_UP);
    gpioSetMode(HALL_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(HALL_SENSOR_2, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_state = read_hall_sensor(HALL_SENSOR_1);
        int sensor2_state = read_hall_sensor(HALL_SENSOR_2);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break; // Exit the loop if there's an error reading sensors
        }

        log_sensor_states(sensor1_state, sensor2_state);

        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    printf("Conveyor monitoring stopped.\n");
    return 0;
}

