#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MMA8452Q I2C address
#define MMA8452Q_ADDR 0x1D

// MMA8452Q registers
#define WHO_AM_I 0x00
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to read a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to verify sensor identity
int verify_sensor_identity(int handle) {
    uint8_t who_am_i;
    if (read_register(handle, WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }

    if (who_am_i != 0x41) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    printf("Sensor identity verified: WHO_AM_I = 0x%02X\n", who_am_i);
    return 0;
}

// Function to initialize the MMA8452Q
int initialize_mma8452q(int handle) {
    // Set to active mode
    if (write_register(handle, CTRL_REG1, 0x01) != 0) {
        return -1;
    }

    // Set data rate to 100 Hz
    if (write_register(handle, CTRL_REG1, 0x0A) != 0) {
        return -1;
    }

    // Set standby time to 0.5 ms
    if (write_register(handle, CTRL_REG1, 0x00) != 0) {
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
    int result;

    result = i2cReadI2CBlockData(handle, OUT_X_MSB, (char *) &x_msb, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading OUT_X_MSB: %s\n", strerror(errno));
        return -1;
    }
    x_msb = (uint8_t)x_msb;

    result = i2cReadI2CBlockData(handle, OUT_X_LSB, (char *) &x_lsb, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading OUT_X_LSB: %s\n", strerror(errno));
        return -1;
    }
    x_lsb = (uint8_t)x_lsb;

    result = i2cReadI2CBlockData(handle, OUT_Y_MSB, (char *) &y_msb, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading OUT_Y_MSB: %s\n", strerror(errno));
        return -1;
    }
    y_msb = (uint8_t)y_msb;

    result = i2cReadI2CBlockData(handle, OUT_Y_LSB, (char *) &y_lsb, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading OUT_Y_LSB: %s\n", strerror(errno));
        return -1;
    }
    y_lsb = (uint8_t)y_lsb;

    result = i2cReadI2CBlockData(handle, OUT_Z_MSB, (char *) &z_msb, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading OUT_Z_MSB: %s\n", strerror(errno));
        return -1;
    }
    z_msb = (uint8_t)z_msb;

    result = i2cReadI2CBlockData(handle, OUT_Z_LSB, (char *) &z_lsb, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading OUT_Z_LSB: %s\n", strerror(errno));
        return -1;
    }
    z_lsb = (uint8_t)z_lsb;

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Function to calculate tilt angle
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float x_g = x / 2048.0f; // Assuming +/- 2g range
    float y_g = y / 2048.0f;
    float z_g = z / 2048.0f;

    float tilt_x = atan2f(x_g, sqrtf(y_g * y_g + z_g * z_g)) * 180 / M_PI;
    float tilt_y = atan2f(y_g, sqrtf(x_g * x_g + z_g * z_g)) * 180 / M_PI;
    float tilt_z = atan2f(z_g, sqrtf(x_g * x_g + y_g * y_g)) * 180 / M_PI;

    return sqrtf(tilt_x * tilt_x + tilt_y * tilt_y + tilt_z * tilt_z);
}

// Function to log fall events
int log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int16_t x, y, z;
    float tilt;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MMA8452Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    if (verify_sensor_identity(i2c_handle) != 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8452Q
    if (initialize_mma8452q(i2c_handle) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_handle, &x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt = calculate_tilt(x, y, z);

            // Check for fall
            if (tilt > 45.0f) {
                log_fall_event(x, y, z);
                printf("Fall detected! Tilt: %.2f degrees\n", tilt);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        // Delay for 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

