#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration data
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Sensitivity
#define SENSITIVITY 0.146 // mG/LSB

// Metal detector threshold
#define METAL_THRESHOLD 800.0 // mG

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_lis3mdl();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
magnetometer_data_t calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z);
float calculate_magnitude(magnetometer_data_t data);
void write_to_log(magnetometer_data_t data);
void handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure LIS3MDL
int configure_lis3mdl() {
    // Set data rate to 10 Hz (100 Hz ODR)
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x77) < 0) {
        handle_error("Failed to write to CTRL_REG1");
        return -1;
    }

    // Set full-scale range to ±4 gauss
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        handle_error("Failed to write to CTRL_REG3");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6) != 6) {
        handle_error("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate data
magnetometer_data_t calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    magnetometer_data_t data;

    data.x = (float)raw_x * X_SCALE + X_OFFSET;
    data.y = (float)raw_y * Y_SCALE + Y_OFFSET;
    data.z = (float)raw_z * Z_SCALE + Z_OFFSET;

    return data;
}

// Function to calculate magnitude
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z) * 1000.0; // in mG
}

// Function to write data to log file
void write_to_log(magnetometer_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written immediately
}

// Function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure LIS3MDL
    if (configure_lis3mdl() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
        cleanup();
        return 1;
    }

    int retry_count = 0;
    while (retry_count < 3) {
        if (configure_lis3mdl() == 0) {
            break; // Configuration successful
        } else {
            fprintf(stderr, "LIS3MDL configuration failed, retrying... (%d/3)\n", retry_count + 1);
            retry_count++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (retry_count == 3) {
        handle_error("LIS3MDL configuration failed after multiple retries. Exiting.");
        cleanup();
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    magnetometer_data_t magnetometer_data;

    // Main loop
    while (!terminate) {
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            magnetometer_data = calibrate_data(raw_x, raw_y, raw_z);
            write_to_log(magnetometer_data);

            float magnitude = calculate_magnitude(magnetometer_data);

            if (magnitude > METAL_THRESHOLD) {
                printf("Metal detector alert! Total field magnitude: %.2f mG\n", magnitude);
            }
        } else {
            handle_error("Failed to read magnetometer data in main loop");
        }

        gpioDelay(100); // 100 ms delay (10 Hz data rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

