#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_RESET_REG 0x02
#define ADXL354B_POWER_CTRL_REG 0x0F
#define ADXL354B_STATUS_REG 0x0D
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_H 0x09
#define ADXL354B_YDATA_L 0x0A
#define ADXL354B_YDATA_H 0x0B
#define ADXL354B_ZDATA_L 0x0C
#define ADXL354B_ZDATA_H 0x0D

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354b_reset();
int adxl354b_write_register(uint8_t reg, uint8_t value);
int adxl354b_read_register(uint8_t reg, uint8_t *value);
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to reset the ADXL354B
int adxl354b_reset() {
    uint8_t reset_value = 0x80; // Reset value
    if (adxl354b_write_register(ADXL354B_RESET_REG, reset_value) != 0) {
        fprintf(stderr, "Error: Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to write a value to a register
int adxl354b_write_register(uint8_t reg, uint8_t value) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = reg | 0x80; // Set MSB for write
    tx_buffer[1] = value;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed\n");
        return -1;
    }
    return 0;
}

// Function to read a value from a register
int adxl354b_read_register(uint8_t reg, uint8_t *value) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = reg & 0x7F; // Clear MSB for read
    tx_buffer[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1;
    }

    *value = rx_buffer[1];
    return 0;
}

// Function to read acceleration data
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buffer[1];
    char rx_buffer[7];
    int retries = 3;

    tx_buffer[0] = ADXL354B_XDATA_L | 0x80; // Start reading from XDATA_L with multi-byte mode

    while (retries > 0) {
