void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int status;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    status = gpioChipOpen(GPIO_CHIP, GPIO_PIN, 0);
    if (status != 0) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", status);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking sequence started\n");

    while (program_running) {
        // Read sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value: %d\n", sensor_value);
            break; // Exit loop on error
        }

        // Check for obstacle
        if (sensor_value == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

