    }

    // Close GPIO chip
    status = gpioChipClose(GPIO_CHIP);
    if (status != 0) {
        fprintf(stderr, "Failed to close GPIO chip: %d\n", status);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Self-parking sequence completed\n");

    return 0;
}

