#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the polling interval in milliseconds
#define POLLING_INTERVAL_MS 100

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} sensor_data_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor values from the GPIO pins
sensor_data_t read_sensors() {
    sensor_data_t data;
    data.sensor1_value = gpioRead(SENSOR1_GPIO);
    data.sensor2_value = gpioRead(SENSOR2_GPIO);
    return data;
}

// Function to log sensor data with a timestamp
void log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, data.sensor1_value, data.sensor2_value);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor_data_t sensor_data = read_sensors();

        // Log sensor data
        log_sensor_data(sensor_data);

        // Wait for the next poll
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

