#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling Factor
#define SCALE_FACTOR 0.02 // deg/sec per LSB

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read data from ADIS16266
int read_adis16266(int spi_handle, int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of address to 1 for read operation
    tx_buf[0] = (reg_addr >> 8) | 0x80; // MSB set for read
    tx_buf[1] = reg_addr & 0xFF;        // LSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to convert raw data to angular rates
void convert_to_rates(int16_t raw_data, float *x_rate, float *y_rate, float *z_rate) {
    *x_rate = raw_data * SCALE_FACTOR;
    *y_rate = raw_data * SCALE_FACTOR;
    *z_rate = raw_data * SCALE_FACTOR;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADIS16266 Gyroscope Data Acquisition\n");

    // Main loop
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        float x_rate, y_rate, z_rate;

        // Read X-axis data
        if (read_adis16266(spi_handle, ADIS16266_XGYRO_OUT, &raw_x) != 0) {
            fprintf(stderr, "Error reading X-axis data, exiting...\n");
            break;
        }

        // Read Y-axis data
        if (read_adis16266(spi_handle, ADIS16266_YGYRO_OUT, &raw_y) != 0) {
            fprintf(stderr, "Error reading Y-axis data, exiting...\n");
            break;
        }

        // Read Z-axis data
        if (read_adis16266(spi_handle, ADIS16266_ZGYRO_OUT, &raw_z) != 0) {
            fprintf(stderr, "Error reading Z-axis data, exiting...\n");
            break;
        }

        // Convert raw data to angular rates
        convert_to_rates(raw_x, &x_rate, &y_rate, &z_rate);

        // Print the angular rates
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

