#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_RATE_MS 1000
#define WINDOW_SIZE_MS 5000
#define THRESHOLD 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor() {
    return gpioRead(GPIO_PIN);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count = 0;
    time_t start_time, current_time;
    double elapsed_time;
    int i;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%d", &threshold) != 1) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time(&start_time);

    while (program_running) {
        high_count = 0;
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        if (elapsed_time >= WINDOW_SIZE_MS) {
            for (i = 0; i < SAMPLE_RATE_MS / 1000; i++) {
                if (read_sensor() == 1) {
                    high_count++;
                }
            }

            if (high_count > threshold) {
                printf("ALERT\n");
            } else {
                printf("OK\n");
            }

            time(&start_time);
        }
    }

    gpioTerminate();
    return 0;
}

