#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the door locks
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define the log file name
#define LOG_FILE "access_log.txt"

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int generate_security_code(char *code);
int read_user_input(char *user_input);
int validate_code(const char *code, const char *generated_code);
int log_access(const char *code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        terminate = 1;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(DOOR_A_PIN, PI_OUTPUT);
    gpioSetMode(DOOR_B_PIN, PI_OUTPUT);

    // Initialize both pins to LOW (locked)
    gpioWrite(DOOR_A_PIN, 0);
    gpioWrite(DOOR_B_PIN, 0);

    return 0; // Indicate success
}

// Function to generate a random six-digit security code
int generate_security_code(char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL in generate_security_code\n");
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Generate a six-digit code
    for (int i = 0; i < 6; i++) {
        code[i] = '1' + (rand() % 10); // Generate a random digit between 1 and 9
    }

    return 0; // Indicate success
}

// Function to read user input from stdin
int read_user_input(char *user_input) {
    if (user_input == NULL) {
        fprintf(stderr, "Error: User input buffer is NULL in read_user_input\n");
        return 1;
    }

    // Read a line from stdin
    if (fgets(user_input, 6, stdin) == NULL) {
        fprintf(stderr, "Error reading from stdin\n");
        return 1; // Indicate failure
    }

    // Remove trailing newline character if present
    if (user_input[strlen(user_input) - 1] == '\n') {
        user_input[strlen(user_input) - 1] = '\0';
    }

    return 0; // Indicate success
}

// Function to validate the user's input against the generated code
int validate_code(const char *code, const char *generated_code) {
    if (code == NULL || generated_code == NULL) {
        fprintf(stderr, "Error: Both codes are NULL in validate_code\n");
        return 1;
    }

    if (strlen(code) != 6) {
        fprintf(stderr, "Error: Input code is not 6 characters long in validate_code\n");
        return 1;
    }

    for (int i = 0; i < 6; i++) {
        if (code[i] != generated_code[i]) {
            return 1; // Codes do not match
        }
    }

    return 0; // Codes match
}

// Function to log access to the file
int log_access(const char *code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%s\n", timestamp, code);
    fclose(fp);

    return 0; // Indicate success
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    char generated_code[6];
    char user_input[6];

    // Generate a random security code
    if (generate_security_code(generated_code) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Generated Security Code: %s\n", generated_code);

    // Main loop
    while (!terminate) {
        // Read user input
        if (read_user_input(user_input) == 0) {
            // Validate the input
            if (validate_code(user_input, generated_code) == 0) {
                // Unlock the doors
                gpioWrite(DOOR_A_PIN, 1);
                gpioWrite(DOOR_B_PIN, 1);
                gpioDelay(5000000); // Wait for 5 seconds
                gpioWrite(DOOR_A_PIN, 0);
                gpioWrite(DOOR_B_PIN, 0);

                // Log access
                if (log_access(generated_code) != 0) {
                    fprintf(stderr, "Error logging access\n");
                }

                printf("Access granted\n");
            } else {
                printf("Access denied\n");
            }
        } else {
            // Clear the input buffer if it's empty
            while (getchar() != '\n');
        }
    }

    // Clean up and exit
    gpioWrite(DOOR_A_PIN, 0);
    gpioWrite(DOOR_B_PIN, 0);
    gpioTerminate();

    return 0;
}

