#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PORT 12345
#define SOFT_RESET_CMD 0x80
#define ELE_CONFIG_CMD 0x5E
#define TOUCH_STATUS_REG 0x00
#define FREQUENCY_LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int socket_fd;
FILE *log_file;
char *shared_secret = NULL;
int num_electrodes = 12; // Default number of electrodes

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_data(int i2c_handle);
int authenticate_command(const char *command, const char *secret);
int set_pwm_frequency(int gpio_pin, int frequency);
int log_frequency(int frequency);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, SOFT_RESET_CMD, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure electrodes
    if (i2cWriteByteData(i2c_handle, ELE_CONFIG_CMD, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode configuration failed\n");
        return -1;
    }

    // Enable all electrodes
    for (int i = 0; i < num_electrodes; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x01) < 0) {
            fprintf(stderr, "Error: Failed to enable electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x01) < 0) {
            fprintf(stderr, "Error: Failed to set electrode %d sensitivity\n", i);
            return -1;
        }
    }

    return 0;
}

// Function to read touch data from the MPR121
int mpr121_read_touch_data(int i2c_handle) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, TOUCH_STATUS_REG, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    return ((buf[1] << 8) | buf[0]);
}

// Function to authenticate the command
int authenticate_command(const char *command, const char *secret) {
    if (strncmp(command, "MOTION_DETECTED:", 17) != 0) {
        return 0; // Invalid command
    }

    if (strcmp(command + 17, secret) != 0) {
        return 0; // Incorrect secret
    }

    return 1; // Command authenticated
}

// Function to set the PWM frequency
int set_pwm_frequency(int gpio_pin, int frequency) {
    if (gpioSetPWMfrequency(gpio_pin, frequency) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        return -1;
    }
    return 0;
}

// Function to log the frequency to a file
int log_frequency(int frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    i2cClose(i2c_handle);
    close(socket_fd);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <shared_secret>\n", argv[0]);
        return 1;
    }

    shared_secret = argv[1];
    if (shared_secret == NULL || strlen(shared_secret) == 0) {
        fprintf(stderr, "Error: Shared secret is required\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Open socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);
    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Socket bind failed\n");
        close(socket_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 1) < 0) {
        fprintf(stderr, "Error: Socket listen failed\n");
        close(socket_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Accept connection
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
    if (client_fd < 0) {
        fprintf(stderr, "Error: Socket accept failed\n");
        close(socket_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read command
    char command[256];
    ssize_t bytes_received = recv(client_fd, command, sizeof(command) - 1, 0);
    if (bytes_received < 0) {
        fprintf(stderr, "Error: Socket receive failed\n");
        close(client_fd);
        close(socket_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    command[bytes_received] = '\0';

    // Authenticate command
    if (authenticate_command(command, shared_secret) == 0) {
        printf("Command authenticated\n");

        // Read touch data
        int touch_data = mpr121_read_touch_data(i2c_handle);
        if (touch_data < 0) {
            fprintf(stderr, "Error: Failed to read touch data\n");
            close(client_fd);
            close(socket_fd);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Determine frequency based on touch data
        int frequency = 0;
        for (int i = 0; i < num_electrodes; i++) {
            if (touch_data & (1 << i)) {
                frequency = 440 * (i + 1); // Map electrode number to frequency
                break;
            }
        }

        // Set PWM frequency
        if (set_pwm_frequency(PWM_PIN, frequency) < 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency\n");
            close(client_fd);
            close(socket_fd);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Log frequency
        log_frequency(frequency);

        // Play tone for 5 seconds
        gpioPWM(PWM_PIN, 128); // 50% duty cycle
        gpioDelay(5000000); // 5 seconds

        // Stop PWM
        gpioPWM(PWM_PIN, 0);

        // Close socket and I2C interface
        close(client_fd);
        close(socket_fd);
        i2cClose(i2c_handle);
        gpioTerminate();

        // Open log file
        log_file = fopen(FREQUENCY_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Failed to open log file\n");
            return 1;
        }

        // Signal handling for graceful shutdown
        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);

    } else {
        fprintf(stderr, "Error: Command authentication failed\n");
        close(client_fd);
        close(socket_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

