#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// LSM303DLHC Magnetometer I2C addresses
#define LSM303_ADDR_1 0x1E
#define LSM303_ADDR_2 0x1D

// LSM303DLHC Magnetometer register addresses
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// GPIO pin for LED
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_magnetometer(int i2c_handle);
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t z);
void set_led_brightness(int gpio_pin, float magnitude);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize magnetometer
int init_magnetometer(int i2c_handle) {
    // Set to continuous conversion mode
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        log_error("Failed to set continuous conversion mode");
        return -1;
    }

    // Set to +/- 4 gauss full scale
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        log_error("Failed to set +/- 4 gauss full scale");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t z) {
    return (float)z;
}

// Set LED brightness using hardware PWM
void set_led_brightness(int gpio_pin, float magnitude) {
    // Map magnitude to PWM duty cycle (0-255)
    int duty_cycle = (int)(magnitude * 2.55); // Scale magnitude to 0-255 range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(gpio_pin, duty_cycle);
}

// Log error message
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
    perror(message); // Also print to stderr
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle_1 = i2cOpen(I2C_BUS, LSM303_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        log_error("Failed to open I2C bus for sensor 1");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

