#define I2C_BUS 1

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_magnetometer(int i2c_handle);
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t z);
void set_led_brightness(int gpio_pin, float magnitude);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize magnetometer
int init_magnetometer(int i2c_handle) {
    // Set to continuous conversion mode
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        log_error("Failed to set continuous conversion mode");
        return -1;
    }

    // Set to +/- 4 gauss full scale
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        log_error("Failed to set +/- 4 gauss full scale");
        return -1;
    }

    return 0;
}

