#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    int16_t x_offset;
    int16_t y_offset;
    int16_t z_offset;
} hard_iron_offsets_t;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
void calculate_hard_iron_offsets(hard_iron_offsets_t *offsets, magnetometer_data_t data, int num_samples);
void apply_hard_iron_offsets(magnetometer_data_t *data, hard_iron_offsets_t offsets);
void print_magnetometer_data(magnetometer_data_t data, hard_iron_offsets_t offsets);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Set configuration register A (0x00) to 0x70 for 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Set configuration register B (0x01) to 0x20 for gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set mode register (0x02) to 0x00 for continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate hard-iron offsets
void calculate_hard_iron_offsets(hard_iron_offsets_t *offsets, magnetometer_data_t data, int num_samples) {
    static magnetometer_data_t samples[num_samples];
    static int sample_index = 0;
    static int sample_count = 0;

    samples[sample_index] = data;
    sample_index = (sample_index + 1) % num_samples;
    if (sample_count < num_samples) {
        sample_count++;
    }

    if (sample_count == num_samples) {
        int16_t x_sum = 0, y_sum = 0, z_sum = 0;
        for (int i = 0; i < num_samples; i++) {
            x_sum += samples[i].x;
            y_sum += samples[i].y;
            z_sum += samples[i].z;
        }

        offsets->x_offset = x_sum / num_samples;
        offsets->y_offset = y_sum / num_samples;
        offsets->z_offset = z_sum / num_samples;
    }
}

// Function to apply hard-iron offsets
void apply_hard_iron_offsets(magnetometer_data_t *data, hard_iron_offsets_t offsets) {
    data->x -= offsets.x_offset;
    data->y -= offsets.y_offset;
    data->z -= offsets.z_offset;
}

// Function to print magnetometer data
void print_magnetometer_data(magnetometer_data_t data, hard_iron_offsets_t offsets) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Hard-iron offsets
    hard_iron_offsets_t offsets = {0, 0, 0};

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Apply hard-iron offsets
        apply_hard_iron_offsets(&data, offsets);

        // Print magnetometer data
        print_magnetometer_data(data, offsets);

        // Delay for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

