#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <math.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define INT1_PIN 0x30

// GPIO pin for interrupt
#define INT1_PIN_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile int running = 1;
static accelerometer_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
int init_i2c(int addr);
int verify_device_id(int fd);
int init_accelerometer(int fd);
int read_accelerometer_data(int fd, accelerometer_data_t *data);
int read_magnetometer_data(int fd, magnetometer_data_t *data);
void interrupt_handler(int signum);
void dump_buffer();
void signal_handler(int signum);

// Function to initialize I2C
int init_i2c(int addr) {
    int fd = i2c_open(1, addr, 0); // Bus 1, address, flags
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to verify the device ID
int verify_device_id(int fd) {
    int id = i2c_smbus_read_byte_data(fd, 0x0F); // Read device ID
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x33) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", id);
        return -1;
    }
    return 0;
}

// Function to initialize the accelerometer
int init_accelerometer(int fd) {
    // Enable accelerometer, 50 Hz data rate, +/- 2g range
    if (i2c_smbus_write_byte_data(fd, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2c_smbus_write_byte_data(fd, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, accelerometer_data_t *data) {
    int16_t x, y, z;

    x = i2c_smbus_read_byte_data(fd, OUT_X_L_A) | (i2c_smbus_read_byte_data(fd, OUT_X_L_A + 1) << 8);
    if (x < 0) {
        fprintf(stderr, "Error reading OUT_X_L_A: %s\n", strerror(errno));
        return -1;
    }
