#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the solenoids
#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27

// Function prototypes
int initialize_gpio();
int activate_solenoid(int gpio);
int deactivate_solenoid(int gpio);
void signal_handler(int signal);

// Global variable to track the active solenoid GPIO
int active_solenoid_gpio = -1;

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Activate solenoid 1
        if (activate_solenoid(SOLENOID1_GPIO) != 0) {
            fprintf(stderr, "Failed to activate solenoid 1.\n");
            break; // Exit the loop on error
        }
        active_solenoid_gpio = SOLENOID1_GPIO;

        // Delay for 500ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500ms
        nanosleep(&delay, NULL);

        // Deactivate solenoid 1
        if (deactivate_solenoid(SOLENOID1_GPIO) != 0) {
            fprintf(stderr, "Failed to deactivate solenoid 1.\n");
            break; // Exit the loop on error
        }

        // Activate solenoid 2
        if (activate_solenoid(SOLENOID2_GPIO) != 0) {
            fprintf(stderr, "Failed to activate solenoid 2.\n");
            break; // Exit the loop on error
        }
        active_solenoid_gpio = SOLENOID2_GPIO;

        // Delay for 500ms
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500ms
        nanosleep(&delay, NULL);

        // Deactivate solenoid 2
        if (deactivate_solenoid(SOLENOID2_GPIO) != 0) {
            fprintf(stderr, "Failed to deactivate solenoid 2.\n");
            break; // Exit the loop on error
        }
    }

    // Cleanly terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an output
    if (gpioSetMode(SOLENOID1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID1_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as an output
    if (gpioSetMode(SOLENOID2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Ensure both solenoids are initially deactivated (LOW)
    gpioWrite(SOLENOID1_GPIO, 0);
    gpioWrite(SOLENOID2_GPIO, 0);

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to write HIGH to GPIO%d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", gpio);
        return 1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate both solenoids
    deactivate_solenoid(SOLENOID1_GPIO);
    deactivate_solenoid(SOLENOID2_GPIO);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

