#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout duration (in milliseconds)
#define TIMEOUT_MS 5000

// Define retry delay (in milliseconds)
#define RETRY_DELAY_MS 100

// Define retry limit
#define RETRY_LIMIT 3

// Define GPIO pin for LED (optional)
#define LED_PIN 22 // BCM GPIO22

// Global variables
static volatile int keepRunning = 1;
static int serial1_fd = -1;
static int serial2_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_uart(const char *port);
int read_code(int fd, char *buffer, int buffer_size);
int validate_code(const char *code, const char *expected_code);
void control_relay(int lock_pin, int state);
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize UART
int init_uart(const char *port) {
    int fd = serialOpen(port, 9600);
    if (fd < 0) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Error opening UART %s: %s", port, strerror(errno));
        log_message(error_message);
        return -1;
    }
    return fd;
}

// Function to read code from UART with timeout
int read_code(int fd, char *buffer, int buffer_size) {
    int i = 0;
    int timeout_counter = 0;
    int bytes_read;

    while (i < buffer_size - 1 && timeout_counter < TIMEOUT_MS) {
        bytes_read = serialGetchar(fd);
        if (bytes_read > 0) {
            buffer[i++] = (char)bytes_read;
            if (buffer[i-1] == '\n') {
                buffer[i] = '\0';
                i++;
                return 0; // Success
            }
        } else {
            if (bytes_read < 0) {
                char error_message[256];
                snprintf(error_message, sizeof(error_message), "Error reading from UART %s: %s", port, strerror(errno));
                log_message(error_message);
                return -1; // Error
            }
            timeout_counter++;
            delay(RETRY_DELAY_MS);
        }
    }

    if (i >= buffer_size - 1) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Timeout reading from UART %s", port);
        log_message(error_message);
        return -1; // Timeout
    }

    return -1; // Not enough data
}

// Function to validate code
int validate_code(const char *code, const char *expected_code) {
    if (strcmp(code, expected_code) == 0) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

