    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file); // Ensure immediate write
    }
    fprintf(stderr, "%s\n", message);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    keepRunning = 0;
    log_message("Received signal, shutting down...");
}

