void cleanup() {
    log_message("Cleaning up...");
    control_relay(LOCK1_PIN, LOW);
    control_relay(LOCK2_PIN, LOW);

    if (serial1_fd != -1) {
        serialClose(serial1_fd);
    }
    if (serial2_fd != -1) {
        serialClose(serial2_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    wiringPiSetup(); // Reinitialize wiringPi to ensure GPIOs are reset
    pinMode(LOCK1_PIN, INPUT); // Set pins to input to avoid spurious output
    pinMode(LOCK2_PIN, INPUT);
    pinMode(LED_PIN, INPUT);

    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins to output mode
    pinMode(LOCK1_PIN, OUTPUT);
    pinMode(LOCK2_PIN, OUTPUT);
    pinMode(LED_PIN, OUTPUT);

    // Initialize UART ports
    serial1_fd = init_uart(UART1_PORT);
    serial2_fd = init_uart(UART2_PORT);

    if (serial1_fd == -1 || serial2_fd == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("door_lock.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

