            code1_valid = 0;
        }

        if (read2_result == 0) {
            code2_valid = 1;
            log_message("Code 2 received");
        } else if (read2_result < 0) {
            code2_valid = 0;
        }

        // Validate codes
        if (code1_valid && code2_valid) {
            if (validate_code(code1_buffer, EXPECTED_CODE) == 0 && validate_code(code2_buffer, EXPECTED_CODE) == 0) {
                log_message("Codes match, unlocking door...");
