#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 200
#define FAILSAFE_TIMEOUT_S 10
#define RELAY_ON_TIME_S 1
#define LOG_FILE "/var/log/motion_sensor.log"

// Global variables
static volatile int running = 1;
static int relay_state = 0; // 0 = LOW, 1 = HIGH
static int failsafe_timer_id = 0;
static int log_fd = -1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int state);
void log_event(const char *message);
void log_relay_event(const char *message);
void failsafe_callback();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set PIR sensor pin as input");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin as output");
        gpioTerminate();
        return -1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to LOW

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to relay pin");
    }
    relay_state = state;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

// Function to log relay events to syslog
void log_relay_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

// Failsafe callback function
void failsafe_callback() {
    log_event("Failsafe triggered: Motion detected continuously for too long.");
    log_relay_event("Failsafe triggered: Motion detected continuously for too long.");
    control_relay(0); // De-energize the relay
    syslog(LOG_WARNING, "Failsafe triggered: Motion detected continuously for too long.");
    signal_handler(SIGTERM); // Simulate a shutdown signal
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    control_relay(0); // Ensure relay is off
    if (failsafe_timer_id > 0) {
        gpioSetTimerFuncEx(0, 0, failsafe_callback, NULL); // Cancel the timer
    }
    gpioTerminate();
    if (log_fd != -1) {
        close(log_fd);
    }
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("motion_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file");
        cleanup();
        return 1;
    }

    // Set up timer for failsafe
    failsafe_timer_id = gpioSetTimerFuncEx(0, DEBOUNCE_DELAY_MS, failsafe_callback, NULL);
    if (failsafe_timer_id == 0) {
        syslog(LOG_ERR, "Failed to set failsafe timer");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Motion sensor monitoring started");

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            log_event("Motion detected");
            log_relay_event("Motion detected");
            control_relay(1); // Activate relay
            gpioDelay(RELAY_ON_TIME_S * 1000000); // Wait for relay time
            control_relay(0); // De-energize relay
            gpioDelay(100000); // Small delay after relay action
        }

        gpioDelay(50000); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

