#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/timerfd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Configuration
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_SCALE 16384.0f // Sensitivity scale factor
#define BUFFER_SIZE 100
#define SAMPLE_RATE 100 // Hz
#define TIMER_PERIOD_NS (1000000000 / SAMPLE_RATE) // Period in nanoseconds

// Global variables
static int i2c_fd = -1;
static int timer_fd = -1;
static int buffer_index = 0;
static int buffer_size = BUFFER_SIZE;
static int running = 1;

// Structure for accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Function prototypes
int init_i2c(int address);
int read_accel_data(int fd, AccelData *data);
int write_data_to_driver(AccelData data);
void timer_callback(int signum);
void signal_handler(int signum);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read accelerometer data
int read_accel_data(int fd, AccelData *data) {
    char buf[6];
    int16_t x, y, z;

    if (read(fd, buf, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    x = (int16_t)((buf[0] << 8) | buf[1]);
    y = (int16_t)((buf[2] << 8) | buf[3]);
    z = (int16_t)((buf[4] << 8) | buf[5]);

    data->x = (float)x / ACCEL_SCALE;
    data->y = (float)y / ACCEL_SCALE;
    data->z = (float)z / ACCEL_SCALE;

    return 0;
}

// Function to write data to the driver interface
int write_data_to_driver(AccelData data) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%.6f,%.6f,%.6f", data.x, data.y, data.z);

    FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (fp == NULL) {
        perror("Error opening driver interface file");
        return -1;
    }

    if (fputs(buffer, fp) == EOF) {
        perror("Error writing to driver interface file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Timer callback function
void timer_callback(int signum) {
    AccelData data;
    if (read_accel_data(i2c_fd, &data) == 0) {
        if (write_data_to_driver(data) != 0) {
            fprintf(stderr, "Error writing data to driver\n");
        }
        buffer_index = (buffer_index + 1) % buffer_size;
    } else {
        fprintf(stderr, "Error reading accelerometer data in timer callback\n");
    }
}

// Signal handler function
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (timer_fd != -1) {
        // Cancel the timer
        struct itimerspec its;
        its.it_value.tv_sec = 0;
        its.it_value.tv_nsec = 0;
        its.it_interval.tv_sec = 0;
        its.it_interval.tv_nsec = 0;
        ioctl(timer_fd, TIMER_SETTIME, &its);

        close(timer_fd);
    }

    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Create timer
    timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("Error creating timer");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set timer interval
    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = TIMER_PERIOD_NS;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = TIMER_PERIOD_NS;
    if (ioctl(timer_fd, TIMER_SETTIME, &its) < 0) {
        perror("Error setting timer interval");
        close(timer_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct sigevent sev;
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGEV_SIGNAL;
    sev.sigev_value.sival_ptr = &timer_fd;

    if (timer_create(CLOCK_REALTIME, &sev, timer_fd) < 0) {
        perror("Error creating timer event");
        close(timer_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        pause(); // Wait for a signal
    }

    // Cleanup resources
    cleanup();

    printf("MPU6050 data acquisition stopped.\n");

    return 0;
}

