#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define intervals in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially off
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    return 0; // Indicate success
}

// Function to turn a relay on
void turn_relay_on(int pin) {
    gpioWrite(pin, 1);
}

// Function to turn a relay off
void turn_relay_off(int pin) {
    gpioWrite(pin, 0);
}

// Function to delay for a specified interval
void delay_interval(int interval) {
    struct timespec ts;
    ts.tv_sec = interval;
    ts.tv_nsec = 0;
    nanosleep(&ts, NULL);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Relay 1
        turn_relay_on(RELAY1_PIN);
        delay_interval(INTERVAL1);
        turn_relay_off(RELAY1_PIN);

        // Relay 2
        turn_relay_on(RELAY2_PIN);
        delay_interval(INTERVAL2);
        turn_relay_off(RELAY2_PIN);

        // Relay 3
        turn_relay_on(RELAY3_PIN);
        delay_interval(INTERVAL3);
        turn_relay_off(RELAY3_PIN);

        // Relay 4
        turn_relay_on(RELAY4_PIN);
        delay_interval(INTERVAL4);
        turn_relay_off(RELAY4_PIN);
    }

    // Clean up GPIO before exiting
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");

    return 0;
}

