    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially off
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    return 0; // Indicate success
}

// Function to turn a relay on
void turn_relay_on(int pin) {
    gpioWrite(pin, 1);
}

// Function to turn a relay off
void turn_relay_off(int pin) {
    gpioWrite(pin, 0);
}

// Function to delay for a specified interval
void delay_interval(int interval) {
    struct timespec ts;
    ts.tv_sec = interval;
    ts.tv_nsec = 0;
    nanosleep(&ts, NULL);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Relay 1
        turn_relay_on(RELAY1_PIN);
        delay_interval(INTERVAL1);
        turn_relay_off(RELAY1_PIN);

        // Relay 2
        turn_relay_on(RELAY2_PIN);
