#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define GPIO_TXD 14
#define GPIO_RXD 15
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_SEC 1
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// MH-Z19B Command Sequence (CO2 only)
const unsigned char co2_command[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and configuration
typedef struct {
    int uart_fd;
    FILE *log_file;
    FILE *error_log_file;
    int gpio_tx_d;
    int gpio_rx_d;
    char *uart_device;
    int baud_rate;
    int sample_interval;
    int timeout;
    int max_retries;
} sensor_config_t;

// Function prototypes
int init_uart(sensor_config_t *config);
int read_sensor_data(sensor_config_t *config, unsigned char *data, int max_retries);
int validate_checksum(const unsigned char *data, int length);
int parse_co2_data(const unsigned char *data, int length, float *co2_ppm, int *error_flag);
int log_data(sensor_config_t *config, float co2_ppm, int error_flag);
int log_error(sensor_config_t *config, const char *message);
void signal_handler(int signal);
void cleanup(sensor_config_t *config);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize UART
int init_uart(sensor_config_t *config) {
    struct termios tty;

    // Open UART
    uart_fd = open(config->uart_device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    // Configure UART
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, config->baud_rate);
    cfsetispeed(&tty, config->baud_rate);

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

// Read sensor data with retry
int read_sensor_data(sensor_config_t *config, unsigned char *data, int max_retries) {
    int retries = 0;
    int bytes_read;
    fd_set readfds;
    struct timeval timeout;

    while (retries < max_retries) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = config->timeout;
        timeout.tv_usec = 0;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("Error in select");
            return -1;
        } else if (select_result == 0) {
            // Timeout occurred
            log_error(config, "Timeout reading from UART");
            return -1;
        } else {
            // Data is available
            bytes_read = read(uart_fd, data, sizeof(data));
            if (bytes_read == sizeof(data)) {
                return 0; // Success
            } else {
                log_error(config, "Error reading from UART (read %d bytes, expected %d)", bytes_read, sizeof(data));
                retries++;
                usleep(config->retry_delay_ms * 1000); // Exponential backoff
            }
        }
    }

    log_error(config, "Max retries reached while reading from UART");
    return -1; // Failure
}

// Validate checksum
int validate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = data[length - 1];
    unsigned char calculated_checksum = 0;
    for (int i = 0; i < length - 1; i++) {
        calculated_checksum += data[i];
    }
    return (checksum == calculated_checksum);
}

// Parse CO2 data
int parse_co2_data(const unsigned char *data, int length, float *co2_ppm, int *error_flag) {
    if (length != 9) {
        log_error(NULL, "Invalid data length (expected 9 bytes)");
        return -1;
    }

    // Extract CO2 value and checksum
    int co2_value = (data[0] << 8) | data[1];
    unsigned char checksum = data[8];

    // Validate checksum
    if (!validate_checksum(data, length)) {
        log_error(NULL, "Checksum mismatch");
        return -1;
