// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for LED control
#define LED_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold compensated heading data
typedef struct {
    float heading;
} compensated_heading_t;

// Structure for circular buffer entry
typedef struct {
    compensated_heading_t data;
} buffer_entry_t;

// Circular buffer
buffer_entry_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C file descriptor
int i2c_fd;

// Function prototypes
int init_hmc5883l();
magnetometer_data_t read_magnetometer_data();
compensated_heading_t compensate_heading(magnetometer_data_t raw_data);
void store_heading(compensated_heading_t heading);
bool check_heading_deviation(compensated_heading_t heading);
void control_led(bool deviate);
void signal_handler(int signal);

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Set configuration register A: 8-average, 15 Hz, normal measurement
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B: Gain = 1.3 Ga
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register: Continuous measurement mode
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    int x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;

    x_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_X_MSB);
    x_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_X_LSB);
    z_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Z_MSB);
    z_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Z_LSB);
    y_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Y_MSB);
    y_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Y_LSB);

    if (x_msb < 0 || x_lsb < 0 || z_msb < 0 || z_lsb < 0 || y_msb < 0 || y_lsb < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((x_msb << 8) | x_lsb);
    data.z = (int16_t)((z_msb << 8) | z_lsb);
    data.y = (int16_t)((y_msb << 8) | y_lsb);

    return data;
}

// Function to compensate heading
compensated_heading_t compensate_heading(magnetometer_data_t raw_data) {
    compensated_heading_t heading;
    float x = (float)raw_data.x;
    float y = (float)raw_data.y;
    float z = (float)raw_data.z;

    // Hard-iron compensation
    float x_comp = x - 100.0;
    float y_comp = y + 50.0;

    // Calculate heading in degrees
    heading.heading = atan2(y_comp, x_comp) * 180.0 / M_PI;

    // Normalize to 0-360 degrees
    if (heading.heading < 0) {
        heading.heading += 360.0;
    }

    return heading;
}

// Function to store heading in circular buffer
void store_heading(compensated_heading_t heading) {
    circular_buffer[buffer_index].data = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check heading deviation
bool check_heading_deviation(compensated_heading_t heading) {
    float deviation = fabs(heading.heading - TARGET_HEADING);
    return (deviation > 10.0);
}

// Function to control LED
void control_led(bool deviate) {
    digitalWrite(LED_PIN, deviate ? HIGH : LOW);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(i2c_fd); // Close I2C connection
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(HMC5883L_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C\n");
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() == -1) {
        fprintf(stderr, "Error initializing HMC5883L\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
