// Function to initialize I2C communication
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C for address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read data from BH1750 sensor
int read_bh1750(int fd) {
    int raw_value;
    int retries = I2C_RETRIES;

    while (retries > 0) {
        // Send start measurement command (High Resolution Mode)
        if (wiringPiI2CWrite(fd, 0x10) == -1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            delay(I2C_DELAY_MS);
            continue;
        }

        delay(180); // Wait for measurement (at least 180ms)

        // Read two bytes of data
        raw_value = wiringPiI2CReadReg16(fd, 0x00);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries--;
            delay(I2C_DELAY_MS);
            continue;
        }

        // Byte swap (BH1750 returns data in big-endian format)
        raw_value = (raw_value >> 8) | (raw_value << 8);

        return raw_value;
    }

    fprintf(stderr, "Failed to read from BH1750 after %d retries.\n", I2C_RETRIES);
    return -1; // Indicate failure
