#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Distance threshold (50 cm)
#define DISTANCE_THRESHOLD 50

// Proportional gain
#define PROPORTIONAL_GAIN 0.5

// Global variables for distance readings
float distance_a = 0.0;
float distance_b = 0.0;

// Function prototypes
void motor_a_forward(int duty_cycle);
void motor_a_backward(int duty_cycle);
void motor_b_forward(int duty_cycle);
void motor_b_backward(int duty_cycle);
void stop_motors();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Motor A forward
void motor_a_forward(int duty_cycle) {
    if (gpioWrite(MOTOR_A_IN1, 1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_A_IN1);
    }
    if (gpioWrite(MOTOR_A_IN2, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_A_IN2);
    }
    if (gpioPWM(MOTOR_A_IN2, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_A_IN2);
    }
}

// Motor A backward
void motor_a_backward(int duty_cycle) {
    if (gpioWrite(MOTOR_A_IN1, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_A_IN1);
    }
    if (gpioWrite(MOTOR_A_IN2, 1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_A_IN2);
    }
    if (gpioPWM(MOTOR_A_IN2, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_A_IN2);
    }
}

// Motor B forward
void motor_b_forward(int duty_cycle) {
    if (gpioWrite(MOTOR_B_IN3, 1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_B_IN3);
    }
    if (gpioWrite(MOTOR_B_IN4, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_B_IN4);
    }
    if (gpioPWM(MOTOR_B_IN4, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_B_IN4);
    }
}

// Motor B backward
void motor_b_backward(int duty_cycle) {
    if (gpioWrite(MOTOR_B_IN3, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_B_IN3);
    }
    if (gpioWrite(MOTOR_B_IN4, 1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_B_IN4);
    }
    if (gpioPWM(MOTOR_B_IN4, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_B_IN4);
    }
}

// Stop motors
void stop_motors() {
    if (gpioWrite(MOTOR_A_IN1, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_A_IN1);
    }
    if (gpioWrite(MOTOR_A_IN2, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_A_IN2);
    }
    if (gpioPWM(MOTOR_A_IN2, 0) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_A_IN2);
    }

    if (gpioWrite(MOTOR_B_IN3, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_B_IN3);
    }
    if (gpioWrite(MOTOR_B_IN4, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", MOTOR_B_IN4);
    }
    if (gpioPWM(MOTOR_B_IN4, 0) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_B_IN4);
    }
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR_A_IN1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR_A_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR_B_IN3);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR_B_IN4);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", MOTOR_A_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", MOTOR_B_IN4);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read distance values
        distance_a = 10.0 + (float)(rand() % 91); // Simulate distance between 10 and 100 cm
        distance_b = 10.0 + (float)(rand() % 91); // Simulate distance between 10 and 100 cm

        // Control motors based on distance
        if (distance_a < DISTANCE_THRESHOLD) {
            motor_a_forward(255);
            motor_b_forward(255);
        } else if (distance_b < DISTANCE_THRESHOLD) {
            motor_a_backward(255);
            motor_b_backward(255);
        } else {
            stop_motors();
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    return 0;
}

