#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define SERVO_PIN 18
#define PWM_PERIOD 20000 // microseconds
#define PWM_DUTY_CYCLE 1000 // microseconds
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int set_servo_angle(float pitch, float roll);
int log_data(float pitch, float roll, int position);
void signal_handler(int signal);

// I2C initialization function
int init_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// MPU6050 initialization function
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, MPU6050_PWR_MGMT_1, 0) < 0) {
        perror("Error writing to MPU6050");
        return -1;
    }

    return 0;
}

// Function to read raw accelerometer and gyroscope data from MPU6050
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];

    if (i2c_smbus_read_i2c_block_data(i2c_fd, MPU6050_ACCEL_XOUT_H, buf, 14) < 0) {
        perror("Error reading MPU6050 data");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Function to calculate pitch angle
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    return pitch;
}

// Function to calculate roll angle
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
    return roll;
}

// Function to set servo angle using pigpio
int set_servo_angle(float pitch, float roll) {
    // Map pitch and roll to PWM duty cycle (0-1000000)
    int duty_cycle = (int)((pitch + roll) / 180.0 * 1000000.0);

    // Set PWM period and duty cycle
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioPWM(SERVO_PIN, duty_cycle);

    return 0;
}

// Function to log data to file
int log_data(float pitch, float roll, int position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int position;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch(accel_x, accel_y, accel_z);
            roll = calculate_roll(accel_x, accel_y, accel_z);

            // Set servo angle
            set_servo_angle(pitch, roll);

            // Simulate position sensor reading (replace with actual sensor reading)
            position = (int)(pitch * 10 + roll * 5); // Example calculation

            // Log data
            log_data(pitch, roll, position);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            // Exponential backoff retry
            int retries = 3;
            int delay_ms = 100;
            while (retries > 0 && !terminate) {
                if (init_i2c() == 0 && init_mpu6050() == 0) {
                    read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "I2C initialization failed. Retrying in %d ms...\n", delay_ms);
                    retries--;
                    delay(delay_ms);
                    delay_ms *= 2; // Exponential backoff
                }
            }
            if (retries == 0) {
                fprintf(stderr, "Failed to recover from I2C errors after multiple retries.\n");
            }
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

