#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the PWM frequency in Hz
#define PWM_FREQUENCY 100

// Define the number of PWM steps
#define PWM_STEPS 100

// Define the number of seconds to check the schedule file
#define SCHEDULE_CHECK_INTERVAL 1

// Structure to represent a relay
typedef struct {
    int gpio_pin;
    int relay_number;
    int on;
    int off;
    int current_duty_cycle;
} Relay;

// Global variables
Relay relays[4];
int num_relays = 4;
FILE *schedule_file = NULL;
pthread_mutex_t schedule_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t relay_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int initialize_gpio();
int read_schedule_file();
void fade_relay(int relay_number, int target_duty_cycle);
void control_relay(int relay_number, int on);
void signal_handler(int signal);
void log_message(const char *message);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize relays
    relays[0].gpio_pin = RELAY1_GPIO;
    relays[0].relay_number = 1;
    relays[0].on = 0;
    relays[0].off = 0;
    relays[0].current_duty_cycle = 0;

    relays[1].gpio_pin = RELAY2_GPIO;
    relays[1].relay_number = 2;
    relays[1].on = 0;
    relays[1].off = 0;
    relays[1].current_duty_cycle = 0;

    relays[2].gpio_pin = RELAY3_GPIO;
    relays[2].relay_number = 3;
    relays[2].on = 0;
    relays[2].off = 0;
    relays[2].current_duty_cycle = 0;

    relays[3].gpio_pin = RELAY4_GPIO;
    relays[3].relay_number = 4;
    relays[3].on = 0;
    relays[3].off = 0;
    relays[3].current_duty_cycle = 0;

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    return 0;
}

// Function to read the schedule file
int read_schedule_file() {
    pthread_mutex_lock(&schedule_mutex);
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        log_message("Error opening schedule file");
        pthread_mutex_unlock(&schedule_mutex);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        // Parse the line
        char *token = strtok(line, ";");
        if (token != NULL) {
            char *time_str = strtok(token, ",");
            if (time_str != NULL) {
                char *hour_str = strtok(time_str, ":");
                if (hour_str != NULL) {
                    char *minute_str = strtok(hour_str, ":");
                    if (minute_str != NULL) {
                        char *second_str = strtok(minute_str, ":");
                        if (second_str != NULL) {
                            int hour, minute, second;
