#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
int echo_start_tick = 0;
int echo_end_tick = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_width);
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down...\n");
        gpioPWM(BUZZER_PIN, 0); // Stop PWM
        gpioTerminate();       // Terminate pigpio
        program_running = 0;
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulseIn(int pin, int level, int timeout) {
    long start = gpioTick();
    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout) {
            return 0; // Timeout
        }
    }
    long pulse_start = gpioTick();
    while (gpioRead(pin) == level) {
        if (gpioTick() - pulse_start > timeout) {
            return 0; // Timeout
        }
    }
    return gpioTick() - pulse_start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width <= 0) {
        return MAX_DISTANCE; // Return max distance on error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY; // Map min distance to max frequency
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY; // Map max distance to min frequency
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency using PWM
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: Frequency out of range (%f Hz)\n", frequency);
        return;
    }
    int range = 1000000; // PWM range
    int duty_cycle = (int)((frequency / MAX_FREQUENCY) * range); // Calculate duty cycle
    gpioPWM(BUZZER_PIN, duty_cycle); // Set PWM duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_width = pulseIn(ECHO_PIN, 1, TIMEOUT_US);
        if (pulse_width == 0) {
            fprintf(stderr, "Error: Timeout waiting for echo\n");
            gpioDelay(60000); // Wait 60ms before retrying
            continue;
        }

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to a frequency
        float frequency = mapDistanceToFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Delay to avoid excessive CPU usage
        gpioDelay(20000); // 20ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio

    return 0;
}

