    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Ensure red, green, and blue values are within the valid range
    if (red < 0) red = 0;
    if (red > PWM_RANGE) red = PWM_RANGE;
    if (green < 0) green = 0;
    if (green > PWM_RANGE) green = PWM_RANGE;
    if (blue < 0) blue = 0;
    if (blue > PWM_RANGE) blue = PWM_RANGE;

    // Set PWM duty cycle for each color
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to simulate proximity value using a sine wave
float simulate_proximity() {
    // Simulate proximity value between 0.0 and 1.0 using a sine wave
    float proximity = 0.5 + 0.5 * sin(2.0 * M_PI * 0.1 * time(NULL)); // Time is in seconds
    if (proximity < 0.0) proximity = 0.0;
    if (proximity > 1.0) proximity = 1.0;
    return proximity;
}

