    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate proximity value
        float proximity = simulate_proximity();

        // Set LED color based on proximity value
        set_led_color((int)(proximity * 255.0), (int)(proximity * 255.0), (int)(proximity * 255.0));

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

