#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_TIMEOUT_MS 1000
#define WINDOW_SIZE 5
#define ALERT_THRESHOLD 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = POLL_TIMEOUT_MS;
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default value: %d ms\n", POLL_TIMEOUT_MS);
            poll_timeout_ms = POLL_TIMEOUT_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    FILE *log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int events[WINDOW_SIZE] = {0};
    int event_index = 0;
    time_t last_event_time = 0;

    while (program_running) {
        int raw_value = gpioRead(GPIO_PIN);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading GPIO pin!\n");
            break;
        }

        time_t current_time = time(NULL);
        if (current_time - last_event_time >= (double)poll_timeout_ms / 1000.0) {
            events[event_index] = raw_value;
            event_index = (event_index + 1) % WINDOW_SIZE;
            last_event_time = current_time;

            if (event_index == 0) {
                int count = 0;
                for (int i = 0; i < WINDOW_SIZE; i++) {
                    if (events[i] == 1) {
                        count++;
                    }
                }

                if (count >= ALERT_THRESHOLD) {
                    time_t now = time(NULL);
                    struct tm *tstruct = localtime(&now);
                    char buf[80];
                    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

                    printf("EARTHQUAKE ALERT: %s\n", buf);

                    for (int i = 0; i < WINDOW_SIZE; i++) {
                        fprintf(log_file, "%s,%d\n", buf, events[i]);
                        fflush(log_file);
                    }
                }
            }
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

