        time_t current_time = time(NULL);
        if (current_time - last_event_time >= (double)poll_timeout_ms / 1000.0) {
            events[event_index] = raw_value;
            event_index = (event_index + 1) % WINDOW_SIZE;
            last_event_time = current_time;

            if (event_index == 0) {
                int count = 0;
                for (int i = 0; i < WINDOW_SIZE; i++) {
                    if (events[i] == 1) {
                        count++;
                    }
                }

                if (count >= ALERT_THRESHOLD) {
                    time_t now = time(NULL);
                    struct tm *tstruct = localtime(&now);
                    char buf[80];
                    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

                    printf("EARTHQUAKE ALERT: %s\n", buf);

                    for (int i = 0; i < WINDOW_SIZE; i++) {
                        fprintf(log_file, "%s,%d\n", buf, events[i]);
                        fflush(log_file);
                    }
                }
            }
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

