#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_L_M 0x03
#define OUT_X_H_M 0x04
#define OUT_Y_L_M 0x05
#define OUT_Y_H_M 0x06
#define OUT_Z_L_M 0x07
#define OUT_Z_H_M 0x08

// Hard iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Heading calculation constants
#define PI 3.14159265359

// Global variables
int fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t x, int16_t y, int16_t z);
char *get_compass_direction(float heading);
void log_data(int16_t x, int16_t y, int16_t z, float heading, char *direction);
void print_data(int16_t x, int16_t y, int16_t z, float heading, char *direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize the magnetometer
int init_magnetometer() {
    // Set to continuous conversion mode
    if (wiringPiI2CWriteReg8(fd, CRA_REG_M, 0x18) < 0) { // 0x18 = 10000000 (1000 Hz, 8 samples averaged)
        fprintf(stderr, "Error writing to CRA_REG_M: %s\n", strerror(errno));
        return -1;
    }

    // Set to continuous conversion mode
    if (wiringPiI2CWriteReg8(fd, MR_REG_M, 0x00) < 0) { // 0x00 = Continuous conversion mode
        fprintf(stderr, "Error writing to MR_REG_M: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = wiringPiI2CReadReg8(fd, OUT_X_L_M);
    x_h = wiringPiI2CReadReg8(fd, OUT_X_H_M);
    y_l = wiringPiI2CReadReg8(fd, OUT_Y_L_M);
    y_h = wiringPiI2CReadReg8(fd, OUT_Y_H_M);
    z_l = wiringPiI2CReadReg8(fd, OUT_Z_L_M);
    z_h = wiringPiI2CReadReg8(fd, OUT_Z_H_M);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Calibrate the raw data
void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = x - X_OFFSET;
    *calibrated_y = y - Y_OFFSET;
    *calibrated_z = z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2(y, x) * 180 / PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Get compass direction
char *get_compass_direction(float heading) {
    if (heading >= 337.5 && heading <= 0) {
        return "N";
    } else if (heading >= 337.5 - 45 && heading < 337.5) {
        return "NE";
    } else if (heading >= 337.5 - 90 && heading < 337.5 - 45) {
        return "E";
    } else if (heading >= 337.5 - 135 && heading < 337.5 - 90) {
        return "SE";
    } else if (heading >= 337.5 - 180 && heading < 337.5 - 135) {
        return "S";
    } else if (heading >= 337.5 - 225 && heading < 337.5 - 180) {
        return "SW";
    } else if (heading >= 337.5 - 270 && heading < 337.5 - 225) {
        return "W";
    } else if (heading >= 337.5 - 315 && heading < 337.5 - 270) {
        return "NW";
    } else {
        return "Invalid";
    }
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float heading, char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %s\n", timestamp, x, y, z, heading, direction);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print data to console
void print_data(int16_t x, int16_t y, int16_t z, float heading, char *direction) {
    printf("Timestamp: %s, X: %d, Y: %d, Z: %d, Heading: %.2f, Direction: %s\n", __TIME__, x, y, z, heading, direction);
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    int16_t calibrated_x, calibrated_y, calibrated_z;
    float heading;
    char *direction;

    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    fd = wiringPiI2CSetup(LSM303_ADDR);
    if (fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() == -1) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }
    fflush(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate the data
            calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y, calibrated_z);

            // Get compass direction
            direction = get_compass_direction(heading);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z, heading, direction);

            // Print data
            print_data(calibrated_x, calibrated_y, calibrated_z, heading, direction);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping this sample.\n");
        }

        // Wait for 1 second
        delay(1000);
    }

    // Close log file
    fclose(log_file);

    return 0;
}

