#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <jansson.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define relay state
#define RELAY_OFF 0
#define RELAY_ON 1

// Global variables
static volatile int relay_state = RELAY_OFF;
static volatile unsigned long last_touch_time = 0;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, unsigned int tick, void *userdata);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int touch_pin;
    int relay_pin;
    int debounce_time;
} config_t;

// Configuration
config_t config = {TOUCH_SENSOR_PIN, RELAY_PIN, DEBOUNCE_TIME};

int main() {
    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Toggle the relay
        if (toggle_relay() != 0) {
            fprintf(stderr, "Failed to toggle relay. Continuing.\n");
        }

        // Sleep for a short period
        gpioDelay(100); // 100ms
    }

    // Cleanup and exit
    gpioWrite(config.relay_pin, RELAY_OFF);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(config.touch_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", config.touch_pin);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(config.relay_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", config.relay_pin);
        gpioTerminate();
        return 1;
    }

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(config.touch_pin, PI_PUD_DOWN);

    // Register interrupt handler for touch sensor
    if (gpioSetISRFuncEx(config.touch_pin, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO %d\n", config.touch_pin);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, unsigned int tick, void *userdata) {
    unsigned long current_time = gpioTick();

    // Debounce the touch sensor
    if (current_time - last_touch_time > config.debounce_time * 1000) {
        relay_state = !relay_state; // Toggle relay state
        gpioWrite(config.relay_pin, relay_state);
        last_touch_time = current_time;
    }
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(config.relay_pin, relay_state);
    return 0;
}

// Log relay state to JSON file
int log_relay_state(int state) {
    json_t *root, *timestamp, *relay_state_json;
    char timestamp_str[30];
    time_t rawtime;
    struct tm *info;
    FILE *fp;

    // Get current timestamp
    time(&rawtime);
    info = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", info);

    // Create JSON object
    root = json_object();
    if (!root) {
        fprintf(stderr, "Failed to create JSON object\n");
        return 1;
    }

    // Create relay_state_json
    relay_state_json = json_string(state == RELAY_ON ? "ON" : "OFF");
    if (!relay_state_json) {
        fprintf(stderr, "Failed to create relay_state_json\n");
        json_decref(root);
        return 1;
    }

    // Add relay_state_json to root
    json_object_set_new(root, "relay_state", relay_state_json);

    // Add timestamp to root
    timestamp = json_string(timestamp_str);
    if (!timestamp) {
        fprintf(stderr, "Failed to create timestamp\n");
        json_decref(root);
        return 1;
    }
    json_object_set_new(root, "timestamp", timestamp);

    // Write JSON object to file
    fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open relay_log.json for writing\n");
        json_decref(root);
        return 1;
    }

    // Check if the file is empty, if so, add the opening bracket
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "[");
    } else {
        // If not empty, go back one character and overwrite the closing bracket
        fseek(fp, -1, SEEK_END);
        char last_char;
        fread(&last_char, 1, 1, fp);
        if (last_char == ']') {
            fseek(fp, -1, SEEK_END);
            fprintf(fp, ",");
        } else {
            fprintf(fp, ",");
        }
    }

    // Write JSON object to file
    char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
    if (!json_str) {
        fprintf(stderr, "Failed to serialize JSON object\n");
        fclose(fp);
        json_decref(root);
        return 1;
    }
    fprintf(fp, "%s", json_str);
    fclose(fp);

    // Clean up
    json_decref(root);
    free(json_str);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Force relay OFF
    gpioWrite(config.relay_pin, RELAY_OFF);

    // Log final state
    log_relay_state(RELAY_OFF);

    // Cleanup pigpio
    gpioTerminate();

    exit(0);
}

