#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture levels
#define MOISTURE_LOW 20
#define MOISTURE_MEDIUM 50
#define MOISTURE_HIGH 100

// Define servo pulse width limits (in microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define watering cycle duration (seconds)
#define WATERING_DURATION 5

// Define servo sweep duration (seconds)
#define SERVO_SWEEP_DURATION 2

// Define retry attempts for servo control
#define SERVO_RETRIES 3

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int set_servo_angle(int gpio_pin, int angle);
int open_valve(int gpio_pin);
int close_valve(int gpio_pin);
int water_plant(int moisture_level);
void signal_handler(int signal);

// Function to set servo angle
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return -1;
    }

    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);
    return gpioServo(gpio_pin, pulse_width);
}

// Function to open the valve
int open_valve(int gpio_pin) {
    int retries = 0;
    int result;

    while (retries < SERVO_RETRIES) {
        result = set_servo_angle(gpio_pin, 90);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to open valve (attempt %d): %d\n", retries + 1, result);
            gpioDelay(100 * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Critical Warning: Failed to open valve after %d retries.\n", SERVO_RETRIES);
    return -1; // Failure
}

// Function to close the valve
int close_valve(int gpio_pin) {
    int retries = 0;
    int result;

    while (retries < SERVO_RETRIES) {
        result = set_servo_angle(gpio_pin, 0);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to close valve (attempt %d): %d\n", retries + 1, result);
            gpioDelay(100 * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Critical Warning: Failed to close valve after %d retries.\n", SERVO_RETRIES);
    return -1; // Failure
}

// Function to water the plant
int water_plant(int moisture_level) {
    if (moisture_level < MOISTURE_LOW) {
        if (open_valve(VALVE_SERVO_PIN) != 0) {
            fprintf(stderr, "Error: Failed to open valve.\n");
            return -1;
        }

        printf("Moisture level: %d, Watering...\n", moisture_level);

        // Sweep nozzle through angles
        for (int angle = 0; angle <= 180; angle += 45) {
            if (set_servo_angle(NOZZLE_SERVO_PIN, angle) != 0) {
                fprintf(stderr, "Error: Failed to set nozzle angle.\n");
                close_valve(VALVE_SERVO_PIN);
                return -1;
            }
            gpioDelay(SERVO_SWEEP_DURATION * 1000); // Delay for sweep duration
        }

        // Hold spray for specified duration
        gpioDelay(WATERING_DURATION * 1000);

        // Close nozzle
        if (set_servo_angle(NOZZLE_SERVO_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to close nozzle.\n");
            close_valve(VALVE_SERVO_PIN);
            return -1;
        }

        // Close valve
        if (close_valve(VALVE_SERVO_PIN) != 0) {
            fprintf(stderr, "Error: Failed to close valve.\n");
            return -1;
        }

        printf("Moisture level: %d, Watering complete.\n", moisture_level);
    } else {
        printf("Moisture level: %d, Skipping watering.\n", moisture_level);
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping servos and exiting...\n", signal);
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for servos
    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate soil moisture levels
        int moisture_level = MOISTURE_LOW;
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        printf("[%s] Moisture level: %d\n", buf, moisture_level);

        // Water the plant
        if (water_plant(moisture_level) != 0) {
            fprintf(stderr, "Error: Failed to water plant.\n");
        }

        // Cycle through moisture levels
        moisture_level = MOISTURE_MEDIUM;
        now = time(NULL);
        tstruct = localtime(&now);
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        printf("[%s] Moisture level: %d\n", buf, moisture_level);

        moisture_level = MOISTURE_HIGH;
        now = time(NULL);
        tstruct = localtime(&now);
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        printf("[%s] Moisture level: %d\n", buf, moisture_level);

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

