#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// MPU6050 initialization function
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    // Set gyroscope full-scale range to +/- 250 degrees/sec
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    raw_x = i2cReadWordData(i2c_handle, GYRO_XOUT_H);
    raw_y = i2cReadWordData(i2c_handle, GYRO_YOUT_H);
    raw_z = i2cReadWordData(i2c_handle, GYRO_ZOUT_H);

    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        data.x = 0.0; data.y = 0.0; data.z = 0.0; // Return zeroed data
        return data;
    }

    // Convert raw data to degrees per second (dps)
    data.x = (float)((int16_t)raw_x) / 131.0;
    data.y = (float)((int16_t)raw_y) / 131.0;
    data.z = (float)((int16_t)raw_z) / 131.0;

    return data;
}

// Function to log data to file
void log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds (10 Hz sampling rate)

    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

