#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <wiringPi.h>
#include <errno.h>

// Define GPIO pins (BCM numbering)
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define motor rotation parameters
#define STEPS_PER_ROTATION 512
#define STEPS_PER_LOCK 512
#define STEPS_PER_UNLOCK 512

// Define delay between steps (in milliseconds)
#define STEP_DELAY 3

// Define motor direction constants
#define CLOCKWISE 1
#define COUNTER_CLOCKWISE -1

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void step_forward(int step);
void step_backward(int step);
void lock_door();
void unlock_door();
void rotate_clockwise();
void rotate_counter_clockwise();
void debounce_button(int button_pin);
void signal_handler(int signal);

// Stepper motor control functions
void step_forward(int step) {
    switch (step) {
        case 0:
            digitalWrite(IN1, HIGH);
            digitalWrite(IN2, LOW);
            digitalWrite(IN3, LOW);
            digitalWrite(IN4, LOW);
            break;
        case 1:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, HIGH);
            digitalWrite(IN3, LOW);
            digitalWrite(IN4, LOW);
            break;
        case 2:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, LOW);
            digitalWrite(IN3, HIGH);
            digitalWrite(IN4, LOW);
            break;
        case 3:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, LOW);
            digitalWrite(IN3, LOW);
            digitalWrite(IN4, HIGH);
            break;
    }
    delay(STEP_DELAY);
}

void step_backward(int step) {
    switch (step) {
        case 0:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, LOW);
            digitalWrite(IN3, HIGH);
            digitalWrite(IN4, LOW);
            break;
        case 1:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, HIGH);
            digitalWrite(IN3, LOW);
            digitalWrite(IN4, LOW);
            break;
        case 2:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, LOW);
            digitalWrite(IN3, LOW);
            digitalWrite(IN4, HIGH);
            break;
        case 3:
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, LOW);
            digitalWrite(IN3, LOW);
            digitalWrite(IN4, LOW);
            break;
    }
    delay(STEP_DELAY);
}

// Button press detection with debouncing
void debounce_button(int button_pin) {
    int i;
    for (i = 0; i < 5; i++) {
        if (digitalRead(button_pin) == LOW) {
            return; // Button is pressed
        }
        delay(1); // Small delay to avoid busy-waiting
    }
    return; // Button is not pressed
}

// Motor rotation functions
void rotate_clockwise() {
    printf("Locking door...\n");
    if (call("lock") != 0) {
        fprintf(stderr, "Error locking door: %s\n", strerror(errno));
    }
    for (int i = 0; i < STEPS_PER_LOCK; i++) {
        step_forward(i % 4);
    }
    printf("Door locked.\n");
}

void rotate_counter_clockwise() {
    printf("Unlocking door...\n");
    if (call("unlock") != 0) {
        fprintf(stderr, "Error unlocking door: %s\n", strerror(errno));
    }
    for (int i = 0; i < STEPS_PER_UNLOCK; i++) {
        step_backward(i % 4);
    }
    printf("Door unlocked.\n");
}

// Button press detection functions
void lock_door() {
    debounce_button(LOCK_BUTTON);
}

void unlock_door() {
    debounce_button(UNLOCK_BUTTON);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0; // Set the flag to exit the main loop
    // De-energize the motor coils
    digitalWrite(IN1, LOW);
    digitalWrite(IN2, LOW);
    digitalWrite(IN3, LOW);
    digitalWrite(IN4, LOW);
    call("de-energize");
    exit(0);
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as output
    pinMode(IN1, OUTPUT);
    pinMode(IN2, OUTPUT);
    pinMode(IN3, OUTPUT);
    pinMode(IN4, OUTPUT);

    // Set button pins as input with pull-up resistors
    pinMode(LOCK_BUTTON, INPUT);
    pullUpDnControl(LOCK_BUTTON, PUD_UP);
    pinMode(UNLOCK_BUTTON, INPUT);
    pullUpDnControl(UNLOCK_BUTTON, PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door control system started. Press LOCK or UNLOCK button to rotate the door.\n");

    // Main loop
    while (program_running) {
        lock_door();
        unlock_door();
    }

    return 0;
}

