#define TIMEOUT_US 50000       // 50ms timeout in microseconds
#define TRIGGER_PULSE_US 10000  // 10us trigger pulse
#define VOLTAGE_DIVIDER_RATIO 10.0 // 10:1 voltage divider

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance();
void log_distance(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int echo_received = 0;

