#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering cycle duration in seconds
#define WATERING_CYCLE_DURATION 86 * 4000 // 86 * 60 * 60 * 24 = 86 * 4000 seconds

// Define the watering interval in seconds
#define WATERING_INTERVAL 60

// Define the number of relays
#define NUM_RELAYS 4

// Global variable to track the program's start time
static time_t program_start_time = 0;

// Function prototypes
int initialize_gpio();
int activate_relay(int relay_pin);
int deactivate_relay(int relay_pin);
int run_watering_cycle();
int log_start_time();
void signal_handler(int signal);

// Structure to hold relay pins
typedef struct {
    int relay1_pin;
    int relay2_pin;
    int relay3_pin;
    int relay4_pin;
} RelayPins;

RelayPins relay_pins = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Run the watering cycle
    if (run_watering_cycle() != 0) {
        fprintf(stderr, "Error running watering cycle.\n");
        gpioTerminate();
        return 1;
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set all relay pins as outputs
    gpioSetMode(relay_pins.relay1_pin, PI_OUTPUT);
    gpioSetMode(relay_pins.relay2_pin, PI_OUTPUT);
    gpioSetMode(relay_pins.relay3_pin, PI_OUTPUT);
    gpioSetMode(relay_pins.relay4_pin, PI_OUTPUT);

    // Set all relay pins HIGH (inactive)
    gpioWrite(relay_pins.relay1_pin, 1);
    gpioWrite(relay_pins.relay2_pin, 1);
    gpioWrite(relay_pins.relay3_pin, 1);
    gpioWrite(relay_pins.relay4_pin, 1);

    return 0;
}

// Function to activate a relay for 5 seconds
int activate_relay(int relay_pin) {
    gpioWrite(relay_pin, 0); // Activate the relay (LOW)
    gpioDelay(5000);         // Wait for 5 seconds
    gpioWrite(relay_pin, 1); // Deactivate the relay (HIGH)
    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int relay_pin) {
    gpioWrite(relay_pin, 1); // Deactivate the relay (HIGH)
    return 0;
}

// Function to run the watering cycle
int run_watering_cycle() {
    time_t current_time = time(NULL);

    // Check if a full cycle has elapsed since the program started
    if (difftime(current_time, program_start_time) >= WATERING_CYCLE_DURATION) {
        // Log the start time of the watering cycle
        if (log_start_time() != 0) {
            fprintf(stderr, "Error logging start time.\n");
            return 1;
        }

        // Activate each relay in turn for 5 seconds
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (activate_relay(relay_pins.relay1_pin) != 0) return 1;
            if (activate_relay(relay_pins.relay2_pin) != 0) return 1;
            if (activate_relay(relay_pins.relay3_pin) != 0) return 1;
            if (activate_relay(relay_pins.relay4_pin) != 0) return 1;
        }

        // Reset the program start time
        program_start_time = current_time;
    }

    return 0;
}

// Function to log the start time of the watering cycle to a file
int log_start_time() {
    FILE *fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening watering_log.txt for writing.\n");
        return 1;
    }

    time_t t = time(NULL);
