    // Set all relay pins as outputs
    gpioSetMode(relay_pins.relay1_pin, PI_OUTPUT);
    gpioSetMode(relay_pins.relay2_pin, PI_OUTPUT);
    gpioSetMode(relay_pins.relay3_pin, PI_OUTPUT);
    gpioSetMode(relay_pins.relay4_pin, PI_OUTPUT);

    // Set all relay pins HIGH (inactive)
    gpioWrite(relay_pins.relay1_pin, 1);
    gpioWrite(relay_pins.relay2_pin, 1);
    gpioWrite(relay_pins.relay3_pin, 1);
    gpioWrite(relay_pins.relay4_pin, 1);

    return 0;
}

