int activate_relay(int relay_pin) {
    gpioWrite(relay_pin, 0); // Activate the relay (LOW)
    gpioDelay(5000);         // Wait for 5 seconds
    gpioWrite(relay_pin, 1); // Deactivate the relay (HIGH)
