        set_gpio_mode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for the relays
    if (set_pwm_frequency(RELAY1_GPIO, PWM_FREQUENCY) != 0 ||
