    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Define the number of steps and the duration
    int num_steps = 30 * 60; // 30 minutes * 60 seconds/minute
    int step_duration = 1;   // 1 second

    // Define the duty cycle increment
    int duty_cycle_increment = 5;

    // Define the log message format
    char log_message[200];

    // Main loop
    for (int i = 0; i < num_steps && program_running; i++) {
        // Calculate the current duty cycle
        int current_duty_cycle = (int)(((float)i / num_steps) * 255.0);

        // Set the duty cycle for all relays
        if (set_pwm_duty_cycle(RELAY1_GPIO, current_duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_GPIO, current_duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_GPIO, current_duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_GPIO, current_duty_cycle) != 0) {
            fprintf(stderr, "Failed to set duty cycle. Exiting.\n");
            program_running = 0;
            break;
        }

        // Log the event
        snprintf(log_message, sizeof(log_message), "Duty cycle: %d for relays: %d, %d, %d, %d", current_duty_cycle, RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO);
        log_event(log_message);

        // Wait for the next step
        gpioDelay(step_duration * 1000000); // Convert seconds to microseconds
    }

    // Clean up and exit
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    return 0;
}

