gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool running = true;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int fd, gyro_data_t *data);
void process_gyro_data(gyro_data_t data);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU6050
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    // Set gyroscope full-scale range to +/- 250 deg/s
    if (wiringPiI2CWriteReg8(fd, GYRO_CONFIG, 0) == -1) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

// Function to read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    int16_t x, y, z;

    x = wiringPiI2CReadReg16(fd, GYRO_XOUT_H);
    if (x == -1) {
        fprintf(stderr, "Error reading GYRO_XOUT_H: %s\n", strerror(errno));
        return -1;
    }
    y = wiringPiI2CReadReg16(fd, GYRO_YOUT_H);
    if (y == -1) {
        fprintf(stderr, "Error reading GYRO_YOUT_H: %s\n", strerror(errno));
        return -1;
    }
    z = wiringPiI2CReadReg16(fd, GYRO_ZOUT_H);
    if (z == -1) {
        fprintf(stderr, "Error reading GYRO_ZOUT_H: %s\n", strerror(errno));
        return -1;
    }

    data->x = x;
    data->y = y;
    data->z = z;

    return 0;
}

// Function to process gyroscope data (convert to degrees per second)
void process_gyro_data(gyro_data_t data) {
    // No conversion needed, data is already in degrees per second
}

// Function to control the LED
void control_led(int state) {
    digitalWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources.\n");
    control_led(LOW); // Turn off LED
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    wiringPiSetup(); // Reinitialize wiringPi to reset GPIO pins
    pinMode(LED_PIN, INPUT); // Set LED pin to input to avoid leaving it high
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t current_data;

    printf("Starting gyroscope data acquisition...\n");

    while (running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &current_data) == 0) {
            // Store data in circular buffer
            gyro_buffer[buffer_index] = current_data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Process gyroscope data
            process_gyro_data(current_data);

            // Control LED based on axis values
            if (abs(current_data.x) > 250 || abs(current_data.y) > 250 || abs(current_data.z) > 250) {
                control_led(HIGH);
            } else {
                control_led(LOW);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Attempting re-initialization...\n");
            close(i2c_fd);
            delay(100); // Small delay before re-initialization
            i2c_fd = init_i2c(MPU6050_ADDR);
            if (i2c_fd == -1) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                running = false; // Exit the loop if re-initialization fails
            }
        }

        delay(50); // Delay for 50ms (20Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

