#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_PIN 8      // GPIO8, BCM
#define CS_LINE_OFFSET 8
#define CS_LINE_NAME "cs-line-0"
#define CS_LINE_CHIP "gpiochip0"
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_RATE_MS 10

// MPU9250 Registers
#define MPU9250_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int mpu9250_init(int spi_fd);
int read_gyro_data(int spi_fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate);
void log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate, int16_t z_rate);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode_val = (mode << 4) | (bits << 0);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU9250 Initialization
int mpu9250_init(int spi_fd) {
    // Wake up the MPU9250 (clear sleep bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep bit
    if (write(spi_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Set gyro full-scale range to +/- 250 degrees/sec
    data[0] = GYRO_CONFIG;
    data[1] = 0x00; // +/- 250 dps
    if (write(spi_fd, data, 2) != 2) {
        perror("Error writing to GYRO_CONFIG");
        return -1;
    }

    return 0;
}

// Read Gyro Data
int read_gyro_data(int spi_fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];

    // Read all six gyro registers in one go
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes
    memset(tx_buf + 1, 0, 6); // Dummy data for reading

    if (write(spi_fd, tx_buf, 7) != 7) {
        perror("Error writing to SPI device");
        return -1;
    }

    if (read(spi_fd, rx_buf, 7) != 7) {
        perror("Error reading from SPI device");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y_rate = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z_rate = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Log Data to File
void log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate, z_rate);
    fflush(fp); // Ensure data is written immediately
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (chip != NULL) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int16_t x_rate, y_rate, z_rate;
    struct timespec ts;
    int retry;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU9250
    if (mpu9250_init(spi_fd) < 0) {
        fprintf(stderr, "MPU9250 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open GPIO chip and get CS line
    chip = gpiod_chip_open_by_name(CS_LINE_CHIP);
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_NAME);
    if (cs_line == NULL) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mpu9250";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyro data
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_gyro_data(spi_fd, &x_rate, &y_rate, &z_rate) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "SPI read error, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read gyro data after %d retries. Skipping.\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Error getting timestamp");
            continue; // Skip to the next iteration
        }

        // Log data
        log_data(log_file, ts, x_rate, y_rate, z_rate);

        // Delay
        usleep(SAMPLE_RATE_MS * 1000); // Sleep for 10ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

