#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define THRESHOLD 200.0
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 64
#define GYRO_SCALE 131.0 // LSB/deg/s for +/- 250 deg/s range

// MPU6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
int spi_handle;
bool running = true;

// Circular buffer structure
typedef struct {
    struct timespec timestamp[BUFFER_SIZE];
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
} gyro_data_t;

gyro_data_t gyro_buffer;
int buffer_index = 0;

// Function prototypes
int init_spi();
int init_gpio();
void close_resources();
void read_gyro_data(float *x, float *y, float *z);
bool check_threshold(float x, float y, float z);
void blink_led(int duration_ms);
void print_buffer();
void signal_handler(int signal);

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to close resources (SPI and GPIO)
void close_resources() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Function to read gyroscope data
void read_gyro_data(float *x, float *y, float *z) {
    char tx_buffer[7];
    char rx_buffer[7];

    // Wake up the MPU6050 (set PWR_MGMT_1 to 0)
    tx_buffer[0] = PWR_MGMT_1;
    tx_buffer[1] = 0x00;
    spiWrite(spi_handle, tx_buffer, 2);
    gpioDelay(100); // Short delay after waking up

    // Read X, Y, and Z axis data
    tx_buffer[0] = GYRO_XOUT_H;
    tx_buffer[1] = 0x00; // Start reading from register 0x43
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    tx_buffer[0] = GYRO_XOUT_H;
    tx_buffer[1] = 0x00; // Start reading from register 0x43
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    tx_buffer[0] = GYRO_YOUT_H;
    tx_buffer[1] = 0x00; // Start reading from register 0x45
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    tx_buffer[0] = GYRO_YOUT_H;
    tx_buffer[1] = 0x00; // Start reading from register 0x45
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    tx_buffer[0] = GYRO_ZOUT_H;
    tx_buffer[1] = 0x00; // Start reading from register 0x47
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    tx_buffer[0] = GYRO_ZOUT_H;
    tx_buffer[1] = 0x00; // Start reading from register 0x47
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    // Combine high and low bytes, and convert to degrees per second
    int16_t raw_x = (rx_buffer[0] << 8) | rx_buffer[1];
