#define RETRY_DELAY_MS 10
#define READ_INTERVAL_MS 100

// Si1145 Registers
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24

// Global variables
