    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Reset the device (example initialization sequence)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x00) < 0) { // Reset command
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
