#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADXRS290 Register Addresses
#define ADXRS290_XGYRO_OUT 0x02
#define ADXRS290_YGYRO_OUT 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // No special flags needed

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg_addr, uint8_t *data, int len);
int spi_write_register(int reg_addr, uint8_t data);
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
int log_data(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// SPI Read Register Function
int spi_read_register(int reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    int result;

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Register Function
int spi_write_register(int reg_addr, uint8_t data) {
    char tx_buf[2];
    int result;

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    result = spiWrite(spi_handle, tx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Read Gyro Data Function
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_data[2], y_data[2];

    if (spi_read_register(ADXRS290_XGYRO_OUT, x_data, 2) != 0) {
        fprintf(stderr, "Error reading X-axis data\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_YGYRO_OUT, y_data, 2) != 0) {
        fprintf(stderr, "Error reading Y-axis data\n");
        return -1;
    }

    *x_rate = (int16_t)((x_data[0] << 8) | x_data[1]);
    *y_rate = (int16_t)((y_data[0] << 8) | y_data[1]);

    return 0;
}

// Log Data Function
int log_data(int16_t x_rate, int16_t y_rate) {
    time_t now;
    struct timespec ts;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &ts);
    now = ts.tv_sec;
    ts.tv_nsec /= 1000; // Convert nanoseconds to microseconds

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec);

    if (fp == NULL) {
        fprintf(stderr, "Error: File not opened for logging\n");
        return -1;
    }

    fprintf(fp, "%ld,%d,%d\n", now, x_rate, y_rate);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

int main() {
    int16_t x_rate, y_rate;
    int init_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            if (log_data(x_rate, y_rate) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

