#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define alert duration (in milliseconds)
#define ALERT_DURATION 2000

// Define log file name
#define LOG_FILE "seismic_events.txt"

// Global variables
FILE *log_file = NULL;
int alert_active = 0;
int alert_start_time = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void handle_sensor_event(int pin, int edge, uint32_t tick, void *user_data);
void trigger_alert();
void log_event();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    int last_state;
} sensor_data_t;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to handle sensor events
void handle_sensor_event(int pin, int edge, uint32_t tick, void *user_data) {
    sensor_data_t *data = (sensor_data_t *)user_data;
    int current_state = read_sensor(pin);

    if (edge == PI_HIGH) {
        if (current_state == 1 && data->last_state == 0) {
            // Rising edge detected
            if (pin == SENSOR_1_PIN) {
                trigger_alert();
            }
        }
    } else if (edge == PI_LOW) {
        if (current_state == 0 && data->last_state == 1) {
            // Falling edge detected
            if (pin == SENSOR_2_PIN) {
                trigger_alert();
            }
        }
    }

    data->last_state = current_state;
}

// Function to trigger the alert
void trigger_alert() {
    if (!alert_active) {
        gpioWrite(ALERT_PIN, 1);
        alert_active = 1;
        alert_start_time = time_time();
        printf("Alert triggered!\n");
    }
}

// Function to log the event
void log_event() {
    time_t now = time_time();
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s - Seismic event detected!\n", buf);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up callbacks for sensor pins
