#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100
#define ADXRS290_REG_X 0x00 // Example register address for X-axis
#define ADXRS290_REG_Y 0x02 // Example register address for Y-axis

// Data structure for circular buffer entries
typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// SPI handle
int spi_handle;

// Function prototypes
int spi_init(int channel, int baud);
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(int handle, float *x_rate, float *y_rate);
void add_to_buffer(struct timespec ts, float x_rate, float y_rate);
float calculate_average_rate(float *rates, int num_rates);
void control_led(float avg_rate);
void signal_handler(int signal);

// SPI initialization function
int spi_init(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// SPI transfer function
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, float *x_rate, float *y_rate) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = 0x80 | ADXRS290_REG_X; // Example: X-axis register with read bit set
    tx_buf[1] = 0x00; // Dummy data for reading

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading X-axis data\n");
        return -1;
    }

    // Convert raw data to degrees per second (example conversion)
    int16_t raw_x = (rx_buf[0] << 8) | rx_buf[1];
    *x_rate = (float)raw_x / 100.0; // Example scaling factor

    tx_buf[0] = 0x80 | ADXRS290_REG_Y; // Example: Y-axis register with read bit set
    tx_buf[1] = 0x00; // Dummy data for reading

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading Y-axis data\n");
        return -1;
    }

    int16_t raw_y = (rx_buf[0] << 8) | rx_buf[1];
    *y_rate = (float)raw_y / 100.0; // Example scaling factor

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(struct timespec ts, float x_rate, float y_rate) {
    pthread_mutex_lock(&buffer_mutex);
    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x_rate = x_rate;
    gyro_buffer[buffer_index].y_rate = y_rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the average angular rate
float calculate_average_rate(float *rates, int num_rates) {
    float sum = 0.0;
    for (int i = 0; i < num_rates; i++) {
        sum += rates[i];
    }
    return sum / num_rates;
}

// Function to control the LED based on the average rate
void control_led(float avg_rate) {
    if (avg_rate > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED

    // Initialize SPI
    spi_handle = spi_init(SPI_CHANNEL, SPI_BAUD);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x_rate, y_rate;
    struct timespec ts;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &x_rate, &y_rate) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                perror("clock_gettime");
                break; // Exit loop on error
            }

            // Add data to circular buffer
            add_to_buffer(ts, x_rate, y_rate);

            // Calculate average rate
            float avg_rate = calculate_average_rate(gyro_buffer, BUFFER_SIZE);

            // Control LED
            control_led(avg_rate);

            // Print data (for debugging)
            printf("X Rate: %.2f deg/s, Y Rate: %.2f deg/s, Avg Rate: %.2f deg/s\n", x_rate, y_rate, avg_rate);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    return 0;
}

