#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 255

// Global variable to store the total duration
volatile int total_duration = 0;

// Function prototypes
void set_lamp_brightness(int gpio, int brightness);
void fade_lamp(int gpio, int duration);
void set_lamp_brightness(int gpio, int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off all lamps
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to set the brightness of a lamp
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration) {
    if (duration <= 0) {
        set_lamp_brightness(gpio, 0);
        return;
    }

    int brightness_increment = 255 / duration;
    int brightness = 255;

    for (int i = 0; i < duration; i++) {
        set_lamp_brightness(gpio, brightness);
        gpioDelay(10000); // 10ms delay (100Hz)
        brightness -= brightness_increment;
        if (brightness < 0) {
            brightness = 0;
        }
    }

    set_lamp_brightness(gpio, 0);
}

int main(int argc, char *argv[]) {
    // Check if the correct number of arguments is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the argument to an integer
    char *endptr;
    total_duration = strtol(argv[1], &endptr, 10);

    // Check for errors during conversion
    if (*endptr != '\0' || total_duration <= 0) {
        fprintf(stderr, "Error: Invalid total duration. Must be a positive integer.\n");
        return 1;
    }

    // Validate the total duration
    if (total_duration > 3600) {
        fprintf(stderr, "Error: Total duration cannot exceed 3600 seconds.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Print status message
    printf("Smart Sunset Simulator started. Total duration: %d seconds\n", total_duration);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, total_duration);
    fade_lamp(LAMP2_GPIO, total_duration);
    fade_lamp(LAMP3_GPIO, total_duration);

    // Print status message after fading
    printf("Fading complete.\n");

    // Clean up and exit
    signal_handler(0); // Call signal handler to turn off lamps and terminate pigpio

    return 0;
}

