#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_ELECTRODE0_REG 0x41
#define MPR121_TOUCH_THRESHOLD_REG 0x2B
#define MPR121_RELEASE_THRESHOLD_REG 0x2C
#define MPR121_MHDR_REG 0x2E
#define MPR121_NHDR_REG 0x2F
#define MPR121_NCLR_REG 0x30
#define MPR121_FDLR_REG 0x31
#define MPR121_MHDF_REG 0x32
#define MPR121_NHDF_REG 0x33
#define MPR121_NCLF_REG 0x34
#define MPR121_FDLF_REG 0x35
#define MPR121_ECR_REG 0x5E
#define MPR121_CONFIG1_REG 0x5B
#define MPR121_CONFIG2_REG 0x5C
#define MPR121_ELECTRODE_CONFIG_REG 0x5D
#define MPR121_TOUCH_STATUS_L 0x00
#define MPR121_TOUCH_STATUS_H 0x01
#define MPR121_ELECTRODE0_L 0x41
#define MPR121_ELECTRODE0_H 0x42
#define MPR121_ELECTRODE1_L 0x43
#define MPR121_ELECTRODE1_H 0x44
#define MPR121_ELECTRODE2_L 0x45
#define MPR121_ELECTRODE2_H 0x46
#define MPR121_ELECTRODE3_L 0x47
#define MPR121_ELECTRODE3_H 0x48
#define MPR121_ELECTRODE4_L 0x49
#define MPR121_ELECTRODE4_H 0x4A
#define MPR121_ELECTRODE5_L 0x4B
#define MPR121_ELECTRODE5_H 0x4C
#define MPR121_ELECTRODE6_L 0x4D
#define MPR121_ELECTRODE6_H 0x4E
#define MPR121_ELECTRODE7_L 0x4F
#define MPR121_ELECTRODE7_H 0x50
#define MPR121_ELECTRODE_CONFIG_VALUE 0x0C // Enable all electrodes

#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int fd);
int read_touch_status(int fd);
void toggle_relay(int gpio_pin);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd >= 0) {
        // No direct I2C close function in wiringPi, but we can reset the bus
        // wiringPiI2CWrite(i2c_fd, 0x00); // Attempt to reset the bus
        // This might not be the best way to close the I2C connection, but it's a start.
        i2c_fd = -1; // Mark as closed
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    digitalWrite(RELAY_GPIO, LOW); // Ensure relay is off
    pinMode(RELAY_GPIO, INPUT); // Set GPIO to input mode
    printf("Cleanup complete.\n");
}

// Log error function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(log_file); // Ensure the log is written immediately
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Reset the device
    if (wiringPiI2CWriteReg8(fd, MPR121_ECR_REG, 0x00) < 0) {
        log_error("Failed to reset MPR121");
        return -1;
    }
    delay(1); // Wait for reset to complete

    // Configure touch and release thresholds
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCH_THRESHOLD_REG, 0x0F) < 0) {
        log_error("Failed to set touch threshold");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASE_THRESHOLD_REG, 0x0A) < 0) {
        log_error("Failed to set release threshold");
        return -1;
    }

    // Configure electrode sensitivity
    if (wiringPiI2CWriteReg8(fd, MPR121_MHDR_REG, 0x01) < 0) {
        log_error("Failed to set MHD_R");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_NHDR_REG, 0x01) < 0) {
        log_error("Failed to set NHD_R");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_NCLR_REG, 0x0F) < 0) {
        log_error("Failed to set NCL_R");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_FDLR_REG, 0x0F) < 0) {
        log_error("Failed to set FDL_R");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_MHDF_REG, 0x01) < 0) {
        log_error("Failed to set MH_D");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_NHDF_REG, 0x01) < 0) {
        log_error("Failed to set NH_D");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_NCLF_REG, 0x0F) < 0) {
        log_error("Failed to set NCL_F");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_FDLF_REG, 0x0F) < 0) {
        log_error("Failed to set FDL_F");
        return -1;
    }

    // Enable all electrodes
    if (wiringPiI2CWriteReg8(fd, MPR121_ELECTRODE_CONFIG_REG, MPR121_ELECTRODE_CONFIG_VALUE) < 0) {
        log_error("Failed to set electrode config");
        return -1;
    }

    // Configure the MPR121 for operation
    if (wiringPiI2CWriteReg8(fd, MPR121_ECR_REG, 0x11) < 0) { // Enable all electrodes and enter run mode
        log_error("Failed to set ECR");
        return -1;
    }

    return 0;
}

// Read touch status function
int read_touch_status(int fd) {
    int touch_status = wiringPiI2CReadReg8(fd, MPR121_TOUCH_STATUS_L);
    if (touch_status < 0) {
        log_error("Failed to read touch status");
        return -1;
    }
    touch_status |= (wiringPiI2CReadReg8(fd, MPR121_TOUCH_STATUS_H) << 8);
    return touch_status;
}

// Toggle relay function
void toggle_relay(int gpio_pin) {
    static bool relay_state = false;
    digitalWrite(gpio_pin, !relay_state);
    relay_state = !relay_state;
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        log_error("Failed to initialize I2C communication.");
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        log_error("MPR121 initialization failed.");
        cleanup();
        return 1;
    }

    // Configure relay GPIO as output
    pinMode(RELAY_GPIO, OUTPUT);
    digitalWrite(RELAY_GPIO, LOW); // Initialize relay to OFF state

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status(i2c_fd);
        if (touch_status == -1) {
            // Error reading touch status, but continue running
            delay(10); // Small delay to avoid busy-waiting
            continue;
        }

        if (touch_status & (1 << 0)) { // Check if electrode 0 is touched
            toggle_relay(RELAY_GPIO);
        }

        delay(10); // Delay for 10ms
    }

    cleanup();
    return 0;
}

