#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27

// Define dispense duration (in milliseconds)
#define DISPENSE_DURATION 1000

// Define half-duration (in milliseconds)
#define HALF_DURATION (DISPENSE_DURATION / 2)

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int gpio_pin, int duration_ms);
int deactivate_solenoid(int gpio_pin);
int dispense_solenoid(int gpio_pin, int duration_ms);
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0; // Set the flag to exit the loop
        deactivate_solenoid(SOLENOID1_GPIO);
        deactivate_solenoid(SOLENOID2_GPIO);
        gpioTerminate(); // Terminate the pigpio library
        exit(0); // Exit the program
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOLENOID1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a solenoid for a given duration
int activate_solenoid(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return 1; // Indicate failure
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to deactivate a solenoid
int deactivate_solenoid(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to dispense a solenoid for a given duration
int dispense_solenoid(int gpio_pin, int duration_ms) {
    if (gpio_pin != SOLENOID1_GPIO && gpio_pin != SOLENOID2_GPIO) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return 1; // Indicate failure
    }
    return activate_solenoid(gpio_pin, duration_ms);
}

// Function to log dispense events to a file
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO17, GPIO27, %d\n", s, solenoid1_pin, solenoid2_pin, duration_ms);
    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense solenoid 1
        if (dispense_solenoid(SOLENOID1_GPIO, HALF_DURATION) != 0) {
            fprintf(stderr, "Error dispensing solenoid 1\n");
        }
        if (log_dispense_event(SOLENOID1_GPIO, SOLENOID2_GPIO, HALF_DURATION) != 0) {
            fprintf(stderr, "Error logging dispense event for solenoid 1\n");
        }

        // Dispense solenoid 2
        if (dispense_solenoid(SOLENOID2_GPIO, HALF_DURATION) != 0) {
            fprintf(stderr, "Error dispensing solenoid 2\n");
        }
        if (log_dispense_event(SOLENOID1_GPIO, SOLENOID2_GPIO, HALF_DURATION) != 0) {
            fprintf(stderr, "Error logging dispense event for solenoid 2\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid(SOLENOID1_GPIO);
    deactivate_solenoid(SOLENOID2_GPIO);
    gpioTerminate();

    return 0;
}

