#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Motor A GPIOs
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIOs
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// ENA and ENB GPIOs
#define ENA 24
#define ENB 25

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup_gpio();
void stop_motors();
void set_motor_speed(int motor, int speed);
float calculate_tilt_error(float angle);
float calculate_distance();
float pid_control(float tilt_error, float previous_error, float integral, float last_error, float *integral_term);
void obstacle_avoidance(float distance);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void log_error(const char *message);

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, 1); // Enable PWM
    gpioWrite(ENB, 1); // Enable PWM

    return 0;
}

// Initialize Logging
int initialize_logging() {
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return 1;
    }
    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    stop_motors();
    gpioTerminate();
}

// Stop Motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
}

// Set Motor Speed
void set_motor_speed(int motor, int speed) {
    if (speed < -255 || speed > 255) {
        log_error("Invalid motor speed");
        return;
    }

    if (motor == MOTOR_A_FORWARD) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor == MOTOR_A_BACKWARD) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
    } else if (motor == MOTOR_B_FORWARD) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else if (motor == MOTOR_B_BACKWARD) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
    } else {
        log_error("Invalid motor");
        return;
    }

    int pwm_value = (int)(((float)speed / 255.0) * 255.0); // Scale speed to 0-255 range
    gpioPWM(ENA, pwm_value);
    gpioPWM(ENB, pwm_value);
}

// Calculate Tilt Error
float calculate_tilt_error(float angle) {
    return angle;
}

// Simulate Distance Sensor
float calculate_distance() {
    return (float)(rand() % 401) + 2; // Random value between 2 and 400
}

// PID Control
float pid_control(float tilt_error, float previous_error, float integral, float last_error, float *integral_term) {
    float error = tilt_error - previous_error;
    *integral_term += error;
    float derivative = error - last_error;
    float output = KP * error + KI * (*integral_term) + KD * derivative;
    return output;
}

// Obstacle Avoidance
void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        printf("Obstacle detected! Reversing...\n");
        set_motor_speed(MOTOR_A, 128); // Reverse Motor A
        set_motor_speed(MOTOR_B, 128); // Reverse Motor B
    } else {
        stop_motors();
    }
}

// Log Data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Log Error
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    // Initialize Signal Handling
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize Logging
    if (initialize_logging() != 0) {
        cleanup_gpio();
        return 1;
    }

    // Initialize PID Variables
    float tilt_error = 0.0;
    float previous_error = 0.0;
    float integral = 0.0;
    float last_error = 0.0;
    float integral_term = 0.0;

    // Main Loop
    while (program_running) {
        // Simulate Tilt Error
        tilt_error = (float)(rand() % 201) - 10.0; // Random value between -10 and 10

        // Calculate Distance
        float distance = calculate_distance();

        // Calculate Motor Speeds
        int motor_a_speed = (int)(pid_control(tilt_error, previous_error, integral, last_error, &integral_term));
        int motor_b_speed = (int)(pid_control(tilt_error, previous_error, integral, last_error, &integral_term));

        // Obstacle Avoidance
        obstacle_avoidance(distance);

        // Set Motor Speeds
        set_motor_speed(MOTOR_A, motor_a_speed);
        set_motor_speed(MOTOR_B, motor_b_speed);

        // Log Data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update PID Variables
        previous_error = tilt_error;
        integral = integral_term;
        last_error = tilt_error;

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Cleanup
    stop_motors();
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

