#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_relay(0); // Turn off relay on exit
    gpioTerminate();   // Terminate pigpio
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set touch sensor pin as input with pull-up resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1; // Indicate failure
    }
    relay_state = state; // Update global relay state
    return 0; // Indicate success
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 0) { // Assuming 0 means touch detected (adjust if needed)
            printf("Touch detected!\n");
            if (control_relay(1) != 0) {
                fprintf(stderr, "Failed to turn on relay\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else {
            // No touch detected, check if relay should be off
            if (relay_state == 1) {
                if (control_relay(0) != 0) {
                    fprintf(stderr, "Failed to turn off relay\n");
                }
            }
        }

        gpioDelay(10 * 1000); // Small delay to prevent busy-waiting
    }

    return 0; // This line will never be reached due to the infinite loop
}

