#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA device name
#define ALSA_DEVICE "default"

// Define default sample rate and buffer size
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_BUFFER_SIZE 1024

// Define sine wave parameters for simulation
#define DEFAULT_SINE_FREQUENCY 440.0
#define DEFAULT_SINE_AMPLITUDE 0.5

// Define command-line argument parsing function
void parse_arguments(int argc, char *argv[], float *sensitivity);

// Define signal handler function
void signal_handler(int signal);

// Define function to initialize ALSA
int init_alsa(snd_pcm_t **pcm, snd_pcm_hw_params_t *hw_params, int sample_rate, int buffer_size);

// Define function to initialize pigpio
int init_pigpio(int red_pin, int green_pin, int blue_pin);

// Define function to set PWM duty cycle
void set_pwm_duty_cycle(int red_pin, int green_pin, int blue_pin, int duty_cycle);

// Define function to calculate RMS amplitude
float calculate_rms(float *buffer, int buffer_size);

// Define function to map RMS amplitude to RGB color
void map_amplitude_to_color(float rms_amplitude, float sensitivity, int red_pin, int green_pin, int blue_pin);

// Define function to simulate audio input
void simulate_audio_input(float *buffer, int buffer_size, float frequency, float amplitude);

// Global variables
snd_pcm_t *pcm = NULL;
snd_pcm_hw_params_t *hw_params = NULL;
int red_pin, green_pin, blue_pin;
float sensitivity = 1.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void parse_arguments(int argc, char *argv[], float *sensitivity);
void signal_handler(int signal);
int init_alsa(snd_pcm_t **pcm, snd_pcm_hw_params_t *hw_params, int sample_rate, int buffer_size);
int init_pigpio(int red_pin, int green_pin, int blue_pin);
void set_pwm_duty_cycle(int red_pin, int green_pin, int blue_pin, int duty_cycle);
float calculate_rms(float *buffer, int buffer_size);
void map_amplitude_to_color(float rms_amplitude, float sensitivity, int red_pin, int green_pin, int blue_pin);
void simulate_audio_input(float *buffer, int buffer_size, float frequency, float amplitude);

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv, &sensitivity);

    // Initialize ALSA
    if (init_alsa(&pcm, &hw_params, DEFAULT_SAMPLE_RATE, DEFAULT_BUFFER_SIZE) != 0) {
        fprintf(stderr, "Error initializing ALSA. Using simulation mode.\n");
        // Initialize pigpio for simulation mode
        if (init_pigpio(red_pin, green_pin, blue_pin) != 0) {
            fprintf(stderr, "Error initializing pigpio. Exiting.\n");
            return 1;
        }
    } else {
        // Initialize pigpio for real ALSA mode
        if (init_pigpio(red_pin, green_pin, blue_pin) != 0) {
            fprintf(stderr, "Error initializing pigpio. Exiting.\n");
            return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Allocate buffer for audio data
    char *buffer = (char *)malloc(DEFAULT_BUFFER_SIZE * sizeof(char));
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating buffer.\n");
        if (pcm) snd_pcm_close(pcm);
        if (hw_params) snd_pcm_hw_params_free(hw_params);
        if (pcm) snd_pcm_destroy(pcm);
        if (hw_params) snd_pcm_hw_params_free(hw_params);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Prepare for playback
        if (snd_pcm_prepare(pcm) < 0) {
            fprintf(stderr, "Error preparing PCM for playback.\n");
            break;
        }

        // Write data to PCM
        int frames = DEFAULT_BUFFER_SIZE;
        int err = snd_pcm_writei(pcm, buffer, frames);
        if (err == -EPIPE) {
