#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x92
#define TCS34725_RDATA 0x94
#define TCS34725_GDATA 0x96
#define TCS34725_BDATA 0x98

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t c;
    uint16_t r;
    uint16_t g;
    uint16_t b;
} color_data_t;

// Function prototypes
int init_tcs34725();
color_data_t read_color_data();
int log_data(color_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME) to 154ms
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0x80) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read color data from TCS34725 sensor
color_data_t read_color_data() {
    color_data_t data;
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        data.c = 0; data.r = 0; data.g = 0; data.b = 0; // Set to zero on error
        return data;
    }

    data.c = (buffer[1] << 8) | buffer[0];
    data.r = (buffer[3] << 8) | buffer[2];
    data.g = (buffer[5] << 8) | buffer[4];
    data.b = (buffer[7] << 8) | buffer[6];

    return data;
}

// Log color data to CSV file
int log_data(color_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fp == NULL) {
        fprintf(stderr, "Error: File not opened.\n");
        return -1;
    }

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, data.c, data.r, data.g, data.b);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Cleanup function to close I2C and file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,c,r,g,b\n");
    }

    // Main loop
    while (!terminate) {
        color_data_t data = read_color_data();
        if (data.c != 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading color data, logging zeros.\n");
            fprintf(fp, "%ld,0,0,0,0\n", time(NULL));
            fflush(fp);
        }
        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

