    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,c,r,g,b\n");
    }

    // Main loop
    while (!terminate) {
        color_data_t data = read_color_data();
        if (data.c != 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading color data, logging zeros.\n");
            fprintf(fp, "%ld,0,0,0,0\n", time(NULL));
            fflush(fp);
        }
        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

