#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the number of relays
#define NUM_RELAYS 4

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 518400

// Define the number of steps for the PWM-like effect
#define NUM_STEPS 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, turning off relays and exiting...\n", signal);
}

// Function to set the GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set the GPIO pins as outputs
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to set the duty cycle for a relay
void set_relay_duty_cycle(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle value: %d\n", duty_cycle);
        return;
    }

    // Calculate the PWM value (0-100)
    int pwm_value = (int)(((float)duty_cycle / 100.0) * 100.0);

    // Set the GPIO pin level (0 for LOW, 1 for HIGH)
    gpioWrite(pin, (pwm_value > 50) ? 0 : 1);
}

// Function to simulate sunrise
void sunrise() {
    printf("Starting sunrise phase...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        int duty_cycle = (int)(((float)i / (float)NUM_STEPS) * 100.0);
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Sunrise phase complete.\n");
}

// Function to simulate daytime
void daytime() {
    printf("Starting daytime phase...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        int duty_cycle = 100 - (int)(((float)i / (float)NUM_STEPS) * 100.0);
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Daytime phase complete.\n");
}

// Function to simulate sunset
void sunset() {
    printf("Starting sunset phase...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        int duty_cycle = (int)(((float)i / (float)NUM_STEPS) * 100.0);
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Sunset phase complete.\n");
}

// Function to simulate nighttime
void nighttime() {
    printf("Starting nighttime phase...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        set_relay_duty_cycle(RELAY1_PIN, 0);
        set_relay_duty_cycle(RELAY2_PIN, 0);
        set_relay_duty_cycle(RELAY3_PIN, 0);
        set_relay_duty_cycle(RELAY4_PIN, 0);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Nighttime phase complete.\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Sunrise phase
        sunrise();
        gpioDelay(SUNRISE_DURATION * 1000); // Delay for sunrise duration

        // Daytime phase
        daytime();
        gpioDelay(DAYTIME_DURATION * 1000); // Delay for daytime duration

        // Sunset phase
        sunset();
        gpioDelay(SUNSET_DURATION * 1000); // Delay for sunset duration

        // Nighttime phase
        nighttime();
        gpioDelay(NIGHTTIME_DURATION * 1000); // Delay for nighttime duration
    }

    // Cleanly release the GPIO resources
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

