#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log motion events to a file
void log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to capture video using raspivid
int capture_video() {
    char command[256];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[25];
    char filename[64];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 25, "%Y%m%dT%H%M%S", timeinfo);

    snprintf(filename, sizeof(filename), "%s/%s.h264", VIDEO_DIR, timestamp);
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_S);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        perror("Failed to execute raspivid");
        return -1;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        // Optionally, you could log the output of raspivid here
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", status);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_trigger_time = 0;
    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value == 0) { // Active-low sensor
            time_t current_time = time(NULL);
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS / 1000.0) {
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    log_motion_event(timestamp);
                    printf("Motion detected at %s\n", timestamp);
                    if (capture_video() != 0) {
                        fprintf(stderr, "Video capture failed.\n");
                    }
                    free(timestamp);
                } else {
                    fprintf(stderr, "Failed to get timestamp.\n");
                }
                last_trigger_time = current_time;
            }
        }
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

