#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// GPIO pin for alarm
#define ALARM_GPIO 27

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (in seconds)
#define FREEFALL_DURATION 0.5

// Alarm duration (in seconds)
#define ALARM_DURATION 5

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int adxl345_read_register(int handle, uint8_t reg);
int adxl345_write_register(int handle, uint8_t reg, uint8_t value);
int adxl345_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
int detect_freefall(int handle, int16_t x, int16_t y, int16_t z);
void trigger_alarm(int gpio_pin);
void log_freefall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to read a register from the ADXL345
int adxl345_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a register to the ADXL345
int adxl345_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = adxl345_read_register(handle, ADXL345_REG_DATAX0);
    x1 = adxl345_read_register(handle, ADXL345_REG_DATAX1);
    y0 = adxl345_read_register(handle, ADXL345_REG_DATAY0);
    y1 = adxl345_read_register(handle, ADXL345_REG_DATAY1);
    z0 = adxl345_read_register(handle, ADXL345_REG_DATAZ0);
    z1 = adxl345_read_register(handle, ADXL345_REG_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Function to detect free-fall
int detect_freefall(int handle, int16_t x, int16_t y, int16_t z) {
    if (x < 0 || y < 0 || z < 0) {
        return -1; // Indicate error
    }

    // Convert raw values to g (assuming +/- 2g range and 10-bit resolution)
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    if (fabs(x_g) < FREEFALL_THRESHOLD && fabs(y_g) < FREEFALL_THRESHOLD && fabs(z_g) < FREEFALL_THRESHOLD) {
        return 1; // Free-fall detected
    } else {
        return 0; // Not in free-fall
    }
}

// Function to trigger the alarm
void trigger_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Function to log free-fall data
void log_freefall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, (float)x / 256.0, (float)y / 256.0, (float)z / 256.0);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345 (set to measurement mode)
    if (adxl345_write_register(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error initializing ADXL345\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int freefall_count = 0;
    int freefall_confirmed = 0;

    // Main loop
    while (1) {
        accelerometer_data_t accel_data;
        int freefall_status;

        // Read acceleration data
        if (adxl345_read_acceleration(i2c_handle, &accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Detect free-fall
            freefall_status = detect_freefall(i2c_handle, accel_data.x, accel_data.y, accel_data.z);

            if (freefall_status == 1) {
                freefall_count++;
                if (freefall_count >= (FREEFALL_DURATION * 10)) { // 0.5 seconds * 10 readings = 5 samples
                    freefall_confirmed = 1;
                    printf("Free-fall detected!\n");
