// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_MS 100
#define MAX_DISTANCE_CM 4.0
#define MAX_PULSE_WIDTH_US 22800
#define TRIGGER_PULSE_US 10000
#define TIMEOUT_US (TIMEOUT_MS * 1000)

// Define mutex
pthread_mutex_t echo_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables
volatile unsigned int echo_start_tick = 0;
volatile unsigned int echo_end_tick = 0;
volatile int echo_valid = 0;
volatile int echo_timeout = 0;
volatile int echo_pulse_width = 0;
volatile int echo_distance = 0.0;
volatile int echo_error = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void *sensor_thread(void *arg);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 1;
        echo_timeout = 0;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1;
        echo_timeout = 0;
    } else if (level == PI_TIMEOUT) {
        echo_valid = 0;
        echo_timeout = 1;
    }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    if (pulse_width > MAX_PULSE_WIDTH_US) {
        return -1.0; // Indicate invalid reading
    }
    return (double)pulse_width / 58.0; // Speed of sound: 343 m/s
}

// Function to log distance to file
void log_distance(double distance) {
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (ts.tv_sec * 1000000000LL) + (ts.tv_nsec);

    fprintf(fp, "%ld,%.2f\n", timestamp_ns, distance);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&echo_mutex); // Destroy mutex
    exit(0);
}

// Thread function for sensor monitoring
void *sensor_thread(void *arg) {
    while (1) {
        trigger_pulse();
        gpioDelay(200000); // Wait 200ms

        if (echo_valid) {
            if (echo_timeout) {
                echo_error = 1; // Set error flag
            } else {
                echo_error = 0;
                echo_distance = calculate_distance(echo_pulse_width);
                if (echo_distance >= 0.0) {
                    log_distance(echo_distance);
                } else {
                    echo_error = 1; // Set error flag
                }
            }
        } else {
            echo_error = 1; // Set error flag
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set interrupt callback for ECHO_PIN
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        perror("Failed to create sensor thread");
        gpioTerminate();
        return 1;
    }

    // Main loop (can be used for other tasks)
    while (1) {
        gpioDelay(100000); // Sleep for 0.1 seconds
    }

    // Cleanup (should not reach here unless there's an error)
    pthread_cancel(sensor_thread_id);
    pthread_join(sensor_thread_id, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&echo_mutex);
    return 0;
}

