#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH Registers
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Configuration Constants
#define CTRL_REG1_DEFAULT 0x77 // 100Hz, Enable all axes
#define CTRL_REG4_DEFAULT 0x88 // +/-2g, High resolution, 12-bit

// Global Variables
static int i2c_handle;
static int i2c_address;
static float threshold;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function Prototypes
int validate_i2c_address(int address);
int configure_lis3dh(int i2c_handle);
accelerometer_data_t read_accelerometer_data(int i2c_handle);
void log_high_acceleration(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Validate I2C Address
int validate_i2c_address(int address) {
    if (address >= 0x18 && address <= 0x1F) {
        return 0; // Valid address
    } else {
        fprintf(stderr, "Error: Invalid I2C address: 0x%02X\n", address);
        return -1; // Invalid address
    }
}

// Configure LIS3DH
int configure_lis3dh(int i2c_handle) {
    // Set CTRL_REG1 to 100Hz, enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, CTRL_REG1_DEFAULT) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Set CTRL_REG4 to +/-2g, high resolution, 12-bit
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, CTRL_REG4_DEFAULT) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read Accelerometer Data
accelerometer_data_t read_accelerometer_data(int i2c_handle) {
    accelerometer_data_t data;
    char buffer[6];
    int16_t x, y, z;

    // Read all six bytes at once
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((buffer[1] << 8) | buffer[0]);
    y = (int16_t)((buffer[3] << 8) | buffer[2]);
    z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g units (assuming +/-2g range and 12-bit resolution)
    data.x = (float)x / 4096.0;
    data.y = (float)y / 4096.0;
    data.z = (float)z / 4096.0;

    return data;
}

// Log High Acceleration
void log_high_acceleration(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    fprintf(fp, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, data.x, data.y, data.z);
    fclose(fp);

    printf("%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, data.x, data.y, data.z);
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (validate_i2c_address(i2c_address) != 0) {
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0.0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "Error: LIS3DH configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data(i2c_handle);

        if (fabs(data.x) > threshold || fabs(data.y) > threshold || fabs(data.z) > threshold) {
            log_high_acceleration(data);
            printf("High acceleration detected! Shutting down...\n");
            cleanup();
            return 0;
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

