#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL_MS 100
#define RETRY_COUNT 50
#define RETRY_DELAY_US 1000 // 1ms

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *field_strength);
void control_relay(int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int si7210_address;
    int relay_gpio;
    float threshold;
    int sample_interval_ms;
} config_t;

// Function to initialize the pigpio library and I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    return 0;
}

// Function to read the magnetic field strength from the Si7210 sensor
int read_magnetic_field(float *field_strength) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        log_event("I2C Read Error", "Failed to read data from I2C device");
        return -1;
    }

    // Convert the raw data to a signed 16-bit integer
    int16_t raw_value = (buf[0] << 8) | buf[1];

    // Convert the raw value to milliTesla (mT)
    *field_strength = (float)raw_value * 0.1; // Example conversion factor

    return 0;
}

// Function to control the relay (active high)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - %s: %s\n", timestamp, event_type, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Shutdown", "Received signal, shutting down...");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_event("Initialization Error", "Failed to initialize I2C");
        return 1;
    }

    float field_strength;
    int retry_count = 0;

    while (program_running) {
        if (read_magnetic_field(&field_strength) == 0) {
            char message[100];
            snprintf(message, sizeof(message), "Field strength: %.2f mT", field_strength);

            if (field_strength > THRESHOLD) {
                control_relay(1); // Activate relay
                snprintf(message, sizeof(message), "Threshold exceeded, relay activated");
                log_event("Relay State Change", message);
            } else {
                control_relay(0); // Deactivate relay
                snprintf(message, sizeof(message), "Field strength below threshold, relay deactivated");
                log_event("Relay State Change", message);
            }

            log_event("Data Read", message);
        } else {
            log_event("I2C Read Error", "Failed to read magnetic field");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    return 0;
}

