#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"

// Function prototypes
int initialize_gpio();
int initialize_socket(int port);
int accept_connection(int socket_fd);
int read_command(int socket_fd, char *buffer, int buffer_size);
int process_command(char *command, int socket_fd);
int control_relay(int socket_fd, int state);
int log_event(const char *event);
void signal_handler(int signal);

// Global variables
int server_socket = -1;
int client_socket = -1;
FILE *log_file = NULL;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Initialize socket
    server_socket = initialize_socket(PORT);
    if (server_socket == -1) {
        fprintf(stderr, "Error initializing socket. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket == -1) {
            log_event("Error accepting connection");
            perror("accept");
            continue; // Continue to the next iteration
        }

        char buffer[1024];
        int bytes_received = read(client_socket, buffer, sizeof(buffer) - 1);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            log_event("Received command");
            if (process_command(buffer, client_socket) != 0) {
                log_event("Invalid command received");
            }
        } else if (bytes_received == 0) {
            log_event("Client disconnected");
        } else {
            log_event("Error reading from socket");
        }
    }

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

int initialize_socket(int port) {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(port);

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(socket_fd);
        return -1;
    }

    if (listen(socket_fd, 5) < 0) {
        perror("listen");
        close(socket_fd);
        return -1;
    }

    return socket_fd;
}

int accept_connection(int socket_fd) {
    int client_socket = accept(socket_fd, NULL, NULL);
    if (client_socket < 0) {
        perror("accept");
        return -1;
    }
    return client_socket;
}

int read_command(int socket_fd, char *buffer, int buffer_size) {
    ssize_t bytes_read = read(socket_fd, buffer, buffer_size - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return 0;
    } else if (bytes_read == 0) {
        return -1; // Client disconnected
    } else {
        perror("read");
        return -1;
    }
}

int process_command(char *command, int socket_fd) {
    char *command_copy = strdup(command); // Duplicate the string for strtok
    if (command_copy == NULL) {
        perror("strdup");
        return 1;
    }

    char *token = strtok(command_copy, " \n");
    while (token != NULL) {
        if (strcmp(token, "ON") == 0) {
            control_relay(socket_fd, 1);
            log_event("Relay ON");
            free(command_copy);
            return 0;
