#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define POLLING_DELAY_MS 100
#define START_MEASUREMENT_CMD 0x3608
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int start_measurement(int handle);
int read_sensor_data(int handle, uint8_t *data);
float calculate_flow_rate(uint8_t *data);
void control_relay(int gpio, int state);
void log_data(float flow1, float flow2);
void cleanup();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to start measurement
int start_measurement(int handle) {
    char cmd[2] = {START_MEASUREMENT_CMD >> 8, START_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to calculate flow rate
float calculate_flow_rate(uint8_t *data) {
    // Combine the two bytes into a 16-bit integer
    int16_t raw_flow = (data[0] << 8) | data[1];

    // Apply the CRC-8 checksum
    uint8_t crc = data[2];
    uint8_t polynomial = CRC8_POLYNOMIAL;
    uint8_t bit = 0;
    for (int i = 0; i < 8; i++) {
        bit = crc ^ polynomial;
        crc >>= 1;
        if (bit & 1) {
            crc = (crc >> 8) ^ 0x31;
        } else {
            crc <<= 1;
        }
    }

    if (crc != 0) {
        fprintf(stderr, "CRC check failed!\n");
        return -1.0; // Indicate CRC error
    }

    // Scale the raw flow value to ml/min (example scaling, adjust as needed)
    float flow_rate = (float)raw_flow / 100.0; // Example scaling factor

    return flow_rate;
}

// Function to control the relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log data to file
void log_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Start measurement on both sensors
    if (start_measurement(i2c_handle1) != 0) {
        cleanup();
        return 1;
    }
    if (start_measurement(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor1_data[3];
    uint8_t sensor2_data[3];
    float flow1, flow2;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, sensor1_data) != 0) {
            fprintf(stderr, "Error reading sensor 1 data. Skipping.\n");
        } else if (read_sensor_data(i2c_handle2, sensor2_data) != 0) {
            fprintf(stderr, "Error reading sensor 2 data. Skipping.\n");
        } else {
            // Calculate flow rates
            flow1 = calculate_flow_rate(sensor1_data);
            flow2 = calculate_flow_rate(sensor2_data);

            // Validate flow rates
            if (flow1 >= 0 && flow2 >= 0) {
                // Log data
                log_data(flow1, flow2);

                // Control relay
                int relay_state = (flow1 >= FLOW_THRESHOLD && flow2 >= FLOW_THRESHOLD) ? 1 : 0;
                control_relay(RELAY_GPIO, relay_state);
            } else {
                fprintf(stderr, "Error: Invalid flow rate(s) received.\n");
            }
        }

        // Delay
        gpioDelay(POLLING_DELAY_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

