#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

// Define motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_BACKWARD 0
#define MOTOR_STOP 2

// Define motor duration constants
#define MOTOR_DURATION 5 // seconds

// Define dry period threshold
#define DRY_PERIOD_THRESHOLD 3 // polls

// Global variables
static volatile int running = 1;
static volatile int dry_count = 0;
static volatile int motor_state = MOTOR_STOP;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int direction);
int stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ENA_PIN, PI_OUTPUT);
    gpioSetMode(IN1_PIN, PI_OUTPUT);
    gpioSetMode(IN2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    log_event("GPIO initialization complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
int control_motor(int direction) {
    if (direction == MOTOR_FORWARD) {
        gpioWrite(IN1_PIN, 1);
        gpioWrite(IN2_PIN, 0);
        log_event("Motor started forward");
    } else if (direction == MOTOR_BACKWARD) {
        gpioWrite(IN1_PIN, 0);
        gpioWrite(IN2_PIN, 1);
        log_event("Motor started backward");
    } else {
        gpioWrite(IN1_PIN, 0);
        gpioWrite(IN2_PIN, 0);
        log_event("Motor stopped");
    }
    return 0;
}

// Function to stop the motor
int stop_motor() {
    gpioWrite(ENA_PIN, 0);
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
    log_event("Motor stopped");
    return 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);

    syslog(LOG_INFO, "%s", log_message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    running = 0;
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (running) {
        int rain_detected = (read_rain_sensor() == 0); // LOW indicates rain

        if (rain_detected) {
            dry_count = 0; // Reset dry count if rain is detected
        } else {
            dry_count++;
        }

        if (dry_count >= DRY_PERIOD_THRESHOLD && motor_state != MOTOR_STOP) {
