// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track servo state
static int servo_state = 0; // 0: locked, 1: unlocked

// Function prototypes
int lock_door();
int unlock_door();
void signal_handler(int signal);

// Function to lock the door
int lock_door() {
    if (gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: Failed to send lock pulse width.\n");
        return -1;
    }
    printf("Door locked.\n");
    servo_state = 0; // Update servo state
    return 0;
}

// Function to unlock the door
int unlock_door() {
    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: Failed to send unlock pulse width.\n");
        return -1;
    }
    printf("Door unlocked.\n");
    servo_state = 1; // Update servo state
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                if (lock_door() != 0) {
                    fprintf(stderr, "Error: Failed to lock door.\n");
                }
            }
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                if (unlock_door() != 0) {
                    fprintf(stderr, "Error: Failed to unlock door.\n");
                }
            }
        }

        gpioDelay(10000); // Sleep for 10ms to reduce CPU usage
    }

    return 0;
}

