#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define FLOODLIGHT_PIN 17

// Define constants
#define FLOODLIGHT_DURATION 60 // seconds
#define POLLING_INTERVAL 100   // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_floodlight();
int deactivate_floodlight();
int log_event(const char *event_type, const char *timestamp, int duration);
int cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to activate the floodlight
int activate_floodlight() {
    gpioWrite(FLOODLIGHT_PIN, 1); // Turn on the floodlight
    return 0;
}

// Function to deactivate the floodlight
int deactivate_floodlight() {
    gpioWrite(FLOODLIGHT_PIN, 0); // Turn off the floodlight
    return 0;
}

// Function to log an event to the security_log.txt file
int log_event(const char *event_type, const char *timestamp, int duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s - %s - Duration: %d seconds\n", timestamp, event_type, duration);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to cleanup the pigpio library and GPIO pins
int cleanup_gpio() {
    gpioWrite(FLOODLIGHT_PIN, 0); // Ensure floodlight is off
    gpioTerminate(); // Terminate pigpio
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Turn off the floodlight
    deactivate_floodlight();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanup GPIO
    cleanup_gpio();

    exit(0); // Exit with status 0
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read PIR sensor
        if (read_pir_sensor() == 1) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Activate floodlight
            if (activate_floodlight() != 0) {
                fprintf(stderr, "Error activating floodlight\n");
            }

            // Log activation event
            if (log_event("FLOODLIGHT", timestamp, FLOODLIGHT_DURATION) != 0) {
                fprintf(stderr, "Error logging floodlight activation\n");
            }

            // Wait for floodlight duration
            gpioDelay(FLOODLIGHT_DURATION * 1000); // Delay in milliseconds

            // Deactivate floodlight
            if (deactivate_floodlight() != 0) {
                fprintf(stderr, "Error deactivating floodlight\n");
            }

            // Log deactivation event
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            if (log_event("FLOODLIGHT", timestamp, 0) != 0) {
                fprintf(stderr, "Error logging floodlight deactivation\n");
            }
        }

        // Wait for polling interval
        gpioDelay(POLLING_INTERVAL * 1000); // Delay in milliseconds
    }

    return 0;
}

