#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define GPIO pin for relay control
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHD 0x2B
#define MPR121_NHD 0x2C
#define MPR121_NCL 0x2D
#define MPR121_FDL 0x2E
#define MPR121_DDBE 0x2F
#define MPR121_FFI 0x2A
#define MPR121_SFI 0x2B
#define MPR121_CDT 0x2C
#define MPR121_AUTOCONF 0x5D

// Global variables
int i2c_fd;
bool relay_state = false; // Track relay state for signal handler

// Function prototypes
int mpr121_init(int fd);
int mpr121_configure(int fd);
int mpr121_enable_auto_config(int fd);
int mpr121_enable_electrodes(int fd, int num_electrodes);
int mpr121_read_touch_status(int fd);
void relay_control(int pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    relay_control(RELAY_PIN, 0); // Turn off relay
    close(i2c_fd);
    wiringPiSetupGpio(); // Reinitialize wiringPi to avoid issues
    pinMode(RELAY_PIN, OUTPUT); // Reinitialize GPIO pin
    digitalWrite(RELAY_PIN, LOW); // Ensure relay is off
    exit(0);
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121 (0x%02X): %s\n", MPR121_ADDR, strerror(errno));
        return -1;
    }
    delay(1); // Wait for reset to complete

    // Configure baseline filtering
    if (wiringPiI2CWriteReg8(fd, MPR121_MHD, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_NHD, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_NCL, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_FDL, 0x01) < 0) return -1;

    // Configure debounce
    if (wiringPiI2CWriteReg8(fd, MPR121_DDBE, 0x0A) < 0) return -1; // 10ms debounce

    // Configure FFI, SFI, and CDT
    if (wiringPiI2CWriteReg8(fd, MPR121_FFI, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_SFI, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_CDT, 0x0A) < 0) return -1; // 10ms CDT

    // Enable auto-config
    if (wiringPiI2CWriteReg8(fd, MPR121_AUTOCONF, 0x8F) < 0) return -1; // Enable auto-config, set range to 12 electrodes

    // Enable electrodes
    if (mpr121_enable_electrodes(fd, 12) < 0) return -1;

    return 0;
}

// MPR121 configuration function
int mpr121_configure(int fd) {
    // Configure MPR121 (example configuration)
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG1, 0x80) < 0) return -1; // Set Electrode Configuration
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG2, 0x01) < 0) return -1; // Set Electrode Configuration

    return 0;
}

// MPR121 enable electrodes function
int mpr121_enable_electrodes(int fd, int num_electrodes) {
    int reg_addr = 0x5E; // ECR register
    int mask = (1 << num_electrodes) - 1; // Mask to enable the specified electrodes

    if (wiringPiI2CWriteReg8(fd, reg_addr, mask) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status: %s\n", strerror(errno));
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Relay control function
void relay_control(int pin, int state) {
    digitalWrite(pin, state);
    relay_state = state; // Update global relay state
}

int main() {
    // Initialize wiringPi
