    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to initialize MPR121\n");
        close(i2c_fd);
        return 1;
    }

    // Configure relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to OFF state

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status, exiting.\n");
