#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <sys/file.h>
#include <pigpio.h>
#include <stdarg.h>

#define PORT 5000
#define LOG_FILE "security.log"
#define SERVO_PIN 17
#define PIR_PIN 4

volatile sig_atomic_t program_running = 1;

// Function to log messages to syslog
void log_syslog(int priority, const char *message, ...) {
    va_list args;
    va_start(args, message);
    vsyslog(priority, message, args);
    va_end(args);
}

// Function to log messages to a file
void log_file(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_syslog(LOG_ERR, "pigpio initialisation failed");
        log_file("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN); // Optional: Set pull-down resistor

    return 0;
}

// Function to set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_syslog(LOG_ERR, "Invalid servo angle: %d", angle);
        log_file("Invalid servo angle");
        return -1;
    }

    int pulse_width = 500 + (angle * 2000 / 180); // Calculate pulse width (microseconds)
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Function to read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to handle TCP connection
void handle_connection(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        log_syslog(LOG_INFO, "Received command: %s", buffer);

        if (strncmp(buffer, "SERVO", 5) == 0) {
            int angle;
            if (sscanf(buffer + 5, "%d", &angle) == 1) {
                if (set_servo_angle(angle) != 0) {
                    char error_message[128];
                    snprintf(error_message, sizeof(error_message), "Failed to set servo angle to %d", angle);
                    send(client_socket, error_message, strlen(error_message), 0);
                }
            } else {
                char error_message[128];
                snprintf(error_message, sizeof(error_message), "Invalid servo command format");
                send(client_socket, error_message, strlen(error_message), 0);
            }
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = read_pir_sensor();
            char response[32];
            snprintf(response, sizeof(response), "PIR:%d", pir_value);
            send(client_socket, response, strlen(response), 0);
        } else {
            char error_message[128];
            snprintf(error_message, sizeof(error_message), "Unknown command: %s", buffer);
            send(client_socket, error_message, strlen(error_message), 0);
        }
    } else if (bytes_received == 0) {
        log_syslog(LOG_INFO, "Client disconnected");
    } else {
        log_syslog(LOG_ERR, "Error receiving data: %zd", bytes_received);
        log_file("Error receiving data");
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

int main() {
    openlog("security_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    // Create socket
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        log_syslog(LOG_ERR, "Error creating socket");
        log_file("Error creating socket");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_syslog(LOG_ERR, "Error binding socket");
        log_file("Error binding socket");
        close(server_socket);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        log_syslog(LOG_ERR, "Error listening on socket");
        log_file("Error listening on socket");
        close(server_socket);
        gpioTerminate();
        closelog();
        return 1;
    }

    log_syslog(LOG_INFO, "Listening on port %d", PORT);

    // Accept connections and handle them
    while (program_running) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            log_syslog(LOG_ERR, "Error accepting connection");
            log_file("Error accepting connection");
        } else {
            handle_connection(client_socket);
        }
    }

    // Cleanup
    close(server_socket);
    gpioTerminate();
    closelog();

    return 0;
}

