// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD_HIGH 150
#define LUX_THRESHOLD_LOW 150
#define SAMPLE_INTERVAL_SEC 2
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x10); // 0x10 for high resolution mode
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert to lux
    uint16_t raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

