                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry_count++;
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read BH1750 after multiple retries. Skipping this cycle.\n");
            gpioDelay(1000000); // Wait 1 second before next cycle
            continue;
        }

        // Control relay based on lux value
