#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Define constants
#define NUM_READINGS 5
#define TARE_READINGS 10
#define SCALE_FACTOR 1.0
#define LOCK_DURATION_MS 200
#define LOCK_THRESHOLD 1000.0
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_DURATION 500
#define MAX_RETRIES 3

// Global variables
volatile int running = 1;
double tare_value = 0.0;
double scale_factor = 1.0;
double lock_threshold = LOCK_THRESHOLD;
int duration_ms = DEFAULT_DURATION;

// Function prototypes
int init_gpio();
int read_hx711();
double tare_load_cell();
double read_weight();
double apply_scale_factor(double weight);
void control_solenoid(int lock);
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially LOW

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int retries = 0;

    // Wait for DOUT to go LOW
    while (gpioRead(HX711_DOUT) == 1 && retries < MAX_RETRIES) {
        log_message(LOG_WARNING, "HX711 DOUT not ready, retrying...");
        gpioDelay(10); // Wait 10ms
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        log_message(LOG_ERR, "HX711 DOUT timeout after multiple retries");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the gain (Channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to perform the tare procedure
double tare_load_cell() {
    double sum = 0.0;
    for (int i = 0; i < TARE_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return 0.0; // Return 0 on error
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    return sum / TARE_READINGS;
}

// Function to read the weight from the HX711
double read_weight() {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        log_message(LOG_ERR, "Error reading HX711");
        return 0.0; // Return 0 on error
    }
    return (double)raw_value / scale_factor;
}

// Function to apply the scale factor
double apply_scale_factor(double weight) {
    return weight;
}

// Function to control the solenoid lock
void control_solenoid(int lock) {
    gpioWrite(SOLENOID_PIN, lock);
    gpioDelay(LOCK_DURATION_MS);
    gpioWrite(SOLENOID_PIN, 0);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is LOW
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                lock_threshold = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s scale]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Perform tare procedure
    tare_value = tare_load_cell();
    log_message(LOG_INFO, "Tare procedure complete. Tare value: %.2f", tare_value);

    // Main loop
    while (running) {
        double sum = 0.0;
        for (int i = 0; i < NUM_READINGS; i++) {
            double weight = read_weight();
            if (weight == 0.0) {
                log_message(LOG_ERR, "Error reading weight, skipping this reading");
                continue;
            }
            sum += weight;
            gpioDelay(10); // Small delay between readings
        }
        double average_weight = sum / NUM_READINGS;

        // Apply scale factor
        double calibrated_weight = apply_scale_factor(average_weight);

        // Check if weight exceeds threshold
        if (calibrated_weight > lock_threshold) {
            log_message(LOG_INFO, "Weight exceeds threshold, activating lock");
            control_solenoid(1); // Activate lock
        } else {
            log_message(LOG_INFO, "Weight below threshold, not activating lock");
        }

        gpioDelay(duration_ms); // Delay for specified duration
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

