#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define GPIO_PIN 17
#define KEEPALIVE 60

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int sig);
void cleanup();
void log_event(int priority, const char *tag, const char *message);
void *mqtt_loop(void *arg);
int gpio_init();
int gpio_set_output(int pin);
int gpio_write(int pin, int value);
int mqtt_connect(struct mosquitto **mosq, const char *client_id, const char *host, int port);
int mqtt_subscribe(struct mosquitto *mosq, const char *topic, int qos);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);

// Signal handler
void signal_handler(int sig) {
    log_event(LOG_INFO, "mqtt_relay", "Signal received, exiting...");
    running = 0;
}

// Cleanup function
void cleanup() {
    log_event(LOG_INFO, "mqtt_relay", "Cleaning up...");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();
}

// Logging function
void log_event(int priority, const char *tag, const char *message) {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s: %s", tag, message);
    closelog();
}

// MQTT loop function
void *mqtt_loop(void *arg) {
    (void)arg; // Suppress unused parameter warning
    int rc;

    while (running) {
        rc = mosquitto_loop(mosq, -1, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_event(LOG_ERR, "mqtt_relay", "MQTT loop error: ");
            if (rc == MOSQ_ERR_INVAL) {
                log_event(LOG_ERR, "mqtt_relay", "Invalid argument to mosquitto_loop");
            } else if (rc == MOSQ_ERR_NO_CONNECTION) {
                log_event(LOG_ERR, "mqtt_relay", "No MQTT connection available");
            } else {
                log_event(LOG_ERR, "mqtt_relay", "Unknown MQTT error: %d", rc);
            }
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }
    return NULL;
}

// GPIO initialization function
int gpio_init() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "gpio_relay", "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// GPIO set output function
int gpio_set_output(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "gpio_relay", "Failed to set GPIO mode");
        return -1;
    }
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        log_event(LOG_ERR, "gpio_relay", "Failed to write to GPIO");
        return -1;
    }
    return 0;
}

// MQTT connect function
int mqtt_connect(struct mosquitto **mosq, const char *client_id, const char *host, int port) {
    int rc;

    *mosq = mosquitto_new(client_id, true, NULL);
    if (!*mosq) {
        log_event(LOG_ERR, "mqtt_relay", "Failed to create mosquitto instance");
        return -1;
    }

    mosquitto_connect_callback_set(*mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(*mosq, mqtt_message_callback);

    rc = mosquitto_connect(*mosq, host, port, KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_event(LOG_ERR, "mqtt_relay", "Failed to connect to MQTT broker: ");
        if (rc == MOSQ_ERR_INVAL) {
            log_event(LOG_ERR, "mqtt_relay", "Invalid argument to mosquitto_connect");
        } else if (rc == MOSQ_ERR_NO_CONNECTION) {
            log_event(LOG_ERR, "mqtt_relay", "No MQTT connection available");
        } else {
            log_event(LOG_ERR, "mqtt_relay", "Unknown MQTT error: %d", rc);
        }
        return -1;
    }

    log_event(LOG_INFO, "mqtt_relay", "Connected to MQTT broker");
    return 0;
}

// MQTT subscribe function
int mqtt_subscribe(struct mosquitto *mosq, const char *topic, int qos) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, qos);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_event(LOG_ERR, "mqtt_relay", "Failed to subscribe to MQTT topic: ");
        if (rc == MOSQ_ERR_INVAL) {
            log_event(LOG_ERR, "mqtt_relay", "Invalid argument to mosquitto_subscribe");
        } else if (rc == MOSQ_ERR_NO_CONNECTION) {
            log_event(LOG_ERR, "mqtt_relay", "No MQTT connection available");
        } else {
            log_event(LOG_ERR, "mqtt_relay", "Unknown MQTT error: %d", rc);
        }
        return -1;
    }
    log_event(LOG_INFO, "mqtt_relay", "Subscribed to MQTT topic");
    return 0;
}

// MQTT message callback function
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        char *endptr;
        long value;

        if (sscanf(payload, "%ld", &value) == 1) {
            if (value == 1) {
                gpio_write(GPIO_PIN, 1); // Energize relay
                log_event(LOG_INFO, "mqtt_relay", "Relay energized");
            } else if (value == 0) {
                gpio_write(GPIO_PIN, 0); // De-energize relay
                log_event(LOG_INFO, "mqtt_relay", "Relay de-energized");
            } else {
                log_event(LOG_ERR, "mqtt_relay", "Invalid payload value: %ld", value);
            }
        } else {
            log_event(LOG_ERR, "mqtt_relay", "Failed to parse payload: %s", payload);
        }
    } else {
        log_event(LOG_ERR, "mqtt_relay", "Empty payload received");
    }
}

// MQTT disconnect callback function
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    log_event(LOG_WARNING, "mqtt_relay", "Disconnected from MQTT broker: ");
    log_event(LOG_WARNING, "mqtt_relay", "Reason: %d", rc);
}

