// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width range (500-2500 us)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping PWM and cleaning up...\n", signal);
}

// Function to set the PWM frequency and range
int set_pwm_frequency(int pin, int frequency, int range) {
    if (gpioSetPWMfrequency(pin, frequency) != frequency) {
        fprintf(stderr, "Error setting PWM frequency for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, range) != range) {
        fprintf(stderr, "Error setting PWM range for pin %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the servo pulse width
int set_servo_pulse_width(int pin, int pulse_width_us) {
    if (pulse_width_us < MIN_PULSE_WIDTH || pulse_width_us > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us)\n", pulse_width_us);
        return -1;
    }

    // Convert pulse width to microseconds
    int pulse_width_ms = pulse_width_us / 1000; // Divide by 1000 to convert us to ms

    // Calculate the duty cycle (0-1000 for 500-2500 us range)
    int duty_cycle = (int)(((float)pulse_width_ms / 2.0) * 1000.0); // Divide by 2 to get 50% duty cycle

    // Set the PWM duty cycle
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for pin %d\n", pin);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Define servo positions
    int servo1_position = 1000;
    int servo2_position = 1500;
    int servo3_position = 2000;
    int servo4_position = 500;
    int servo5_position = 2500;

    // Set PWM frequency and range for each servo
    if (set_pwm_frequency(SERVO1_PIN, PWM_FREQUENCY, 10000) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm_frequency(SERVO2_PIN, PWM_FREQUENCY, 10000) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm_frequency(SERVO3_PIN, PWM_FREQUENCY, 10000) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm_frequency(SERVO4_PIN, PWM_FREQUENCY, 10000) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm_frequency(SERVO5_PIN, PWM_FREQUENCY, 10000) != 0) {
        gpioTerminate();
        return 1;
    }

    // Move servos to predefined positions
    printf("Moving servos to predefined positions...\n");
    if (set_servo_pulse_width(SERVO1_PIN, servo1_position) != 0) {
        fprintf(stderr, "Error setting servo 1 position\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO2_PIN, servo2_position) != 0) {
        fprintf(stderr, "Error setting servo 2 position\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO3_PIN, servo3_position) != 0) {
        fprintf(stderr, "Error setting servo 3 position\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO4_PIN, servo4_position) != 0) {
        fprintf(stderr, "Error setting servo 4 position\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO5_PIN, servo5_position) != 0) {
        fprintf(stderr, "Error setting servo 5 position\n");
        gpioTerminate();
        return 1;
    }

    printf("Servos moved to predefined positions.\n");

    // Stop PWM and release resources
    printf("Stopping PWM and cleaning up...\n");
    gpioPWM(SERVO1_PIN, 0); // Stop PWM on all servos
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    gpioTerminate(); // Terminate pigpio

    printf("Program finished.\n");
    return 0;
}

