#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_A_A 4
#define MOTOR_A_B 5

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define MOTOR_B_A 6
#define MOTOR_B_B 12

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Constants
#define REVOLUTIONS_PER_SECOND 50.0
#define TICKS_PER_REVOLUTION 64
#define PWM_FREQUENCY 10000 // 10 kHz
#define PWM_RANGE 255
#define STALL_THRESHOLD 2000 // 2 seconds
#define MAX_DUTY_CYCLE 255
#define MIN_DUTY_CYCLE 0

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_stall_count = 0;
volatile int encoder_b_stall_count = 0;
volatile int running = 1;

// PI controller parameters
double Kp = 1.0;
double Ki = 0.1;
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;

// Function prototypes
void motor_a_forward(int duty_cycle);
void motor_a_backward(int duty_cycle);
void motor_b_forward(int duty_cycle);
void motor_b_backward(int duty_cycle);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_ticks);
void pi_control(double target_rpm, double *duty_cycle);
void signal_handler(int signal);

// Motor control functions
void motor_a_forward(int duty_cycle) {
    gpioWrite(MOTOR_A_DIR, 1);
    gpioPWM(MOTOR_A_PWM, duty_cycle);
}

void motor_a_backward(int duty_cycle) {
    gpioWrite(MOTOR_A_DIR, 0);
    gpioPWM(MOTOR_A_PWM, duty_cycle);
}

void motor_b_forward(int duty_cycle) {
    gpioWrite(MOTOR_B_DIR, 1);
    gpioPWM(MOTOR_B_PWM, duty_cycle);
}

void motor_b_backward(int duty_cycle) {
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_B_PWM, duty_cycle);
}

// Encoder ISR functions
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    if (gpio == ENCODER_A_B) {
        if (level == 1) {
            encoder_a_ticks++;
        }
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    if (gpio == ENCODER_B_B) {
        if (level == 1) {
            encoder_b_ticks++;
        }
    }
}

// RPM calculation function
double calculate_rpm(int encoder_ticks) {
    return (double)encoder_ticks / TICKS_PER_REVOLUTION * REVOLUTIONS_PER_SECOND;
}

// PI controller function
void pi_control(double target_rpm, double *duty_cycle) {
    double error_a = target_rpm - calculate_rpm(encoder_a_ticks);
    double error_b = target_rpm - calculate_rpm(encoder_b_ticks);

    integral_a += error_a;
    integral_b += error_b;

    double proportional_a = Kp * error_a;
    double proportional_b = Kp * error_b;

    double output_a = proportional_a + Ki * integral_a;
    double output_b = proportional_b + Ki * integral_b;

    // Anti-windup
    if (output_a > MAX_DUTY_CYCLE) output_a = MAX_DUTY_CYCLE;
    if (output_a < MIN_DUTY_CYCLE) output_a = MIN_DUTY_CYCLE;
    if (output_b > MAX_DUTY_CYCLE) output_b = MAX_DUTY_CYCLE;
    if (output_b < MIN_DUTY_CYCLE) output_b = MIN_DUTY_CYCLE;

    *duty_cycle = output_a; // Use motor A duty cycle for both motors

