#define REVOLUTIONS_PER_SECOND 50.0
#define TICKS_PER_REVOLUTION 64
#define PWM_FREQUENCY 10000 // 10 kHz
#define PWM_RANGE 255
#define STALL_THRESHOLD 2000 // 2 seconds
#define MAX_DUTY_CYCLE 255
#define MIN_DUTY_CYCLE 0

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_stall_count = 0;
volatile int encoder_b_stall_count = 0;
volatile int running = 1;

