#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define LUX_THRESHOLD_DAWN 200
#define LUX_THRESHOLD_DUSK 50
#define HYSTERESIS 10
#define POLL_INTERVAL 5 // seconds
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_bh1750(float *lux);
void control_led(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO for LED control
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(LED_GPIO, 0); // Initialize LED to OFF
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char data[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x10); // 0x00 is register address, 0x10 is command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // BH1750 datasheet

    return 0;
}

// Control the LED strip
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state == 1 ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int i2c_retry = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Chicken coop light monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read light level
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Control relay based on light level and hysteresis
            if (lux < LUX_THRESHOLD_DAWN && relay_state == 0) {
                control_led(1); // Turn on relay
                relay_state = 1;
            } else if (lux > LUX_THRESHOLD_DUSK && relay_state == 1) {
                control_led(0); // Turn off relay
                relay_state = 0;
            }

            // Log data
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Error reading light level. Retrying...\n");
            i2c_retry++;
            if (i2c_retry > I2C_RETRY_COUNT) {
                fprintf(stderr, "Too many I2C retries. Exiting.\n");
                program_running = 0;
            }
            gpioDelay(1000000); // Wait 1 second before retrying
            i2c_retry = 0; // Reset retry count
        }

        gpioDelay(POLL_INTERVAL * 1000000); // Wait for POLL_INTERVAL seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

