#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Function prototypes
int read_touch_sensor();
void toggle_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, turning relay OFF and exiting...\n");
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor() {
    int touch_detected = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_detected < 0) {
        fprintf(stderr, "Error reading touch sensor: %d\n", touch_detected);
        return -1; // Indicate an error
    }
    return touch_detected;
}

// Function to toggle the relay state
void toggle_relay(int state) {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state); // Set the relay pin to the new state
    log_relay_state(relay_state);
}

// Function to log the relay state with an ISO 8601 timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();
        if (touch_detected == 1) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            int debounced_touch = read_touch_sensor();
            if (debounced_touch == 0) {
                toggle_relay(1); // Toggle relay ON
            }
        } else if (touch_detected < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting...\n");
            break; // Exit the loop on error
        }
        gpioDelay(10000); // Sleep for 10ms
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    gpioTerminate();
    return 0;
}

