        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioSetPWMrange(SERVO_PIN, 2000); // 2000 us range

    return 0;
}

// Function to initialize the TCP server
int init_tcp_server(int port) {
    int server_socket;
    struct sockaddr_in server_address;

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        return -1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(port);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        return -1;
    }

    // Listen for connections
    if (listen(server_socket, 5) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        return -1;
    }

    return server_socket;
}

// Function to initialize the API call
int init_api_call() {
    // Placeholder for API call initialization
    // Replace with actual API call initialization code
    // For example, setting up a connection to a remote API endpoint
    // and authenticating with credentials.
    // This example assumes a simple API call that returns a handle.
    api_call_handle = 1; // Simulate API call handle
    return 0;
}

// Function to calibrate the load cell
int calibrate_load_cell() {
    double known_weight;
    double actual_weight;
    double calibration_factor;

    printf("Enter known weight in grams: ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return -1;
    }

    printf("Calibrating... Please wait.\n");
    gpioDelay(2000); // Wait for calibration

    actual_weight = read_weight();
    if (actual_weight == -1) {
        fprintf(stderr, "Error reading weight during calibration.\n");
        return -1;
    }

    calibration_factor = known_weight / actual_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    // Save calibration factor to config.ini
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        perror("Error opening config.ini for writing");
        return -1;
    }
    fprintf(fp, "calibration_factor = %lf\n", calibration_factor);
    fclose(fp);

    return 0;
}

// Function to read the weight from the load cell
double read_weight() {
    int raw_value;
    double weight;

    raw_value = hx711_read(DATA_PIN, SCK_PIN, 1000); // Timeout of 1000 us
    if (raw_value == -1) {
        return -1.0; // Indicate error
    }

    // Convert raw value to weight (grams)
    weight = (double)raw_value / calibration_factor;

    return weight;
}

// Function to map the weight to a pulse width
int map_weight_to_pulse_width(double weight) {
    // Map 0-1000 grams to 1000-2000 us
    int pulse_width = (int)((weight / 1000.0) * (2000.0 - 1000.0) + 1000.0);
    return pulse_width;
}

// Function to dispense the ingredient
int dispense_ingredient(double target_weight) {
    int pulse_width;
    int result;

    // Map target weight to pulse width
    pulse_width = map_weight_to_pulse_width(target_weight);

    // Set servo motor to the calculated pulse width
    gpioPWM(SERVO_PIN, pulse_width);

    // Wait for 1 second
    gpioDelay(1000); // 1000 ms = 1 second

    // Read the actual weight
    double actual_weight = read_weight();
    if (actual_weight == -1.0) {
        log_event("Error reading weight during dispensing");
        result = -1; // Indicate error
    } else {
        // Log the dispensing event
        char message[256];
        snprintf(message, sizeof(message), "Dispensed %lf grams, actual weight: %lf grams", target_weight, actual_weight);
        log_event(message);

        // Send the actual weight back to the client
        char weight_str[64];
        snprintf(weight_str, sizeof(weight_str), "%.2f", actual_weight);
        send(server_socket, weight_str, strlen(weight_str), 0);
        result = 0; // Indicate success
    }

    return result;
}

// Function to log an event to the dispensing_log.json file
int log_event(const char *message) {
    pthread_mutex_lock(&log_mutex);
    if (log_file == NULL) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "message", json_string(message));

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
    if (json_str == NULL) {
        fprintf(stderr, "Error creating JSON string\n");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    fprintf(log_file, "%s\n", json_str);
    fflush(log_file);

    json_decref(root);
    free(json_str);

    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Signal received: %d. Shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop servo motor
    gpioPWM(SERVO_PIN, 0);

    // Close API call
    if (api_call_handle > 0) {
        // Placeholder for API call cleanup
        // Replace with actual API call cleanup code
        api_call_handle = 0;
    }

    // Close socket
    if (server_socket > 0) {
        close(server_socket);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    pthread_mutex_destroy(&log_mutex);

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    int server_port = DEFAULT_SERVER_PORT;
    int logging_interval = DEFAULT_LOGGING_INTERVAL;

    // Parse command-line arguments
    if (argc > 1) {
        server_port = atoi(argv[1]);
    }
    if (argc > 2) {
        logging_interval = atoi(argv[2]);
    }

    printf("Server port: %d, Logging interval: %d seconds\n", server_port, logging_interval);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize TCP server
    server_socket = init_tcp_server(server_port);
    if (server_socket == -1) {
        cleanup();
        return 1;
    }

    // Initialize API call
    if (init_api_call() != 0) {
        cleanup();
        return 1;
    }

    // Calibrate load cell
    if (calibrate_load_cell() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening dispensing_log.json");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Server started. Listening on port %d...\n", server_port);

    // Main loop
    while (running) {
        // Accept incoming connections
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        // Receive data from client
        char buffer[1024];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Error receiving data");
            close(client_socket);
            continue; // Continue listening for other connections
        }
        buffer[bytes_received] = '\0';

        // Process the received data
        double target_weight;
        if (sscanf(buffer, "%lf", &target_weight) == 1) {
            // Dispense the ingredient
            if (dispense_ingredient(target_weight) != 0) {
                char error_message[256];
                snprintf(error_message, sizeof(error_message), "Dispensing failed for target weight: %lf", target_weight);
                log_event(error_message);
            }
        } else {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "Invalid target weight received: %s", buffer);
            log_event(error_message);
        }

        // Sleep for the logging interval
        gpioDelay(logging_interval * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

