#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_MS 50

volatile int relay_state = 0; // 0 = OFF, 1 = ON
volatile int last_touch_state = 0;
volatile unsigned long last_touch_time = 0;
volatile int debounce_time = DEBOUNCE_MS;

FILE *log_file = NULL;

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log relay state changes to the console
void log_relay_state()
{
    char timestamp[20];
    get_timestamp(timestamp);

    if (relay_state == 1)
    {
        fprintf(log_file, "%s Relay: ON\n", timestamp);
        fflush(log_file);
    }
    else
    {
        fprintf(log_file, "%s Relay: OFF\n", timestamp);
        fflush(log_file);
    }
}

// Function to handle touch sensor input
void touch_callback(int gpio, int level, unsigned int tick)
{
    unsigned long current_time = gpioTick();

    if (level == 1) // Rising edge detected
    {
        if (last_touch_state == 0 && (current_time - last_touch_time) > debounce_time * 1000) // Debounce
        {
            relay_state = !relay_state; // Toggle relay state
            gpioWrite(RELAY_GPIO, relay_state);
            log_relay_state();
            last_touch_state = 1;
            last_touch_time = current_time;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    exit(0);
}

int main(int argc, char *argv[])
{
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1)
    {
        switch (opt)
        {
        case 'd':
            debounce_time = atoi(optarg);
            if (debounce_time <= 0)
            {
                fprintf(stderr, "Error: Invalid debounce time. Using default value (%d ms).\n", DEBOUNCE_MS);
                debounce_time = DEBOUNCE_MS;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-d milliseconds]\n", argv[0]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for touch sensor
    gpioSetAlertFuncEx(TOUCH_SENSOR_GPIO, touch_callback, NULL);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (1)
    {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

