#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50000 // 50 Hz
#define PWM_RANGE 2000       // 20ms period (5000/250)
#define SERVO_MIN_PULSE_WIDTH 1500 // 0°
#define SERVO_MAX_PULSE_WIDTH 2500 // 180°

volatile sig_atomic_t program_running = 1;
volatile int current_angle = 90;

// Function to handle keyboard input
void handle_keyboard_input(int angle) {
    char input_buffer[2];
    int input_index = 0;
    int prev_key = 0;

    while (program_running) {
        int key = getchar();
        if (key == EOF) break; // End of file
        if (key == '\n') break; // Newline

        if (input_index == 0 && key != '\r') {
            input_buffer[input_index++] = key;
        } else if (input_index > 0 && key == '\r') {
            input_buffer[input_index] = '\0';
            input_index = 0;
            prev_key = 0; // Reset previous key
        } else if (input_index > 0 && key == '\n') {
            input_buffer[input_index] = '\0';
            input_index = 0;
            prev_key = 0; // Reset previous key
        } else if (input_index > 0 && key != '\r' && key != '\n') {
            input_buffer[input_index++] = key;
        }

        if (input_index > 0) {
            int current_key = input_buffer[0];

            if (current_key == '+' && prev_key != '-') {
                angle += 10;
                if (angle > 180) angle = 180;
            } else if (current_key == '-' && prev_key != '+') {
                angle -= 10;
                if (angle < 0) angle = 0;
            }

            printf("Current Angle: %d\n", angle);
            current_angle = angle;
            gpioServo(GPIO_PIN, (int)(current_angle * (SERVO_MAX_PULSE_WIDTH / 180.0)));
            prev_key = current_key;
            input_index = 0;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Stopping servo and exiting.\n");
        program_running = 0;
        gpioServo(GPIO_PIN, 0); // Stop the servo
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Set PWM duty cycle to 0 (stop the servo initially)
    gpioPWM(GPIO_PIN, 0);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set terminal to raw mode
    struct termios old_termios, new_termios;
    tcgetattr(STDIN_FILENO, &old_termios);
    atexit(tcsetattr(STDIN_FILENO, TCSANOW, &old_termios));

    new_termios.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    new_termios.c_iflag &= ~(IXON | IXOFF | IXANY);
    new_termios.c_oflag &= ~OPOST;
    new_termios.c_cflag &= ~(PARENB | PARODD | CSTOPB | CSIZE | CNLIZ | CREAD | CLOCAL);
    new_termios.c_cflag &= ~CRTSCTS;
    new_termios.c_cflag |= CS8;
    new_termios.c_cflag &= ~HUPCL;
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);

    // Call handle_keyboard_input function
    handle_keyboard_input(current_angle);

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);

    // Save and restore the driver library state
    // gpioSaveLibraryState(); // Not implemented in pigpio
    // gpioRestoreLibraryState(); // Not implemented in pigpio

    return 0;
}

