#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int last_tick;
    int current_tick;
    double last_time;
    double current_time;
    double rpm;
} ProgramState;

ProgramState state = {0, 0, 0.0, 0.0, 0.0};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the Hall effect sensor
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to debounce the sensor reading
int debounce_sensor() {
    int current_value = read_sensor();
    if (current_value == 0) {
        gpioDelay(DEBOUNCE_MS * 1000); // Delay in microseconds
        return read_sensor();
    } else {
        return current_value;
    }
}

// Function to calculate RPM
double calculate_rpm() {
    double time_diff = state.current_time - state.last_time;
    if (time_diff > 0) {
        state.rpm = 60.0 / time_diff; // RPM = 60 / time_per_revolution
        return state.rpm;
    } else {
        return 0.0; // Avoid division by zero
    }
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", buf, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Function to get current timestamp
void get_timestamp(char *timestamp) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    strftime(timestamp, 80, "%Y-%m-%dT%H:%M:%SZ", tstruct);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor
        int sensor_value = debounce_sensor();

        // Update last tick
        if (sensor_value == 1) {
            state.current_tick = gpioTick();
        }

        // Calculate RPM
        state.rpm = calculate_rpm();

        // Get current timestamp
        get_timestamp(state.current_time);

        // Log RPM
        log_rpm(state.rpm);

        // Print RPM
        print_rpm(state.rpm);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

