#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLLING_INTERVAL_MS 50
#define CONTINUOUS_HIGH_THRESHOLD_MS 10000
#define DEBOUNCE_DELAY_MS 500

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
void toggle_relay();
void handle_signal(int signal);
void cleanup();

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to state: %d\n", relay_state);
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_touch_state = 0;
    unsigned long last_touch_time = 0;

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 1 && last_touch_state == 0) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
                toggle_relay();
                last_touch_time = current_time;
            }
        }

        last_touch_state = touch_state;

        if (relay_state == 1) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > CONTINUOUS_HIGH_THRESHOLD_MS * 1000) {
                printf("Sensor continuously HIGH, forcing relay OFF.\n");
                gpioWrite(RELAY_PIN, 0);
                relay_state = 0; // Ensure relay is OFF
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

