#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM parameters
#define PWM_RANGE 255

// Define I2C address for ADC
#define ADC_I2C_ADDR 0x48

// Define ADC channel for flow sensor
#define FLOW_SENSOR_CHANNEL 0

// Define ADC resolution
#define ADC_RESOLUTION 12

// Define flow rate range
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 10.0

// Define target flow rate range
#define MIN_TARGET_FLOW_RATE 0.0
#define MAX_TARGET_FLOW_RATE 10.0

// Define PID parameters
#define KP 1.0

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define PWM period
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Define interrupt pin
#define INTERRUPT_PIN FLOW_SENSOR_PIN

// Define log file name
#define LOG_FILE "flow_log.csv"

// Global variables
volatile unsigned long pulse_count = 0;
volatile int running = 1;

// Function prototypes
int initialize_gpio();
int initialize_adc();
float read_flow_rate();
void set_valve_position(int duty_cycle);
int calculate_duty_cycle(float target_flow_rate);
void log_data(float flow_rate, int duty_cycle);
void interrupt_handler();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(VALVE_PWM_PIN, PWM_OUTPUT);
    pinMode(VALVE_ENABLE_PIN, OUTPUT);
    pinMode(INTERRUPT_PIN, INPUT);

    // Enable PWM on GPIO 18
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    // Enable interrupt on GPIO 24
    if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_RISING, &interrupt_handler) < 0) {
        fprintf(stderr, "Error setting up ISR: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to initialize ADC
int initialize_adc() {
    int fd = wiringPiI2CSetup(ADC_I2C_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read flow rate from ADC
float read_flow_rate() {
    int adc_value = wiringPiI2CReadReg16(fd, FLOW_SENSOR_CHANNEL);
    if (adc_value == -1) {
        fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
        return -1.0;
    }

    // Convert ADC value to flow rate (L/min)
    float flow_rate = (float)adc_value / pow(2, ADC_RESOLUTION) * MAX_FLOW_RATE;

    // Clamp flow rate to the defined range
    if (flow_rate < MIN_FLOW_RATE) {
        flow_rate = MIN_FLOW_RATE;
    } else if (flow_rate > MAX_FLOW_RATE) {
        flow_rate = MAX_FLOW_RATE;
    }

    return flow_rate;
}

// Function to set valve position
void set_valve_position(int duty_cycle) {
    pwmWrite(VALVE_PWM_PIN, duty_cycle);
}

// Function to calculate duty cycle
int calculate_duty_cycle(float target_flow_rate) {
    float error = target_flow_rate - read_flow_rate();
    float duty_cycle = KP * error;

    // Clamp duty cycle to the range 0-255
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    return (int)duty_cycle;
}

// Function to log data
void log_data(float flow_rate, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, flow_rate, duty_cycle);
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler() {
    pulse_count++;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    // Disable PWM
    pwmWrite(VALVE_PWM_PIN, 0);

    // Disable interrupt
    wiringPiISR(INTERRUPT_PIN, INT_EDGE_RISING, NULL);

    // Set valve enable pin low
    digitalWrite(VALVE_ENABLE_PIN, LOW);

    // Close log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    }

    // Terminate wiringPi
    wiringPiSetup(); // Reinitialize to allow proper cleanup
    exit(0);
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    // Parse command-line argument
    char *endptr;
    float target_flow_rate = strtof(argv[1], &endptr);
    if (*endptr != '\0' || target_flow_rate < MIN_TARGET_FLOW_RATE || target_flow_rate > MAX_TARGET_FLOW_RATE) {
        fprintf(stderr, "Error: Target flow rate must be between %.2f and %.2f L/min\n", MIN_TARGET_FLOW_RATE, MAX_TARGET_FLOW_RATE);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Initialize ADC
    fd = initialize_adc();
    if (fd == -1) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Calculate duty cycle
        int duty_cycle = calculate_duty_cycle(target_flow_rate);

        // Set valve position
        set_valve_position(duty_cycle);

        // Log data
        float flow_rate = read_flow_rate();
        log_data(flow_rate, duty_cycle);

        // Delay
        delay(100);
    }

    // Cleanup
    cleanup();

    return 0;
}

