    wiringPiSetup(); // Reinitialize to allow proper cleanup
    exit(0);
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    // Parse command-line argument
    char *endptr;
    float target_flow_rate = strtof(argv[1], &endptr);
    if (*endptr != '\0' || target_flow_rate < MIN_TARGET_FLOW_RATE || target_flow_rate > MAX_TARGET_FLOW_RATE) {
        fprintf(stderr, "Error: Target flow rate must be between %.2f and %.2f L/min\n", MIN_TARGET_FLOW_RATE, MAX_TARGET_FLOW_RATE);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Initialize ADC
    fd = initialize_adc();
    if (fd == -1) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Calculate duty cycle
        int duty_cycle = calculate_duty_cycle(target_flow_rate);

        // Set valve position
        set_valve_position(duty_cycle);

        // Log data
        float flow_rate = read_flow_rate();
        log_data(flow_rate, duty_cycle);

        // Delay
        delay(100);
    }

    // Cleanup
    cleanup();

    return 0;
}

