#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz
#define SPI_MODE 0

// Define RFID reader parameters
#define RFID_READ_DELAY_MS 10

// Define button debounce time (in milliseconds)
#define BUTTON_DEBOUNCE_MS 50

// Define lock disengagement time (in seconds)
#define LOCK_DISENGAGE_TIME 5

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Define valid tag pattern
#define VALID_TAG_LENGTH 10
#define VALID_TAG_START 0x00
#define VALID_TAG_END 0xFF

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_rfid_tag();
int verify_tag(const unsigned char *tag);
int button_pressed();
int disengage_locks();
int engage_locks();
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read data from RFID reader
int read_rfid_tag() {
    unsigned char tag_data[12]; // 10 bytes of data + 2 bytes of command
    int i;

    // Send command to read 10 bytes of data (adjust command as needed)
    for (i = 0; i < 4; i++) {
        if (spiXfer(spi_handle, NULL, tag_data, 12) == 12) {
            // Tag data received successfully
            return 1; // Success
        } else {
            // SPI read failed
            log_event("SPI read failed");
            return 0; // Failure
        }
    }

    // If we reach here, SPI read failed after multiple retries
    log_event("SPI read failed after multiple retries");
    return 0; // Failure
}

// Function to verify the RFID tag
int verify_tag(const unsigned char *tag) {
    if (tag == NULL || tag == NULL || tag == NULL) {
        return 0; // Invalid tag
    }

    if (tag[0] != VALID_TAG_START || tag[VALID_TAG_LENGTH - 1] != VALID_TAG_END) {
        return 0; // Invalid tag length
    }

    // Basic data integrity check (example: check if all bytes are within a range)
    for (int i = 0; i < VALID_TAG_LENGTH; i++) {
        if (tag[i] < VALID_TAG_START || tag[i] > VALID_TAG_END) {
            return 0; // Invalid data
        }
    }

    return 1; // Valid tag
}

// Function to check if the button is pressed
int button_pressed() {
    int button_state = gpioRead(BUTTON_PIN);
    gpioDelay(BUTTON_DEBOUNCE_MS * 1000); // Debounce delay
    return (button_state == 0); // Active-low button
}

// Function to disengage the locks
int disengage_locks() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    log_event("Locks disengaged");
    return 0;
}

// Function to engage the locks
int engage_locks() {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    log_event("Locks engaged");
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Log file not opened. Message: %s\n", message);
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
    spiClose(spi_handle);
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_event("Door access control system started");

    // Main loop
    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag() == 1) {
            unsigned char *tag = NULL;
            int tag_length = 0;

            // Determine tag length based on available data
            for (int i = 0; i < 12; i++) {
                if (spiRead(spi_handle, &tag[i], 1) != 1) {
                    tag = NULL;
                    tag_length = 0;
                    break;
                }
            }

            if (tag != NULL && tag_length > 0) {
                log_event("RFID tag read");
                if (verify_tag(tag)) {
                    log_event("Valid RFID tag");
                    if (button_pressed()) {
                        log_event("Button pressed, disengaging locks");
                        if (disengage_locks() == 0) {
                            log_event("Button press confirmed, engaging locks");
                            gpioDelay(LOCK_DISENGAGE_TIME * 1000000); // Disengage for 5 seconds
                            engage_locks();
                        } else {
                            log_event("Lock disengagement failed");
                        }
                    } else {
                        log_event("Button press not confirmed");
                    }
                } else {
                    log_event("Invalid RFID tag");
                }
                free(tag);
            } else {
                log_event("No RFID tag data received");
            }
        } else {
            log_event("RFID read failed");
        }

        gpioDelay(RFID_READ_DELAY_MS * 1000); // Delay between RFID reads
    }

    return 0;
}

