#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR1_A 5
#define MOTOR1_B 6

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define MOTOR2_A 26
#define MOTOR2_B 19

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target Speed (RPM)
#define TARGET_SPEED 60.0

// Global Variables
volatile int motor1_count = 0;
volatile int motor2_count = 0;
pthread_mutex_t motor1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t motor2_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Structure to hold PID data
typedef struct {
    double P;
    double I;
    double D;
    double integral;
    double previous_error;
} PIDData;

// Function Prototypes
void motor1_forward(int pwm);
void motor1_backward(int pwm);
void motor1_stop();
void motor2_forward(int pwm);
void motor2_backward(int pwm);
void motor2_stop();
void *encoder_thread1(void *arg);
void *encoder_thread2(void *arg);
double calculate_rpm(int count, double dt);
double pid_control(double setpoint, double actual_speed, PIDData *pid_data, double dt);
void log_data(double motor1_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_rpm, double motor2_p, double motor2_i, double motor2_d, double motor2_output);
void signal_handler(int signal);

// Motor Control Functions
void motor1_forward(int pwm) {
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, pwm);
}

void motor1_backward(int pwm) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
    gpioPWM(MOTOR1_ENA, pwm);
}

void motor1_stop() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, 0);
}

void motor2_forward(int pwm) {
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, pwm);
}

void motor2_backward(int pwm) {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
    gpioPWM(MOTOR2_ENB, pwm);
}

void motor2_stop() {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

// Encoder Thread Functions
void *encoder_thread1(void *arg) {
    int a, b;
    double dt = 0.1; // Sample time (100ms)
    double rpm = 0.0;
    double pid_data = (PIDData){KP, KI, KD, 0.0, 0.0};
    double integral = 0.0;
    double previous_error = 0.0;
    int pwm = 0;

    while (1) {
        gpioRead(MOTOR1_A, &a);
        gpioRead(MOTOR1_B, &b);

        if (a == 1 && b == 0) {
            motor1_count++;
        } else if (a == 0 && b == 1) {
            motor1_count--;
        }

        gpioDelay(1000); // Delay for 1ms (1000us)
    }

    return NULL;
}

void *encoder_thread2(void *arg) {
    int a, b;
    double dt = 0.1; // Sample time (100ms)
    double rpm = 0.0;
    double pid_data = (PIDData){KP, KI, KD, 0.0, 0.0};
    double integral = 0.0;
    double previous_error = 0.0;
    int pwm = 0;

    while (1) {
        gpioRead(MOTOR2_A, &a);
        gpioRead(MOTOR2_B, &b);

        if (a == 1 && b == 0) {
            motor2_count++;
        } else if (a == 0 && b == 1) {
            motor2_count--;
        }

        gpioDelay(1000); // Delay for 1ms (1000us)
    }

    return NULL;
}

// RPM Calculation
double calculate_rpm(int count, double dt) {
    return (count / dt) * 60.0;
}

// PID Control
double pid_control(double setpoint, double actual_speed, PIDData *pid_data, double dt) {
    double error = setpoint - actual_speed;
    pid_data->integral += error * dt;
    double derivative = (error - pid_data->previous_error) / dt;
    double output = pid_data->P * error + pid_data->I * pid_data->integral + pid_data->D * derivative;
    pid_data->previous_error = error;
    return output;
}

// Logging Function
void log_data(double motor1_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_rpm, double motor2_p, double motor2_i, double motor2_d, double motor2_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor1_p, motor1_i, motor1_d, motor1_output,
            motor2_rpm, motor2_p, motor2_i, motor2_d, motor2_output);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    motor1_stop();
    motor2_stop();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR1_A, PI_INPUT);
    gpioSetMode(MOTOR1_B, PI_INPUT);
    gpioSetMode(MOTOR2_A, PI_INPUT);
    gpioSetMode(MOTOR2_B, PI_INPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(MOTOR1_ENA, 100); // 100 Hz
    gpioSetPWMfrequency(MOTOR2_ENB, 100); // 100 Hz

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(MOTOR1_ENA, 1000); // Range of 0-1000 for 100Hz
    gpioSetPWMrange(MOTOR2_ENB, 1000); // Range of 0-1000 for 100Hz

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_RPM,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder threads
    pthread_t thread1, thread2;
    if (pthread_create(&thread1, NULL, encoder_thread1, NULL) != 0) {
        perror("Failed to create encoder thread 1");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    if (pthread_create(&thread2, NULL, encoder_thread2, NULL) != 0) {
        perror("Failed to create encoder thread 2");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        double current_time = timeinfo->tm_sec + timeinfo->tm_min * 60 + timeinfo->tm_hour * 3600;

        // Calculate RPM
        double motor1_rpm = calculate_rpm(motor1_count, 0.1);
        double motor2_rpm = calculate_rpm(motor2_count, 0.1);

        // PID control
        PIDData motor1_pid = (PIDData){KP, KI, KD, 0.0, 0.0};
        PIDData motor2_pid = (PIDData){KP, KI, KD, 0.0, 0.0};
        double motor1_output = pid_control(TARGET_SPEED, motor1_rpm, &motor1_pid, 0.1);
        double motor2_output = pid_control(TARGET_SPEED, motor2_rpm, &motor2_pid, 0.1);

        // Set motor speeds
        motor1_forward((int)motor1_output);
        motor2_forward((int)motor2_output);

        // Log data
        log_data(motor1_rpm, motor1_pid.P, motor1_pid.I, motor1_pid.D, motor1_output, motor2_rpm, motor2_pid.P, motor2_pid.I, motor2_pid.D, motor2_output);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    motor1_stop();
    motor2_stop();
    gpioTerminate();
    fclose(log_file);
    return 0;
}

