#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17 // BCM GPIO 17
#define I2C_BUS 1

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(uint16_t touch_status);
void log_relay_state(uint16_t touch_status);
void signal_handler(int signal);

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure filtering parameters
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG1, 0x20) < 0) {
        fprintf(stderr, "Error: Config1 write failed: %s\n", strerror(errno));
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Touch threshold write failed for electrode %d: %s\n", i, strerror(errno));
            return -1;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Release threshold write failed for electrode %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    // Enable run mode
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: ECR write failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    int touch_status_l, touch_status_h;

    touch_status_l = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Read touch status low byte failed: %s\n", strerror(errno));
        return -1;
    }

    touch_status_h = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Read touch status high byte failed: %s\n", strerror(errno));
        return -1;
    }

    *touch_status = (touch_status_h << 8) | touch_status_l;
    return 0;
}

// Function to control the relay based on the touch status
void control_relay(uint16_t touch_status) {
    digitalWrite(RELAY_PIN, HIGH); // Set relay HIGH if any electrode is touched
    if (touch_status == 0) {
        digitalWrite(RELAY_PIN, LOW); // Set relay LOW if no electrode is touched
    }
}

// Function to log the relay state to a file
void log_relay_state(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay: %s\n", timestamp, touch_status ? "HIGH" : "LOW");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_BUS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        return 1;
    }

    // Initialize relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to LOW state

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;

    printf("MPR121 and Relay Control Program running. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            control_relay(touch_status);
            log_relay_state(touch_status);
        } else {
            fprintf(stderr, "Error: Failed to read touch status.\n");
        }

        delay(50); // Delay for 50ms
    }

    // Cleanup
    digitalWrite(RELAY_PIN, LOW); // Turn off relay on exit
    fclose(log_file);
    return 0;
}

