#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define VALVE1_RELAY_PIN 17
#define VALVE2_RELAY_PIN 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Define the sleep duration in milliseconds
#define SLEEP_DURATION_MS 5000

// Define the sleep duration for Valve 2 in milliseconds
#define VALVE2_SLEEP_DURATION_MS 1000

// Define the sleep duration for Valve 2 in seconds
#define VALVE2_SLEEP_DURATION_S 10

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_schedule();
int activate_valve(int valve_number, int duration_ms);
int log_event(int valve_number, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate both valves
    gpioWrite(VALVE1_RELAY_PIN, 0);
    gpioWrite(VALVE2_RELAY_PIN, 0);

    // Close the log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file for closing.\n");
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(VALVE1_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(VALVE2_RELAY_PIN, PI_OUTPUT);

    // Ensure relays are initially off (valves are closed)
    gpioWrite(VALVE1_RELAY_PIN, 0);
    gpioWrite(VALVE2_RELAY_PIN, 0);

    return 0; // Indicate success
}

// Function to read the schedule from the file
int read_schedule() {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file for reading.\n");
        return 1; // Indicate failure
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read line from log file.\n");
        fclose(fp);
        return 1; // Indicate failure
    }

    fclose(fp);

    // Parse the line to extract the valve number and duration
    char *token = strtok(line, ",");
    if (token != NULL) {
        int valve_number = atoi(token);
        token = strtok(NULL, ",");
        if (token != NULL) {
            int duration_ms = atoi(token);
            return (valve_number == 1 || valve_number == 2) && duration_ms > 0 ? 0 : 1; // Validate
        } else {
            fprintf(stderr, "Error: Invalid schedule format: missing duration.\n");
            return 1; // Indicate failure
        }
    } else {
        fprintf(stderr, "Error: Invalid schedule format: missing valve number.\n");
        return 1; // Indicate failure
    }
}

// Function to activate a valve for a specified duration
int activate_valve(int valve_number, int duration_ms) {
    int relay_pin;
    if (valve_number == 1) {
        relay_pin = VALVE1_RELAY_PIN;
    } else if (valve_number == 2) {
        relay_pin = VALVE2_RELAY_PIN;
    } else {
        fprintf(stderr, "Error: Invalid valve number: %d\n", valve_number);
        return 1; // Indicate failure
    }

    gpioWrite(relay_pin, 1); // Activate the relay (open the valve)
