#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER 0x2C
#define MPR121_CHARGE_TIME 0x2D
#define MPR121_ELECTRODE_CONFIG2 0x5F
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_FILTER_CONFIG 0x5B
#define MPR121_ELECTRODE_CONFIG3 0x5C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_configure(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
void relay_toggle(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to toggle the relay
void relay_toggle(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    printf("Relay toggled to state: %d\n", !current_state);
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set baseline filter\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_CHARGE_TIME, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }

    // Configure electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    // Filter config
    if (i2cWriteByteData(i2c_handle, MPR121_FILTER_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set filter config\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG3, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Function to configure the MPR121
int mpr121_configure(int i2c_handle) {
    // Run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0D) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int i2c_handle) {
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte\n");
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure MPR121
    if (mpr121_configure(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
        } else {
            if (touch_status > 0) {
                relay_toggle(RELAY_GPIO);
            }
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

