    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    fprintf(log_file, "%s - %s: %s\n", buf, event_type, message);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Door strike control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= 0.1) { // Debounce
                printf("Motion detected!\n");
                log_event("Motion", "Motion detected");
                control_relay(1); // Activate relay
                gpioDelay(UNLOCK_DURATION_MS * 1000); // Keep relay on for 500ms
                control_relay(0); // Deactivate relay

                // Rate limiting
                last_motion_time = now;
                log_event("Rate Limited", "Motion detected within rate limit window");
                gpioDelay(RATE_LIMIT_DURATION_S * 1000); // Wait for 2 seconds

                // Debounce delay
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            }
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

