#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define WEIGHT_THRESHOLD 10.0 // kg
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Function prototypes
int initialize_gpio();
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void log_weight(double weight);
void load_calibration();
void save_calibration();
void calibrate_hx711();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 500) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 500) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Apply the 25th clock pulse to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage the lock (active-high)
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage the lock
    }
}

// Function to log weight data to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found or could not be opened. Using default values.\n");
        scale_factor = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data in file. Using default values.\n");
        scale_factor = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Function to save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return;
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Function to perform one-time startup calibration
void calibrate_hx711() {
    double sum = 0.0;
    int raw_value;
    int num_readings = NUM_CALIBRATION_READINGS;

    printf("Starting calibration... Please keep the weight at 0 kg.\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off during calibration

    for (int i = 0; i < num_readings; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = sum / num_readings;
    printf("Calibration complete. Offset: %.2f\n", offset);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration data
    load_calibration();

    // Calibrate HX711 if not already calibrated
    if (offset == DEFAULT_OFFSET) {
        calibrate_hx711();
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value);
            printf("Weight: %.2f kg\n", weight);
            log_weight(weight);
            control_solenoid(weight);
        } else {
            fprintf(stderr, "Error reading HX711. Skipping iteration.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

