#include <syslog.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define PWM_ENABLE_PIN 27

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 2

// Define PWM parameters
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Define debounce delay
#define DEBOUNCE_DELAY_MS 50

// Define rain detection threshold
#define RAIN_DETECTED 3

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction, int duty_cycle);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[5];
    int i;

    for (i = 0; i < 5; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Check if rain is detected (LOW signal for at least 3 readings)
    int rain_detected = 0;
    for (i = 0; i < 5; i++) {
        if (readings[i] == 0) {
            rain_detected++;
        }
    }

    return rain_detected >= RAIN_DETECTED ? 1 : 0; // Return 1 if rain is detected, 0 otherwise
}

// Function to control the motor
void control_motor(int direction, int duty_cycle) {
    int result;

    // Set motor direction
    if (direction == MOTOR_FORWARD) {
        result = gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
    } else if (direction == MOTOR_REVERSE) {
        result = gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
    } else {
        result = gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        return; // Stop the motor
    }

    if (result != 0) {
        log_event("Error setting motor direction");
        syslog(LOG_ERR, "Error setting motor direction: %d", result);
    }

    // Set PWM duty cycle
    if (duty_cycle < 0 || duty_cycle > 255) {
        log_event("Error: Invalid PWM duty cycle");
        syslog(LOG_ERR, "Error: Invalid PWM duty cycle: %d", duty_cycle);
        return;
    }

    result = gpioPWM(PWM_ENABLE_PIN, duty_cycle);
    if (result != 0) {
        log_event("Error setting PWM duty cycle");
        syslog(LOG_ERR, "Error setting PWM duty cycle: %d", result);
