void signal_handler(int signal) {
    log_event("Received signal, stopping...");
    syslog(LOG_INFO, "Received signal, stopping...");

    // Stop the motor
    control_motor(MOTOR_STOP, 0);

    // Release GPIO resources
    if (pigpio_initialized) {
        gpioTerminate();
    }

    // Close syslog
    closelog();

    // Exit the program
    running = 0;
    exit(0);
}

