        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(PWM_ENABLE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_ENABLE_PIN, PWM_FREQUENCY);

    // Main loop
    while (running) {
        rain_detected = read_rain_sensor();

        if (rain_detected && !last_rain_state) {
            log_event("Rain detected");
            syslog(LOG_INFO, "Rain detected");
            control_motor(MOTOR_FORWARD, PWM_DUTY_CYCLE);
            gpioDelay(MOTOR_RUN_TIME * 1000000); // Run motor for specified time
            control_motor(MOTOR_STOP, 0);
            log_event("Motor stopped");
            syslog(LOG_INFO, "Motor stopped");
            last_rain_state = 1;
        } else if (!rain_detected && last_rain_state) {
            log_event("Rain stopped");
            syslog(LOG_INFO, "Rain stopped");
            last_rain_state = 0;
        }

        gpioDelay(60000); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (pigpio_initialized) {
        gpioTerminate();
    }
    closelog();
    return 0;
}

