#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define weight threshold (in grams)
#define WEIGHT_THRESHOLD 100.0

// Define solenoid activation time (in seconds)
#define SOLENOID_DURATION 5.0

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 1000

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    while (gpioRead(HX711_DT) == 1 && timeout_counter < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_DURATION) {
        log_event("HX711 timeout: DT signal not received.");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw data to weight in grams
double convert_to_weight(int raw_value) {
    // Calibration factor (adjust based on your load cell)
    double calibration_factor = 100.0; // Example: 100g per unit
    return (double)raw_value / calibration_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    log_event("Solenoid activated.");
    gpioDelay(SOLENOID_DURATION * 1000); // Delay for solenoid duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    log_event("Solenoid deactivated.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error reading HX711, skipping weight check.");
        } else {
            double weight = convert_to_weight(raw_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
            log_event(log_message);

            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating solenoid.");
                activate_solenoid();
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

