#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 100

// Define solenoid activation duration (in seconds)
#define SOLENOID_DURATION 5

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "security.log"

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 5.0

// Global variables
FILE *log_file = NULL;
int solenoid_locked = 0;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_hx711();
int calibrate_hx711();
int save_calibration_factor(float calibration_factor);
int load_calibration_factor(float *calibration_factor);
int check_weight_threshold(float weight, float calibration_factor);
int control_solenoid(int lock);
int log_event(float weight, int solenoid_status);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_DURATION) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate HX711
int calibrate_hx711() {
    float known_weight;
    float calibration_factor;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%f", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight\n");
        return 1;
    }

    printf("Reading calibration factor...\n");
    if (load_calibration_factor(&calibration_factor) != 0) {
        fprintf(stderr, "Failed to load calibration factor. Calibration required.\n");
        if (save_calibration_factor(known_weight) != 0) {
            fprintf(stderr, "Failed to save calibration factor\n");
            return 1;
        }
        printf("Calibration factor saved. Please exit and run the program again.\n");
        return 0; // Calibration successful, but program will exit
    }

    printf("Calibration factor: %f\n", calibration_factor);
    return 0;
}

// Function to save calibration factor to file
int save_calibration_factor(float calibration_factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return 1;
    }
    fprintf(fp, "%f", calibration_factor);
    fclose(fp);
    return 0;
}

// Function to load calibration factor from file
