    }

    // Open the log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started. Press Ctrl-C to exit.\n");

    // Main loop
    while (running) {
        // Read PIR sensors
        int pir1_value = read_pir_sensor(PIR_SENSOR_1);
        int pir2_value = read_pir_sensor(PIR_SENSOR_2);

        if (pir1_value < 0 || pir2_value < 0) {
            fprintf(stderr, "Error reading PIR sensors, exiting...\n");
            break; // Exit loop if there's an error reading sensors
        }

        // Check for motion detection
        if (pir1_value == 1) {
            printf("Motion detected on GPIO %d\n", PIR_SENSOR_1);
            activate_buzzer(BUZZER, BUZZER_DURATION);
            log_motion(PIR_SENSOR_1);
        }
        if (pir2_value == 1) {
            printf("Motion detected on GPIO %d\n", PIR_SENSOR_2);
            activate_buzzer(BUZZER, BUZZER_DURATION);
            log_motion(PIR_SENSOR_2);
