#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>

// Define GPIO pin for the solenoid valve
#define VALVE_PIN 18

// Define the path to the configuration file
#define CONFIG_FILE "watering.conf"

// Global variable to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_duration_from_config(const char *filename);
void activate_valve(int duration);
void deactivate_valve(void);
void log_status(const char *message);
void signal_handler(int signal);

// Function to read the watering duration from the configuration file
int read_duration_from_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s: %s\n", filename, strerror(errno));
        return -1; // Indicate an error
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1; // Indicate an error
    }

    // Remove trailing newline character
    line[strcspn(line, "\n")] = 0;

    // Check for empty line
    if (line[0] == '\0') {
        fprintf(stderr, "Error: Empty config file %s\n", filename);
        fclose(fp);
        return -1; // Indicate an error
    }

    // Parse the line for the duration
    char *token = strtok(line, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Malformed config file %s: Missing duration\n", filename);
        fclose(fp);
        return -1; // Indicate an error
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Malformed config file %s: Missing duration value\n", filename);
        fclose(fp);
        return -1; // Indicate an error
    }

    int duration;
    if (sscanf(token, "%d", &duration) != 1) {
        fprintf(stderr, "Error: Malformed config file %s: Invalid duration value\n", filename);
        fclose(fp);
        return -1; // Indicate an error
    }

    // Validate the duration
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Invalid duration in config file %s: duration=%d\n", filename, duration);
        fclose(fp);
        return -1; // Indicate an error
    }

    fclose(fp);
    return duration;
}

// Function to activate the solenoid valve
void activate_valve(int duration) {
    char message[256];
    snprintf(message, sizeof(message), "Activating valve for %d seconds", duration);
    log_status(message);
    digitalWrite(VALVE_PIN, HIGH); // Set the valve to the active state
    delay(duration * 1000);         // Wait for the specified duration
    deactivate_valve();
}

// Function to deactivate the solenoid valve
void deactivate_valve(void) {
    char message[256];
    snprintf(message, sizeof(message), "Deactivating valve");
    log_status(message);
    digitalWrite(VALVE_PIN, LOW);  // Set the valve to the inactive state
}

// Function to log status messages to stdout
void log_status(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        terminate = 1;
        log_status("Received signal, shutting down...");
    }
}

int main(void) {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Unable to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set the valve pin as an output
    pinMode(VALVE_PIN, OUTPUT);
    digitalWrite(VALVE_PIN, LOW); // Initialize valve to OFF

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read the watering duration from the configuration file
    int duration = read_duration_from_config(CONFIG_FILE);
    if (duration == -1) {
        fprintf(stderr, "Error: Failed to read watering duration from config file\n");
        return 1;
    }

    // Activate the valve
    activate_valve(duration);

    // Main loop to poll for termination signal
    while (!terminate) {
        delay(100); // Small delay to prevent busy-waiting
    }

    // Deactivate the valve before exiting
    deactivate_valve();

    // Release the GPIO pin
    pinMode(VALVE_PIN, INPUT); // Set to input to release the pin

    log_status("Program terminated");

    return 0;
}

