#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define GPIO pins for motor control
#define MOTOR_LEFT_PIN 22
#define MOTOR_RIGHT_PIN 25

// Define GPIO pins for sensor inputs
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Define base motor speed
#define BASE_SPEED 150

// Define sensor threshold
#define SENSOR_THRESHOLD 50

// Define I2C address for MPU6050
#define MPU6050_ADDR 0x68

// Define MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int read_sensor(int pin);
int calculate_motor_speed(int left_sensor, int middle_sensor, int right_sensor);
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(MOTOR_LEFT_PIN, PWM_OUTPUT);
    pinMode(MOTOR_RIGHT_PIN, PWM_OUTPUT);
    pinMode(LEFT_SENSOR_PIN, INPUT);
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);

    // Set PWM mode to mark:space
    pwmSetMode(PWM_MODE_MS);

    // Set PWM range (0-255)
    pwmSetRange(255);

    // Set PWM clock divider (adjust as needed for 1 kHz frequency)
    pwmSetClock(192); // For 1kHz = 1000Hz / (2 * 192 + 1) = 5.2083

    return 0;
}

// Function to initialize I2C communication with MPU6050
int initialize_i2c() {
    int fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read sensor value from a given GPIO pin
int read_sensor(int pin) {
    return digitalRead(pin);
}

// Function to calculate motor speed based on sensor readings
int calculate_motor_speed(int left_sensor, int middle_sensor, int right_sensor) {
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;

    if (middle_sensor == 0) {
        // Drive straight
        left_speed = right_speed = BASE_SPEED;
    } else if (left_sensor == 0) {
        // Turn right
        left_speed = BASE_SPEED / 2;
        right_speed = BASE_SPEED;
    } else if (right_sensor == 0) {
        // Turn left
        left_speed = BASE_SPEED;
        right_speed = BASE_SPEED / 2;
    } else {
        // Stop
        left_speed = right_speed = 0;
    }

    return (left_speed + right_speed) / 2; // Average the speeds
}

// Function to set motor speed using PWM
void set_motor_speed(int left_speed, int right_speed) {
    pwmWrite(MOTOR_LEFT_PIN, left_speed);
    pwmWrite(MOTOR_RIGHT_PIN, right_speed);
}

// Function to log data to a file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_motor_speed(0, 0); // Stop motors
    if (log_file != NULL) {
        fclose(log_file);
    }
    wiringPiSetupGpio(); // Reinitialize to allow proper cleanup of GPIO pins
    pinMode(MOTOR_LEFT_PIN, INPUT); // Set pins to input to avoid spurious output
    pinMode(MOTOR_RIGHT_PIN, INPUT);
    pinMode(LEFT_SENSOR_PIN, INPUT);
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Initialize I2C
    int i2c_fd = initialize_i2c();
    if (i2c_fd == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Calculate motor speed
        int left_speed = calculate_motor_speed(left_sensor, middle_sensor, right_sensor);
        int right_speed = calculate_motor_speed(left_sensor, middle_sensor, right_sensor);

        // Set motor speed
        set_motor_speed(left_speed, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay for 10ms
        delay(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

