    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn ON
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn OFF
                relay_state = 0;
                log_data(lux, relay_state);
            }

            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Turn OFF relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

