#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int angle);
int read_button_state(int pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        program_running = 0; // Set the flag to exit the main loop
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate(); // Terminate pigpio
        exit(0); // Exit the program
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return 1; // Indicate failure
    }

    // Calculate pulse width based on angle (0-180 degrees)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Ensure pulse width is within safe limits
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0; // Indicate success
}

// Function to read button state with debouncing
int read_button_state(int pin) {
    int state = gpioRead(pin);
    gpioDelay(100); // Debounce delay
    return state;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_state = read_button_state(LOCK_BUTTON_PIN);
        int unlock_button_state = read_button_state(UNLOCK_BUTTON_PIN);

        // Check for lock button press
        if (lock_button_state == 0) {
            printf("Lock button pressed!\n");
            set_servo_angle(0); // Set servo to lock position (0 degrees)
            gpioDelay(500); // Debounce delay
        }

        // Check for unlock button press
        if (unlock_button_state == 0) {
            printf("Unlock button pressed!\n");
            set_servo_angle(180); // Set servo to unlock position (180 degrees)
            gpioDelay(500); // Debounce delay
        }

        gpioDelay(50); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

