#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define motor pulse duration (in milliseconds)
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Define pigpio error codes
#define PIGPIO_OK 0
#define PIGPIO_ERROR 1

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to drive motor 1
int drive_motor1() {
    int result = gpioWrite(MOTOR1_GPIO, 1); // Turn motor 1 on
    if (result != PIGPIO_OK) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", MOTOR1_GPIO, result);
        return PIGPIO_ERROR;
    }
    gpioDelay(MOTOR1_PULSE_DURATION * 1000); // Delay for motor 1 pulse duration
    result = gpioWrite(MOTOR1_GPIO, 0); // Turn motor 1 off
    if (result != PIGPIO_OK) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", MOTOR1_GPIO, result);
        return PIGPIO_ERROR;
    }
    return PIGPIO_OK;
}

// Function to drive motor 2
int drive_motor2() {
    int result = gpioWrite(MOTOR2_GPIO, 1); // Turn motor 2 on
    if (result != PIGPIO_OK) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", MOTOR2_GPIO, result);
        return PIGPIO_ERROR;
    }
    gpioDelay(MOTOR2_PULSE_DURATION * 1000); // Delay for motor 2 pulse duration
    result = gpioWrite(MOTOR2_GPIO, 0); // Turn motor 2 off
    if (result != PIGPIO_OK) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", MOTOR2_GPIO, result);
        return PIGPIO_ERROR;
    }
    return PIGPIO_OK;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (drive_motor1() != PIGPIO_OK) {
            fprintf(stderr, "Error driving motor 1, exiting...\n");
            break;
        }
        if (drive_motor2() != PIGPIO_OK) {
            fprintf(stderr, "Error driving motor 2, exiting...\n");
            break;
        }
    }

    // Stop motors and release GPIO lines
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

