#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define alert message format
#define ALERT_MESSAGE_SIZE 256

// Global variables
int zmq_socket = -1;
void *zmq_context = NULL;
int alarm_node_mode = 0; // 0 for sound_sensor, 1 for alarm_node

// Function prototypes
int read_sound_sensor();
int publish_alert(const char *message);
int subscribe_alerts();
void handle_alert(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Cleaning up and exiting.\n", signal);
    cleanup();
    exit(0);
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to publish an alert message
int publish_alert(const char *message) {
    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    int rc = zmq_msg_send(&zmq_message, zmq_socket, 0);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        fprintf(stderr, "Error sending message: %s\n", zmq_strerror(zmq_errno()));
        return -1;
    }

    return 0;
}

// Function to subscribe to alerts
int subscribe_alerts() {
    zmq_msg_t zmq_message;
    zmq_msg_init(&zmq_message);

    int rc = zmq_msg_recv(&zmq_message, zmq_socket, 0);
    if (rc == -1) {
        if (zmq_errno() == ENOBUZZER) {
            fprintf(stderr, "No messages available. Waiting...\n");
            sleep(1); // Wait for a message
            rc = zmq_msg_recv(&zmq_message, zmq_socket, 0);
            if (rc == -1) {
                fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(zmq_errno()));
                zmq_msg_close(&zmq_message);
                return -1;
            }
        } else {
            fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(zmq_errno()));
            zmq_msg_close(&zmq_message);
            return -1;
        }
    }

    char *message = (char *)zmq_msg_data(&zmq_message);
    zmq_msg_close(&zmq_message);

    return 1; // Message received
}

// Function to handle an alert message
void handle_alert(const char *message) {
    printf("Received alert: %s\n", message);
}

// Cleanup function to release resources
void cleanup() {
    if (zmq_socket != -1) {
