#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define MQTT_KEEPALIVE 60
#define MQTT_WILL_TOPIC "ir/decoded"
#define MQTT_WILL_MESSAGE "{\"command\": \"ERROR\"}"

// NEC Constants
#define NEC_MARK 9000
#define NEC_SPACE 4500
#define NEC_BIT_DELAY 560
#define NEC_LOGIC_1_SPACE 1690
#define NEC_LOGIC_0_SPACE 560
#define NEC_CHECKSUM 0xFF

// Global Variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_times[100]; // Assuming a maximum of 100 pulses
static volatile int pulse_index = 0;
static volatile int nec_frame_valid = 0;
static volatile int nec_command = 0;
static volatile int nec_address = 0;
static volatile int nec_inverted_address = 0;
static volatile int nec_command_valid = 0;
static volatile int nec_address_valid = 0;
static volatile int nec_inverted_address_valid = 0;
static volatile int nec_checksum_valid = 0;
static volatile int mqtt_client = NULL;
static volatile int running = 1;

// Function Prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
int decode_nec_frame(unsigned int *pulse_times, int pulse_count, int *address, int *command, int *inverted_address, int *checksum);
int validate_nec_frame(int address, int command, int inverted_address, int checksum);
int publish_mqtt(const char *message);
void signal_handler(int signal);
int init_mqtt();
void cleanup_mqtt();

// Pulse Callback Function
void pulse_callback(int gpio, int level, uint32_t tick)
{
    static uint32_t last_tick = 0;
    unsigned int pulse_width = tick - last_tick;
    last_tick = tick;

    if (level == FALLING_EDGE)
    {
        pulse_count++;
        pulse_times[pulse_index++] = pulse_width;
        if (pulse_index >= 100)
        {
            pulse_index = 0;
            if (decode_nec_frame(pulse_times, pulse_count, &nec_address, &nec_command, &nec_inverted_address, &nec_checksum) != 0)
            {
                syslog(LOG_ERR, "Failed to decode NEC frame");
            }
        }
    }
}

// NEC Frame Decoding Function
int decode_nec_frame(unsigned int *pulse_times, int pulse_count, int *address, int *command, int *inverted_address, int *checksum)
{
    if (pulse_count < 34)
    {
        syslog(LOG_ERR, "Insufficient pulses for NEC frame");
        return -1;
    }

    // Check for start bit
    if (pulse_times[0] < NEC_MARK * 0.8 || pulse_times[0] > NEC_MARK * 1.2)
    {
        syslog(LOG_ERR, "Invalid start bit");
        return -1;
    }

    // Decode address
    *address = 0;
    for (int i = 1; i < 9; i++)
    {
        if (pulse_times[2 * i] > NEC_MARK * 0.8 && pulse_times[2 * i] < NEC_MARK * 1.2)
        {
            if (pulse_times[2 * i + 1] > NEC_SPACE * 0.8 && pulse_times[2 * i + 1] < NEC_SPACE * 1.2)
            {
                if (pulse_times[2 * i + 2] > NEC_MARK * 0.8 && pulse_times[2 * i + 2] < NEC_MARK * 1.2)
                {
                    if (pulse_times[2 * i + 3] > NEC_SPACE * 0.8 && pulse_times[2 * i + 3] < NEC_SPACE * 1.2)
                    {
                        *address |= (1 << (7 - i));
                    }
                }
            }
        }
    }

    // Decode command
    *command = 0;
    for (int i = 9; i < 17; i++)
    {
        if (pulse_times[2 * i] > NEC_MARK * 0.8 && pulse_times[2 * i] < NEC_MARK * 1.2)
        {
            if (pulse_times[2 * i + 1] > NEC_SPACE * 0.8 && pulse_times[2 * i + 1] < NEC_SPACE * 1.2)
            {
                if (pulse_times[2 * i + 2] > NEC_MARK * 0.8 && pulse_times[2 * i + 2] < NEC_MARK * 1.2)
                {
                    if (pulse_times[2 * i + 3] > NEC_SPACE * 0.8 && pulse_times[2 * i + 3] < NEC_SPACE * 1.2)
                    {
                        *command |= (1 << (15 - i));
                    }
                }
            }
        }
    }

    // Decode inverted address
    *inverted_address = 0;
    for (int i = 17; i < 25; i++)
    {
        if (pulse_times[2 * i] > NEC_MARK * 0.8 && pulse_times[2 * i] < NEC_MARK * 1.2)
        {
            if (pulse_times[2 * i + 1] > NEC_SPACE * 0.8 && pulse_times[2 * i + 1] < NEC_SPACE * 1.2)
            {
                if (pulse_times[2 * i + 2] > NEC_MARK * 0.8 && pulse_times[2 * i + 2] < NEC_MARK * 1.2)
                {
                    if (pulse_times[2 * i + 3] > NEC_SPACE * 0.8 && pulse_times[2 * i + 3] < NEC_SPACE * 1.2)
                    {
                        *inverted_address |= (1 << (24 - i));
                    }
                }
            }
        }
    }

    // Decode checksum
    *checksum = 0;
    for (int i = 25; i < 33; i++)
    {
        if (pulse_times[2 * i] > NEC_MARK * 0.8 && pulse_times[2 * i] < NEC_MARK * 1.2)
        {
            if (pulse_times[2 * i + 1] > NEC_SPACE * 0.8 && pulse_times[2 * i + 1] < NEC_SPACE * 1.2)
            {
                if (pulse_times[2 * i + 2] > NEC_MARK * 0.8 && pulse_times[2 * i + 2] < NEC_MARK * 1.2)
                {
                    if (pulse_times[2 * i + 3] > NEC_SPACE * 0.8 && pulse_times[2 * i + 3] < NEC_SPACE * 1.2)
                    {
                        *checksum |= (1 << (32 - i));
                    }
                }
            }
        }
    }

    return 0;
}

// NEC Frame Validation Function
int validate_nec_frame(int address, int command, int inverted_address, int checksum)
{
    int inverted_checksum = 0;
    for (int i = 0; i < 8; i++)
    {
        inverted_checksum <<= 1;
        inverted_checksum |= (checksum & 1);
        checksum >>= 1;
    }

    if (address != inverted_address)
    {
        syslog(LOG_ERR, "Address mismatch");
        return -1;
    }

    if (command != (~command)) // Invert command
    {
        syslog(LOG_ERR, "Command mismatch");
        return -1;
    }

    if (checksum != inverted_checksum)
    {
        syslog(LOG_ERR, "Checksum mismatch");
        return -1;
    }

    return 0;
}

// MQTT Publish Function
int publish_mqtt(const char *message)
{
    if (mqtt_client == NULL)
    {
        syslog(LOG_ERR, "MQTT client not initialized");
        return -1;
    }

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal Handler Function
void signal_handler(int signal)
{
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT Initialization Function
int init_mqtt()
{
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client)
    {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return -1;
    }

    int ret = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_publish(mqtt_client, NULL, MQTT_WILL_TOPIC, strlen(MQTT_WILL_MESSAGE), MQTT_WILL_MESSAGE, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to send MQTT will message: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_loop_start(mqtt_client);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// MQTT Cleanup Function
void cleanup_mqtt()
{
    if (mqtt_client != NULL)
    {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
    }
}

int main()
{
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin mode
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set alert function
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    // Initialize MQTT
    if (init_mqtt() != 0)
    {
        syslog(LOG_ERR, "MQTT initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    // Main loop
    while (running)
    {
        sleep(1); // Reduce CPU usage

        // Validate NEC frame
        if (nec_frame_valid)
        {
            if (validate_nec_frame(nec_address, nec_command, nec_inverted_address, nec_checksum) == 0)
            {
                // Create JSON message
                json_t *root = json_object();
                json_object_set_new(root, "command", json_integer(nec_command));
                json_object_set_new(root, "address", json_integer(nec_address));
                json_object_set_new(root, "checksum", json_integer(nec_checksum));

                // Publish to MQTT
                char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
                if (json_str != NULL)
                {
                    publish_mqtt(json_str);
                    free(json_str);
                }
                else
                {
                    syslog(LOG_ERR, "Failed to create JSON message");
                }

                json_decref(root);
            }
            else
            {
                syslog(LOG_ERR, "NEC frame validation failed");
            }
            nec_frame_valid = 0;
        }
    }

    // Cleanup
    gpioTerminate();
    cleanup_mqtt();
    closelog();

    return 0;
}

