            if (pulse_times[2 * i + 1] > NEC_SPACE * 0.8 && pulse_times[2 * i + 1] < NEC_SPACE * 1.2)
            {
                if (pulse_times[2 * i + 2] > NEC_MARK * 0.8 && pulse_times[2 * i + 2] < NEC_MARK * 1.2)
                {
                    if (pulse_times[2 * i + 3] > NEC_SPACE * 0.8 && pulse_times[2 * i + 3] < NEC_SPACE * 1.2)
                    {
                        *checksum |= (1 << (32 - i));
                    }
                }
            }
        }
    }

    return 0;
}

// NEC Frame Validation Function
int validate_nec_frame(int address, int command, int inverted_address, int checksum)
{
    int inverted_checksum = 0;
    for (int i = 0; i < 8; i++)
    {
        inverted_checksum <<= 1;
        inverted_checksum |= (checksum & 1);
        checksum >>= 1;
    }

    if (address != inverted_address)
    {
        syslog(LOG_ERR, "Address mismatch");
        return -1;
    }

    if (command != (~command)) // Invert command
    {
        syslog(LOG_ERR, "Command mismatch");
        return -1;
    }

    if (checksum != inverted_checksum)
    {
        syslog(LOG_ERR, "Checksum mismatch");
        return -1;
    }

    return 0;
}

// MQTT Publish Function
int publish_mqtt(const char *message)
{
    if (mqtt_client == NULL)
    {
        syslog(LOG_ERR, "MQTT client not initialized");
        return -1;
    }

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal Handler Function
void signal_handler(int signal)
{
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT Initialization Function
int init_mqtt()
{
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client)
    {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return -1;
    }

    int ret = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_publish(mqtt_client, NULL, MQTT_WILL_TOPIC, strlen(MQTT_WILL_MESSAGE), MQTT_WILL_MESSAGE, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to send MQTT will message: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_loop_start(mqtt_client);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// MQTT Cleanup Function
void cleanup_mqtt()
{
    if (mqtt_client != NULL)
    {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
    }
}

int main()
{
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin mode
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set alert function
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    // Initialize MQTT
    if (init_mqtt() != 0)
    {
        syslog(LOG_ERR, "MQTT initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    // Main loop
    while (running)
    {
        sleep(1); // Reduce CPU usage

        // Validate NEC frame
        if (nec_frame_valid)
        {
            if (validate_nec_frame(nec_address, nec_command, nec_inverted_address, nec_checksum) == 0)
            {
                // Create JSON message
                json_t *root = json_object();
                json_object_set_new(root, "command", json_integer(nec_command));
                json_object_set_new(root, "address", json_integer(nec_address));
                json_object_set_new(root, "checksum", json_integer(nec_checksum));

                // Publish to MQTT
                char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
                if (json_str != NULL)
                {
                    publish_mqtt(json_str);
                    free(json_str);
                }
                else
                {
                    syslog(LOG_ERR, "Failed to create JSON message");
                }

                json_decref(root);
            }
            else
            {
                syslog(LOG_ERR, "NEC frame validation failed");
            }
            nec_frame_valid = 0;
        }
    }

    // Cleanup
    gpioTerminate();
    cleanup_mqtt();
    closelog();

    return 0;
}

