#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_PORT 5005
#define SLEEP_MS 1000 // Sleep for 1 second

// Global variables
int i2c_handles[4] = {0};
int udp_socket = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
float read_bh1750(int handle);
void send_udp_multicast(float lux_values[4]);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read lux value from BH1750 sensor
float read_bh1750(int handle) {
    char config[1] = {0x10}; // Continuous high resolution mode
    int result = i2cWriteDevice(handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return NAN;
    }
    gpioDelay(180); // Wait for measurement (at least 180ms)

    char data[2];
    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return NAN;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / 1.2;
}

// Function to send UDP multicast packet
void send_udp_multicast(float lux_values[4]) {
    char buffer[256];
    int offset = 0;

    // Format sensor data into string
    for (int i = 0; i < 4; i++) {
        char sensor_str[20];
        snprintf(sensor_str, sizeof(sensor_str), "%d,%f", i + 1, lux_values[i]);
        offset += snprintf(buffer + offset, sizeof(buffer) - offset, "%s;", sensor_str);
    }

    // Null-terminate the string
    buffer[offset] = '\0';

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_PORT);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending UDP multicast: %s\n", strerror(errno));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    for (int i = 0; i < 4; i++) {
        i2c_handles[i] = init_i2c(I2C_BUS, BH1750_ADDR);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to initialize I2C for sensor %d\n", i + 1);
            // Attempt to close any previously opened handles
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            gpioTerminate();
            return 1;
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        // Attempt to close any previously opened I2C handles
        for (int i = 0; i < 4; i++) {
            i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float lux_values[4];

        // Read lux values from each sensor
        for (int i = 0; i < 4; i++) {
            lux_values[i] = read_bh1750(i2c_handles[i]);
            if (isnan(lux_values[i])) {
                fprintf(stderr, "Error reading from sensor %d\n", i + 1);
                lux_values[i] = NAN; // Set to NaN to avoid further processing issues
            }
        }

        // Send UDP multicast packet
        send_udp_multicast(lux_values);

        // Sleep for 1 second
        gpioDelay(SLEEP_MS);
    }

    // Cleanup
    for (int i = 0; i < 4; i++) {
        i2cClose(i2c_handles[i]);
    }
    close(udp_socket);
    gpioTerminate();

    return 0;
}

