#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define START_CONDITION 0x00
#define LOG_FILE "airflow_log.txt"
#define RETRY_DELAY_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t raw_flow;
    float slpm;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_start_condition(int handle);
int read_sensor_data(int handle, uint16_t *raw_flow);
sensor_data_t convert_to_slpm(uint16_t raw_flow);
int log_data(float slpm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write start condition
int write_start_condition(int handle) {
    int result = i2cWriteByteData(handle, 0x00, START_CONDITION);
    if (result < 0) {
        fprintf(stderr, "Failed to write start condition: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data with retry
int read_sensor_data(int handle, uint16_t *raw_flow) {
    int retries = 0;
    int result;
    char buffer[2];

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, 0x00, buffer, 2);
        if (result == 2) {
            // Success
            *raw_flow = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw flow to SLPM
sensor_data_t convert_to_slpm(uint16_t raw_flow) {
    sensor_data_t data;
    data.raw_flow = raw_flow;
    // Assuming 14-bit resolution and 0-100 SLPM range
    data.slpm = (float)raw_flow / 4095.0 * 100.0;
    return data;
}

// Log data to file
int log_data(float slpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, slpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Write start condition
    if (write_start_condition(i2c_handle) != 0) {
        fprintf(stderr, "Failed to write start condition\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_flow;
        if (read_sensor_data(i2c_handle, &raw_flow) == 0) {
            sensor_data_t slpm_data = convert_to_slpm(raw_flow);
            if (log_data(slpm_data.slpm) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // 1 second delay (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    printf("Airflow monitoring stopped.\n");
    return 0;
}

