    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // I2C bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify the AS7341 sensor ID
int verify_sensor_id() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2); // Read sensor ID
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor ID: %s\n", strerror(errno));
        return -1;
    }

    uint16_t sensor_id = (buf[0] << 8) | buf[1];
    if (sensor_id != 0x9343) {
