        return -1;
    }

    printf("Sensor ID verified: 0x%04X\n", sensor_id);
    return 0;
}

// Configure the AS7341 sensor
int configure_sensor() {
    // Enable power (PON)
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Failed to write to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Configure SMUX (Channel 1 to Channel 2)
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03) < 0) {
        fprintf(stderr, "Failed to write to CFG6 register: %s\n", strerror(errno));
        return -1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03 | 0x08) < 0) {
        fprintf(stderr, "Failed to write to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor configured successfully\n");
    return 0;
}

// Read spectral and lux data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[20];
    int result;

    // Read F1-F8 channels
    for (int i = 0; i < 8; i++) {
        char reg_addr = (0x94 + i) & 0x0F; // F1-F8 registers
        result = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read F%d data: %s\n", i + 1, strerror(errno));
            return -1;
        }
        data->f{i + 1} = (buf[1] << 8) | buf[0];
    }

    // Read Clear and NIR channels
    char clear_reg_addr = 0xA4;
    char nir_reg_addr = 0xA6;
    result = i2cReadI2CBlockData(i2c_handle, clear_reg_addr, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Clear data: %s\n", strerror(errno));
        return -1;
    }
    data->clear = (buf[1] << 8) | buf[0];

    result = i2cReadI2CBlockData(i2c_handle, nir_reg_addr, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read NIR data: %s\n", strerror(errno));
        return -1;
    }
    data->nir = (buf[1] << 8) | buf[0];

    return 0;
}

// Calculate a simplified lux approximation
float calculate_lux(sensor_data_t data) {
    // This is a placeholder.  A real lux calculation would involve
    // more complex calculations based on the sensor's gain and integration time.
    // For simplicity, we'll just return a value based on the clear channel.
    float lux = (float)data.clear * 0.1; // Example calculation
    return lux;
}

