int log_data(sensor_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp,
            data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8,
            data.clear, data.nir, lux);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

