#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x1D  // Omron D7S I2C address
#define CSV_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILENAME "seismic_error.log"

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // I2C bus 1, address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[6];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, buf, 6) == 6) {
            data.x = (int16_t)((buf[0] << 8) | buf[1]);
            data.y = (int16_t)((buf[2] << 8) | buf[3]);
            data.z = (int16_t)((buf[4] << 8) | buf[5]);
            return data;
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            log_error("I2C read failed");
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    log_error("I2C read failed after multiple retries");
    data.x = 0; // Indicate error
    data.y = 0;
    data.z = 0;
    return data;
}

// Function to log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, (float)data.x, (float)data.y, (float)data.z);
    fflush(csv_file); // Ensure data is written to file immediately
}

// Function to log errors to error log file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(csv_file, "%s: %s\n", timestamp, message);
    fflush(csv_file);
}

// Cleanup function to close files and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sampling_interval = 1; // Default sampling interval
    char *output_filename = CSV_FILENAME; // Default output filename
    int i2c_address = I2C_ADDR; // Default I2C address

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtol(optarg, NULL, 0);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default (1 second).\n");
                    sampling_interval = 1;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open CSV file for writing
    csv_file = fopen(output_filename, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", output_filename);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic data logger started. Sampling interval: %d seconds, Output filename: %s, I2C address: 0x%02X\n", sampling_interval, output_filename, i2c_address);

    // Main loop
    while (program_running) {
        sensor_data_t data = read_sensor_data();

        if (data.x != 0) { // Check for read error
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping logging.\n");
        }

