#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int sockfd = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sockfd != -1) {
        close(sockfd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the BH1750 sensor
int config_bh1750(int fd) {
    int result = ioctl(fd, I2C_SLAVE, BH1750_ADDR);
    if (result < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    result = ioctl(fd, I2C_SLAVE, BH1750_ADDR); // Re-set the address for mode selection
    if (result < 0) {
        perror("Error setting I2C slave address for mode selection");
        return -1;
    }
    result = ioctl(fd, I2C_SLAVE, BH1750_ADDR); // Re-set the address for measurement
    if (result < 0) {
        perror("Error setting I2C slave address for measurement");
        return -1;
    }

    int mode = CONTINUOUS_HIGH_RES_MODE;
    unsigned char mode_cmd[1] = {mode};
    if (write(fd, mode_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the light level from the BH1750 sensor
int read_light_level(int fd, unsigned short *raw_value) {
    unsigned char buffer[2];
    int bytes_read = read(fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert the raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to create a UDP socket
int create_socket() {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }
    return sockfd;
}

// Function to configure the multicast address
int configure_multicast(const char *addr, int port) {
    struct sockaddr_in addr_info;
    memset(&addr_info, 0, sizeof(addr_info));
    addr_info.sin_family = AF_INET;
    addr_info.sin_addr.s_addr = inet_addr(addr);
    addr_info.sin_port = htons(port);

    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&TTL, sizeof(TTL)) < 0) {
        perror("Error setting TTL");
        return -1;
    }
    if (bind(sockfd, (struct sockaddr *)&addr_info, sizeof(addr_info)) < 0) {
        perror("Error binding socket");
        return -1;
    }
    return 0;
}

// Function to send the lux value via UDP multicast
int send_lux_value(int sockfd, float lux_value) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);
    if (sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&(struct sockaddr_in){0, 0}, sizeof(struct sockaddr_in)) < 0) {
        perror("Error sending data");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure BH1750 sensor
    if (config_bh1750(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Create UDP socket
    sockfd = create_socket();
    if (sockfd < 0) {
        close(i2c_fd);
        return 1;
    }

    // Configure multicast address
    if (configure_multicast(MULTICAST_ADDR, MULTICAST_PORT) < 0) {
        close(i2c_fd);
        close(sockfd);
        return 1;
    }

    // Main loop
    while (1) {
        unsigned short raw_value;
        if (read_light_level(i2c_fd, &raw_value) == 0) {
            float lux_value = convert_to_lux(raw_value);
            if (send_lux_value(sockfd, lux_value) == 0) {
                printf("Lux: %.2f\n", lux_value);
            } else {
                fprintf(stderr, "Failed to send lux value.\n");
            }
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    close(i2c_fd);
    close(sockfd);

    return 0;
}

