#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAGIC_WORD_SIZE 8
#define MAX_FRAME_SIZE 2048 // Adjust based on expected TLV sizes
#define MAX_OBJECTS 10
#define TIMEOUT_MS 100

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    long timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Function prototypes
int initialize_uart();
int read_uart_data(unsigned char *buffer, int max_len);
int validate_magic_word(const unsigned char *buffer, int len);
int parse_tlv_data(const unsigned char *buffer, int len, RadarData *data, int *object_count);
int extract_range_velocity(const unsigned char *tlv_data, int tlv_len, float *range, float *velocity);
int write_data_to_csv(const RadarData *data, int object_count);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read data from UART with timeout
int read_uart_data(unsigned char *buffer, int max_len) {
    int bytes_read = 0;
    int start_time = gpioTick();

    while (bytes_read < max_len && !terminate) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int bytes_to_read = (available < max_len) ? available : max_len - bytes_read;
            int bytes_read_now = serRead(uart_handle, buffer + bytes_read, bytes_to_read);
            if (bytes_read_now > 0) {
                bytes_read += bytes_read_now;
            } else if (bytes_read_now < 0) {
                fprintf(stderr, "Error reading from UART: %d\n", bytes_read_now);
                return -1; // Indicate error
            }
            start_time = gpioTick();
        } else {
            // No data available, check timeout
            int elapsed_time = gpioTick() - start_time;
            if (elapsed_time > TIMEOUT_MS * 1000) {
                fprintf(stderr, "Timeout waiting for data\n");
                return -1; // Indicate timeout
            }
        }
    }
    return bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, int len) {
    if (len != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Invalid magic word length: %d\n", len);
        return -1;
    }

    for (int i = 0; i < len; i++) {
        if (buffer[i] != 0) {
            fprintf(stderr, "Invalid magic word byte: 0x%02X\n", buffer[i]);
            return -1;
        }
    }

    // Assuming the magic word is little-endian
    unsigned char magic_word[4] = {0x00, 0x00, 0x00, 0x00};
    for (int i = 0; i < 4; i++) {
        if (buffer[i] != magic_word[4 - i - 1]) {
            fprintf(stderr, "Invalid magic word value: 0x%02X (expected 0x%02X)\n", buffer[i], magic_word[4 - i - 1]);
            return -1;
        }
    }

    return 0;
}

// Parse TLV data
int parse_tlv_data(const unsigned char *buffer, int len, RadarData *data, int *object_count) {
    int offset = 0;
    *object_count = 0;

    while (offset < len) {
        // Extract TLV header (4 bytes)
        unsigned short tlv_type = (buffer[offset + 1] << 8) | buffer[offset];
        unsigned short tlv_length = (buffer[offset + 3] << 8) | buffer[offset + 2];

        // Check for valid TLV type (example: 1 for range, 2 for velocity)
        if (tlv_type == 1 || tlv_type == 2) {
            // Extract range and velocity data
            if (tlv_type == 1) {
                if (extract_range_velocity(buffer + offset + 4, tlv_length, &data[*object_count].range_m, &data[*object_count].velocity_mps) != 0) {
                    fprintf(stderr, "Error extracting range data\n");
                    return -1;
                }
            } else if (tlv_type == 2) {
                if (extract_range_velocity(buffer + offset + 4, tlv_length, &data[*object_count].range_m, &data[*object_count].velocity_mps) != 0) {
                    fprintf(stderr, "Error extracting velocity data\n");
                    return -1;
                }
            }

            (*object_count)++;
        }

        offset += 4 + tlv_length; // Move to the next TLV
    }

    return 0;
}

// Extract range and velocity from TLV data
int extract_range_velocity(const unsigned char *tlv_data, int tlv_len, float *range, float *velocity) {
    // Assuming range is a float in the first 4 bytes and velocity in the next 4 bytes
    if (tlv_len < 8) {
        fprintf(stderr, "Invalid TLV length for range and velocity\n");
        return -1;
    }

    memcpy(range, tlv_data, 4);
    memcpy(velocity, tlv_data + 4, 4);

    return 0;
}

// Write data to CSV file
int write_data_to_csv(const RadarData *data, int object_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s", timestamp);
    for (int i = 0; i < object_count; i++) {
        fprintf(csv_file, ",%d,%.2f,%.2f", i, data[i].range_m, data[i].velocity_mps);
    }
    fprintf(csv_file, "\n");

    fflush(csv_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    unsigned char buffer[MAX_FRAME_SIZE];
    int bytes_read;
    RadarData radar_data[MAX_OBJECTS];
    int object_count = 0;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart_data(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            // Validate magic word
            if (validate_magic_word(buffer, bytes_read) == 0) {
                // Parse TLV data
                if (parse_tlv_data(buffer, bytes_read, radar_data, &object_count) == 0) {
                    // Write data to CSV
                    if (write_data_to_csv(radar_data, object_count) != 0) {
                        fprintf(stderr, "Error writing data to CSV\n");
                    }
                } else {
                    fprintf(stderr, "Error parsing TLV data\n");
                }
            } else {
                fprintf(stderr, "Invalid magic word received\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART\n");
            break;
        }
    }

    cleanup();
    fprintf(stderr, "Data acquisition stopped.\n");
    return 0;
}

