#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 500
#define TIMEOUT_S 2
#define MAX_BUFFER_SIZE 256
#define MAX_RANGE 10.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_MS / 100; // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_S;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

int parse_data(const char *data, float *range) {
    char *token;
    char *rest = data;
    char *temp = strdup(data); // Duplicate the string for strtok_r
    if (temp == NULL) {
        perror("strdup failed");
        return -1;
    }

    if ((token = strtok_r(temp, ",", &rest)) != NULL) {
        long seconds = strtol(token, NULL, 10);
        if (seconds == 0 && rest != NULL) {
            free(temp);
            return -1; // Invalid timestamp
        }
        if (rest != NULL) {
            *range = strtof(rest, NULL);
            free(temp);
            return 0;
        }
    } else {
        free(temp);
        return -1;
    }
    return -1;
}

int log_data(float range) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (range >= 0.0 && range <= MAX_RANGE) {
        printf("Timestamp: %s, Range: %.2f meters\n", buf, range);
        return 0;
    } else {
        fprintf(stderr, "Invalid range: %.2f meters\n", range);
        return -1;
    }
}

int main() {
    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char buffer[MAX_BUFFER_SIZE];
    float range;
    ssize_t bytes_read;

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            if (parse_data(buffer, &range) == 0) {
                log_data(range);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }
        usleep(10000); // 10ms delay
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

