#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <termios.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for UART file descriptor
int uart_fd = -1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int initialize_uart();
int send_uart_message(const char *message);
void log_sensor_states(int left_state, int middle_state, int right_state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to initialize UART communication
int initialize_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return 1;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8 data bits, no parity, 1 stop bit
    options.c_iflag = IGNPAR;                           // Ignore parity errors
    options.c_oflag = 0;
    options.c_lflag = 0;                               // Non-canonical mode
    tcflush(uart_fd, TCIFLUSH);
    tcsetattr(uart_fd, TCSANOW, &options);

    return 0;
}

// Function to send a message over UART
int send_uart_message(const char *message) {
    if (uart_fd == -1) {
        fprintf(stderr, "UART not initialized\n");
        return 1;
    }

    ssize_t bytes_written = write(uart_fd, message, strlen(message));
    if (bytes_written == -1) {
        perror("Error writing to UART");
        return 1;
    }

    return 0;
}

// Function to log sensor states with timestamp
void log_sensor_states(int left_state, int middle_state, int right_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left_state, middle_state, right_state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (uart_fd != -1) {
        close(uart_fd);
    }

    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor values
        sensor_data.left = read_sensor(LEFT_SENSOR_PIN);
        sensor_data.middle = read_sensor(MIDDLE_SENSOR_PIN);
        sensor_data.right = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor states
        log_sensor_states(sensor_data.left, sensor_data.middle, sensor_data.right);

        // Check for emergency stop condition
        if (sensor_data.left == 0 && sensor_data.middle == 0 && sensor_data.right == 0) {
            printf("EMERGENCY STOP!\n");
            if (send_uart_message("EMERGENCY STOP!\n") != 0) {
                fprintf(stderr, "Failed to send emergency stop message\n");
            }
        }

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

